insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'bank', 0, $official_bank_source${"code":"ACC101","courseId":"bf4eae11-b8cf-51d1-bfb1-5f32b1b2d55a","seedActor":"00000000-0000-4000-8000-000000000042","actor":"00000000-0000-4000-8000-000000000043","bankCount":587,"shell":{"contentKey":"introduction-financial-accounting-1","titles":["Introduction to Financial Accounting I"],"level":"100-level","semesters":["first-semester"]},"rows":{"audited":0,"keep":0,"retire":0,"add":587}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 1, $official_bank_source${"itemId":"4237fb07-7b69-58c7-8666-518268bc9d50","questionId":"bb1f436e-9123-50bb-ab55-0bf5ea4000a0","sourceKey":"bank:ACC101:ACC-0209","payload":{"prompt":"Any definition of accounting must necessarily address the fact that accounting involves","options":["Provision of information for management use only","Identifying and recording of transactions of a business","Provision of qualitative data for shareholders","None of the above"],"correctOption":1,"section":"Nature, scope and objectives of accounting","explanation":"Every definition of accounting starts with identifying and recording business transactions, which are then classified, summarised and communicated. Option A is too narrow because accounting serves many users, not only management. Option C is wrong because accounting deals mainly with quantitative financial data, not only qualitative data for shareholders."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 2, $official_bank_source${"itemId":"22627568-7556-54ff-bab6-48c738503c3e","questionId":"606af168-32e9-53dc-96ef-dbd58d371f11","sourceKey":"bank:ACC101:ACC-0213","payload":{"prompt":"book keeping is a ____ activity","options":["Recording","interpreting","Reporting","Analysing"],"correctOption":0,"section":"Nature, scope and objectives of accounting","explanation":"Bookkeeping is the recording side of accounting: entering transactions in the books of prime entry and ledgers. Interpreting (B), reporting (C) and analysing (D) are wider accounting tasks that come after the bookkeeping is done."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 3, $official_bank_source${"itemId":"efbdc5cd-6338-5471-96f1-bcc91a38813b","questionId":"7120fdcf-a4c5-58dc-89e5-ad2e8e9fc881","sourceKey":"bank:ACC101:ACC-0230","payload":{"prompt":"The two primary objectives of a business are","options":["Earn a profit and remain solvent","Earn a profit and create wealth","Earn a profit and prepare financial statements","Earn a profit and report financial performance"],"correctOption":0,"section":"Nature, scope and objectives of accounting","explanation":"The two main goals of a business are to earn a profit and to stay solvent, meaning it can pay its debts as they fall due. Option B is close, but creating wealth is really another way of describing profit. Options C and D describe accounting tasks that help measure these goals, not the goals themselves."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 4, $official_bank_source${"itemId":"a5c6dc82-36ca-5859-b575-d7ecba27e747","questionId":"67c1d17b-b334-5d34-955d-610e3bfebef9","sourceKey":"bank:ACC101:ACC-0242","payload":{"prompt":"The father of Accounting is ___","options":["Leonardo Da Vinci","Luca Pacioli","Adam Smith","John Woods"],"correctOption":1,"section":"Nature, scope and objectives of accounting","explanation":"Luca Pacioli, an Italian mathematician, is known as the father of accounting because he published the first detailed description of the double entry system in 1494. Leonardo da Vinci (A) was his friend but not an accountant, and Adam Smith (C) is famous as an economist."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 5, $official_bank_source${"itemId":"1561c52f-35b1-5194-9cde-5dedf22fac2a","questionId":"a347d8b9-b63d-51b7-9668-c4e7d28a4e73","sourceKey":"bank:ACC101:A101N1-001","payload":{"prompt":"Ancient Babylonian merchants kept records of their sales and lending on which medium?","options":["Bound paper ledgers","Papyrus sheets","Clay tablets","Engraved public stones"],"correctOption":2,"section":"Nature, scope and objectives of accounting","explanation":"Babylonian merchants recorded their sales and lending on clay tablets, one of the earliest known forms of record keeping. Papyrus was used by the Egyptians, mainly for tax records, and stones engraved and displayed in public belong to ancient Greece."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 6, $official_bank_source${"itemId":"70d3f76f-1ab2-5691-8a93-664b8ecd1e26","questionId":"022ee4a7-f00f-5bb8-9c5a-0e07bd359a27","sourceKey":"bank:ACC101:A101N1-002","payload":{"prompt":"In ancient Egypt, papyrus was used mainly to record which activity?","options":["Profits shared by partners","Tax collection","Sales and lending by merchants","Public display of state accounts"],"correctOption":1,"section":"Nature, scope and objectives of accounting","explanation":"The Egyptians used papyrus to keep records of tax collection. Recording sales and lending was the work of Babylonian merchants on clay tablets, while accounts displayed in public were a Greek practice."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 7, $official_bank_source${"itemId":"1519b1f5-0f2b-59ad-b51b-cb74a183775f","questionId":"b1bb5c67-597b-53f7-b05f-0eabe713dd01","sourceKey":"bank:ACC101:A101N1-003","payload":{"prompt":"Which ancient civilisation engraved its accounts on stones and displayed them in public?","options":["Babylon","Greece","Egypt","Britain"],"correctOption":1,"section":"Nature, scope and objectives of accounting","explanation":"In ancient Greece, accounts were engraved on stones and put on public display. Babylon is linked with clay tablets for sales and lending, and Egypt with papyrus records of tax collection."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 8, $official_bank_source${"itemId":"65c3948e-c488-5a72-a1e8-baf18daf73ce","questionId":"76a4bef3-214e-5f4d-b1bb-bd6735b660e3","sourceKey":"bank:ACC101:A101N1-004","payload":{"prompt":"Luca Pacioli, who produced the first documented work on bookkeeping, was by profession a","options":["Banker","Tax collector","Mathematician","Chartered accountant"],"correctOption":2,"section":"Nature, scope and objectives of accounting","explanation":"Luca Pacioli was a mathematician, and his 1494 work is the first documented work on bookkeeping. Calling him a chartered accountant is tempting because he is the father of accounting, but professional accounting bodies such as the ICAEW only appeared centuries later during the Industrial Revolution."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 9, $official_bank_source${"itemId":"a0ee1428-9e55-5b84-bd46-1392f869d539","questionId":"08ed4ad7-c6b3-5300-b265-c5006c0095c3","sourceKey":"bank:ACC101:A101N1-005","payload":{"prompt":"In which year did Luca Pacioli produce the first documented work on bookkeeping?","options":["1494","1965","1449","1594"],"correctOption":0,"section":"Nature, scope and objectives of accounting","explanation":"Pacioli's work on bookkeeping appeared in 1494, which is why he is called the father of accounting. 1449 and 1594 simply reshuffle or shift the digits, and 1965 is the year ICAN was set up in Nigeria."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 10, $official_bank_source${"itemId":"55c071c4-c3a1-50e8-bd01-9f062ab78ea3","questionId":"3289942e-3140-5a6a-913e-e9df1ee1c78e","sourceKey":"bank:ACC101:A101N1-006","payload":{"prompt":"Luca Pacioli is called the 'father of accounting' mainly because he","options":["produced the first documented work on bookkeeping","introduced clay tablets for recording trade","set up the first accounting standards board","founded the first professional accounting body"],"correctOption":0,"section":"Nature, scope and objectives of accounting","explanation":"Pacioli earned the title because his 1494 work was the first documented work on bookkeeping. The first professional bodies, such as the ICAEW, came much later during the Industrial Revolution, and clay tablets were used by Babylonian merchants long before him."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 11, $official_bank_source${"itemId":"acbc7025-1c52-5aaa-9ea7-16cc7f2aba43","questionId":"24777fb4-a7f8-51f8-a8f3-021a6a75a382","sourceKey":"bank:ACC101:A101N1-007","payload":{"prompt":"Professional bodies such as the ICAEW developed accounting theory and practice during which period?","options":["The era of Babylonian merchants","The Industrial Revolution in Britain","The indigenisation era in Nigeria","The age of information technology"],"correctOption":1,"section":"Nature, scope and objectives of accounting","explanation":"The growth of industry in Britain during the Industrial Revolution led professional bodies such as the ICAEW to develop accounting theory and practice. The indigenisation era is linked with ICAN members running Nigerian enterprises and the creation of the NASB, not with the ICAEW."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 12, $official_bank_source${"itemId":"3596528d-0a9d-593b-bc60-13342b02e34b","questionId":"51a2a99f-ab26-5ae0-a5e3-03adf95a2a96","sourceKey":"bank:ACC101:A101N1-008","payload":{"prompt":"The abbreviation ICAEW stands for","options":["Institute of Chartered Accountants in England and Wales","International Council of Accountants in England and Wales","Institute of Certified Auditors of England and Wales","Institute of Chartered Accountants of Europe and the West"],"correctOption":0,"section":"Nature, scope and objectives of accounting","explanation":"ICAEW is the Institute of Chartered Accountants in England and Wales, one of the professional bodies that developed accounting during the Industrial Revolution. The other options change one word, such as Council for Institute or Certified Auditors for Chartered Accountants, which gives a different, wrong name."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 13, $official_bank_source${"itemId":"f13c290b-c1a6-5bf3-833b-b294eb1c0a1e","questionId":"8c5e8211-566d-5598-8ba6-dc943d2cabe4","sourceKey":"bank:ACC101:A101N1-009","payload":{"prompt":"Through the Industrial Revolution and the arrival of information technology, which feature of accounting has remained unchanged?","options":["The speed of processing records","The basic double-entry rule","The use of handwritten books only","The use of clay tablets and papyrus"],"correctOption":1,"section":"Nature, scope and objectives of accounting","explanation":"Accounting theory and practice developed a great deal, but the basic double-entry rule did not change, and computerised accounting still uses double entry. The speed of processing is exactly what information technology has improved, so it has not stayed the same."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 14, $official_bank_source${"itemId":"ebdac389-91b4-551d-b3f2-1e4c29810d7b","questionId":"4574ef91-8ddf-5c68-8dff-c40d00b06c04","sourceKey":"bank:ACC101:A101N1-010","payload":{"prompt":"The Institute of Chartered Accountants of Nigeria (ICAN) was established by","options":["A directive of the Nigerian Accounting Standards Board","Act of Parliament No. 15 of 1982","Act of Parliament No. 65 of 1915","Act of Parliament No. 15 of 1965"],"correctOption":3,"section":"Nature, scope and objectives of accounting","explanation":"ICAN was set up by Act of Parliament No. 15 of 1965. The year 1982 belongs to the Nigerian Accounting Standards Board, which came after ICAN and could not have created it."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 15, $official_bank_source${"itemId":"d967cd84-cca5-5ee7-aba8-3edb56dbb49c","questionId":"dd61dcff-9347-5141-85e6-91462bd858a0","sourceKey":"bank:ACC101:A101N1-011","payload":{"prompt":"Which body sets the code of ethics for accountants and regulates the accounting profession in Nigeria?","options":["ICAEW","ICAN","Corporate Affairs Commission","Central Bank of Nigeria"],"correctOption":1,"section":"Nature, scope and objectives of accounting","explanation":"The Institute of Chartered Accountants of Nigeria (ICAN) sets the code of ethics and regulates the accounting profession in Nigeria. The ICAEW plays a similar role, but for England and Wales, not Nigeria."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 16, $official_bank_source${"itemId":"c8ff3623-9e56-5d48-8d8c-697295467a03","questionId":"0e01284e-8dfa-5538-8b79-cc84a873f733","sourceKey":"bank:ACC101:A101N1-012","payload":{"prompt":"The Nigerian Accounting Standards Board (NASB), set up in 1982, is now known as the","options":["Federal Inland Revenue Service (FIRS)","Institute of Chartered Accountants of Nigeria (ICAN)","Securities and Exchange Commission (SEC)","Financial Reporting Council of Nigeria (FRCN)"],"correctOption":3,"section":"Nature, scope and objectives of accounting","explanation":"The NASB, set up in 1982, has become the Financial Reporting Council of Nigeria (FRCN). ICAN is a separate and older body, set up in 1965 to regulate the accounting profession, so it is not the NASB under a new name."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 17, $official_bank_source${"itemId":"a82e5dea-87e4-5191-8c2c-9acb488a8849","questionId":"f19e1a3f-e8f4-5389-8d27-cc92bed3f782","sourceKey":"bank:ACC101:A101N1-013","payload":{"prompt":"In which year was the Nigerian Accounting Standards Board (NASB) established?","options":["1965","1982","1494","2011"],"correctOption":1,"section":"Nature, scope and objectives of accounting","explanation":"The NASB was established in 1982, after ICAN members had come to run most Nigerian enterprises. 1965 is the year ICAN itself was set up, so it is the most tempting wrong choice."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 18, $official_bank_source${"itemId":"4e05e61f-8a4f-50f1-90e1-0ded70f67e92","questionId":"611e7ff7-e78f-595f-ba81-ae24ccdb4a93","sourceKey":"bank:ACC101:A101N1-014","payload":{"prompt":"The setting up of the Nigerian Accounting Standards Board followed which development in Nigeria?","options":["Foreign accountants took over most Nigerian enterprises","The Industrial Revolution reached Nigerian factories and industries","ICAN members came to run most enterprises after the indigenisation decrees","Information technology replaced manual bookkeeping in enterprises"],"correctOption":2,"section":"Nature, scope and objectives of accounting","explanation":"After the indigenisation decrees, ICAN members ran most enterprises in Nigeria, and this led to the creation of the NASB in 1982. The idea of foreign accountants taking over is the opposite of what indigenisation brought about."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 19, $official_bank_source${"itemId":"251c3831-5f11-56eb-8106-fd977b7aec7c","questionId":"622d353a-306f-5ed3-8697-de3b326266fd","sourceKey":"bank:ACC101:A101N1-015","payload":{"prompt":"Which statement best describes the effect of information technology on accounting?","options":["It has removed the need to summarise transactions at all","It has improved the speed and quality of accounting, but double entry is still used","It has reduced the speed of accounting but improved its quality","It has replaced double entry with simpler single-entry records"],"correctOption":1,"section":"Nature, scope and objectives of accounting","explanation":"Information technology has made accounting faster and of better quality, yet the work is still based on double entry. The claim that it replaced double entry is wrong, because computerised systems apply the same debit and credit rule."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 20, $official_bank_source${"itemId":"9359a06e-f659-5bdb-b831-1870715c9c0f","questionId":"9e799475-349f-5acd-856d-9448d9f58309","sourceKey":"bank:ACC101:A101N1-016","payload":{"prompt":"The process of collecting, recording, analysing and summarising a business's financial transactions, and interpreting the information for users of the financial statements, is","options":["Financial accounting","Bookkeeping","Cost accounting","Auditing"],"correctOption":0,"section":"Nature, scope and objectives of accounting","explanation":"This is the definition of financial accounting, which runs from collecting and recording transactions to interpreting the results for users. Bookkeeping is tempting, but it covers only collecting and recording, not analysing and interpreting."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 21, $official_bank_source${"itemId":"317bb227-539e-58a5-b221-7d6a2a5ad2de","questionId":"5f338a12-e295-5076-ab4e-6ec5b1cb56bb","sourceKey":"bank:ACC101:A101N1-017","payload":{"prompt":"In financial accounting, transactions are first entered in the ____, then posted to ledgers, and finally summarised in the financial statements.","options":["trial balance","general ledger","statement of financial position","books of original entry"],"correctOption":3,"section":"Nature, scope and objectives of accounting","explanation":"Transactions are first entered in the books of original entry, then posted to the ledgers and finally summarised in the financial statements. The general ledger is the second step, not the first, because entries are posted to it from the books of original entry."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 22, $official_bank_source${"itemId":"332104d4-b050-5840-a8ab-312ebad18fe7","questionId":"548f21e3-b271-5719-8976-e2c9474f64d9","sourceKey":"bank:ACC101:A101N1-018","payload":{"prompt":"The objective of financial statements is to","options":["show the tax authorities the personal tax that each owner of the enterprise should pay","give only the managers a detailed record of daily cash receipts and payments made by the enterprise","give information about an enterprise's financial position that a wide range of users can use to make economic decisions","record every business transaction of the enterprise in the exact order in which it took place"],"correctOption":2,"section":"Nature, scope and objectives of accounting","explanation":"Financial statements aim to give information about an enterprise's financial position that many different users can rely on for economic decisions. Recording every transaction in date order is the job of the books of original entry, not the purpose of the financial statements."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 23, $official_bank_source${"itemId":"135f346f-2984-567e-a8de-57a5668b87f4","questionId":"9642091f-d653-5d8d-8d58-54e53f28b75d","sourceKey":"bank:ACC101:A101N1-019","payload":{"prompt":"Bookkeeping is best described as","options":["the preparation of financial statements for external users","the wider process that analyses and interprets the recorded data","the part of accounting that covers collecting and accurately recording transactions","the independent examination of a firm's financial statements"],"correctOption":2,"section":"Nature, scope and objectives of accounting","explanation":"Bookkeeping is only one part of accounting, and it covers collecting and accurately recording transactions. Analysing and interpreting the recorded data is the wider work of accounting, not bookkeeping."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 24, $official_bank_source${"itemId":"03a5b7be-91f2-5b67-af1d-f3e21ce16791","questionId":"9b95b732-34d2-5a99-9532-e32ff459299e","sourceKey":"bank:ACC101:A101N1-020","payload":{"prompt":"Which of the following activities is NOT part of bookkeeping?","options":["Collecting invoices and receipts for each transaction","Interpreting the results shown in the financial statements","Recording credit sales in the sales day book","Entering cash payments accurately in the cash book"],"correctOption":1,"section":"Nature, scope and objectives of accounting","explanation":"Interpretation belongs to accounting, not bookkeeping, because bookkeeping is a recording activity. Collecting invoices and receipts may look like more than recording, but gathering the evidence of each transaction is part of bookkeeping too."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 25, $official_bank_source${"itemId":"4e232a96-aa15-5e4e-bdfd-4e7fc14e63b9","questionId":"8bd94adf-90a2-58d4-94d1-0ccc009d6aab","sourceKey":"bank:ACC101:A101N1-021","payload":{"prompt":"How does accounting differ from bookkeeping?","options":["Accounting and bookkeeping are two different names for exactly the same activity","Accounting is wider: it analyses, summarises and interprets the records and prepares the financial statements","Accounting is a narrow part of bookkeeping that deals only with cash transactions","Accounting covers only recording, while bookkeeping analyses and interprets the records"],"correctOption":1,"section":"Nature, scope and objectives of accounting","explanation":"Accounting is the wider activity: it takes the recorded data, analyses, summarises and interprets it, and prepares the financial statements. The option that swaps the two roles is wrong, because it is bookkeeping that covers recording and accounting that interprets."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 26, $official_bank_source${"itemId":"6c74d123-9b33-51df-bd67-d92f2f6dded7","questionId":"92155ebb-c310-503f-bab8-1404a92749ff","sourceKey":"bank:ACC101:A101N1-022","payload":{"prompt":"At a firm in Ikeja, Tunde's only job is to collect invoices and receipts and record each transaction accurately in the day books. Tunde's work is best described as","options":["Interpreting financial statements","Auditing","Financial management","Bookkeeping"],"correctOption":3,"section":"Nature, scope and objectives of accounting","explanation":"Collecting the documents and accurately recording each transaction is exactly what bookkeeping covers. Interpreting financial statements is the wider accounting work that comes after the recording, and Tunde does not do that."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 27, $official_bank_source${"itemId":"e14fd7c2-a282-5046-a2c6-41e8f7244dd9","questionId":"e9a442cd-20ef-5581-b6be-3dbc65354da7","sourceKey":"bank:ACC101:A101N1-023","payload":{"prompt":"Which of the following shows the correct order of the financial accounting cycle?","options":["Books of prime entry, business transaction, ledger, financial statements, trial balance","Business transaction, books of prime entry, trial balance, ledger, financial statements","Business transaction, ledger, books of prime entry, trial balance, financial statements","Business transaction, books of prime entry, ledger, trial balance, financial statements"],"correctOption":3,"section":"Nature, scope and objectives of accounting","explanation":"The cycle starts with a business transaction, which is entered in the books of prime entry, posted to the ledger, listed in a trial balance and finally summarised in the financial statements. The order that puts the ledger before the books of prime entry is wrong, because entries are posted to the ledger from those books."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 28, $official_bank_source${"itemId":"7363b1fa-259a-57b6-af93-e6c5f0127e1a","questionId":"61754592-0568-5251-ba55-4018fb642ccf","sourceKey":"bank:ACC101:A101N1-024","payload":{"prompt":"In the financial accounting cycle, which stage comes immediately after posting to the ledger?","options":["Identifying the business transaction","Preparing the financial statements","Recording in the books of prime entry","Extracting the trial balance"],"correctOption":3,"section":"Nature, scope and objectives of accounting","explanation":"Once transactions are posted to the ledger, the next stage is to extract the trial balance from the ledger balances. Preparing the financial statements comes after the trial balance, as the last stage of the cycle."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 29, $official_bank_source${"itemId":"7b86d91f-3c5a-5a5a-a07b-bb68e83981bf","questionId":"23dc1b1c-13be-560b-a9b5-2796f11dcf84","sourceKey":"bank:ACC101:A101N1-025","payload":{"prompt":"In the accounting process, which stage lies between recording in the journal (books of prime entry) and extracting the trial balance?","options":["Interpreting the results","Issuing the sales invoice","Preparing the financial statements","Posting to the ledger"],"correctOption":3,"section":"Nature, scope and objectives of accounting","explanation":"After transactions are recorded in the journal, they are posted to the ledger, and the trial balance is then extracted from the ledger. Preparing the financial statements is the final stage, after the trial balance."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 30, $official_bank_source${"itemId":"ae132249-a576-5861-99a3-9b4ea1690001","questionId":"b47f52bb-f110-5968-943b-a2a8a8a02f43","sourceKey":"bank:ACC101:A101N1-026","payload":{"prompt":"What is the final stage of the financial accounting cycle?","options":["Posting to the ledger","Extracting the trial balance","Preparing the financial statements","Recording in the journal"],"correctOption":2,"section":"Nature, scope and objectives of accounting","explanation":"The cycle ends with the financial statements, which summarise everything recorded in the earlier stages. Extracting the trial balance is the stage just before, used to check the ledger before the statements are prepared."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 31, $official_bank_source${"itemId":"97a82e54-380e-5722-9a69-09398224ac69","questionId":"f925e266-2a0a-5677-9670-0e373b8b1edf","sourceKey":"bank:ACC101:A101N1-027","payload":{"prompt":"On the basis of their aim, organisations are divided into which two types?","options":["Profit-making and non-profit-making","Sole proprietorships and companies","Public and private companies","Trading and manufacturing firms"],"correctOption":0,"section":"Nature, scope and objectives of accounting","explanation":"Organisations are grouped into profit-making organisations and non-profit-making organisations such as ministries, NGOs and clubs. Sole proprietorships and companies are both forms within the profit-making group, so they are not the two broad types."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 32, $official_bank_source${"itemId":"c23408b5-88c9-5bf2-bae9-59471e293b6a","questionId":"1f1db7ee-17a8-5e8b-9809-ea85dff84054","sourceKey":"bank:ACC101:A101N1-028","payload":{"prompt":"Which of the following is NOT one of the three forms of profit-making organisation?","options":["Charity organisation","Partnership","Sole proprietorship","Company"],"correctOption":0,"section":"Nature, scope and objectives of accounting","explanation":"A charity organisation is a non-profit-making organisation, so it is not a form of profit-making business. Sole proprietorships, partnerships and companies are the three forms of profit-making organisation."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 33, $official_bank_source${"itemId":"c8d06bef-5aef-5449-80f4-dd1c065f6537","questionId":"dd31bc13-023a-5d5c-91e1-40252efd9b4c","sourceKey":"bank:ACC101:A101N1-029","payload":{"prompt":"Mama Nkechi owns and runs a provisions shop in Balogun market alone. She takes all the profit and is fully liable for the shop's debts. Her business is a","options":["Non-profit organisation","Company","Sole proprietorship","Partnership"],"correctOption":2,"section":"Nature, scope and objectives of accounting","explanation":"A business with one owner who takes all the profit and is fully liable for its debts is a sole proprietorship. A partnership needs at least two owners sharing profit, and a company would be liable for its own debts as a separate legal person."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 34, $official_bank_source${"itemId":"8d2bceb1-ce7d-50b1-8e7d-6cc37724e046","questionId":"e73c68b9-3d31-5f3a-972d-9b9c3c14cd95","sourceKey":"bank:ACC101:A101N1-030","payload":{"prompt":"Two friends in Yaba set up a printing business, agree to share profits in the ratio 3:2, and are jointly and fully liable for its debts. This business is a","options":["Partnership","Sole proprietorship","Company","Charity organisation"],"correctOption":0,"section":"Nature, scope and objectives of accounting","explanation":"A partnership has two or more owners who are jointly and fully liable and share profit in an agreed ratio, which fits the two friends exactly. A company is not right, because a company is a separate legal person liable for its own debts, so the owners would not be fully liable."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 35, $official_bank_source${"itemId":"b7423a57-2403-542f-b938-a5f9ff18f7b2","questionId":"7c5126e2-a5b5-5463-a7cf-b7ec9309d6b6","sourceKey":"bank:ACC101:A101N1-031","payload":{"prompt":"Which form of business organisation is a separate legal ('artificial') person, distinct from its owners and liable for its own debts?","options":["Company","Partnership","Club or society","Sole proprietorship"],"correctOption":0,"section":"Nature, scope and objectives of accounting","explanation":"A company is an artificial legal person separate from its owners, so the company itself is liable for its debts. In a partnership, the partners themselves are jointly and fully liable, so the business is not separate from its owners in this way."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 36, $official_bank_source${"itemId":"f278e52c-db56-5d82-98fb-1057698fb081","questionId":"fd507936-1c97-5ce8-a0a3-addd5e195b31","sourceKey":"bank:ACC101:A101N1-032","payload":{"prompt":"What is the minimum number of persons needed to form a partnership?","options":["One","Three","Two","Seven"],"correctOption":2,"section":"Nature, scope and objectives of accounting","explanation":"A partnership needs a minimum of two persons who share profit in an agreed ratio. A business with only one owner is a sole proprietorship, not a partnership."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 37, $official_bank_source${"itemId":"8f9599b2-9302-58a6-9831-3afc29b88b48","questionId":"17c4b805-ab9e-5897-a6d0-cefded189a01","sourceKey":"bank:ACC101:A101N1-033","payload":{"prompt":"Which of the following is an example of a non-profit-making organisation?","options":["A government ministry","A public limited company","A partnership of lawyers","A sole proprietorship"],"correctOption":0,"section":"Nature, scope and objectives of accounting","explanation":"Government ministries, NGOs, clubs and societies, and charities are examples of non-profit-making organisations. A partnership of lawyers is tempting because it offers a service, but it exists to earn profit for the partners."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 38, $official_bank_source${"itemId":"c7d9ef4c-7081-580a-9f61-7617d8a0b0c6","questionId":"34ca46f1-33f8-56c5-a2a8-98a0dcc3bc5e","sourceKey":"bank:ACC101:A101N1-034","payload":{"prompt":"A social club in Surulere exists to serve its members rather than to earn a profit. It is best classified as a","options":["Profit-making organisation","Sole proprietorship","Non-profit-making organisation","Partnership"],"correctOption":2,"section":"Nature, scope and objectives of accounting","explanation":"Clubs and societies are examples of non-profit-making organisations because they exist to serve members, not to earn profit. A partnership is a profit-making form in which the partners share profit, so it does not fit a members' club."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 39, $official_bank_source${"itemId":"1a477a3a-5984-5272-923f-7e19d566c18e","questionId":"7b322c3b-27eb-599f-ad3e-e72bff22a738","sourceKey":"bank:ACC101:A101N1-035","payload":{"prompt":"A trading firm in Ikeja reports a good profit but cannot pay its debts as they fall due. Which of the two primary objectives of a business has it failed to meet?","options":["Paying dividends","Earning a profit","Growing its market share","Remaining solvent"],"correctOption":3,"section":"Nature, scope and objectives of accounting","explanation":"The two primary objectives of a business are to earn a profit and to remain solvent, which means being able to pay debts as they fall due. The firm has met the profit objective, so it is solvency that it has failed."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 40, $official_bank_source${"itemId":"84f0ece4-1013-53d6-ad0d-5ab52d7573f7","questionId":"89de1f4f-5c8d-5cb4-b511-7e82943555fe","sourceKey":"bank:ACC101:A101N1-036","payload":{"prompt":"In a computerised accounting system, the books of account","options":["must still be printed daily before they are valid","are replaced completely by the trial balance","no longer need to follow the double-entry rule","may be stored in computer memory rather than printed"],"correctOption":3,"section":"Nature, scope and objectives of accounting","explanation":"In a computerised system the books may be kept in computer memory instead of being printed on paper. They still follow double entry, because information technology has not changed the basic double-entry rule."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 41, $official_bank_source${"itemId":"75fafdc2-f158-5dc8-93fc-a8531c1c6a62","questionId":"f1be6f6e-af4c-5bec-a8e7-c92a3c419716","sourceKey":"bank:ACC101:ACC-0208","payload":{"prompt":"One of the following is not attribute of financial reports","options":["Understandable","Biased","Relevant","Timely"],"correctOption":1,"section":"Users and qualitative characteristics","explanation":"Good financial reports should be free from bias, so they are objective and favour no group of users; being biased is a defect, not an attribute. Understandable, relevant and timely (options A, C and D) are all qualities that make financial information useful for decisions."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 42, $official_bank_source${"itemId":"ffcc4696-2d6f-5b8d-bc1b-3608886d5ca3","questionId":"23cc9f16-6b4e-52a1-b5d1-d1dcff20b2b9","sourceKey":"bank:ACC101:A101N1-037","payload":{"prompt":"The Federal Inland Revenue Service studies a company's financial statements mainly to","options":["judge how much profit can be withdrawn","decide whether to supply goods on credit","assess the tax payable by the company","check the company's ability to repay loans"],"correctOption":2,"section":"Users and qualitative characteristics","explanation":"Taxation authorities such as the FIRS use financial statements to assess how much tax a company should pay. Judging how much profit can be withdrawn is the concern of shareholders, not the tax authority."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 43, $official_bank_source${"itemId":"b9d84a2b-9b25-5781-b53b-61c98562146a","questionId":"d19b5c1d-4826-5b7c-8c5c-aabc73014c08","sourceKey":"bank:ACC101:A101N1-038","payload":{"prompt":"A bank in Lagos is considering a loan to a manufacturing firm. It studies the firm's financial statements mainly to check","options":["the firm's ability to pay interest and repay the loan","how much profit the owners can withdraw","whether the firm pollutes the local area","the amount of tax the firm should pay"],"correctOption":0,"section":"Users and qualitative characteristics","explanation":"Providers of finance, such as banks giving loans or overdrafts, check whether the borrower can pay interest and repay what it owes. How much profit can be withdrawn is a shareholder's question, not a lender's."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 44, $official_bank_source${"itemId":"9065b602-4a06-50b7-8db1-34100871afd6","questionId":"c927b426-0de4-50c7-b61d-ac5e069fe88f","sourceKey":"bank:ACC101:A101N1-039","payload":{"prompt":"A supplier in Ikeja who sells goods on credit to a company studies the company's financial statements mainly to check","options":["national statistics for resource allocation","management's performance on behalf of owners","the tax payable on the company's profit","the company's ability to pay for the goods"],"correctOption":3,"section":"Users and qualitative characteristics","explanation":"Suppliers are trade contacts, and they check whether the company can pay for what it buys on credit. Judging management's performance is what shareholders do, so it is not the supplier's main concern."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 45, $official_bank_source${"itemId":"b789a6a8-300e-50fb-a0a6-2e7dfedd728a","questionId":"ea921baf-8108-5aac-9d91-e8bffa56d662","sourceKey":"bank:ACC101:A101N1-040","payload":{"prompt":"A customer who relies on one manufacturer for all its stock studies that manufacturer's financial statements mainly to check that it is","options":["allowed to withdraw its profits","paying the right amount of tax","a good employer for long careers","a secure supplier it can keep relying on"],"correctOption":3,"section":"Users and qualitative characteristics","explanation":"Customers are trade contacts, and they want to be sure the company will remain a secure supplier they can keep relying on. Whether the company is a good employer for long careers is the interest of employees, not customers."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 46, $official_bank_source${"itemId":"d8cb9612-8c7f-5f1a-a045-baefb3d1afa2","questionId":"c7fa5d9d-db32-5132-9a3e-0ad5bbb95514","sourceKey":"bank:ACC101:A101N1-041","payload":{"prompt":"Suppliers and customers of a company are grouped together in which category of users of financial statements?","options":["The public","Trade contacts","Financial analysts and advisers","Providers of finance"],"correctOption":1,"section":"Users and qualitative characteristics","explanation":"Suppliers and customers are both trade contacts: suppliers check the company can pay, and customers check that it will remain a secure supplier. Providers of finance are lenders such as banks, which is a different group."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 47, $official_bank_source${"itemId":"70ab8081-4cc5-5ca4-ba02-3a69f5f1738c","questionId":"9ee2979d-9b66-5e26-91a1-d7bdfb9377c4","sourceKey":"bank:ACC101:A101N1-042","payload":{"prompt":"Shareholders use a company's financial statements mainly to","options":["decide whether the company will keep supplying its customers","assess the tax payable by the company each year","compile national statistics and allocate resources","judge management's performance and how much profit can be withdrawn"],"correctOption":3,"section":"Users and qualitative characteristics","explanation":"Shareholders want to judge how well management has run the company, how profitable it is, and how much profit can be withdrawn. Checking that the company will keep supplying them is the concern of customers, who are trade contacts."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 48, $official_bank_source${"itemId":"b73f4d68-db3b-54f7-bbd4-ed15e5f7d3c3","questionId":"9931bf87-8bfd-5603-9c26-1dcbf094faef","sourceKey":"bank:ACC101:A101N1-043","payload":{"prompt":"Which user group relies on financial statements to run the business efficiently and make decisions?","options":["Managers","Financial analysts","Taxation authorities","Shareholders"],"correctOption":0,"section":"Users and qualitative characteristics","explanation":"Managers use financial information to run the business efficiently and to make decisions. Shareholders also read the statements, but they use them to judge management's performance rather than to run the business themselves."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 49, $official_bank_source${"itemId":"0e1c1091-ae4e-5dfd-8a40-5331b0ccb6dc","questionId":"6ce39201-e0bc-5b40-8908-f97694e660be","sourceKey":"bank:ACC101:A101N1-044","payload":{"prompt":"Workers at a bank in Lagos read the bank's annual report because their careers and wages depend on the bank. As users of financial statements, they are","options":["Employees","Managers","The public","Shareholders"],"correctOption":0,"section":"Users and qualitative characteristics","explanation":"Employees are users because their careers and wages depend on the company. The public is interested in matters such as local jobs and pollution, not in their own wages from the bank."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 50, $official_bank_source${"itemId":"57d1e590-6a67-5247-91b6-33839f9d544d","questionId":"6cd06f71-fa07-5889-955d-e95ccce71a18","sourceKey":"bank:ACC101:A101N1-045","payload":{"prompt":"Labour unions are interested in a company's financial statements mainly because","options":["they lend money to the company and need to be repaid","they assess the tax that the company must pay each year","the careers and wages of the employees they represent depend on the company","they decide how much profit the company can withdraw"],"correctOption":2,"section":"Users and qualitative characteristics","explanation":"Labour unions count as users through employees, whose careers and wages depend on the company. Lending money and needing repayment describes providers of finance such as banks, not unions."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 51, $official_bank_source${"itemId":"fe3aaf19-9221-584b-98c7-e7e0aa581d55","questionId":"e6643817-5957-5593-a98c-46c0cb3420e1","sourceKey":"bank:ACC101:A101N1-046","payload":{"prompt":"A stockbroker advising clients on whether to buy shares in a listed company belongs to which group of users?","options":["Trade contacts","Providers of finance","Shareholders","Financial analysts and advisers"],"correctOption":3,"section":"Users and qualitative characteristics","explanation":"Stockbrokers, credit agencies and journalists are grouped as financial analysts and advisers. The stockbroker is advising others rather than owning the shares, so he is not a shareholder."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 52, $official_bank_source${"itemId":"59b34a0f-9003-52d9-96d1-3582e9997ee0","questionId":"760b9354-cf26-5aa0-ae7a-1b4f4d8c2a6b","sourceKey":"bank:ACC101:A101N1-047","payload":{"prompt":"Which of the following belongs to the user group 'financial analysts and advisers'?","options":["A government ministry","A credit agency","A trade supplier","A tax authority"],"correctOption":1,"section":"Users and qualitative characteristics","explanation":"Credit agencies, together with stockbrokers and journalists, are financial analysts and advisers. A trade supplier is a trade contact, a separate user group that checks the company's ability to pay."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 53, $official_bank_source${"itemId":"12c175c0-2eff-5639-ad67-da71d7ad43b7","questionId":"6cd8558e-93b6-5a7e-a1a2-fa2df327d469","sourceKey":"bank:ACC101:A101N1-048","payload":{"prompt":"The National Bureau of Statistics uses company financial statements to compile national figures. Which user group does this represent?","options":["Government and its agencies","Financial analysts and advisers","Taxation authorities","The public"],"correctOption":0,"section":"Users and qualitative characteristics","explanation":"Government and its agencies use financial statements for resource allocation and national statistics, which is what the bureau is doing. Taxation authorities are also arms of government, but their purpose is to assess tax payable, not to compile statistics."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 54, $official_bank_source${"itemId":"8bedf24b-087c-5e9d-91cb-e6c0ff2d668a","questionId":"5e2de096-9a7b-5e34-9d47-db3191cb69e8","sourceKey":"bank:ACC101:A101N1-049","payload":{"prompt":"Government and its agencies use financial statements mainly for","options":["checking that supplies will continue","resource allocation and national statistics","assessing interest and repayment ability","judging how much profit to withdraw"],"correctOption":1,"section":"Users and qualitative characteristics","explanation":"Government and its agencies use the information to allocate resources and to produce national statistics. Assessing interest and repayment ability is what banks and other providers of finance do."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 55, $official_bank_source${"itemId":"d672c6af-f1a4-571f-8381-75be63b98ea9","questionId":"bfed5bc6-70ab-5c9a-8011-fe9818c3752f","sourceKey":"bank:ACC101:A101N1-050","payload":{"prompt":"Residents living near a factory in Ikeja want to know about its pollution and whether it hires local people and uses local suppliers. As users of financial statements, they are classified as","options":["Employees","Government agencies","Trade contacts","The public"],"correctOption":3,"section":"Users and qualitative characteristics","explanation":"The public is interested in local employment, the use of local suppliers and environmental effects such as pollution. The residents do not work for the factory, so they are not employees."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 56, $official_bank_source${"itemId":"c528325a-8a1e-5fa1-9265-f22655241e63","questionId":"15b6aa19-0cbe-532b-adfc-6736784647a3","sourceKey":"bank:ACC101:A101N1-051","payload":{"prompt":"Which of the following is NOT a reason why shareholders study a company's financial statements?","options":["To assess the tax payable by the company","To see how much profit can be withdrawn","To judge management's performance","To assess the company's profitability"],"correctOption":0,"section":"Users and qualitative characteristics","explanation":"Assessing the tax payable is the purpose of the taxation authorities, not shareholders. Shareholders use the statements to judge management, check profitability and see how much profit can be withdrawn."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 57, $official_bank_source${"itemId":"18a4213f-dbde-56ce-9153-d409839c3d72","questionId":"3bdbbc61-ca39-5a30-8441-680dec369c43","sourceKey":"bank:ACC101:A101N1-052","payload":{"prompt":"Banks that give overdrafts and loans to a business are classified as which user group?","options":["Shareholders","Financial analysts and advisers","Providers of finance","Trade contacts"],"correctOption":2,"section":"Users and qualitative characteristics","explanation":"Banks giving overdrafts or loans are providers of finance, and they check the business's ability to pay interest and repay. Financial analysts and advisers, such as credit agencies, assess companies but do not lend the money themselves."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 58, $official_bank_source${"itemId":"95e934e8-841d-51df-acb2-9a6f414e8029","questionId":"b48111c9-4293-5d18-ab8c-07ea4f5a1c99","sourceKey":"bank:ACC101:A101N1-053","payload":{"prompt":"Which user group is mainly interested in a company's effect on local employment, local suppliers and the environment?","options":["Employees","The public","Shareholders","Providers of finance"],"correctOption":1,"section":"Users and qualitative characteristics","explanation":"The public looks at local employment, use of local suppliers and environmental effects such as pollution. Employees are interested in their own careers and wages, which is narrower than the wider community's concerns."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 59, $official_bank_source${"itemId":"5b65c6bc-38bf-5e50-9e2a-9804af191501","questionId":"ac7db652-819b-5bff-9ddd-c9e4809fa936","sourceKey":"bank:ACC101:A101N1-054","payload":{"prompt":"Which user group studies financial statements mainly to judge management's performance and decide how much profit can be withdrawn?","options":["Providers of finance","Shareholders","Employees","Managers"],"correctOption":1,"section":"Users and qualitative characteristics","explanation":"Shareholders own the company, so they judge management's performance and see how much profit can be withdrawn. Managers are the people being judged, and they use the statements to run the business."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 60, $official_bank_source${"itemId":"433a4d37-4804-50cf-b353-6d42480f91b1","questionId":"88f6e9d5-1742-5f21-9d84-79ba14e843d0","sourceKey":"bank:ACC101:A101N1-055","payload":{"prompt":"Financial information that contains enough facts to meet users' needs and the decision at hand has the quality of","options":["Comparability","Objectivity","Relevance","Timeliness"],"correctOption":2,"section":"Users and qualitative characteristics","explanation":"Relevant information gives enough facts to meet users' needs for the decision they are making. Timeliness is about when the information is available, not whether it bears on the decision."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 61, $official_bank_source${"itemId":"411a157b-5016-592b-a344-c543d2fed086","questionId":"994d720e-0e14-55cf-a187-e818691b3d3c","sourceKey":"bank:ACC101:A101N1-056","payload":{"prompt":"Financial information is said to be reliable when it is","options":["given in just enough detail, not too much","verifiable, with one piece of evidence confirming another","available early enough to be useful to users","prepared on the same basis in every period"],"correctOption":1,"section":"Users and qualitative characteristics","explanation":"Reliable information can be verified, with one piece of evidence corroborating another. Preparing on the same basis every period describes comparability, which is a different characteristic."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 62, $official_bank_source${"itemId":"8f36385b-2002-5d9e-9437-fc0bb4e25ded","questionId":"2be20885-19cf-524b-b70d-238df7b2f1c9","sourceKey":"bank:ACC101:A101N1-057","payload":{"prompt":"Which qualitative characteristic requires financial information to be verifiable, with one piece of evidence confirming another?","options":["Comparability","Timeliness","Relevance","Reliability"],"correctOption":3,"section":"Users and qualitative characteristics","explanation":"Reliability means the information can be verified because different pieces of evidence corroborate each other. Relevance is about meeting users' needs for a decision, which says nothing about verification."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 63, $official_bank_source${"itemId":"bd1963c9-dba6-53a7-bcd9-6e5287c531ea","questionId":"af6e2cb3-d614-5441-b5d5-5ff41fe1d773","sourceKey":"bank:ACC101:A101N1-058","payload":{"prompt":"When the basis of preparing financial statements does not change from one period to the next, the statements possess","options":["Relevance","Comprehensiveness","Comparability","Timeliness"],"correctOption":2,"section":"Users and qualitative characteristics","explanation":"Comparability means the basis of preparation stays the same from period to period, so users can compare one year with another. Timeliness only concerns how early the information is available, not whether the basis is the same."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 64, $official_bank_source${"itemId":"d33eaeea-0bba-5fd7-b030-89109c200dd6","questionId":"380757ca-8dfd-55cf-a87f-8219bbeae580","sourceKey":"bank:ACC101:A101N1-059","payload":{"prompt":"A firm in Ikeja publishes its annual report for 2024 only in late 2026. Which qualitative characteristic does the report most clearly lack?","options":["Timeliness","Comprehensiveness","Comparability","Objectivity"],"correctOption":0,"section":"Users and qualitative characteristics","explanation":"Timely information is available early enough to be useful, and annual reports should come out soon after the year end. A report released almost two years late fails this test, even if it is prepared on the same basis as before, so comparability is not the problem."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 65, $official_bank_source${"itemId":"bd6b0247-bffa-5fe1-b068-621eba87d5b7","questionId":"b4ee26d9-e7cd-5a40-ba58-033a93e307b0","sourceKey":"bank:ACC101:A101N1-060","payload":{"prompt":"Financial statements that show no bias or window dressing and can be traced to documents possess","options":["Objectivity","Timeliness","Comparability","Comprehensiveness"],"correctOption":0,"section":"Users and qualitative characteristics","explanation":"Objectivity means the statements are free from bias and window dressing and can be traced to documents. Comprehensiveness is about giving the right amount of detail, not about freedom from bias."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 66, $official_bank_source${"itemId":"af07d5d4-d79a-5ab6-9c7e-a6d088f5b3e2","questionId":"c44e7831-e57c-52ad-8a56-583f8c61bdc5","sourceKey":"bank:ACC101:A101N1-061","payload":{"prompt":"The managing director of a Lagos company arranges year-end transactions to make the financial position look better than it really is. This window dressing most directly violates","options":["Comprehensiveness","Timeliness","Objectivity","Comparability"],"correctOption":2,"section":"Users and qualitative characteristics","explanation":"Objective information is free from bias and window dressing, so deliberately making the position look better breaks this characteristic. Timeliness is not the issue, because the statements could still be published on time while being biased."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 67, $official_bank_source${"itemId":"50fa79d0-872e-534c-8506-f28bc9eb551d","questionId":"28d404d9-6d21-547f-965d-0fb33d34e29d","sourceKey":"bank:ACC101:A101N1-062","payload":{"prompt":"The qualitative characteristic that requires financial statements to give just enough detail, neither too little nor too much, is","options":["Reliability","Timeliness","Comparability","Comprehensiveness"],"correctOption":3,"section":"Users and qualitative characteristics","explanation":"Comprehensiveness means giving just enough detail, neither too little nor too much. Reliability is about whether the information can be verified, not about how much detail is shown."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 68, $official_bank_source${"itemId":"b5b3bbef-0ac5-5977-8de8-f38edb11e9d0","questionId":"ac123061-e35e-5d26-aa02-494c7312e81d","sourceKey":"bank:ACC101:A101N1-063","payload":{"prompt":"A company's annual report lists every individual receipt it issued during the year, running to thousands of pages, so users cannot find the key figures. Which characteristic is poorly applied?","options":["Timeliness","Comparability","Reliability","Comprehensiveness"],"correctOption":3,"section":"Users and qualitative characteristics","explanation":"Comprehensiveness calls for just enough detail, and thousands of pages of receipts is far too much. The figures may well be reliable, since receipts support them, so reliability is not what has gone wrong."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 69, $official_bank_source${"itemId":"725a1850-d2d1-5fc9-8839-4131c46c7b3a","questionId":"7bf44d72-ce82-508a-8dc7-15d7bc81ce6f","sourceKey":"bank:ACC101:A101N1-064","payload":{"prompt":"Timeliness, as a qualitative characteristic of financial information, means that the information is","options":["free from bias and window dressing","available early enough to be useful","confirmed by more than one piece of evidence","prepared on the same basis every period"],"correctOption":1,"section":"Users and qualitative characteristics","explanation":"Timely information reaches users early enough for them to use it, which is why annual reports should come out soon after the year end. Being prepared on the same basis every period is comparability, not timeliness."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 70, $official_bank_source${"itemId":"62ae5a66-f279-503b-89ff-a716a6826829","questionId":"66c44cb0-b602-5121-ae02-a4ae3c5aa705","sourceKey":"bank:ACC101:A101N1-065","payload":{"prompt":"A shareholder compares a Lagos bank's 2024 and 2025 profits and finds that the bank changed its basis of preparation between the two years. Which characteristic has been weakened?","options":["Comprehensiveness","Timeliness","Comparability","Objectivity"],"correctOption":2,"section":"Users and qualitative characteristics","explanation":"Comparability needs the basis of preparation to stay the same from period to period, so changing it makes the two years hard to compare. Objectivity is about bias and window dressing, which is not what this change describes."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 71, $official_bank_source${"itemId":"5844526b-03fa-5e76-9c01-9159e3bcab0d","questionId":"c50c9509-003b-562d-873b-c5ff0e82cec7","sourceKey":"bank:ACC101:A101N1-066","payload":{"prompt":"An auditor accepts a firm's cash sales figure because the receipts, the cash book and the bank statement all agree. This shows that the figure is","options":["Timely","Comparable","Comprehensive","Reliable"],"correctOption":3,"section":"Users and qualitative characteristics","explanation":"Reliable information is verifiable, with one piece of evidence corroborating another, as the three records do here. Comparable would mean the figure is prepared on the same basis as earlier periods, which the agreement of these records does not show."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 72, $official_bank_source${"itemId":"acfc83ee-2a89-5e47-867a-2e588b1138bd","questionId":"e083f18c-27d8-53a0-a56b-ea4e87bc8dd9","sourceKey":"bank:ACC101:A101N1-067","payload":{"prompt":"A Lagos bank asks a borrower for information on its ability to repay a loan, but the firm sends only a history of its staff sports events. The information sent lacks","options":["Relevance","Comparability","Objectivity","Timeliness"],"correctOption":0,"section":"Users and qualitative characteristics","explanation":"Relevant information meets the user's needs for the decision at hand, and sports events say nothing about loan repayment. The information might arrive on time, so timeliness is not the real problem."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 73, $official_bank_source${"itemId":"acd6df00-3d45-5d5e-89a8-607433c01dbf","questionId":"696a7709-22ab-58ad-abac-7413c807ee7c","sourceKey":"bank:ACC101:A101N1-068","payload":{"prompt":"Under the current IASB Conceptual Framework, the two fundamental qualitative characteristics are","options":["Timeliness and understandability","Relevance and faithful representation","Relevance and comparability","Comparability and verifiability"],"correctOption":1,"section":"Users and qualitative characteristics","explanation":"The current IASB framework names relevance and faithful representation as the fundamental characteristics. Comparability is tempting, but it is one of the enhancing characteristics, along with verifiability, timeliness and understandability."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 74, $official_bank_source${"itemId":"a34b88ae-0bbd-5965-8495-9bd784d1d377","questionId":"f9968b7f-7b8e-5cbc-88d9-02f54c9a846b","sourceKey":"bank:ACC101:A101N1-069","payload":{"prompt":"The current IASB framework treats some qualitative characteristics as enhancing rather than fundamental. Which of these is one of them?","options":["Going concern","Verifiability","Relevance","Faithful representation"],"correctOption":1,"section":"Users and qualitative characteristics","explanation":"Verifiability is one of the four enhancing characteristics, with comparability, timeliness and understandability. Relevance and faithful representation are the fundamental characteristics, and going concern is an accounting concept, not a qualitative characteristic."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 75, $official_bank_source${"itemId":"40ec33e2-ddf2-5ee6-b7f1-b69b0f7643d7","questionId":"b2745e36-3a29-501e-9421-73a11c4e1e38","sourceKey":"bank:ACC101:A101N1-070","payload":{"prompt":"Which of the following is NOT an enhancing qualitative characteristic under the current IASB framework?","options":["Relevance","Comparability","Understandability","Timeliness"],"correctOption":0,"section":"Users and qualitative characteristics","explanation":"Relevance is a fundamental characteristic, together with faithful representation, so it is not an enhancing one. Understandability might seem too basic to be listed, but it is one of the four enhancing characteristics."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 76, $official_bank_source${"itemId":"4895e6e1-eecc-5616-93f3-4e1f38b145a4","questionId":"6f7c26ac-a487-539e-8500-5d536d6b975c","sourceKey":"bank:ACC101:A101N1-071","payload":{"prompt":"Under the current IASB framework, understandability is classified as","options":["an accounting convention, not a characteristic","a limitation of financial accounting","a fundamental qualitative characteristic","an enhancing qualitative characteristic"],"correctOption":3,"section":"Users and qualitative characteristics","explanation":"Understandability is one of the four enhancing characteristics, with comparability, verifiability and timeliness. It is not fundamental, because that label is reserved for relevance and faithful representation."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 77, $official_bank_source${"itemId":"d9b89bb7-24ce-5c75-b6f9-506953f98e33","questionId":"256a3f29-0557-52f6-b235-d76d9ae72ec8","sourceKey":"bank:ACC101:A101N1-072","payload":{"prompt":"How many enhancing qualitative characteristics does the current IASB framework identify?","options":["Six","Four","Three","Two"],"correctOption":1,"section":"Users and qualitative characteristics","explanation":"There are four enhancing characteristics: comparability, verifiability, timeliness and understandability. Two is the number of fundamental characteristics, relevance and faithful representation."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 78, $official_bank_source${"itemId":"5d4c3e11-d044-5df6-88aa-54d674b20ee7","questionId":"5c277690-c5c4-557a-9632-652ebeab4112","sourceKey":"bank:ACC101:A101N1-073","payload":{"prompt":"Alongside relevance, which other characteristic does the current IASB framework name as fundamental?","options":["Timeliness","Comparability","Faithful representation","Verifiability"],"correctOption":2,"section":"Users and qualitative characteristics","explanation":"Faithful representation is one of the two fundamental characteristics, alongside relevance. Verifiability is closely linked to it, but it is classed as an enhancing characteristic."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 79, $official_bank_source${"itemId":"5e017f90-13b6-5b79-a600-ca2124e2f19b","questionId":"62921c9b-708e-56b7-85d2-cc49ce5e0cc8","sourceKey":"bank:ACC101:A101N1-074","payload":{"prompt":"Which of the following is NOT a qualitative characteristic of financial information?","options":["Timeliness","Comparability","Profitability","Relevance"],"correctOption":2,"section":"Users and qualitative characteristics","explanation":"Profitability describes how well a business performs, not a quality of the information in its financial statements. Relevance, comparability and timeliness are all qualities that make financial information useful."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 80, $official_bank_source${"itemId":"5ce288f3-2b81-5899-b89e-b5f0c229db87","questionId":"98e7975e-b0ad-525d-a37f-727663f5c85a","sourceKey":"bank:ACC101:A101N1-075","payload":{"prompt":"The older IASB Framework lists the qualitative characteristics as relevance, reliability, comparability, understandability, timeliness and","options":["liquidity","profitability","completeness","solvency"],"correctOption":2,"section":"Users and qualitative characteristics","explanation":"The older IASB Framework list is relevance, reliability, completeness, comparability, understandability and timeliness. Solvency is a business objective, the ability to pay debts, not a quality of financial information."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 81, $official_bank_source${"itemId":"b0db03b9-1043-5d97-88fc-b5293d80ccee","questionId":"58de289e-9b31-59e9-9c02-fe5279bf30c7","sourceKey":"bank:ACC101:ACC-0026","payload":{"prompt":"Which of the following transactions would lead to reduction in assets and liabilities?","options":["Cash purchases","Sale of goods on credit","Purchase of goods on credit","Cash paid to creditors"],"correctOption":3,"section":"Elements and the accounting equation","explanation":"Paying creditors in cash reduces an asset (cash) and a liability (creditors) by the same amount. Option A swaps one asset for another, while option C increases both assets and liabilities."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 82, $official_bank_source${"itemId":"a6c24edb-3762-5ffa-a403-327eab72b29b","questionId":"3a94419e-6fe1-57d6-90ab-cbfd45d71140","sourceKey":"bank:ACC101:ACC-0040","payload":{"prompt":"Which of the following is correct?","options":["Capital-drawings = assets","Liabilities- capital = asset","Capital + liabilities = assets","Assets + liabilities = capital"],"correctOption":2,"section":"Elements and the accounting equation","explanation":"The accounting equation says that what a business owns equals what it owes to its owner and to outsiders: Assets = Capital + Liabilities. Option D wrongly adds liabilities to assets, and option B subtracts in the wrong direction."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 83, $official_bank_source${"itemId":"8ea71115-96f1-5531-afdc-44d0fa12c2f2","questionId":"e235a656-7b5e-5755-bf41-be0a4b094be3","sourceKey":"bank:ACC101:ACC-0140","payload":{"prompt":"The bookkeeping or accounting equation is Assets = Liabilities + Owner's ____.","options":["Journal","Ledger","Equity","Balance sheet"],"correctOption":2,"section":"Elements and the accounting equation","explanation":"The accounting equation is Assets = Liabilities + Owner's Equity, where equity (capital) is the owner's claim on the business. A journal (Option A) and a ledger (Option B) are books for recording transactions, and the balance sheet (Option D) is a statement that is built on the equation rather than part of it."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 84, $official_bank_source${"itemId":"cc36bdb7-b232-57e3-9c5e-ea88519e8a9b","questionId":"2e0f326d-bec7-5581-b0a5-e7db54e3f526","sourceKey":"bank:ACC101:ACC-0150","payload":{"prompt":"Cash and Accounts Receivable are two examples of accounts that are reported on the classified balance sheet under the heading ____ assets.","options":["Current","Revenue","Net loss","Cost"],"correctOption":0,"section":"Elements and the accounting equation","explanation":"Cash and accounts receivable are expected to be turned into cash or used within one year, so they are reported as current assets. Revenue (Option B) and net loss (Option C) are profit and loss items, not balance sheet headings, and cost (Option D) is a measurement basis."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 85, $official_bank_source${"itemId":"8d2a8c55-6cfc-5669-b551-bed5faa67a58","questionId":"eab452ee-4ed5-5a9b-913e-8f6d587989ff","sourceKey":"bank:ACC101:ACC-0153","payload":{"prompt":"A corporation's quarterly ____ will cause a reduction in the corporation's retained earnings, which in turn reduces the corporation's stockholders' equity. However, this will not reduce the corporation's net income.","options":["Retained earnings","Balance sheet","Cost","Dividends"],"correctOption":3,"section":"Elements and the accounting equation","explanation":"Dividends are distributions of profit to shareholders, so they reduce retained earnings and stockholders' equity, but they are not an expense and so do not reduce net income. Retained earnings (Option A) is the account being reduced, not the cause, and the balance sheet (Option B) and cost (Option C) do not reduce equity."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 86, $official_bank_source${"itemId":"fd5fdee0-ea81-50c8-91d5-aaef4d550d96","questionId":"ee733c47-83ea-5670-a74e-d4d8bd29a607","sourceKey":"bank:ACC101:ACC-0170","payload":{"prompt":"Which of the following will cause owner's equity to increase?","options":["Expenses","Owner Draws","Liability","Revenue"],"correctOption":3,"section":"Elements and the accounting equation","explanation":"Revenue increases profit, and profit increases owner's equity. Expenses (Option A) and owner's drawings (Option B) reduce equity, while a liability (Option C) is an amount owed to outsiders, not an increase in the owner's claim."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 87, $official_bank_source${"itemId":"7f9a4ed5-1564-5b98-b2f2-93d89369e4ff","questionId":"43e68f8e-4274-551a-b867-9e94a4529566","sourceKey":"bank:ACC101:ACC-0174","payload":{"prompt":"A corporation's net income is eventually recorded in the following stockholders' equity account:","options":["Dividends","Economic Entity","Retained earnings","Revenues are Earned"],"correctOption":2,"section":"Elements and the accounting equation","explanation":"At the end of each period a corporation's net income is closed to retained earnings, the part of stockholders' equity that holds profits kept in the business. Dividends (Option A) are paid out of retained earnings, and Option D, 'revenues are earned', describes when revenue is recognised, not an account."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 88, $official_bank_source${"itemId":"4e641b3b-2442-5c99-a5b5-89a0b01fe398","questionId":"eaf05730-2e63-5aba-aeef-b97dd9d8d3b9","sourceKey":"bank:ACC101:ACC-0181","payload":{"prompt":"Asset, ____, and stockholders' equity accounts are known as balance sheet accounts.","options":["Journal","Ledger","Equity","liability"],"correctOption":3,"section":"Elements and the accounting equation","explanation":"The balance sheet (statement of financial position) shows assets, liabilities and equity, so these are the balance sheet accounts. Option C, equity, is already named in the question, while a journal (Option A) and ledger (Option B) are books, not types of account."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 89, $official_bank_source${"itemId":"601058c4-c04f-56b0-ad9d-afa0b04181e7","questionId":"f8395c03-ccbc-5baf-b959-0bf48cb3983e","sourceKey":"bank:ACC101:ACC-0192","payload":{"prompt":"Working capital is","options":["Excess of current assets over fixed assets","Excess of fixed asset's over current liabilities","Excess of current assets over current liabilities","Excess of fixed assets over long-term liabilities"],"correctOption":2,"section":"Elements and the accounting equation","explanation":"Working capital (net current assets) is current assets minus current liabilities, showing whether the business can meet its short-term debts. Options A, B and D bring in fixed (non-current) assets, which are long-term items and are not part of working capital."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 90, $official_bank_source${"itemId":"381371c8-a0da-5193-86db-b1eb3d9a5069","questionId":"1a4fb79b-bf4a-5c1f-be90-2f77f37eaecf","sourceKey":"bank:ACC101:ACC-0193","payload":{"prompt":"Capital account of a sole trader represents","options":["The claim of long term creditors over the business assets","The claim of the business on the proprietor","indebtedness of the business to the proprietor","Indebtedness payable in one accounting period"],"correctOption":2,"section":"Elements and the accounting equation","explanation":"Under the business entity concept the business is separate from its owner, so the capital account shows what the business owes the proprietor for the resources they put in. Option A describes long-term liabilities owed to outside lenders, and Option D describes current liabilities."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 91, $official_bank_source${"itemId":"8261dac9-8c92-5229-ad92-c5cb89ea53e7","questionId":"101ba83a-ccbd-5154-b358-7f8e4f697ea7","sourceKey":"bank:ACC101:ACC-0212","payload":{"prompt":"Assets equal","options":["Beginning owner's Equity + Additional Owner Investments + Revenus - Liabilities - Expenses - Drawings","Liabilities + Beginning Owner's Equity + Additional Owner Investments + (Revenue - Expense) - Drawings","Beginning owner's Equity + Additional Owner investment + Liabilities - Revenue - Expenses - Drawings","Liabilities + Beginning Owner's Equity + Additional Owner Investments + Expenses - Revenue - Drawings"],"correctOption":1,"section":"Elements and the accounting equation","explanation":"Assets = Liabilities + Owner's Equity, and owner's equity is the opening capital plus new investment plus profit (revenue - expenses) minus drawings. Option B puts all of this together correctly. Options A and C subtract liabilities or revenue wrongly, and Option D adds expenses and subtracts revenue, which is the reverse of profit."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 92, $official_bank_source${"itemId":"8072738e-51aa-5f2f-8a2b-c04044a152a3","questionId":"287fc11e-ba9f-5605-b2c3-d0e064ac5bc5","sourceKey":"bank:ACC101:ACC-0222","payload":{"prompt":"____ is based on the following fundamental accounting equation Assets = Liabilities + Equity","options":["Cash flow statement","Balance sheet","Profit and loss Account","Trail balance"],"correctOption":1,"section":"Elements and the accounting equation","explanation":"The balance sheet (statement of financial position) is built on Assets = Liabilities + Equity, listing what the business owns against how it is financed. The profit and loss account (C) measures performance over a period, the cash flow statement (A) shows cash movements, and the trial balance (D) is a list of ledger balances used to check arithmetic."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 93, $official_bank_source${"itemId":"759b543f-7605-51c9-a604-820da3d56b35","questionId":"8d139814-59f6-597b-9422-89bb3badf1dd","sourceKey":"bank:ACC101:ACC-0227","payload":{"prompt":"Current capital equals","options":["Beginning Owner's Equity + Owners Investments + Revenue + Expenses - Drawing","Initial Capital + Owner's investments - Revenues - Expenses - Drawings","Beginning Owner's Equity (Capital) + owner's investment + Revenues - Expenses - Drawings","Beginning owner's Equity + Revenue - owner's investment - Expenses - Drawing"],"correctOption":2,"section":"Elements and the accounting equation","explanation":"Current capital = opening capital + further investment by the owner + revenues - expenses - drawings, since profit (revenue minus expenses) increases capital and drawings reduce it. Option A adds expenses instead of subtracting them, Option B subtracts revenue, and Option D subtracts the owner's investment."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 94, $official_bank_source${"itemId":"ddaf0ea3-a398-529d-b8c8-f5519d0145ba","questionId":"e6b14a5f-bd5a-5d33-82b9-473f0ddbfe28","sourceKey":"bank:ACC101:ACC-0281","payload":{"prompt":"It is a golden rule that Accounting equation remains balanced at all time","options":["true","sometimes true","often true","false"],"correctOption":0,"section":"Elements and the accounting equation","explanation":"Every transaction has two equal effects, so Assets = Liabilities + Capital always remains in balance. For example, buying a machine on credit raises assets and liabilities by the same amount. Options B, C and D suggest it can go out of balance, which would mean the double entry had been done wrongly."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 95, $official_bank_source${"itemId":"1c347f7c-9114-54a2-bd87-6aaa3ed9ffd1","questionId":"340109f3-5aa3-566b-ac8c-710018bb7328","sourceKey":"bank:ACC101:ACC-0378","payload":{"prompt":"Calculate the capital from the following information: Premises N20,000; Closing stock N8,000; Cash N100; Creditors N3,000; Loan N4,000","options":["N21,600","N21,100","N25,600","N28,600"],"correctOption":1,"section":"Elements and the accounting equation","explanation":"Capital = assets - liabilities. Assets: N20,000 + N8,000 + N100 = N28,100; liabilities: N3,000 + N4,000 = N7,000; capital = N28,100 - N7,000 = N21,100. Remember that the loan and the creditors are both liabilities, so both must be deducted; leaving either out gives a figure that is too high."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 96, $official_bank_source${"itemId":"ef2593c6-24eb-52f0-822d-4236595d4425","questionId":"076a0b56-f49b-5259-9d00-66c5dbd82296","sourceKey":"bank:ACC101:ACC-0385","payload":{"prompt":"The long-term assets that have no physical existence but are rights that have value is known as","options":["Current assets","Fixed assets","Intangible assets","Investments"],"correctOption":2,"section":"Elements and the accounting equation","explanation":"Intangible assets are long-term assets with no physical form, such as goodwill, patents and trademarks, whose value lies in the rights they give. Option B (fixed assets) usually means tangible items like buildings and machinery, and option A (current assets) are short-term items such as inventory and cash."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 97, $official_bank_source${"itemId":"3b47793d-c672-501b-81b5-8ee0f3768d55","questionId":"dd4c45a0-be22-53c5-8c39-46962c355694","sourceKey":"bank:ACC101:ACC-0386","payload":{"prompt":"The assets that can be converted into cash within a short period (i.e., 1 year or less) are known as","options":["Current assets","Fixed assets","Intangible assets","Investments"],"correctOption":0,"section":"Elements and the accounting equation","explanation":"Current assets are those expected to be turned into cash within a year, such as inventory, receivables and cash itself. Options B and C are long-term assets kept for use over many years, and option D (investments) are often held for the long term too."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 98, $official_bank_source${"itemId":"53a38f30-c0da-58e0-8450-05df5a64b746","questionId":"e9deda41-f3f8-58e0-a9f8-aa3e1f20713f","sourceKey":"bank:ACC101:A101N1-076","payload":{"prompt":"The statement of financial position shows the financial position of a business","options":["for every year since it started","for the next accounting period","at a point in time","over the whole accounting year"],"correctOption":2,"section":"Elements and the accounting equation","explanation":"The statement of financial position is a snapshot of assets, capital and liabilities at one date. Covering the whole accounting year describes the income statement, which reports performance over a period."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 99, $official_bank_source${"itemId":"9452e4c9-bbe9-57a5-b84e-d86d6bf84c97","questionId":"ae91f0a9-dc58-5035-86f2-9a51b570dbad","sourceKey":"bank:ACC101:A101N1-077","payload":{"prompt":"The three sub-heads of the statement of financial position are","options":["assets, capital and liabilities","revenue, expenses and profit","assets, revenue and expenses","capital, revenue and drawings"],"correctOption":0,"section":"Elements and the accounting equation","explanation":"The statement of financial position has three sub-heads: assets, capital and liabilities. Revenue, expenses and profit belong to the income statement, which measures performance rather than position."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 100, $official_bank_source${"itemId":"53123f50-c4f7-5858-a73f-727aa3a839f5","questionId":"dca6e488-b8da-56cd-9c00-8b688abf796d","sourceKey":"bank:ACC101:A101N1-078","payload":{"prompt":"Assets held for use in the business rather than for sale, for more than one accounting period, are called","options":["Non-current assets","Prepayments","Current liabilities","Current assets"],"correctOption":0,"section":"Elements and the accounting equation","explanation":"Non-current assets, such as motor vehicles and land and buildings, are held for use rather than for sale over more than one accounting period. Current assets are cash or items expected to turn into cash within the period."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 101, $official_bank_source${"itemId":"d2e3f013-b139-5bc7-8336-19741d2b20d6","questionId":"9d8d67c9-a717-5df9-b389-cedaa7acd60e","sourceKey":"bank:ACC101:A101N1-079","payload":{"prompt":"Which of these items would a trader in Balogun market show under current assets?","options":["Prepayments","Plant and machinery","Fixtures and fittings","Land and buildings"],"correctOption":0,"section":"Elements and the accounting equation","explanation":"Prepayments are current assets, along with inventory, receivables and cash. Fixtures and fittings may look small, but they are held for use over several periods, so they are non-current assets."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 102, $official_bank_source${"itemId":"24e8067e-7bbe-54bb-bd24-12f0f2d51aab","questionId":"3f8ee0ad-0962-5a0a-94a4-fac6e92f496d","sourceKey":"bank:ACC101:A101N1-080","payload":{"prompt":"A firm in Ikeja is listing its assets. Which item should NOT appear under current assets?","options":["Motor vehicles","Trade receivables","Cash at bank","Inventory"],"correctOption":0,"section":"Elements and the accounting equation","explanation":"Motor vehicles are held for use over more than one period, so they are non-current assets. Inventory is a current asset even though it is not yet cash, because it is expected to be turned into cash within the period."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 103, $official_bank_source${"itemId":"9dd11b6a-1b5c-5fef-bca0-1db6cd95aa6e","questionId":"fa514030-aa53-5038-92dd-ed28e183be3c","sourceKey":"bank:ACC101:A101N1-081","payload":{"prompt":"In accounting, capital is best defined as","options":["finance provided by the owners that is not meant to be repaid in the ordinary course of business","the resources that the business owns and uses in its operations","finance provided by outsiders such as banks and suppliers to the business","the amount by which current assets exceed current liabilities"],"correctOption":0,"section":"Elements and the accounting equation","explanation":"Capital is the owners' finance, which is not meant to be repaid in the normal course of business. Finance provided by outsiders such as banks and suppliers is a liability, not capital."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 104, $official_bank_source${"itemId":"2688c7bb-a504-5013-b55b-d06e9e018a84","questionId":"cfb31f52-83f5-55c3-8f2b-13879a7ad932","sourceKey":"bank:ACC101:A101N1-082","payload":{"prompt":"Liabilities represent","options":["the income earned during the period","the part of the assets financed by outsiders","the part of the assets financed by the owner","the resources that the business owns"],"correctOption":1,"section":"Elements and the accounting equation","explanation":"Liabilities are the part of the assets financed by outsiders, through loans, credit purchases or an overdraft. The part financed by the owner is capital, which sits beside liabilities on the same side of the equation."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 105, $official_bank_source${"itemId":"c9bdd1c0-ce92-5ecf-9cce-e40c3f97b7f1","questionId":"7bac995f-9360-58b3-94fe-afcadb47a34e","sourceKey":"bank:ACC101:A101N1-083","payload":{"prompt":"Which item is classified among the non-current liabilities of a business?","options":["Accrued expenses","Bank overdraft","Trade payables","Debentures"],"correctOption":3,"section":"Elements and the accounting equation","explanation":"Debentures, like long-term loans, are not due within 12 months, so they are non-current liabilities. A bank overdraft is also bank finance, but it is repayable within the year and is a current liability."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 106, $official_bank_source${"itemId":"2bfa9447-b5b9-5419-98eb-34887db440b0","questionId":"9e23903d-46d1-51e4-ae3b-9f32160900b2","sourceKey":"bank:ACC101:A101N1-084","payload":{"prompt":"A trader in Balogun market has a bank overdraft with a bank in Lagos. In the trader's statement of financial position, the overdraft is shown as a","options":["current asset","current liability","part of capital","non-current liability"],"correctOption":1,"section":"Elements and the accounting equation","explanation":"A bank overdraft is due within the year, so it is a current liability, together with trade payables and accrued expenses. It is not a non-current liability, because it is not a long-term loan due after more than 12 months."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 107, $official_bank_source${"itemId":"f5ef5f56-b41e-5088-b9c8-7f043ed31ba5","questionId":"99df650a-201b-5d5e-be11-e2d4d5a54ef3","sourceKey":"bank:ACC101:A101N1-085","payload":{"prompt":"Which form of the accounting equation places all the debit-nature items on one side and all the credit-nature items on the other?","options":["A + L = C + R + E","A + E = C + R + L","A = C + L - R + E","A + R = C + E + L"],"correctOption":1,"section":"Elements and the accounting equation","explanation":"In A + E = C + R + L, assets and expenses (debit-nature items) are on the left, and capital, revenue and liabilities (credit-nature items) are on the right. The version with liabilities on the left is wrong, because liabilities are credit-nature items and belong with capital and revenue."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 108, $official_bank_source${"itemId":"c37f3990-9e4a-594c-be87-5341b2c34cff","questionId":"3ca9baaa-cb79-511b-8fcc-24af33de31b1","sourceKey":"bank:ACC101:A101N1-086","payload":{"prompt":"In the equation A + E = C + R + L, the items on the left-hand side (assets and expenses) are","options":["items owned by the proprietor","credit-nature items","items financed by outsiders","debit-nature items"],"correctOption":3,"section":"Elements and the accounting equation","explanation":"Assets and expenses both increase by debits, so they are the debit-nature items on the left of the equation. Capital, revenue and liabilities on the right are the credit-nature items."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 109, $official_bank_source${"itemId":"7c1c02fc-48ba-5507-b298-06ebb1f4c68c","questionId":"60c03ba2-3f2e-515e-a181-5b2e27900f07","sourceKey":"bank:ACC101:A101N1-087","payload":{"prompt":"If liabilities are deducted from total assets (A - L), the result equals","options":["capital (owner's equity)","current assets","working capital","total revenue"],"correctOption":0,"section":"Elements and the accounting equation","explanation":"Rearranging A = C + L gives A - L = C, so net assets equal the owner's equity. Working capital is a narrower measure, current assets less current liabilities, and does not use total assets."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 110, $official_bank_source${"itemId":"d52692cc-47bf-5d35-ad29-7c21e0f4239b","questionId":"f09bcae6-3a7f-5605-bdb1-44674dc78bba","sourceKey":"bank:ACC101:A101N1-088","payload":{"prompt":"When a business is first started with only the owner's money and no outside finance, the accounting equation is","options":["Capital = Revenue","Assets = Capital","Assets = Revenue - Expenses","Assets = Liabilities"],"correctOption":1,"section":"Elements and the accounting equation","explanation":"At the start, all the assets are financed by the owner, so assets equal capital. Liabilities only appear once outsiders such as banks or suppliers provide finance, giving A = C + L."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 111, $official_bank_source${"itemId":"d8cbc929-8901-589c-b78c-b8e0ef817c09","questionId":"b1979172-262b-5251-af5a-90fcef45c606","sourceKey":"bank:ACC101:A101N1-089","payload":{"prompt":"Since capital = original contribution + profit, and profit = revenue - expenses, the accounting equation can be expanded as","options":["A = C + R + E - L","A + R = C + E + L","A = C - R + E + L","A = C + R - E + L"],"correctOption":3,"section":"Elements and the accounting equation","explanation":"Replacing profit with revenue minus expenses in A = C + L gives A = C + R - E + L. The version with revenue subtracted and expenses added has the signs reversed, which would mean revenue reduces the owner's capital."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 112, $official_bank_source${"itemId":"f3fa01d3-9539-593a-a371-90c0e67e7652","questionId":"103182a1-1b29-536c-aadc-1f55f8a175d2","sourceKey":"bank:ACC101:A101N1-090","payload":{"prompt":"Kunle starts a business in Ikeja with capital of N3,500,000, all in cash. He then buys equipment on credit for N400,000. What are the total assets of the business after the purchase?","options":["N3,500,000","N4,300,000","N3,900,000","N3,100,000"],"correctOption":2,"section":"Elements and the accounting equation","explanation":"Cash of N3,500,000 plus equipment of N400,000 gives total assets of N3,900,000, matched by capital N3,500,000 plus a payable of N400,000. N3,500,000 would be right only if the equipment had been paid for in cash, but buying on credit adds a new asset and a liability."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 113, $official_bank_source${"itemId":"06493598-6e5a-5f1f-8c88-08749abadd84","questionId":"cbc8d9d5-a795-579c-b45d-068b4b91085a","sourceKey":"bank:ACC101:A101N1-091","payload":{"prompt":"A firm in Lagos has total assets of N12,600,000. It still owes N3,850,000 on a delivery van bought on credit and has no other liabilities. What is the owner's capital?","options":["N3,850,000","N12,600,000","N16,450,000","N8,750,000"],"correctOption":3,"section":"Elements and the accounting equation","explanation":"Capital is the balancing figure: assets minus liabilities, N12,600,000 - N3,850,000 = N8,750,000. Adding the unpaid amount to the assets, which gives N16,450,000, treats the liability as if it belonged to the owner."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 114, $official_bank_source${"itemId":"39276038-c471-5a62-b057-694d20c81de5","questionId":"47c6988c-5db8-5807-a24c-42da23d31fa1","sourceKey":"bank:ACC101:A101N1-092","payload":{"prompt":"Bisi's opening capital was N800,000. During the year she introduced a further N150,000, revenue was N900,000, expenses were N620,000 and drawings were N90,000. What is her closing capital?","options":["N1,320,000","N990,000","N1,140,000","N1,230,000"],"correctOption":2,"section":"Elements and the accounting equation","explanation":"Closing capital = 800,000 + 150,000 + (900,000 - 620,000) - 90,000 = N1,140,000. N1,230,000 forgets to deduct the drawings, which reduce the owner's capital."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 115, $official_bank_source${"itemId":"b8aff753-335e-556d-9e3b-7e0851b64f46","questionId":"e471fd76-2875-5ab9-a970-2ac42756d57c","sourceKey":"bank:ACC101:A101N1-093","payload":{"prompt":"A firm in Ikeja has a delivery van of N2,000,000, inventory of N540,000, trade receivables of N410,000, cash of N300,000, trade payables of N360,000 and accrued expenses of N120,000. What is its working capital?","options":["N1,250,000","N770,000","N2,770,000","N1,730,000"],"correctOption":1,"section":"Elements and the accounting equation","explanation":"Current assets are 540,000 + 410,000 + 300,000 = N1,250,000, and current liabilities are 360,000 + 120,000 = N480,000, so working capital is N770,000. Including the van gives N2,770,000, but a van is a non-current asset and does not form part of working capital."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 116, $official_bank_source${"itemId":"ddcf360e-2f9d-5624-a226-136389e62d27","questionId":"8d6b41b7-90e5-5105-87ee-65e0315050e3","sourceKey":"bank:ACC101:A101N1-094","payload":{"prompt":"Which of the following decreases owner's equity?","options":["Revenue earned","Net profit","Capital introduced","Drawings"],"correctOption":3,"section":"Elements and the accounting equation","explanation":"Drawings take resources out of the business for the owner, so they reduce owner's equity, as do expenses and a net loss. Revenue earned does the opposite and increases owner's equity."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 117, $official_bank_source${"itemId":"1ff1c00f-aa62-5c68-be2b-310500292e2f","questionId":"f77eb493-57da-522b-a15c-74c344acd04e","sourceKey":"bank:ACC101:A101N1-095","payload":{"prompt":"A trader in Balogun market has a motor van of N1,800,000, inventory of N650,000, receivables of N220,000, cash of N130,000 and trade payables of N300,000. What are the total assets?","options":["N3,100,000","N1,000,000","N2,800,000","N2,500,000"],"correctOption":2,"section":"Elements and the accounting equation","explanation":"Total assets = non-current assets + current assets = 1,800,000 + (650,000 + 220,000 + 130,000) = N2,800,000. Deducting the trade payables gives N2,500,000, but payables are a liability and do not reduce the total assets figure."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 118, $official_bank_source${"itemId":"97971d26-9a8c-5f21-8615-3399eaf9bd16","questionId":"cc602358-aa69-5360-b406-bc17db5f665e","sourceKey":"bank:ACC101:A101N1-096","payload":{"prompt":"For a business, assets are N4,750,000, expenses N1,300,000, capital N3,000,000 and revenue N2,250,000. Using A + E = C + R + L, what are the liabilities?","options":["N1,750,000","N800,000","N2,700,000","N3,050,000"],"correctOption":1,"section":"Elements and the accounting equation","explanation":"L = (A + E) - (C + R) = (4,750,000 + 1,300,000) - (3,000,000 + 2,250,000) = N800,000. N1,750,000 comes from ignoring revenue and expenses altogether, which leaves out part of both sides of the equation."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 119, $official_bank_source${"itemId":"29e6585a-0fb7-522d-b797-c3237c534dd6","questionId":"4916b0be-27f7-5b60-ae73-f0f6fd730d41","sourceKey":"bank:ACC101:A101N1-097","payload":{"prompt":"A non-current liability is one that","options":["is owed by the business to its owner","has no physical existence at all","is not due for payment within 12 months","is due for payment within the year"],"correctOption":2,"section":"Elements and the accounting equation","explanation":"Non-current liabilities, such as long-term loans and debentures, are not due within 12 months. A liability due within the year is a current liability, such as trade payables or a bank overdraft."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 120, $official_bank_source${"itemId":"f41fcbf9-7bb8-50ce-b7e1-99b3f103a5c6","questionId":"df2862b0-657e-5981-8160-dcad86931fe6","sourceKey":"bank:ACC101:A101N1-098","payload":{"prompt":"A trader buys a delivery van on credit. What is the effect on the accounting equation?","options":["Assets decrease and liabilities increase","Assets increase and capital increases","Assets increase and liabilities increase","Assets and liabilities are unchanged"],"correctOption":2,"section":"Elements and the accounting equation","explanation":"The van is a new asset and the amount owed to the seller is a new liability, so both sides rise by the same amount. Capital does not change, because the owner has put no new money into the business."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 121, $official_bank_source${"itemId":"823b8688-2d5a-5f97-9749-dec40c940976","questionId":"8bbef861-1353-5a81-92c7-a5f9ed35eb6b","sourceKey":"bank:ACC101:ACC-0004","payload":{"prompt":"Motimo introduced N250000 cash into his business on the 1st day of February 2021, the necessary accounting entries are","options":["Debit capital account, credit drawing account","Debit loan account, credit income statement","Debit drawing account, credit cash account","Debit cash account, credit capital account"],"correctOption":3,"section":"Double-entry principles","explanation":"When the owner brings cash into the business, the cash account receives value and is debited, while the capital account records what the business owes the owner and is credited. Option A and option C wrongly involve drawings, which record money taken out of the business, not put in."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 122, $official_bank_source${"itemId":"7eb3d0d7-5f8d-5600-a5d7-7d3b3bf3b5ff","questionId":"4e1ec6ce-808b-55b4-92c9-e919caf6402c","sourceKey":"bank:ACC101:ACC-0013","payload":{"prompt":"Mr. A sold goods to Mr. B, the list price of which is N50,000, on credit allowing 2.5% trade discount and another 5% cash discount for prompt payment by the debtor. What is the amount to be paid by Mr. B after the cash discount?","options":["N48,750","N45,350","N46,312.5","N38,750.5"],"correctOption":2,"section":"Double-entry principles","explanation":"Trade discount comes off first: N50,000 - 2.5% = N48,750 is the invoice amount. Cash discount is then 5% of N48,750 = N2,437.50, so Mr. B pays N48,750 - N2,437.50 = N46,312.50. Option A stops after the trade discount and forgets the cash discount."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 123, $official_bank_source${"itemId":"780257f5-f80b-5b7d-8530-fff122511453","questionId":"3267c88e-6ebd-5163-8237-74071cae6f9c","sourceKey":"bank:ACC101:ACC-0018","payload":{"prompt":"A business sold goods, the list price of which is N50,000, on credit allowing 2.5% trade discount and another 5% cash discount for prompt payment by the debtor. What is the value of the cash discount?","options":["N5,350","N2,437.5","N1,250","N6,312.5"],"correctOption":1,"section":"Double-entry principles","explanation":"Cash discount is worked on the amount after trade discount: N50,000 - 2.5% = N48,750, and 5% of N48,750 = N2,437.50. Option C, N1,250, is the trade discount, not the cash discount."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 124, $official_bank_source${"itemId":"fd2ef11a-3ba1-5337-8e11-8aa658e859c2","questionId":"9be1240b-1c6d-5323-bc4b-052e1f2fa524","sourceKey":"bank:ACC101:ACC-0037","payload":{"prompt":"The principle of double entry in bookkeeping relates to","options":["Income statement items only","Cash transactions only","The items of the statement of financial position only","Every transaction"],"correctOption":3,"section":"Double-entry principles","explanation":"Double entry applies to every transaction: each one has a debit and an equal credit. Options A, B and C wrongly limit it to certain types of transactions or statements."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 125, $official_bank_source${"itemId":"7ba618b5-faaa-5b27-b127-450bd98049ec","questionId":"df7b9c07-dd6a-5fa0-951f-0154c07ef93d","sourceKey":"bank:ACC101:ACC-0142","payload":{"prompt":"What type of entry will increase the normal balances of the general ledger accounts Electricity Expense, Insurance Expense, Interest Expense, and Repairs Expense?","options":["Debit","Credit","Revenue","Expense"],"correctOption":0,"section":"Double-entry principles","explanation":"Expense accounts have normal debit balances, so a debit entry increases electricity, insurance, interest and repairs expense. A credit (Option B) would reduce them, and Options C and D are types of accounts, not types of entry."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 126, $official_bank_source${"itemId":"32d6e610-0ee2-521f-8cc9-16f9d249762c","questionId":"21866793-1b37-56d0-8ae1-018cbcad69c8","sourceKey":"bank:ACC101:ACC-0146","payload":{"prompt":"Liability accounts will normally have ____ balances.","options":["Debit","Nil","Credit","None of the above"],"correctOption":2,"section":"Double-entry principles","explanation":"Liabilities are claims against the business and sit on the right-hand side of the accounting equation, so they normally carry credit balances. A debit balance (Option A) is normal for assets and expenses, not liabilities."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 127, $official_bank_source${"itemId":"0005a985-8e3b-5053-9ca9-b911f5074b70","questionId":"1e65873c-78ec-5434-96a9-411f1a8a7e32","sourceKey":"bank:ACC101:ACC-0149","payload":{"prompt":"What type of entry will increase the normal balance of the general ledger account Service Revenues?","options":["Debit","Credit","Revenue","Equity"],"correctOption":1,"section":"Double-entry principles","explanation":"Service revenues are income, and income accounts have normal credit balances, so a credit entry increases them. A debit (Option A) would reduce revenue, and Options C and D are account types, not types of entry."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 128, $official_bank_source${"itemId":"39643a0f-2e99-5936-9d2a-b8405c30975e","questionId":"41b35768-ed64-588a-a76d-9f0b7f5bd49b","sourceKey":"bank:ACC101:ACC-0169","payload":{"prompt":"The accounting equation should remain in balance because every transaction affects how many accounts?","options":["Only One","Only Two","Two Or More","Only Three"],"correctOption":2,"section":"Double-entry principles","explanation":"Every transaction affects at least two accounts, and some (compound entries) affect three or more, with total debits always equal to total credits - this keeps the equation in balance. Option B, only two, is tempting, but it ignores entries that hit several accounts at once. Option A, only one, would break double entry."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 129, $official_bank_source${"itemId":"514c5acb-dbf3-5c45-b701-685581602fb4","questionId":"0e28df15-b03c-5c96-b83f-bcec592310db","sourceKey":"bank:ACC101:ACC-0178","payload":{"prompt":"Revenue accounts will normally have ____ balances.","options":["Debit","Credit","Net loss","dividends"],"correctOption":1,"section":"Double-entry principles","explanation":"Revenue (income) accounts increase owner's equity, and equity is a credit-side item, so revenue accounts normally have credit balances. A debit balance (Option A) is normal for assets and expenses, and Options C and D are not types of balance."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 130, $official_bank_source${"itemId":"179b5668-e5a9-5d8b-ab96-2fb8328c4d4f","questionId":"14849896-a777-5ee5-9ce5-4e76531556b2","sourceKey":"bank:ACC101:ACC-0183","payload":{"prompt":"When a sale is made on credit, the seller will debit the asset account Accounts","options":["liability","Receivable","Monetary Entity","Full disclosure"],"correctOption":1,"section":"Double-entry principles","explanation":"A credit sale gives the seller the right to collect money later, so it debits the asset account Accounts Receivable (trade receivables) and credits sales. A liability (Option A) is what the business owes, not what it is owed, and Options C and D are not accounts."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 131, $official_bank_source${"itemId":"605ae612-3a98-5d12-b48b-38d704c2bd00","questionId":"b765e186-0b27-598d-9604-794db18c2c8e","sourceKey":"bank:ACC101:ACC-0185","payload":{"prompt":"When a check is written, a cash account should be ____.","options":["Debited","Credited","Current","None of the above"],"correctOption":1,"section":"Double-entry principles","explanation":"Writing a cheque pays money out of the bank, which reduces the cash (bank) asset, so the cash account is credited. Option A, debited, would mean money is coming in, which is the opposite of a payment."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 132, $official_bank_source${"itemId":"db0c4231-0311-55c4-b3c8-605412d077ff","questionId":"4db8d25b-2bde-5e81-8601-88ad2609f3a4","sourceKey":"bank:ACC101:ACC-0199","payload":{"prompt":"Ojukwu purchased a motor vehicle for N1.5m on credit from Biafra Ltd. The double entry recording of this transaction is to","options":["Debit cash and credit Ojukwu","Credit cash and debit Ojukwu","Debit motor vehicle and credit Biafra Ltd","Debit Biafra Ltd and credit motor vehicle"],"correctOption":2,"section":"Double-entry principles","explanation":"Ojukwu receives a motor vehicle, an asset, so the Motor Vehicle account is debited, and Biafra Ltd becomes a creditor, so Biafra Ltd's account is credited. Options A and B involve cash, but no cash changed hands because the purchase was on credit. Option D reverses the correct entry."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 133, $official_bank_source${"itemId":"94f8f88d-f17d-525f-8f3e-22ee6fa340f8","questionId":"4343f1f1-0278-58fe-a399-25dda3a7f049","sourceKey":"bank:ACC101:ACC-0216","payload":{"prompt":"The dual effect of N15,000 cash payment to a creditor is to","options":["Increase cash account and decrease creditors account","Decrease both accounts","Increase creditors account and decrease cash account","Increase both accounts"],"correctOption":1,"section":"Double-entry principles","explanation":"Paying N15,000 cash to a creditor reduces the asset cash by N15,000 and reduces the liability to the creditor by N15,000, so both accounts decrease. Options A and C wrongly have one account increasing, and Option D has both increasing, which would describe buying on credit, not paying a creditor."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 134, $official_bank_source${"itemId":"8b51f525-75ee-5ef1-84bf-1f3c25afed33","questionId":"bab6c0f1-3ea3-5e21-9d23-a49c5bc83544","sourceKey":"bank:ACC101:ACC-0218","payload":{"prompt":"A cash discount is best described as a reduction in the sum paid if payment is made","options":["by cash, not cheque","on due date","within an agreed period","For bulk purchase"],"correctOption":2,"section":"Double-entry principles","explanation":"A cash discount is a reduction given to a debtor for paying within an agreed period, encouraging prompt payment. Option A confuses \"cash\" with the payment method, and Option D describes a trade or quantity discount for bulk buying. Option B is wrong because the discount is for paying early, not simply on the due date."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 135, $official_bank_source${"itemId":"07f30802-c334-567c-8192-93c9e6b2444f","questionId":"c86bb1e0-ac95-5f62-b201-db2edc777fdb","sourceKey":"bank:ACC101:ACC-0225","payload":{"prompt":"Ojuwoye Ltd. was allowed 3.5% trade discount on N1.7m goods bought. The discount and the net amount paid by Ojuwoye Ltd. are","options":["N95,500 and N1,540,600","N59,500 and N1,645,000","N59,500 and N1,640,500","N55,900 and N1,640,500"],"correctOption":2,"section":"Double-entry principles","explanation":"Trade discount = 3.5% x N1,700,000 = N59,500, so the net amount paid = N1,700,000 - N59,500 = N1,640,500. Option B has the right discount but the wrong net figure, while Options A and D swap digits in the discount (N95,500 and N55,900)."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 136, $official_bank_source${"itemId":"389fa7d0-9210-5232-a8c1-d1517cf5a723","questionId":"1d3e9d22-6ece-536c-a95b-ef09b02ae5d0","sourceKey":"bank:ACC101:ACC-0238","payload":{"prompt":"Which of the following is correct of principle of Double Entry System","options":["for every debit entry, there must always be a corresponding debit entry and vice versa","for every credit entry, there must always be a corresponding credit entry and vice versa","for every credit entry, there must always be a corresponding debit entry and vice versa","all of the above"],"correctOption":2,"section":"Double-entry principles","explanation":"The double entry principle says every debit entry must have a corresponding credit entry of equal value, and vice versa. Options A and B pair a debit with a debit or a credit with a credit, which breaks the rule. Because those two are wrong, Option D cannot be right either."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 137, $official_bank_source${"itemId":"6785fcc5-1190-5b5a-9dd4-6c3390fdcca1","questionId":"65ec12a0-b11a-5393-a10c-9d92faacc5f6","sourceKey":"bank:ACC101:ACC-0253","payload":{"prompt":"An entry which reflects both on the debit and credit side of an account is called ___","options":["counter charge","contra entry","invoices","imprest system"],"correctOption":1,"section":"Double-entry principles","explanation":"A contra entry is a transaction that appears on both the debit and credit sides of the cash book, such as cash paid into the bank or cash withdrawn from the bank for office use. Option D, the imprest system, is a method of running petty cash. Invoices (C) are source documents, and a counter charge (A) is not a bookkeeping entry."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 138, $official_bank_source${"itemId":"498b02e3-0c7e-560d-aac8-7892bb6b8ebc","questionId":"9b23e3f7-b27b-55d1-96ce-019b46429486","sourceKey":"bank:ACC101:ACC-0351","payload":{"prompt":"What is the discount given to customers to encourage early settlement of their debts?","options":["Discount received","Trade discount","Cash discount","Provision for discount"],"correctOption":2,"section":"Double-entry principles","explanation":"Cash discount is given to customers who pay early, to encourage prompt settlement; for the seller it is recorded as discount allowed. Option A (discount received) is what the business gets from its own suppliers, and option B (trade discount) is a price reduction given for bulk or trade buying, not for paying early."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 139, $official_bank_source${"itemId":"f4129299-95b9-501d-a497-a3b9c6fe2e2a","questionId":"36a76d90-188a-5c0d-9ce6-474e553707cb","sourceKey":"bank:ACC101:ACC-0355","payload":{"prompt":"Goods were bought by cheque from Graciousness Ltd and a trade discount of N20,000 received. Under the double entry principle, how will the trade discount be posted in the book of account?","options":["DR Trade discount A/c and CR Bank A/c","DR Bank A/c and CR Trade discount","DR Trade discount A/c and CR Graciousness Ltd A/c","None of the Above"],"correctOption":3,"section":"Double-entry principles","explanation":"Trade discount is simply a reduction in the list price shown on the invoice, so it is never posted to any account; only the net amount paid is recorded. That makes options A, B and C wrong, since each one tries to open a trade discount account or credit the supplier for it."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 140, $official_bank_source${"itemId":"c9162f90-040a-5643-b652-675e7d9e05f5","questionId":"67d5f39e-da19-5825-99d4-3ec744aca0ea","sourceKey":"bank:ACC101:ACC-0361","payload":{"prompt":"Ade started business with N100,000 in his bank account, he introduced N25,000 worth of furniture. Paid business N5,600 business expenses and paid N4,300 for his son's school fees from his personal a/c. How much is his business bank balance?","options":["N76,400","N90,100","N94,400","N95,700"],"correctOption":2,"section":"Double-entry principles","explanation":"Only business transactions affect the business bank account: N100,000 - N5,600 expenses = N94,400. The furniture was brought in as an asset, not paid for from the bank, and the school fees were paid from Ade's personal account. Option B (N90,100) wrongly deducts the school fees, which were paid from Ade's personal account."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 141, $official_bank_source${"itemId":"c69db9c0-72a5-509e-a1a4-55ad6e98a3e2","questionId":"8aff101f-db12-5051-a580-8358f0187691","sourceKey":"bank:ACC101:A101N1-099","payload":{"prompt":"Which statement about debit and credit is correct?","options":["They show only the side of an entry; the type of account decides whether it is an increase or a decrease","A debit always means a decrease in an account and a credit always means an increase","Debit entries are used only for asset accounts and credit entries only for liabilities","A debit always means an increase in an account and a credit always means a decrease"],"correctOption":0,"section":"Double-entry principles","explanation":"Debit and credit only describe the direction of an entry, and the nature of the account decides its effect: a debit increases an asset but decreases a liability. Saying a debit always means an increase is wrong for that reason, since a debit to a liability or capital account reduces it."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 142, $official_bank_source${"itemId":"23ea6b71-f4d1-577d-ab32-96e6a968a320","questionId":"5bcc60b3-11b1-5ebe-9de1-1419880f7c5c","sourceKey":"bank:ACC101:A101N1-100","payload":{"prompt":"What is the first step in applying double entry to a transaction?","options":["Decide whether each account increases","Classify each account by its type","Confirm that a transaction has occurred","Identify the two accounts affected"],"correctOption":2,"section":"Double-entry principles","explanation":"Before anything is recorded, you must confirm that a transaction has actually occurred, with at least two parties and a money value. Identifying the two accounts comes second, once you know there is something to record."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 143, $official_bank_source${"itemId":"56105640-cdb9-5156-b13f-6b8caa363ece","questionId":"3c9148a6-3b71-554d-a898-7ceda1b4311e","sourceKey":"bank:ACC101:A101N1-101","payload":{"prompt":"Which is the correct order of steps in applying double entry?","options":["Confirm the transaction, decide increase or decrease, identify the two accounts, classify each account","Confirm the transaction, identify the two accounts, classify each account, decide increase or decrease","Classify each account, confirm the transaction, identify the two accounts, decide increase or decrease","Identify the two accounts, confirm the transaction, decide increase or decrease, classify each account"],"correctOption":1,"section":"Double-entry principles","explanation":"You first confirm that a transaction has occurred, then identify the two accounts, classify each one by type, and finally decide whether each increases or decreases. Deciding increase or decrease before classifying cannot work, because the type of account determines the effect."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 144, $official_bank_source${"itemId":"ceb43d93-2686-5657-bd72-0287d6d45759","questionId":"dd8623ab-fa94-5529-822f-706df9600da8","sourceKey":"bank:ACC101:A101N1-102","payload":{"prompt":"For an event to be treated as a transaction to be recorded in the books, it must","options":["involve only one party and be recorded daily","involve at least two parties and be measurable in money","affect only the owner's capital account","involve cash and be approved by the owner"],"correctOption":1,"section":"Double-entry principles","explanation":"A transaction needs at least two parties, a giver and a receiver, and must be measurable in money. Requiring cash is wrong, because credit sales and purchases are transactions even though no cash changes hands at once."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 145, $official_bank_source${"itemId":"0d86e1b9-cbb9-5ac9-a348-c97b5a531c41","questionId":"fb1dc6d0-c515-589d-868f-0e602c88dc9a","sourceKey":"bank:ACC101:A101N1-103","payload":{"prompt":"Which two types of account normally have debit balances?","options":["Assets and revenue","Liabilities and expenses","Assets and expenses","Capital and revenue"],"correctOption":2,"section":"Double-entry principles","explanation":"Assets and expenses both have a normal debit side and are increased by debits. Revenue is a credit-nature account, like capital and liabilities, so pairing it with assets is wrong."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 146, $official_bank_source${"itemId":"4101bcf9-6a49-5e21-92cf-a89d4876ada3","questionId":"2ebc1eb4-06f3-5701-9d97-b7f4cdee6a73","sourceKey":"bank:ACC101:A101N1-104","payload":{"prompt":"A firm in Ikeja pays wages of N85,000 in cash. The double entry is","options":["Debit capital, credit cash","Debit wages, credit capital","Debit cash, credit wages","Debit wages, credit cash"],"correctOption":3,"section":"Double-entry principles","explanation":"Wages are an expense that increases, so wages is debited, and cash is an asset that decreases, so cash is credited. Debiting cash would mean cash had increased, which is the opposite of paying wages."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 147, $official_bank_source${"itemId":"37ed6adb-a4f1-57cf-8d7a-476c76e2e466","questionId":"9c06e4ab-6820-5e91-81d1-c1501a553012","sourceKey":"bank:ACC101:A101N1-105","payload":{"prompt":"A company in Lagos buys a motor car and pays for it in cash. The correct entries are","options":["Debit motor vehicle, credit cash","Debit purchases, credit cash","Debit cash, credit motor vehicle","Debit motor vehicle, credit capital"],"correctOption":0,"section":"Double-entry principles","explanation":"The motor vehicle account receives a new asset and is debited, while cash leaves the business and is credited. Debiting purchases is wrong, because the car is a non-current asset for use, not goods bought for resale."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 148, $official_bank_source${"itemId":"4d8ceba3-8e17-5f13-8f5d-0a1e0cd26403","questionId":"03e9bf9a-71de-5d0f-a056-199442e6d08e","sourceKey":"bank:ACC101:A101N1-106","payload":{"prompt":"The owner of a shop in Balogun market withdraws money from the business bank account to pay his son's hospital bill. The entry is","options":["Debit bank, credit drawings","Debit medical expenses, credit bank","Debit capital, credit medical expenses","Debit drawings, credit bank"],"correctOption":3,"section":"Double-entry principles","explanation":"Money taken out for the owner's private purposes is drawings, so drawings is debited and bank is credited. Debiting medical expenses would wrongly treat a family bill as a cost of running the shop."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 149, $official_bank_source${"itemId":"eefb09d1-eeb3-533d-b0db-34c9b01153b0","questionId":"7d3c09cf-27c9-5341-8103-831a13b74a03","sourceKey":"bank:ACC101:A101N1-107","payload":{"prompt":"The sole owner of a business in Ikeja pays himself a monthly 'salary' of N200,000 from the business bank account. Which account is debited?","options":["Salaries","Bank","Drawings","Wages"],"correctOption":2,"section":"Double-entry principles","explanation":"A salary paid to the owner himself is treated as drawings, not as a business expense, so drawings is debited. The salaries account is for employees, and the owner is not an employee of his own sole proprietorship."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 150, $official_bank_source${"itemId":"3f7779c1-e59d-55c6-82ec-68bce3341ffa","questionId":"47ffd92e-1692-50e3-88a7-62f0ffe85d8a","sourceKey":"bank:ACC101:A101N1-108","payload":{"prompt":"The owner of a sole trader business pays a dividend he received personally on his own shares into the business bank account. The entry is","options":["Debit bank, credit dividend income","Debit drawings, credit bank","Debit capital, credit bank","Debit bank, credit capital"],"correctOption":3,"section":"Double-entry principles","explanation":"The owner's personal dividend is his own money, so paying it in is capital introduced: bank is debited and capital is credited. Crediting dividend income is wrong, because the business did not earn the dividend."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 151, $official_bank_source${"itemId":"e583d1d0-1258-5c9f-99f6-058784356c15","questionId":"4de45dcf-1dfb-508f-9dc6-b1bb2c07649c","sourceKey":"bank:ACC101:A101N1-109","payload":{"prompt":"In the final accounts of a sole trader, drawings are","options":["added to capital as part of the profit for the year","charged as an operating expense in the income statement","deducted from capital, never charged as an expense in the income statement","shown as a current liability of the business"],"correctOption":2,"section":"Double-entry principles","explanation":"Drawings are debit-nature items, but they reduce the owner's capital and never go to the income statement. Charging them as an operating expense would wrongly reduce the profit of the business."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 152, $official_bank_source${"itemId":"a561ad78-da7a-544c-b6e3-3b83923b5a13","questionId":"d985fe8d-0780-5bc9-a425-f8075ed09dc0","sourceKey":"bank:ACC101:A101N1-110","payload":{"prompt":"Goods bought on credit are returned to the supplier. On which side of the returns outwards account is the return recorded?","options":["Credit side","Debit side","Both sides, as a contra entry","It is not recorded"],"correctOption":0,"section":"Double-entry principles","explanation":"Returns outwards reduce purchases, which are expense-type items, so they are credited. The debit side is wrong, because the debit for this return goes to the supplier's account, which is reduced."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 153, $official_bank_source${"itemId":"ed5acadd-051f-5fc1-ba69-9dc9ca35970a","questionId":"227df7d9-3b53-5eef-a821-29c19cb4c647","sourceKey":"bank:ACC101:A101N1-111","payload":{"prompt":"Discount received is classified as","options":["an asset, and debited","an expense, and debited","revenue, and credited","a liability, and credited"],"correctOption":2,"section":"Double-entry principles","explanation":"Discount received is a gain to the business, so it is treated as revenue and credited. Treating it as an expense confuses it with discount allowed, which the business gives to its customers."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 154, $official_bank_source${"itemId":"270e4951-8994-554a-bec6-dda563564510","questionId":"8539cefa-1793-582c-952e-afb6f1e76ee4","sourceKey":"bank:ACC101:A101N1-112","payload":{"prompt":"Discount allowed to customers is classified as","options":["a reduction of capital, and debited","an expense, and debited","a liability, and credited","revenue, and credited"],"correctOption":1,"section":"Double-entry principles","explanation":"Discount allowed is a cost to the business for early payment by customers, so it is an expense and debited. Treating it as revenue confuses it with discount received, which the business gets from suppliers."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 155, $official_bank_source${"itemId":"81b7ec4c-d51a-582c-af67-bc9f7ab141dd","questionId":"c5fdc748-00f3-5ced-bf5b-b387a2962bf5","sourceKey":"bank:ACC101:A101N1-113","payload":{"prompt":"A trader in Balogun market buys goods with a list price of N84,000 less 7.5% trade discount. At what amount are the purchases recorded in the books?","options":["N90,300","N84,000","N6,300","N77,700"],"correctOption":3,"section":"Double-entry principles","explanation":"Trade discount is deducted at the start and never entered in the books, so purchases are recorded at 84,000 - (7.5% x 84,000) = 84,000 - 6,300 = N77,700. Recording the full N84,000 list price ignores that rule."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 156, $official_bank_source${"itemId":"4bab25b6-7808-5235-8911-474d514c89c0","questionId":"da5b4c8a-afa4-5c58-89af-0c8313be1f45","sourceKey":"bank:ACC101:A101N1-114","payload":{"prompt":"A firm buys goods on credit for N320,000 (after trade discount) and later returns goods worth N20,000. It is allowed a 5% cash discount for prompt payment. What is the cash discount?","options":["N15,000","N1,000","N16,000","N17,000"],"correctOption":0,"section":"Double-entry principles","explanation":"Cash discount is worked out after trade discount and after returns: 5% x (320,000 - 20,000) = 5% x 300,000 = N15,000. N16,000 applies the 5% to the full N320,000, forgetting to remove the returns first."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 157, $official_bank_source${"itemId":"55c10381-dffa-54b0-b431-0122298d049d","questionId":"fd4430d6-5d82-5880-bd8b-1767dbf9967e","sourceKey":"bank:ACC101:A101N1-115","payload":{"prompt":"Goods with a list price of N240,000 are sold on credit to a customer in Ikeja with 10% trade discount and a further 2.5% cash discount for payment within 14 days. If the customer pays within 14 days, how much does he pay?","options":["N216,000","N210,600","N234,000","N210,000"],"correctOption":1,"section":"Double-entry principles","explanation":"Trade discount gives 240,000 x 90% = N216,000, and the cash discount is then 2.5% of that, N5,400, leaving N210,600 to pay. N210,000 comes from adding the two rates and taking 12.5% off the list price, but the cash discount is worked on the amount after trade discount."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 158, $official_bank_source${"itemId":"e6041c2b-23c5-54fb-a172-fe8063c35a92","questionId":"3d6e0029-82d8-5a53-a868-84bb6fffb360","sourceKey":"bank:ACC101:A101N1-116","payload":{"prompt":"When closing off (balancing) an asset account at the end of a period, the 'Balance c/d' is entered on","options":["the debit side in every case","the side with the larger total","the credit side in every case","the side with the smaller total"],"correctOption":3,"section":"Double-entry principles","explanation":"The larger total is written on both sides, and the balance c/d is inserted on the smaller side to make the two sides agree. It then comes down as balance b/d on the opposite side, so writing it on the larger side would not balance the account."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 159, $official_bank_source${"itemId":"2422ff29-826f-5a8e-9605-fc8165df62ba","questionId":"b0778988-7f84-5bf1-9ec7-94318870ed25","sourceKey":"bank:ACC101:A101N1-117","payload":{"prompt":"At the end of the year, revenue and expense accounts are closed off by","options":["carrying down a balance to the next period","a transfer to the profit or loss account","a contra entry in the cash book","a transfer to the trial balance"],"correctOption":1,"section":"Double-entry principles","explanation":"Revenue and expense accounts are closed by transferring their balances to the profit or loss account for the year. Carrying down a balance is how assets, capital and liabilities are closed, because those accounts continue into the next period."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 160, $official_bank_source${"itemId":"ad15adf4-b2c8-5c45-bd7a-9512c25fad6f","questionId":"c394e8ed-4a7a-513c-97a2-77c3eea1e51b","sourceKey":"bank:ACC101:A101N1-118","payload":{"prompt":"A cash discount is called ____ in the seller's books and ____ in the buyer's books.","options":["discount allowed; discount received","discount received; discount allowed","discount received; trade discount","trade discount; cash discount"],"correctOption":0,"section":"Double-entry principles","explanation":"The seller allows the discount to the customer, so it is discount allowed in the seller's books, and the buyer receives it, so it is discount received in the buyer's books. Swapping the two names gets the direction backwards."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 161, $official_bank_source${"itemId":"54a63286-c106-52a6-b7fb-61bff329fb0c","questionId":"5ea10932-e1ca-5d27-9920-b4b3460467aa","sourceKey":"bank:ACC101:ACC-0007","payload":{"prompt":"A gain on disposal of asset is","options":["Debited to bank statement","Credited to income statement","Credited to cash account","Debited to income statement"],"correctOption":1,"section":"Capital and revenue classification","explanation":"A gain on disposal is a form of income, so it is credited to the income statement (statement of profit or loss) to increase profit. Option D would treat it as an expense, and options A and C mix it up with cash or bank records."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 162, $official_bank_source${"itemId":"d3ca0de7-5d22-514d-a191-363e4edf1a29","questionId":"4c1d2fb8-9225-52c8-a9ba-167d4ef18521","sourceKey":"bank:ACC101:ACC-0031","payload":{"prompt":"The expired portion of capital expenditure is","options":["Asset","Expense","Income","Liability"],"correctOption":1,"section":"Capital and revenue classification","explanation":"Capital expenditure buys an asset, and the part of it that has been used up (for example through depreciation) becomes an expense in that period. Option A describes the unexpired portion that is still an asset."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 163, $official_bank_source${"itemId":"ff6a5120-71c8-5f7a-96cc-77d2c7fae795","questionId":"c07ceb70-c349-5442-a3c8-7dfbcaf5f478","sourceKey":"bank:ACC101:ACC-0274","payload":{"prompt":"Payment of teachers salary in a school is an example of ___ expenditure","options":["capital","recurrent","deferred","formative"],"correctOption":1,"section":"Capital and revenue classification","explanation":"Teachers' salaries are paid again and again to keep the school running, so they are recurrent (revenue) expenditure. Capital expenditure (option A) is spending on long-term assets such as buildings and equipment. Deferred (option C) and formative (option D) expenditure do not describe regular running costs."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 164, $official_bank_source${"itemId":"0fa4e5f9-fe24-5110-82b2-9105bd46134e","questionId":"97cbdfea-64d2-5150-a31e-4fbbf3737f4e","sourceKey":"bank:ACC101:ACC-0371","payload":{"prompt":"All the following are examples of a capital expenditure except","options":["N7,000 spent in overhauling an engine which increased its useful life by 30 months","Purchases of a new equipment for the business","Installation of automatic control in the business vehicle","Amount spent to repair a motor vehicle in order to maintain its useful life at the original estimate"],"correctOption":3,"section":"Capital and revenue classification","explanation":"Capital expenditure buys or improves non-current assets beyond their original condition, while spending that only keeps an asset working as originally expected is revenue expenditure. The repair in option D only maintains the vehicle's original useful life, so it is not capital expenditure. Option A extends the engine's life, and options B and C add new assets or features, so they are capital."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 165, $official_bank_source${"itemId":"364e90e4-33ea-5ca9-ab2a-c9e5acf8e1a1","questionId":"f34a33bb-c399-54c8-9def-48b6ab069b70","sourceKey":"bank:ACC101:A101N2-001","payload":{"prompt":"Expenditure that buys or improves a non-current asset, or extends its useful life or capacity, is best described as","options":["Revenue receipt","Capital expenditure","Capital receipt","Revenue expenditure"],"correctOption":1,"section":"Capital and revenue classification","explanation":"Capital expenditure is spending on non-current assets: buying them, improving them, or extending their life or capacity. Revenue expenditure is the tempting alternative, but it covers the day-to-day cost of running the business, not spending that adds to an asset. Capital and revenue receipts are money coming in, not money spent."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 166, $official_bank_source${"itemId":"3a0f90b1-769f-5faf-a1a5-2b244cc09596","questionId":"a3c1fe34-5b54-5b6d-ada9-c4d6fd8fe990","sourceKey":"bank:ACC101:A101N2-002","payload":{"prompt":"Which of the following best describes revenue expenditure?","options":["Money received from the owner, from loans and from selling non-current assets","The cost of buying non-current assets such as land, equipment and vehicles","The day-to-day cost of running the business, including repairs that only keep an asset at its original estimate","Spending on an asset that extends its useful life beyond the original estimate"],"correctOption":2,"section":"Capital and revenue classification","explanation":"Revenue (recurrent) expenditure is the ordinary running cost of the business, and it includes repairs that merely maintain an asset at its original estimate. Spending that extends an asset's useful life beyond that estimate is capital expenditure, even though it may look like a repair. Money received from the owner, loans or asset sales is a capital receipt, not expenditure at all."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 167, $official_bank_source${"itemId":"7953b8de-882d-568e-a163-4ea538f9d58e","questionId":"073340ed-c8e7-51f0-b8fc-9297e7aa3d62","sourceKey":"bank:ACC101:A101N2-003","payload":{"prompt":"Revenue expenditure is also referred to as","options":["Recurrent expenditure","Deferred expenditure","Capital expenditure","Fixed expenditure"],"correctOption":0,"section":"Capital and revenue classification","explanation":"Revenue expenditure is also called recurrent expenditure because it recurs as part of the day-to-day running of the business, like salaries and routine repairs. Capital expenditure is the opposite category, spent on buying or improving non-current assets."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 168, $official_bank_source${"itemId":"332f2abe-c39b-56fc-ad39-c8537deae5bc","questionId":"5915e786-d157-520e-85e3-9dc804a84499","sourceKey":"bank:ACC101:A101N2-004","payload":{"prompt":"A firm in Ikeja buys a new photocopier for use in its office. How should this payment be classified?","options":["Capital receipt","Drawings","Capital expenditure","Revenue expenditure"],"correctOption":2,"section":"Capital and revenue classification","explanation":"The photocopier is equipment bought for use in the business, so it is a non-current asset and the payment is capital expenditure. It would be revenue expenditure only if it were a running cost such as paper or a routine repair. It is not drawings because it is for the business, not the owner's private use."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 169, $official_bank_source${"itemId":"12e1380e-85b5-5397-9830-59bc6bacb741","questionId":"8fd07432-4881-5cea-9271-5a910f0bd46f","sourceKey":"bank:ACC101:A101N2-005","payload":{"prompt":"A logistics company in Apapa installs automatic controls in one of its delivery vehicles. The cost of the installation is","options":["Revenue expenditure, because it is a cost of running the vehicle","A capital receipt, because it increases the value of the vehicle","Revenue expenditure, because the vehicle already exists in the books","Capital expenditure, because it improves the vehicle"],"correctOption":3,"section":"Capital and revenue classification","explanation":"Installing automatic controls improves the vehicle, so the cost is capital expenditure and is added to the asset. The fact that the vehicle was already owned does not make the spending revenue expenditure; what matters is that the asset is improved rather than merely maintained. A capital receipt is money received, not money spent."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 170, $official_bank_source${"itemId":"554ada88-0522-5921-8e3f-bb6d6a49d84a","questionId":"9b07474e-db27-576f-868a-be0d395317a2","sourceKey":"bank:ACC101:A101N2-006","payload":{"prompt":"A transport company in Lagos pays for an engine overhaul on one of its buses, which extends the bus's useful life by 30 months. How should the cost be treated?","options":["As a capital receipt, because the bus will earn income for longer","As revenue expenditure, because an overhaul is a type of repair","As revenue expenditure, because the bus is already a non-current asset","As capital expenditure, because it extends the useful life of the bus"],"correctOption":3,"section":"Capital and revenue classification","explanation":"Spending that extends the useful life of a non-current asset is capital expenditure, and this overhaul adds 30 months to the bus's life. Calling it a repair is the common trap: only repairs that keep an asset at its original estimate are revenue expenditure. A capital receipt is money coming in, not a cost."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 171, $official_bank_source${"itemId":"4c27f9f8-e4c0-5fcc-ae14-b870288f6133","questionId":"fd19dd27-fb2a-5c9d-b98a-62038614ecab","sourceKey":"bank:ACC101:A101N2-007","payload":{"prompt":"A school in Yaba repairs its generator so that it continues working as originally expected, without extending its life. The cost of the repair is","options":["Capital expenditure","Revenue expenditure","Revenue receipt","Capital receipt"],"correctOption":1,"section":"Capital and revenue classification","explanation":"A repair that only maintains an asset at its original estimate is revenue expenditure, charged as a running cost of the period. It would be capital expenditure only if it improved the generator or extended its useful life or capacity. Receipts are money coming in, so neither receipt option fits a repair payment."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 172, $official_bank_source${"itemId":"5f9d7648-ac19-5f91-a0e6-4030946d28d1","questionId":"aef00393-6fcd-550e-97de-748d8eb80ac9","sourceKey":"bank:ACC101:A101N2-008","payload":{"prompt":"A firm in Surulere buys a plot of land on which to build a new warehouse. This purchase is","options":["Recurrent expenditure","Revenue receipt","Revenue expenditure","Capital expenditure"],"correctOption":3,"section":"Capital and revenue classification","explanation":"Buying land for use in the business acquires a non-current asset, so it is capital expenditure. Revenue and recurrent expenditure are the same idea, the day-to-day running costs, so neither fits a one-off purchase of land. A revenue receipt is income such as sales."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 173, $official_bank_source${"itemId":"602d8e1d-0c04-502f-917c-7d430386ac3c","questionId":"7173504f-f57b-5ee7-9813-e183bea7c963","sourceKey":"bank:ACC101:A101N2-009","payload":{"prompt":"A UNILAG department spends money to increase the capacity of its printing machine so that it can print twice as many pages per hour. This spending is","options":["Revenue expenditure, because the machine is used every day","Revenue expenditure, because it keeps the machine at its original estimate","A capital receipt, because the machine becomes more valuable","Capital expenditure, because it increases the capacity of a non-current asset"],"correctOption":3,"section":"Capital and revenue classification","explanation":"Increasing the capacity of a non-current asset is capital expenditure, because the asset ends up better than it was. Revenue expenditure would apply only to running costs or to repairs that keep the machine at its original estimate, which is not the case here. A capital receipt is money received, not spent."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 174, $official_bank_source${"itemId":"bc01b8b6-321c-5312-a950-9f9811baba81","questionId":"f1835ace-795c-557e-9333-e5d14a944031","sourceKey":"bank:ACC101:A101N2-010","payload":{"prompt":"A furniture maker in Ikorodu records several inflows of money during the month. Which of them is a capital receipt?","options":["Cash received from the sale of goods","A loan received from a bank in Lagos","Money received from customers for services rendered","Daily takings from its furniture showroom"],"correctOption":1,"section":"Capital and revenue classification","explanation":"Capital receipts are owner capital, loans and the proceeds from selling non-current assets, so a bank loan is a capital receipt. Cash from selling goods, fees for services and daily shop takings are all sales or operating income, which makes them revenue receipts."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 175, $official_bank_source${"itemId":"0bffc535-561b-53b6-98be-453c27e9e12d","questionId":"ea898ef4-ed50-51ff-a13d-08eb12874be7","sourceKey":"bank:ACC101:A101N2-011","payload":{"prompt":"A trader in Balogun market sells an old delivery van that the business no longer needs. The cash received from the sale is","options":["A revenue receipt","A capital receipt","Revenue expenditure","Capital expenditure"],"correctOption":1,"section":"Capital and revenue classification","explanation":"Proceeds from selling a non-current asset are a capital receipt. It is tempting to call it a revenue receipt because cash comes in, but revenue receipts are sales of trading goods and other operating income, and the van was never trading stock. The two expenditure options describe money going out."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 176, $official_bank_source${"itemId":"6817196d-e055-5c17-ab7e-5c5240d16063","questionId":"3c09e22c-f34c-5307-ba87-024283e5c367","sourceKey":"bank:ACC101:A101N2-012","payload":{"prompt":"The owner of a provisions shop in Mushin pays N500,000 of personal savings into the business as additional capital. For the business, this is","options":["A capital receipt","Revenue expenditure","Other operating income","A revenue receipt"],"correctOption":0,"section":"Capital and revenue classification","explanation":"Money introduced by the owner as capital is a capital receipt. It is not a revenue receipt or operating income, because it does not come from selling goods or from the business's normal operations. Revenue expenditure is a running cost paid out, not money received."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 177, $official_bank_source${"itemId":"980591ab-32a3-5980-92d0-4e01dcf7036c","questionId":"122482a3-0231-56ad-a020-bb91a0cabad2","sourceKey":"bank:ACC101:A101N2-013","payload":{"prompt":"Money flowing into a business can be a capital receipt or a revenue receipt. Which of these inflows is a revenue receipt?","options":["Proceeds from selling an old generator","Sales of goods to customers","Additional capital brought in by the owner","A loan from a microfinance bank"],"correctOption":1,"section":"Capital and revenue classification","explanation":"Revenue receipts are sales and other operating income, so money from selling goods to customers is a revenue receipt. A loan, the proceeds from selling a non-current asset such as a generator, and capital brought in by the owner are all capital receipts."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 178, $official_bank_source${"itemId":"219b05c5-4206-5b8e-999b-231e57876636","questionId":"a604cd4c-a513-5ddf-92a8-be1701615329","sourceKey":"bank:ACC101:A101N2-014","payload":{"prompt":"Owner capital, loans and asset sale proceeds are typical capital receipts. Which item below does NOT belong in that category?","options":["Cash sales of trading goods","Proceeds from selling office furniture no longer needed","Capital introduced by the owner","A long-term loan from a bank"],"correctOption":0,"section":"Capital and revenue classification","explanation":"Cash sales of trading goods are a revenue receipt, because sales are part of operating income. Loans, proceeds from selling non-current assets such as unwanted furniture, and capital introduced by the owner are the three kinds of capital receipt."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 179, $official_bank_source${"itemId":"295e732b-823b-5005-bce9-016aff5ecd13","questionId":"71a7e6e4-8870-5add-ae36-e7a2840e1e38","sourceKey":"bank:ACC101:A101N2-015","payload":{"prompt":"A business wants to list its capital receipts for the year. Which group contains capital receipts and nothing else?","options":["Cash sales, credit sales, proceeds from selling non-current assets","Loans received, cash sales, other operating income","Owner's capital, loans received, cash sales","Owner's capital, loans received, proceeds from selling non-current assets"],"correctOption":3,"section":"Capital and revenue classification","explanation":"Capital receipts are exactly these three: owner capital, loans, and proceeds from selling non-current assets. Each of the other groups slips in sales or operating income, which are revenue receipts, so none of them is made up of capital receipts only."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 180, $official_bank_source${"itemId":"30a027e2-dfdf-5293-ae94-f83adc6d03f8","questionId":"10e0eeec-a695-5e18-8ac8-9383027fcc8f","sourceKey":"bank:ACC101:A101N2-016","payload":{"prompt":"Which pair correctly shows a capital receipt followed by a revenue receipt?","options":["Bank loan received; sales of goods","Sales of goods; other operating income","Proceeds from sale of old machine; owner's additional capital","Sales of goods; bank loan received"],"correctOption":0,"section":"Capital and revenue classification","explanation":"A bank loan is a capital receipt and sales of goods are a revenue receipt, so this pair is in the right order. Putting sales first reverses the order. The pair of old machine proceeds and owner's capital is two capital receipts, while sales and operating income are two revenue receipts."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 181, $official_bank_source${"itemId":"fca3d057-37d7-5904-bf40-1876b95fd913","questionId":"2329a2bf-9789-5238-88ae-7c6e4826a367","sourceKey":"bank:ACC101:A101N2-017","payload":{"prompt":"Which of the following is a revenue expenditure for a supermarket in Lekki?","options":["Purchase of a delivery van","Purchase of new shelving for the shop","Installation of a new cold room","Salaries of the shop attendants"],"correctOption":3,"section":"Capital and revenue classification","explanation":"Salaries are part of the day-to-day cost of running the business, so they are revenue (recurrent) expenditure. Shelving, a cold room and a delivery van are all non-current assets bought for long-term use, which makes them capital expenditure."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 182, $official_bank_source${"itemId":"b9cd8648-785c-58f6-acef-b2ad397b117e","questionId":"bed2f22a-fad1-5aac-a044-84ab973359ce","sourceKey":"bank:ACC101:A101N2-018","payload":{"prompt":"Which statement best explains the difference between capital expenditure and revenue expenditure?","options":["Capital expenditure covers the day-to-day running costs, while revenue expenditure buys non-current assets","Capital expenditure buys or improves non-current assets, while revenue expenditure covers the day-to-day running costs","Capital expenditure is money received from owners, while revenue expenditure is money received from customers","Capital expenditure is paid in cash, while revenue expenditure is paid by cheque"],"correctOption":1,"section":"Capital and revenue classification","explanation":"The distinction rests on what the spending is for: capital expenditure buys, improves or extends non-current assets, while revenue expenditure meets the ordinary running costs of the business. The reversed statement swaps the two definitions. The method of payment, cash or cheque, has nothing to do with the classification."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 183, $official_bank_source${"itemId":"eac3d466-0507-5568-a072-2ce0b599d54e","questionId":"8f0c7bb1-0688-568c-8dd0-51fb6d14051f","sourceKey":"bank:ACC101:A101N2-019","payload":{"prompt":"When part of the cost of a machine is charged to the income statement each year as depreciation, which accounting concept is being applied?","options":["Matching concept","Materiality concept","Business entity concept","Money measurement concept"],"correctOption":0,"section":"Capital and revenue classification","explanation":"Depreciation charges the expired portion of capital expenditure as an expense, so that the cost of the machine is matched against the revenue it helps to earn each year. The business entity concept is about separating the business from its owner, and money measurement only says items must be measurable in money, so neither explains spreading the cost."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 184, $official_bank_source${"itemId":"5d7ce90c-474b-54c4-9447-c725d94e2d43","questionId":"925ee32c-1880-5a08-a1a5-0e93f41fcdaa","sourceKey":"bank:ACC101:A101N2-020","payload":{"prompt":"The expired portion of capital expenditure that is charged as an expense each period is known as","options":["Drawings","Depreciation","Prepayment","Accrued expense"],"correctOption":1,"section":"Capital and revenue classification","explanation":"Depreciation is the part of a non-current asset's cost that has been used up and is charged as an expense of the period. A prepayment is an expense paid in advance and an accrued expense is one incurred but not yet paid; neither relates to using up a non-current asset. Drawings are amounts the owner takes out for private use."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 185, $official_bank_source${"itemId":"640ee706-6088-59fd-b1b0-f2d170fe45a9","questionId":"f9fbd360-ff1a-5cbd-8f24-8b0fbf114657","sourceKey":"bank:ACC101:A101N2-022","payload":{"prompt":"A Lagos transport company spends money on its bus engine, which extends the bus's useful life by 30 months. In the ledger, the cost is best","options":["Charged to the income statement as a repair expense","Added to the cost of the bus in the non-current asset account","Credited to the bus account as a reduction in its cost","Treated as drawings by the owner"],"correctOption":1,"section":"Capital and revenue classification","explanation":"Because the work extends the bus's useful life, it is capital expenditure and is added to the cost of the asset. Charging it to the income statement would treat it as an ordinary repair, which is right only for repairs that keep the asset at its original estimate. Crediting the bus account would reduce the asset, and drawings are for the owner's private use."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 186, $official_bank_source${"itemId":"d345ac63-5bcb-5ef8-81c7-3cf48630c16b","questionId":"d2fb71d3-3d64-5417-bf22-ff8883513ff7","sourceKey":"bank:ACC101:A101N2-023","payload":{"prompt":"A firm in Ikeja pays to repair a machine so that it keeps working at its original estimate. Where should the cost be charged?","options":["To the income statement as an expense of the period","To the machine account as part of its cost","To the statement of financial position as a non-current asset","To the owner's capital account as drawings"],"correctOption":0,"section":"Capital and revenue classification","explanation":"A repair that only maintains the machine at its original estimate is revenue expenditure, so it is charged to the income statement for the period. Adding it to the machine account or showing it as a non-current asset would treat it as capital expenditure, which is only correct when the asset is improved or its life is extended."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 187, $official_bank_source${"itemId":"1c1671b2-77bf-54ae-8b85-b976f8a43b2c","questionId":"d6b6531f-f4be-5d5a-b57f-69379e2f145a","sourceKey":"bank:ACC101:A101N2-024","payload":{"prompt":"A firm in Ikeja spends the following: new machine N800,000; transport of the new machine N20,000; installation of the new machine N30,000; repair of an old machine to keep it at its original estimate N15,000; staff salaries N100,000. What is the total capital expenditure?","options":["N865,000","N965,000","N800,000","N850,000"],"correctOption":3,"section":"Capital and revenue classification","explanation":"Capital expenditure includes the full cost of getting the new machine ready for use: 800,000 + 20,000 + 30,000 = N850,000. Taking only the N800,000 price leaves out transport and installation, which are part of the asset's cost. N865,000 wrongly adds the maintenance repair, which is revenue expenditure, and N965,000 also adds the salaries."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 188, $official_bank_source${"itemId":"7259e151-f7d7-5732-91e1-342ea34412ba","questionId":"2c991251-d21e-505e-be8f-71788e471482","sourceKey":"bank:ACC101:A101N2-025","payload":{"prompt":"During the month, a business received: cash sales N900,000; a bank loan N500,000; proceeds from selling an old van N300,000; additional capital from the owner N400,000. What is the total of capital receipts?","options":["N1,200,000","N900,000","N800,000","N2,100,000"],"correctOption":0,"section":"Capital and revenue classification","explanation":"Capital receipts are the loan, the van proceeds and the owner's capital: 500,000 + 300,000 + 400,000 = N1,200,000. N2,100,000 wrongly includes the cash sales, which are a revenue receipt. N800,000 forgets the owner's capital, and N900,000 is just the sales figure."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 189, $official_bank_source${"itemId":"1249ca12-ebcb-5b50-9742-c77316798e7f","questionId":"10e7125d-47ac-534e-b7c5-64c08f5dd53c","sourceKey":"bank:ACC101:A101N2-026","payload":{"prompt":"A business pays: salaries N150,000; repairs to keep equipment at its original estimate N40,000; a new delivery vehicle N2,000,000; installation of automatic controls in the vehicle N120,000; electricity N25,000. What is the total revenue expenditure?","options":["N2,120,000","N215,000","N335,000","N175,000"],"correctOption":1,"section":"Capital and revenue classification","explanation":"Revenue expenditure is the day-to-day running cost: salaries, maintenance repairs and electricity, 150,000 + 40,000 + 25,000 = N215,000. N335,000 wrongly includes the automatic controls, which improve the vehicle and are capital expenditure. N175,000 leaves out the maintenance repairs, and N2,120,000 is the capital expenditure total."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 190, $official_bank_source${"itemId":"4ab0559f-1660-527d-9de9-137d9b34284f","questionId":"d3b4d3d1-2988-5e0e-8ba7-590d7baacf55","sourceKey":"bank:ACC101:A101N2-027","payload":{"prompt":"A haulage firm in Kano made four payments this month. Which one should NOT be treated as capital expenditure?","options":["Installing automatic controls in a vehicle","Buying a new generator for the factory","Paying for routine repairs that keep a vehicle at its original estimate","Overhauling an engine so that it lasts 30 months longer"],"correctOption":2,"section":"Capital and revenue classification","explanation":"Routine repairs that only maintain an asset at its original estimate are revenue expenditure. Buying a generator acquires a non-current asset, installing automatic controls improves one, and an overhaul that adds 30 months extends its life, so all three are capital expenditure."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 191, $official_bank_source${"itemId":"2760d514-f3ad-50e2-ad9a-7787a74d6147","questionId":"da775a6c-7b2b-50cc-9963-8f3d0242b700","sourceKey":"bank:ACC101:A101N2-028","payload":{"prompt":"Money received from the owner as capital, from loans, and from selling non-current assets is collectively known as","options":["Revenue receipts","Capital receipts","Capital expenditure","Operating income"],"correctOption":1,"section":"Capital and revenue classification","explanation":"These three inflows are the capital receipts of a business. Revenue receipts and operating income are the sales and other income earned from normal trading, which these are not. Capital expenditure is money spent on non-current assets, not money received."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 192, $official_bank_source${"itemId":"1d1406da-b1fb-51de-832d-583f380f90ce","questionId":"04da9a4f-c9f7-583d-8308-81ed6d0dedb6","sourceKey":"bank:ACC101:A101N2-029","payload":{"prompt":"Sales and other operating income of a business are classified as","options":["Capital expenditure","Revenue receipts","Revenue expenditure","Capital receipts"],"correctOption":1,"section":"Capital and revenue classification","explanation":"Revenue receipts are the sales and other income earned from the business's normal operations. Capital receipts are owner capital, loans and proceeds from selling non-current assets. The two expenditure options are money spent, not money earned."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 193, $official_bank_source${"itemId":"46aa815b-126f-5e12-9b36-4239f5e5ddf5","questionId":"c4a11ed3-8017-5080-8bdd-b602a5e76d82","sourceKey":"bank:ACC101:ACC-0002","payload":{"prompt":"Which of the following is a necessary condition for a change in accounting method overriding the consistency concept?","options":["The effects of such change on reported profits should not be communicated","The users of the financial statement should be informed of the change","The changes should be made for the purpose of profit manipulation","The changes should be made frequently"],"correctOption":1,"section":"Accounting concepts, conventions and limitations","explanation":"A business may change an accounting method only when the change gives a fairer view, and users of the financial statements must be told about the change and its effect. Option A is the opposite of what is required, while options C and D describe profit manipulation and frequent changes, which are exactly what the consistency concept is meant to prevent."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 194, $official_bank_source${"itemId":"ff25a9ee-5a46-5d2e-9d77-89ec8c8fba70","questionId":"795196ab-d736-5ac8-bb87-137e19b3de2e","sourceKey":"bank:ACC101:ACC-0003","payload":{"prompt":"Depreciation follows which accounting concept","options":["Historical cost concept","Money measurement concept","Going concern concept","Matching concept"],"correctOption":3,"section":"Accounting concepts, conventions and limitations","explanation":"Depreciation spreads the cost of a non-current asset over the periods that benefit from using it, so each period's revenue carries a fair share of that cost - this is the matching concept. Option A is tempting because depreciation starts from the asset's cost, but the reason it is charged every year is to match cost against the revenue it helps to earn."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 195, $official_bank_source${"itemId":"a99fa0f7-4989-5e0b-9579-264e1f38f9a2","questionId":"5faa5637-93b9-5a06-a8e8-ebb31eadbc81","sourceKey":"bank:ACC101:ACC-0011","payload":{"prompt":"Which of the following accounting concepts is violated by the inclusion of private assets in the balance sheet of a business by its owner?","options":["Matching","Materiality","Entity","Consistency"],"correctOption":2,"section":"Accounting concepts, conventions and limitations","explanation":"The entity concept treats the business as separate from its owner, so the owner's private assets must not appear in the business balance sheet. Option B, materiality, is about whether an item is big enough to matter, and option D, consistency, is about using the same methods each year - neither is broken here."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 196, $official_bank_source${"itemId":"33cc3af0-c0c8-50a8-b9ba-ac5930089d2b","questionId":"c1c74f10-70f6-5ace-8d95-f808d2bf4c5d","sourceKey":"bank:ACC101:ACC-0028","payload":{"prompt":"Which of the following is an implication of the entity concept to a sole trader?","options":["Liability of the owner is limited","Private use of business assets increases owners capital","Business can sue and be sued separately","Private use of business assets reduces owners capital"],"correctOption":3,"section":"Accounting concepts, conventions and limitations","explanation":"Under the entity concept the business is separate from the owner, so when the owner uses business assets privately it is treated as drawings, which reduces the owner's capital. Option B gets the direction wrong, and options A and C describe features of a limited company, not a sole trader."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 197, $official_bank_source${"itemId":"a7928fb9-0dce-5653-b54a-c23775882914","questionId":"9a6ba6c5-4b94-5e4b-ac23-6c3df5a75316","sourceKey":"bank:ACC101:ACC-0139","payload":{"prompt":"Accountants might recognize losses but not gains in certain situations. For example, the company might write-down the cost of inventory, but will not write-up the cost of inventory. Which principle/guideline is associated with this action?","options":["Monetary Unit","Materiality","Conservatism","Retained earnings"],"correctOption":2,"section":"Accounting concepts, conventions and limitations","explanation":"Conservatism (prudence) says losses should be recognised as soon as they are expected but gains only when they are realised, which is why inventory is written down but never written up above cost. Materiality (Option B) is about whether an amount is big enough to matter, and the monetary unit idea (Option A) is about measuring in money."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 198, $official_bank_source${"itemId":"3cc70f59-3d12-5326-9643-dfe24929a152","questionId":"7ee9704b-b721-5287-b018-579ce3b9c5ff","sourceKey":"bank:ACC101:ACC-0141","payload":{"prompt":"Which principle/guideline requires the company's financial statements to have footnotes containing information that is important to users of the financial statements?","options":["Full Disclosure","Economic Entity","Conservatism","Receivable"],"correctOption":0,"section":"Accounting concepts, conventions and limitations","explanation":"The full disclosure principle requires financial statements to include all information that would matter to users, often given in notes (footnotes) to the accounts. The economic entity idea (Option B) keeps business and owner separate, and conservatism (Option C) is about being cautious with gains and losses."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 199, $official_bank_source${"itemId":"32a95a93-62f3-5408-922d-44bab1ed4db2","questionId":"7542016d-d306-507c-a6f1-24f661c662d4","sourceKey":"bank:ACC101:ACC-0147","payload":{"prompt":"Which principle/guideline justifies a company violating an accounting principle because the amounts are immaterial?","options":["Conservatism","Full Disclosure","Reconciliation","Materiality"],"correctOption":3,"section":"Accounting concepts, conventions and limitations","explanation":"The materiality concept allows a business to ignore strict accounting treatment for amounts that are too small to influence users' decisions. Conservatism (Option A) is about caution with gains and losses, full disclosure (Option B) asks for more information rather than less, and reconciliation (Option C) is not an accounting principle."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 200, $official_bank_source${"itemId":"7622c31c-48ff-561d-80de-affc3679d502","questionId":"59b8b489-0f82-5fbf-aff8-aeded3d14b84","sourceKey":"bank:ACC101:ACC-0152","payload":{"prompt":"The creative chief executive of a corporation who is personally responsible for numerous inventions and innovations is not reported as an asset on the corporation's balance sheet. The accounting principle/guideline that prevents the corporation for reporting this person as an asset is","options":["Conservatism","Cost","Going Concerns","Matching"],"correctOption":1,"section":"Accounting concepts, conventions and limitations","explanation":"Under the cost principle, items are recorded at the amount actually paid in a transaction; the business never paid a measurable price to acquire the chief executive's talent, so it cannot be shown as an asset. Conservatism (option A) is about caution with gains and losses, going concern (option C) assumes the business will continue, and matching (option D) links expenses to revenues."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 201, $official_bank_source${"itemId":"af1b2de2-895b-506a-8341-e96a259514e8","questionId":"5d77559c-0b1d-5a68-b4e3-7690000d5d0d","sourceKey":"bank:ACC101:ACC-0157","payload":{"prompt":"Which principle/guideline directs a company to show all the expenses related to its revenues of a specified period even if the expenses were not paid in that period?","options":["Monetary Unit","Matching","Cost","Going concern"],"correctOption":1,"section":"Accounting concepts, conventions and limitations","explanation":"The matching principle requires expenses to be recorded in the same period as the revenues they helped earn, whether or not they have been paid. Going concern (Option D) assumes the business will continue, and the cost and monetary unit ideas (Options C and A) are about measurement."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 202, $official_bank_source${"itemId":"af9899d1-5a1a-5536-8b08-b5566de3835f","questionId":"d8b61d1f-a643-5665-8c67-6d806f9e8ec1","sourceKey":"bank:ACC101:ACC-0158","payload":{"prompt":"The personal assets of the owner of a company will not appear on the company's balance sheet because of which principle/guideline?","options":["Cost","Economic Entity","Monetary Unit","Net loss"],"correctOption":1,"section":"Accounting concepts, conventions and limitations","explanation":"The economic entity (business entity) concept treats the business as separate from its owner, so the owner's personal assets are not shown on the business's balance sheet. The cost principle (Option A) and monetary unit idea (Option C) concern how items are measured, not whose items they are."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 203, $official_bank_source${"itemId":"291e45ad-17f7-5338-b593-ffd587bbbb65","questionId":"2ef5b8e1-71ad-5b7b-8381-0f58263af8d5","sourceKey":"bank:ACC101:ACC-0159","payload":{"prompt":"A very large corporation's financial statements have the dollar amounts rounded to the nearest $1,000. Which accounting principle/guideline justifies not reporting the amounts to the penny?","options":["Monetary Unit","Materiality","Full Disclosure","Economic Entity"],"correctOption":1,"section":"Accounting concepts, conventions and limitations","explanation":"Rounding to the nearest $1,000 is acceptable because such small differences would not affect the decisions of users of a very large company's statements - this is materiality. The monetary unit concept (Option A) only says items are measured in money, and full disclosure (Option C) is about including important information."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 204, $official_bank_source${"itemId":"ef907bbb-fb2d-5690-a8cc-baa8f43a5ee1","questionId":"e4836c1d-b015-571e-802a-3750d33bcdc6","sourceKey":"bank:ACC101:ACC-0160","payload":{"prompt":"A company borrowed $100,000 in December and will make its only payment for interest when the note comes due six months later. The total interest for the six months will be $3,600. On the December income statement the accountant reported Interest Expense of $600. This action was the result of which accounting principle/guideline?","options":["Cost","Matching","Revenue Recognition","Equity"],"correctOption":1,"section":"Accounting concepts, conventions and limitations","explanation":"One month's interest ($3,600 / 6 = $600) relates to December, so it is recorded as December's expense even though it will be paid later - this is the matching principle. Revenue recognition (Option C) deals with when income is recorded, not expenses, and cost (Option A) concerns the amount recorded for assets."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 205, $official_bank_source${"itemId":"255181b3-7f04-54d8-b0aa-672f01664b15","questionId":"f7a2dcdc-b632-5f7c-8866-90223ad30a2b","sourceKey":"bank:ACC101:ACC-0161","payload":{"prompt":"A company sold merchandise of $8,000 to a customer in December. The company's sales terms require the customer to pay the company in 30 days. The company's income statement reported the sale in December. This is proper under which accounting principle/guideline?","options":["Full Disclosure","Monetary Unit","Revenue Recognition","Matching"],"correctOption":2,"section":"Accounting concepts, conventions and limitations","explanation":"Revenue recognition says revenue is recorded when it is earned, which here is when the goods were sold in December, not when cash is received. Matching (Option D) is about recording expenses in the same period as related revenues, and full disclosure (Option A) is about notes and information."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 206, $official_bank_source${"itemId":"6efa4193-1ee7-5639-80e3-85a81a7de0fe","questionId":"697a4dfb-1d71-5f65-8ee1-5cb67b27959f","sourceKey":"bank:ACC101:ACC-0162","payload":{"prompt":"When the accountant has to choose between two acceptable alternatives, the accountant should select the alternative that will report less profit, less asset amount, or a greater liability amount. This is based upon which principle/guideline?","options":["Conservatism","Cost","Materiality","Profit and loss"],"correctOption":0,"section":"Accounting concepts, conventions and limitations","explanation":"Conservatism (prudence) means that when two methods are acceptable, the accountant chooses the one that gives the lower profit or asset figure or the higher liability, to avoid overstating the business's position. Materiality (Option C) is about the size of an item, and cost (Option B) concerns recording items at what was paid."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 207, $official_bank_source${"itemId":"6456bbb2-209c-5a93-95e1-54a59cd79ed0","questionId":"27d88e04-f6fe-5393-a2f7-2ed2e10a3de8","sourceKey":"bank:ACC101:ACC-0167","payload":{"prompt":"An asset with a cost of $120,000 is depreciated over its useful life of 10 years rather than expensing the entire amount when it is purchased. This complies with which principle/guideline?","options":["Cost","Revenue Recognition","Full Disclosure","Matching"],"correctOption":3,"section":"Accounting concepts, conventions and limitations","explanation":"Depreciating the $120,000 asset over 10 years ($120,000 / 10 = $12,000 a year with no residual value) spreads its cost over the periods that benefit from using it, which is the matching principle. The cost principle (Option A) decides the $120,000 recorded, not how it is spread, and revenue recognition (Option B) concerns income."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 208, $official_bank_source${"itemId":"8a62aa59-1613-5a02-ac4a-13c5d0298f02","questionId":"91cb42da-7c09-5356-bb92-d17c2842bc2d","sourceKey":"bank:ACC101:ACC-0168","payload":{"prompt":"A corporation pays its annual property tax bill of approximately $12,000 in one payment each December 28. During the year, the corporation's monthly income statements report Property Tax Expense of $1,000. This is an example of which accounting principle/guideline?","options":["Conservatism","Matching","Monetary Unit","Going Concerns"],"correctOption":1,"section":"Accounting concepts, conventions and limitations","explanation":"Charging $12,000 / 12 = $1,000 of property tax to each month spreads the expense over the periods it relates to, even though it is paid once a year - that is matching. Conservatism (Option A) is about caution, and going concern (Option D) assumes the business will continue."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 209, $official_bank_source${"itemId":"55302dde-23d4-56ae-be1d-5b449bd6dcda","questionId":"fcc817f1-169f-51b3-bffb-3cb02ccc6baa","sourceKey":"bank:ACC101:ACC-0171","payload":{"prompt":"A large company purchases a $250 digital camera and expenses it immediately instead of recording it as an asset and depreciating it over its useful life. This practice may be acceptable because of which principle/guideline?","options":["Cost","Matching","Materiality","Conservatism"],"correctOption":2,"section":"Accounting concepts, conventions and limitations","explanation":"A $250 camera is so small compared with a large company's totals that expensing it immediately will not mislead anyone, so materiality allows it. Option B, matching, would actually require the camera to be capitalised and depreciated over its useful life. Conservatism (Option D) is about caution with gains and losses rather than ignoring small amounts."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 210, $official_bank_source${"itemId":"fa9be84f-5539-51d5-8231-30e639be3ee2","questionId":"ba1cdfd8-1b05-5575-8217-e01f5ff43f8a","sourceKey":"bank:ACC101:ACC-0172","payload":{"prompt":"A retailer wishes to report its merchandise inventory on its balance sheet at its retail value. This would violate which accounting principle/guideline?","options":["Cost","Full Disclosure","Monetary Unit","Materiality"],"correctOption":0,"section":"Accounting concepts, conventions and limitations","explanation":"The cost principle says inventory and other assets are recorded at what the business paid, not at their selling (retail) price, so reporting inventory at retail value breaks it. Full disclosure (Option B) is about notes and information, and materiality (Option D) is about the size of items."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 211, $official_bank_source${"itemId":"e6f26220-0794-5e28-9052-5c9507d439e5","questionId":"4c5fed1c-8e58-5044-a4bb-e1e72d9fc8c4","sourceKey":"bank:ACC101:ACC-0173","payload":{"prompt":"Near the end of the current year, a company required a customer to pay $200,000 as a deposit for work that is to begin in the following year. At the end of the current year the company reported the $200,000 as a liability on its balance sheet. Which accounting principle/guideline prevented the company from reporting the $200,000 on its income statement for the current year?","options":["Going Concern","Materiality","Revenue Recognition","Full Disclosure"],"correctOption":2,"section":"Accounting concepts, conventions and limitations","explanation":"Revenue recognition says income is recorded only when it is earned; the work starts next year, so the $200,000 deposit is unearned and shown as a liability. Going concern (Option A) assumes the business will continue, and full disclosure (Option D) concerns notes, not when revenue is recorded."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 212, $official_bank_source${"itemId":"3c9059ed-1bc6-5924-8d1f-99a1b421a101","questionId":"18f9057c-20ee-514b-b464-60b982891162","sourceKey":"bank:ACC101:ACC-0175","payload":{"prompt":"Which principle/guideline is associated with the assumption that the company will continue on long enough to carry out its objectives and commitments?","options":["Economic Entity","Matching","Time Period","Going Concern"],"correctOption":3,"section":"Accounting concepts, conventions and limitations","explanation":"The going concern concept assumes the business will continue operating long enough to carry out its objectives and commitments, which is why assets are carried at cost rather than at what they would fetch if sold off. The time period idea (Option C) divides the business life into periods, and economic entity (Option A) separates business from owner."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 213, $official_bank_source${"itemId":"da58163b-55d3-5b8a-8528-7624ab68e7b0","questionId":"c9554a04-fe7f-5ed4-a52f-92415620a4b9","sourceKey":"bank:ACC101:ACC-0177","payload":{"prompt":"Accrual accounting is based on this principle/guideline.","options":["Cost","Full Disclosure","Matching","Monetary Unit"],"correctOption":2,"section":"Accounting concepts, conventions and limitations","explanation":"Accrual accounting records expenses in the period they help earn revenue, whether or not cash has changed hands - this is the matching principle. Cost (Option A) and monetary unit (Option D) are about measurement, and full disclosure (Option B) is about giving enough information."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 214, $official_bank_source${"itemId":"6e7e3880-7ac2-5895-9939-f17f2ad5de01","questionId":"7c72bde5-fc48-53b3-8f82-a5ecaaa46df6","sourceKey":"bank:ACC101:ACC-0179","payload":{"prompt":"Which principle/guideline allows a company to ignore the change in the purchasing power of the dollar over time?","options":["Cost","Economic Entity","Monetary Unit","Retained earnings"],"correctOption":2,"section":"Accounting concepts, conventions and limitations","explanation":"The monetary unit concept assumes money keeps a stable value, so accounts are kept in money terms without adjusting for changes in purchasing power (inflation). Cost (Option A) records items at what was paid, and economic entity (Option B) separates the business from its owner."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 215, $official_bank_source${"itemId":"e740f173-7d15-523b-9bfc-953f7e5b47a4","questionId":"7c4cafe2-194c-5713-ba04-d4060e5786e5","sourceKey":"bank:ACC101:ACC-0180","payload":{"prompt":"Public utilities' balance sheets list the plant assets before the current assets. This is acceptable under which accounting principle/guideline?","options":["Conservatism","Cost","Materiality","Industry Practices"],"correctOption":3,"section":"Accounting concepts, conventions and limitations","explanation":"Industry practices allow an industry to depart from the usual presentation when its special nature makes another approach more useful, as with public utilities listing plant assets first. Materiality (Option C) is about small amounts, and conservatism (Option A) is about caution, so neither explains this presentation."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 216, $official_bank_source${"itemId":"18ff78c3-d708-5db2-80c8-d8e400c6f15c","questionId":"33d10da5-c114-549b-85a2-d638cc5df734","sourceKey":"bank:ACC101:ACC-0186","payload":{"prompt":"Which principle/guideline requires a company's balance sheet to report its land at the amount the company paid to acquire the land, even if the land could be sold today at a significantly higher amount?","options":["Economic Entity","Cost","Monetary Unit","Full disclosure"],"correctOption":1,"section":"Accounting concepts, conventions and limitations","explanation":"Under the cost (historical cost) principle, assets such as land are recorded at the amount paid to acquire them, even if their market value later rises. The monetary unit idea (Option C) says items are measured in money, and full disclosure (Option D) concerns giving extra information in notes."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 217, $official_bank_source${"itemId":"c94e380e-627f-5f64-8bdb-f34b65c4ba18","questionId":"e762a5d9-6262-51ba-b911-45f87a6bf409","sourceKey":"bank:ACC101:ACC-0187","payload":{"prompt":"Large corporations should report revenues on their income statements when the","options":["Cash Is Received","Monetary Entity","Retained earnings","Revenues Are Earned"],"correctOption":3,"section":"Accounting concepts, conventions and limitations","explanation":"Under accrual accounting and the revenue recognition principle, revenue is reported when it is earned, for example when goods are delivered or services performed. Option A, when cash is received, describes cash basis accounting, which large corporations do not use for their income statements."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 218, $official_bank_source${"itemId":"c6e2ee95-ba42-528c-8236-f7c2a37fed1d","questionId":"f7f6f9f6-ddf3-5375-91f6-7cd2f5f4f623","sourceKey":"bank:ACC101:ACC-0188","payload":{"prompt":"Consistency concept does not imply one of the following.","options":["Possibility of comparing financial statements over time","Treatment of like items in a similar manner","All companies in the same industry should use the same methods","Effect of changes in the adopted method is properly disclosed"],"correctOption":2,"section":"Accounting concepts, conventions and limitations","explanation":"The consistency concept means the same business should treat similar items the same way from year to year, so its statements can be compared over time, and any change in method must be disclosed. It does not require different companies in the same industry to use the same methods, which is why Option C is the exception. Options A, B and D are all part of what consistency means."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 219, $official_bank_source${"itemId":"b5bed28d-db26-5618-9137-b20f96cfc554","questionId":"9a330eb6-6b71-5762-a822-179c5b75ed32","sourceKey":"bank:ACC101:ACC-0194","payload":{"prompt":"The basic points of agreement on which financial accounting theory and practice is founded is termed","options":["Accounting slogan","Accounting theory","Accounting concepts","Accounting software"],"correctOption":2,"section":"Accounting concepts, conventions and limitations","explanation":"Accounting concepts are the basic assumptions or points of agreement - such as going concern, accruals and consistency - on which accounting theory and practice are built. Option B, accounting theory, is the body of reasoning that is built on those concepts rather than the basic points themselves."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 220, $official_bank_source${"itemId":"8b4dffde-6bec-596c-8f5d-b79789ff83cb","questionId":"02776999-e178-5cc2-9e7c-b2d063314e0f","sourceKey":"bank:ACC101:ACC-0195","payload":{"prompt":"One of the following is not a limitation of Accounting","options":["It lacks qualitative analysis.","It is not free from bias.","It ignores changes in price levels.","It provides a permanent record of business transactions."],"correctOption":3,"section":"Accounting concepts, conventions and limitations","explanation":"Keeping a permanent, organised record of transactions is one of the main benefits of accounting, so it is not a limitation. Option C is a real limitation, because figures are kept at historical cost and do not reflect inflation, just as options A and B are: accounting shows only quantitative information and leaves room for bias in estimates and judgements."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 221, $official_bank_source${"itemId":"6318e1e5-7a92-57d8-ba28-9262ee8bc73a","questionId":"b8101ffa-1e64-5cf1-98a7-74c4497b8240","sourceKey":"bank:ACC101:ACC-0197","payload":{"prompt":"The rule to recognise revenue when it is reasonably certain and recognise expenses as soon as they are reasonably possible is known as","options":["Materiality","Matching","Realisation","Conservatism"],"correctOption":3,"section":"Accounting concepts, conventions and limitations","explanation":"Conservatism (prudence) says revenue and profits are recognised only when reasonably certain, while expenses and losses are provided for as soon as they are reasonably possible. Option C, realisation, only deals with when revenue is earned and says nothing about recognising expenses early. Matching (Option B) links expenses to the revenue of the same period."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 222, $official_bank_source${"itemId":"0b0664b3-e163-52e3-8267-19527bbf4a3d","questionId":"3e4f8089-0011-54ec-b46a-fccf93b0f786","sourceKey":"bank:ACC101:ACC-0210","payload":{"prompt":"In order that financial statements report financial performance fairly and consistently, they are prepared according to widely accepted accounting standards. These standards are referred to as","options":["Generally Accepted Accounting Principles","Generally Accepted Accounting Principle","Generally Acceptable Accounting Principles","Generally Acceptable Accounting Principle"],"correctOption":0,"section":"Accounting concepts, conventions and limitations","explanation":"The widely accepted body of rules for preparing financial statements is called Generally Accepted Accounting Principles (GAAP). Options B, C and D are near misses: the term uses \"Accepted\" not \"Acceptable\", and \"Principles\" in the plural."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 223, $official_bank_source${"itemId":"9bd5a096-0fca-5b1d-afd5-c65ffd120e84","questionId":"a13a9bf9-018b-5023-a66e-cc8ae83e46b1","sourceKey":"bank:ACC101:A101N2-030","payload":{"prompt":"A trader in Balogun market bought 80 bags of rice for N2,400,000 and sold 60 of them during the period. Applying the matching concept, what is the cost of sales for the period?","options":["N600,000","N2,400,000","N1,200,000","N1,800,000"],"correctOption":3,"section":"Accounting concepts, conventions and limitations","explanation":"Matching charges only the cost of the goods actually sold against the revenue they earned: 60/80 x 2,400,000 = N1,800,000. N600,000 is the cost of the 20 unsold bags, which is carried forward as inventory, not charged. Charging the full N2,400,000 ignores matching altogether."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 224, $official_bank_source${"itemId":"a446a9b0-a85a-53f2-a9a6-936a29ee758a","questionId":"feb22b65-ce43-52e5-9868-f84f96bbe1e7","sourceKey":"bank:ACC101:A101N2-031","payload":{"prompt":"A firm in Ikeja buys a generator for N750,000, pays N15,000 to transport it and N10,000 to install it. Under the accounting cost concept, at what amount should the generator be recorded?","options":["N775,000","N750,000","N765,000","N760,000"],"correctOption":0,"section":"Accounting concepts, conventions and limitations","explanation":"Under the accounting cost concept, the cost of an asset includes its purchase price plus transport and installation: 750,000 + 15,000 + 10,000 = N775,000. Recording only the N750,000 price leaves out costs needed to get the generator working. N765,000 and N760,000 each leave out one of the two extra costs."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 225, $official_bank_source${"itemId":"7dd50675-f8aa-59a5-b5fb-dd4dad32d815","questionId":"d9a7a27b-d67e-58ef-85ad-b827f600c050","sourceKey":"bank:ACC101:A101N2-032","payload":{"prompt":"A firm in Ikeja receives a customer's order in March, delivers the goods and invoices the customer in April, and is paid in May. Under the realisation concept, in which month is the revenue realised?","options":["April","June, when the accounts are prepared","March","May"],"correctOption":0,"section":"Accounting concepts, conventions and limitations","explanation":"Revenue is realised when the goods are sold and the customer incurs a liability to pay, which happens on delivery in April. Receiving an order in March creates no legal right to receive money, so it is not realisation. Waiting for the cash in May would confuse realisation with cash receipt."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 226, $official_bank_source${"itemId":"e773549f-7355-54ba-b6f3-7ff51c131e26","questionId":"6465a627-5c7f-5725-80e2-0e8c2a69384f","sourceKey":"bank:ACC101:A101N2-033","payload":{"prompt":"A company accounts for an asset it holds under a lease in line with the economic reality of the arrangement rather than its legal form. Which concept is being applied?","options":["Business entity","Objectivity","Historical cost","Substance over form"],"correctOption":3,"section":"Accounting concepts, conventions and limitations","explanation":"Substance over form requires transactions to be accounted for by their economic substance rather than their legal form, and leases are the usual example. Historical cost is about recording assets at what they cost, and objectivity is about evidence free from bias; neither deals with substance versus legal form."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 227, $official_bank_source${"itemId":"7e30b3c7-538c-5030-8bb5-01fb50b47230","questionId":"9dfe0d2b-f377-5ea5-a435-7d7d54763843","sourceKey":"bank:ACC101:A101N2-034","payload":{"prompt":"The accounting concept that extends objectivity so that financial reports do not favour any particular group of users is","options":["Materiality","Fairness","Periodicity","Consistency"],"correctOption":1,"section":"Accounting concepts, conventions and limitations","explanation":"Fairness is described as an extension of objectivity: reports should be prepared so that they favour no group. Consistency is about using the same methods from period to period, materiality is about disclosing significant items, and periodicity is about reporting at regular intervals."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 228, $official_bank_source${"itemId":"cb2b00a3-0201-5912-98c1-eba817e1d236","questionId":"0f2ff0c8-5330-5de3-9400-9b605b4b4ea0","sourceKey":"bank:ACC101:A101N2-035","payload":{"prompt":"Limited companies prepare and publish their financial statements every year so that performance can be reviewed at regular intervals. This reflects which concept?","options":["Consistency","Periodicity","Going concern","Accrual"],"correctOption":1,"section":"Accounting concepts, conventions and limitations","explanation":"The periodicity concept says performance is reviewed periodically, and limited companies report annually. Going concern is the assumption that the business will continue operating, which is different from reporting at regular intervals. Consistency concerns using the same methods each period, not how often reports are made."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 229, $official_bank_source${"itemId":"de07299a-911a-5afc-8123-8968772cf219","questionId":"a8e2e53f-eba8-59bb-a9c7-d249d06509d6","sourceKey":"bank:ACC101:A101N2-036","payload":{"prompt":"A manufacturing company in Ota is facing a large lawsuit that could cost it heavily. It reports this in its financial statements even though the information is unfavourable. Which convention is it following?","options":["Full disclosure","Materiality","Consistency","Money measurement"],"correctOption":0,"section":"Accounting concepts, conventions and limitations","explanation":"Full disclosure requires all significant information to be disclosed, even when it is unfavourable to the business. Materiality decides whether an item is significant enough to show separately, but it is full disclosure that insists on reporting bad news. Consistency is about keeping the same methods, and money measurement is about recording only items measurable in money."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 230, $official_bank_source${"itemId":"b09fa386-fd0d-5981-9180-14765860f5f8","questionId":"dd0a0295-61e4-5b6b-a9d4-3643f9bb9550","sourceKey":"bank:ACC101:A101N2-037","payload":{"prompt":"Financial accounting has several weaknesses. Identify the one that is a recognised limitation.","options":["It records every transaction on a double-entry basis","It reports on the business as a whole, not by product, process or department","It provides evidence that makes an audit possible","It summarises the results of the business for a period"],"correctOption":1,"section":"Accounting concepts, conventions and limitations","explanation":"Financial accounting reports only on the whole concern, so it does not show how individual products, processes or departments are performing, which is a recognised limitation. Providing audit evidence, recording transactions by double entry and summarising results for a period are useful features of accounting, not limitations."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 231, $official_bank_source${"itemId":"64a49b0f-3f6b-5670-8d83-e7aefb5ce978","questionId":"19cd6241-c1b0-57b1-a3b6-d4eb81fbe40a","sourceKey":"bank:ACC101:A101N2-038","payload":{"prompt":"A company in Lagos still reports a building bought many years ago at its original cost, even though inflation has greatly changed the value of the naira since then. This illustrates which limitation of financial accounting?","options":["It does not give the cost of products manufactured","It ignores price-level changes","It is too technical for non-accountants","It cannot compare actual results with budget"],"correctOption":1,"section":"Accounting concepts, conventions and limitations","explanation":"Financial accounting records items at historical cost and ignores changes in the price level, so the building's figure no longer reflects current values after years of inflation. Being too technical, not comparing results with budget, and not costing products are also limitations, but they have nothing to do with inflation and old asset values."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 232, $official_bank_source${"itemId":"c6bfecb0-2adf-51f9-b15b-138e39bb61f7","questionId":"b2187890-e444-5925-a625-a9136f3284d2","sourceKey":"bank:ACC101:A101N2-039","payload":{"prompt":"When the owner invests money in a business, it is recorded as capital, treated as an amount the business owes to the owner. Which concept explains this treatment?","options":["Going concern concept","Business entity concept","Money measurement concept","Dual aspect concept"],"correctOption":1,"section":"Accounting concepts, conventions and limitations","explanation":"The business entity concept treats the business as separate from its owner, so the owner's investment is recorded as capital, a liability of the business towards the owner. Dual aspect explains why the investment is recorded twice, but not why the owner is treated as a separate party. Money measurement and going concern do not deal with the owner's relationship to the business."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 233, $official_bank_source${"itemId":"db59142c-5ced-5610-8aa6-6e7838adea29","questionId":"23e55c2f-53eb-579e-b6ea-e210b3554e6d","sourceKey":"bank:ACC101:A101N2-040","payload":{"prompt":"Which of the following is NOT one of the four accounting conventions?","options":["Full disclosure","Materiality","Going concern","Conservatism"],"correctOption":2,"section":"Accounting concepts, conventions and limitations","explanation":"The four accounting conventions are conservatism, consistency, full disclosure and materiality. Going concern is an accounting concept, not one of these conventions: it assumes the business will continue operating in the foreseeable future."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 234, $official_bank_source${"itemId":"afd9e84d-9df3-5f87-be22-7186254ba0a9","questionId":"d9d8c19b-46fc-5218-9a1a-b34ed8a79eaa","sourceKey":"bank:ACC101:ACC-0001","payload":{"prompt":"From which of the following are entries posted into the ledger?","options":["Income and expenditure account","Income statement","Subsidiary books","Statement of affairs"],"correctOption":2,"section":"Source documents and books of prime entry","explanation":"Subsidiary books (the books of prime entry, such as the day books and journal) are where transactions are first recorded, and their entries are then posted into the ledger. Options A, B and D are statements prepared at the end of a period from ledger balances, so they come after the ledger, not before it."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 235, $official_bank_source${"itemId":"c296cc48-b7a9-551d-9643-560e47e1edd6","questionId":"1836b2bb-7efb-51dd-8fae-95b949f31458","sourceKey":"bank:ACC101:ACC-0006","payload":{"prompt":"In which of the following book of prime entry would purchase of equipment on credit be captured?","options":["Cashbook","Purchases journal","Return inward journal","Journal proper"],"correctOption":3,"section":"Source documents and books of prime entry","explanation":"The purchases journal records only credit purchases of goods meant for resale, so buying equipment on credit, which is a non-current asset, goes into the journal proper. Option B is the tempting trap, and option A is wrong because no cash moved at the time of purchase."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 236, $official_bank_source${"itemId":"69c4e999-65f3-5eb2-9827-8ef9d12bd6d6","questionId":"e6418d15-45d6-5071-bbea-8ee04d59333c","sourceKey":"bank:ACC101:ACC-0042","payload":{"prompt":"Recording of transactions must be done on double entry basis in which of the following subsidiary books?","options":["Journal proper","Sales Day Book","Return outwards Day Book","Cashbook"],"correctOption":3,"section":"Source documents and books of prime entry","explanation":"The cash book is both a book of prime entry and part of the ledger, so the cash and bank accounts kept in it form one side of the double entry directly. Option A, the journal proper, shows both sides of an entry, but it is still only a book of prime entry and its items must be posted to the ledger. Options B and C are also books of prime entry only."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 237, $official_bank_source${"itemId":"637617c2-e580-5f4b-b914-99f6b0e21198","questionId":"b148047f-73f9-544b-b229-62bd99dba7e8","sourceKey":"bank:ACC101:ACC-0176","payload":{"prompt":"The book of original entry is the definition of a","options":["Journal","Ledger","Reconciliation","liability"],"correctOption":0,"section":"Source documents and books of prime entry","explanation":"A journal is the book of original (prime) entry where transactions are first recorded before they are posted. The ledger (Option B) is where the entries are posted afterwards, so it is the book of final entry rather than original entry."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 238, $official_bank_source${"itemId":"d0c9cbbf-78fa-5d05-adae-6296aa6454aa","questionId":"eca0aa28-3cf9-529e-8dca-b2aafaee4ca4","sourceKey":"bank:ACC101:ACC-0233","payload":{"prompt":"A note informing credit suppliers of charges to their accounts for goods returned is called","options":["Promissory note","Sales return note","Purchases return note","Debit note"],"correctOption":3,"section":"Source documents and books of prime entry","explanation":"A debit note is sent by a buyer to a supplier to show that the supplier's account in the buyer's books has been debited, for example for goods returned. Option C, a purchases returns note, is not the standard name for this document. Option A is a written promise to pay money, and Option B is a document used on the selling side."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 239, $official_bank_source${"itemId":"a2b92cdc-eda1-5865-87ca-ecf852b479fb","questionId":"d9340bcd-37bf-53f2-ad9f-831da023da57","sourceKey":"bank:ACC101:ACC-0246","payload":{"prompt":"Which document is used for undercharge of commodities","options":["credit note","debit note","invoice","proforma invoice"],"correctOption":1,"section":"Source documents and books of prime entry","explanation":"If a seller has undercharged a customer, it sends a debit note to increase the amount the customer owes. Option A, a credit note, is used for the opposite case, an overcharge or goods returned. A proforma invoice (D) is a quotation-style invoice sent before a sale."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 240, $official_bank_source${"itemId":"a5a36010-32e8-5372-a111-1278ffdcf009","questionId":"00ed923c-3287-5543-94eb-7acafe667da6","sourceKey":"bank:ACC101:ACC-0247","payload":{"prompt":"___ is used for overcharge","options":["credit note","debit note","proforma invoice","invoice"],"correctOption":0,"section":"Source documents and books of prime entry","explanation":"When a customer has been overcharged, the seller sends a credit note to reduce the amount the customer owes. A debit note (B) is used to correct an undercharge. An invoice (D) records the original sale, and a proforma invoice (C) is sent before the sale is made."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 241, $official_bank_source${"itemId":"60732b72-47f9-5c0d-b741-5ffc137d2391","questionId":"165ca23c-1014-5a83-a31f-eeefdd0670fc","sourceKey":"bank:ACC101:ACC-0318","payload":{"prompt":"Which of the following documents should accompany a return of goods to a supplier?","options":["Debit note","Remittance advice","Purchase invoice","Credit note"],"correctOption":0,"section":"Source documents and books of prime entry","explanation":"A debit note is sent to a supplier along with returned goods, telling the supplier that their account in the buyer's books is being reduced (debited) by the value of the return. Option D, a credit note, is the document the supplier sends back to confirm the reduction. Option B, a remittance advice, goes with a payment, and option C, a purchase invoice, is received when goods are bought."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 242, $official_bank_source${"itemId":"2b8cb141-c544-5ea6-bb87-f92693753e82","questionId":"4df925d0-dc20-56b8-beec-da3132ae7d16","sourceKey":"bank:ACC101:ACC-0319","payload":{"prompt":"Which of the following are books of prime entry? 1 Sales day book; 2 Cash book; 3 Journal; 4 Purchase ledger","options":["1 and 2 only","1, 2 and 3 only","1 only","All of them"],"correctOption":1,"section":"Source documents and books of prime entry","explanation":"Books of prime entry are where transactions are first recorded before posting to the ledger: the sales day book, the cash book and the journal all qualify. The purchase ledger is a ledger, not a book of prime entry, so option D is wrong. Options A and C leave out books that are genuinely books of prime entry."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 243, $official_bank_source${"itemId":"2536f708-74f2-5e1d-a915-ff5273e1ddc7","questionId":"954b904d-9e5e-506e-891e-c06be28592a9","sourceKey":"bank:ACC101:ACC-0320","payload":{"prompt":"In which book of prime entry will a business record debit notes in respect of goods which have been sent back to suppliers?","options":["The sales returns daybook","The cash book","The purchase returns daybook","The purchase daybook"],"correctOption":2,"section":"Source documents and books of prime entry","explanation":"Goods sent back to suppliers are purchase returns (returns outwards), so the debit notes are recorded in the purchase returns day book. Option A (sales returns day book) is for goods returned by customers, and option D (purchase day book) records credit purchases, not returns. Option B is wrong because no cash changes hands on a return."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 244, $official_bank_source${"itemId":"f764390b-546e-5390-9924-8247b62202c9","questionId":"d49692af-7d50-59f8-8bfa-421068230e28","sourceKey":"bank:ACC101:ACC-0321","payload":{"prompt":"Which of the following would be recorded in the sales daybook?","options":["Discounts allowed","Sales invoices","Credit notes received","Trade discounts"],"correctOption":1,"section":"Source documents and books of prime entry","explanation":"The sales day book records credit sales, and its entries come from the sales invoices sent to customers. Option A (discounts allowed) is recorded in the cash book, and option C (credit notes received) would go in the purchase returns day book. Option D is wrong because trade discounts are deducted on the invoice and are not recorded in the books at all."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 245, $official_bank_source${"itemId":"f2441fe1-7571-5563-90fb-a5983807da63","questionId":"fe6598f6-f0f4-53ae-8bf4-2f06050ca7ef","sourceKey":"bank:ACC101:ACC-0332","payload":{"prompt":"In which of the following financial records or documents will trade discount be recorded?","options":["Cash book","Purchases day book","General ledger","Invoices"],"correctOption":3,"section":"Source documents and books of prime entry","explanation":"Trade discount is a reduction in list price shown only on the invoice; it is never entered in the books of account. That is why options A, B and C (cash book, purchases day book and general ledger) are wrong: they record only the net amount after the trade discount has already been taken off."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 246, $official_bank_source${"itemId":"48baacd8-4e02-5a23-9089-2a2c1239a1a2","questionId":"dbfc3db8-848e-5653-843e-fb36fb5ae98d","sourceKey":"bank:ACC101:ACC-0341","payload":{"prompt":"The total value in the sales day book would be transferred to","options":["Credit side of sales account","Debit side of payables account","Debit side of non-current account","None of the above"],"correctOption":0,"section":"Source documents and books of prime entry","explanation":"The sales day book lists credit sales, and its periodic total is posted to the credit side of the sales account, with each customer's account being debited. Option B is wrong because payables relate to suppliers, not sales, and option C has nothing to do with sales. Option D is ruled out because A is correct."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 247, $official_bank_source${"itemId":"53d376d1-d68c-5f58-bbd2-5f23d0c6bb4c","questionId":"52d22616-0e69-5e51-9f58-5595b55121a4","sourceKey":"bank:ACC101:ACC-0342","payload":{"prompt":"Furniture and fittings purchased on credit (for resale) will first be recorded in the","options":["Journal proper","Sales journal","Purchases journal","Cashbook"],"correctOption":2,"section":"Source documents and books of prime entry","explanation":"Because the furniture is bought for resale, it is stock in trade for this business, so a credit purchase of it is first recorded in the purchases journal. Option A, the journal proper, would be right only if the furniture were bought for use in the business as a non-current asset. Option D is wrong because no cash is paid on a credit purchase."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 248, $official_bank_source${"itemId":"56eb4be3-00d3-5093-90aa-8aaae8ab0785","questionId":"1affd597-3dfd-58a3-9b45-0a54289b5405","sourceKey":"bank:ACC101:A101N2-041","payload":{"prompt":"The original evidence of a transaction, without which nothing should be recorded in the books, is called a","options":["Ledger account","Book of prime entry","Trial balance","Source document"],"correctOption":3,"section":"Source documents and books of prime entry","explanation":"Source documents, also called accounting documents, are the original evidence of every transaction, and nothing is recorded without one. A book of prime entry is where the transaction is first written up from that document, and the ledger and trial balance come even later in the process."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 249, $official_bank_source${"itemId":"580e96ea-adc7-5e10-b67c-42e0dd890b13","questionId":"89c100eb-47ef-5bc1-b6a5-82a01d3b4e77","sourceKey":"bank:ACC101:A101N2-042","payload":{"prompt":"Which of the following is NOT a function of source documents?","options":["They provide evidence that makes an audit possible","They provide evidence that guards against fraud","They are signed by the parties, so they cannot easily be denied","They show the net profit or loss for the period"],"correctOption":3,"section":"Source documents and books of prime entry","explanation":"Source documents serve as evidence: they guard against fraud, make audit possible, cannot easily be denied because the parties sign them, and are hard to alter. Showing net profit or loss is the job of the income statement, prepared at the end of the period, not of individual source documents."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 250, $official_bank_source${"itemId":"f1cd3f74-1f9e-5355-8229-cc3f233d53fe","questionId":"b0483173-7e48-5339-8d71-08307b4f2c16","sourceKey":"bank:ACC101:A101N2-043","payload":{"prompt":"A purchase invoice received from a supplier is the source document for entries in the","options":["Returns inwards book","Petty cash book","Sales day book","Purchases day book"],"correctOption":3,"section":"Source documents and books of prime entry","explanation":"A purchase invoice is the original of the supplier's sales invoice, and it is used to write up the purchases day book for credit purchases. The sales day book is written up from the duplicate sales invoices the business issues, and the returns inwards book from credit notes issued to customers."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 251, $official_bank_source${"itemId":"02b571dd-31c8-5f45-af48-5491e9965059","questionId":"31a98614-ed53-58d9-b831-f827abe3651d","sourceKey":"bank:ACC101:A101N2-044","payload":{"prompt":"A firm in Ikeja receives electricity on credit and later gets a document showing the amount it owes. This document is best described as a","options":["Sales invoice","Payment voucher","Bill","Credit note"],"correctOption":2,"section":"Source documents and books of prime entry","explanation":"Bills are used for services supplied on credit, such as electricity, water or telephone, while invoices are used for goods. A credit note reduces what a buyer owes, and a payment voucher authorises a payment, so neither describes a charge for electricity."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 252, $official_bank_source${"itemId":"d1318e40-c4bd-5aa6-840f-d288b7cedf04","questionId":"42ad6103-ed58-5ed5-bced-5732ed0fcce1","sourceKey":"bank:ACC101:A101N2-045","payload":{"prompt":"A trader in Balogun market issues a credit note to a customer who returned some goods. In the trader's books, the credit note represents","options":["Discount received","Returns on sales (returns inwards)","Returns on purchases (returns outwards)","Additional credit sales"],"correctOption":1,"section":"Source documents and books of prime entry","explanation":"A credit note issued by a business means its customer has returned goods, so it records returns on sales, also called returns inwards. Returns outwards would apply if the trader had received a credit note from a supplier. It reduces sales rather than adding to them, and it has nothing to do with discount."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 253, $official_bank_source${"itemId":"24e0a1a9-c50c-5a3e-9bb5-045ba3f7ba0d","questionId":"55da54e3-5258-5f0e-a19b-ebf3fef32f16","sourceKey":"bank:ACC101:A101N2-046","payload":{"prompt":"A customer returns damaged goods to a wholesaler in Idumota, and the wholesaler replaces them with new goods of the same kind. Which statement is correct?","options":["A debit note must be issued to increase the customer's debt","A new sales invoice must be issued for the replacement goods","No credit note is needed because the goods were replaced","A credit note must be issued for the value of the damaged goods"],"correctOption":2,"section":"Source documents and books of prime entry","explanation":"A credit note is issued to reduce a buyer's debt, but when returned goods are simply replaced, the debt is unchanged, so no credit note is needed. Issuing a credit note here would wrongly reduce what the customer owes, and a new invoice would wrongly charge the customer twice."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 254, $official_bank_source${"itemId":"3e2a4c6f-af1b-5a92-80fe-b3a4cda35387","questionId":"61e9f421-86ec-5279-a472-b4f5a19a1e33","sourceKey":"bank:ACC101:A101N2-047","payload":{"prompt":"Which of the following is a reason for returning goods that would lead to a credit note being issued?","options":["The goods delivered were of the wrong specification","The customer paid by cheque instead of cash","The customer bought in bulk and qualified for trade discount","The customer paid within the cash discount period"],"correctOption":0,"section":"Source documents and books of prime entry","explanation":"Goods are returned when they are damaged before delivery or are of the wrong specification, and a credit note is then issued to reduce the buyer's debt. Prompt payment and bulk buying relate to discounts, not returns, and paying by cheque does not involve returning anything."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 255, $official_bank_source${"itemId":"cf5c4db1-fd29-59d8-841b-e79a90eda4d7","questionId":"70cdf62b-ee49-5348-bc6b-8b83cae163cc","sourceKey":"bank:ACC101:A101N2-049","payload":{"prompt":"A seller in Ikeja discovers that delivery charges were left out of an invoice already sent to a customer. Which document should the seller send to increase the amount the customer owes?","options":["Receipt","Debit note","Credit note","Payment voucher"],"correctOption":1,"section":"Source documents and books of prime entry","explanation":"A seller uses a debit note to increase the amount a debtor owes, for example after undercharging or for omitted charges such as delivery. A credit note does the opposite and reduces the debt. A receipt acknowledges money received, and a payment voucher authorises a payment."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 256, $official_bank_source${"itemId":"b5c17fb7-1e21-566b-8b2b-9e728716f212","questionId":"cc9b945a-77b4-544b-8c47-678f353a3c14","sourceKey":"bank:ACC101:A101N2-050","payload":{"prompt":"Which document is checked and authorised by a responsible officer before cash is paid out?","options":["Cheque counterfoil","Store issue voucher","Bank pay-in slip","Payment voucher"],"correctOption":3,"section":"Source documents and books of prime entry","explanation":"A payment voucher is an authorising document checked by a responsible officer before cash is paid. A pay-in slip is evidence of money lodged into the bank, a store issue voucher updates the store ledger, and a cheque counterfoil is the record kept after a cheque has been written."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 257, $official_bank_source${"itemId":"5d9b371c-ed61-5fc4-9d01-aa61c625817d","questionId":"ff0a47cb-870f-5523-a1ae-aed798a09fe5","sourceKey":"bank:ACC101:A101N2-051","payload":{"prompt":"The main source document for the debit side of the bank column of the cash book is the","options":["Purchase invoice","Bank pay-in slip","Cheque counterfoil","Payment voucher"],"correctOption":1,"section":"Source documents and books of prime entry","explanation":"The bank pay-in slip is evidence of lodgements into the bank, and lodgements are receipts entered on the debit side of the bank column. The cheque counterfoil is the tempting choice, but it is evidence of payments by cheque, which go on the credit side."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 258, $official_bank_source${"itemId":"cfdf2326-af9a-5063-8249-35d5f5aa02fb","questionId":"2a16ac04-1a5c-57fb-8075-d88b347f86de","sourceKey":"bank:ACC101:A101N2-052","payload":{"prompt":"Evidence of a payment made by cheque is provided by the","options":["Credit note","Bank pay-in slip","Cheque counterfoil (stub)","Sales invoice"],"correctOption":2,"section":"Source documents and books of prime entry","explanation":"The cheque counterfoil, or stub, is kept by the business as evidence of each payment made by cheque. A pay-in slip is evidence of money paid into the bank, which is the opposite direction. Invoices and credit notes relate to sales, purchases and returns rather than payments."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 259, $official_bank_source${"itemId":"410d1cd2-7c51-5d42-8475-f2216317f6ab","questionId":"f6c1a9f5-1827-53b5-b5a7-405645de9f18","sourceKey":"bank:ACC101:A101N2-053","payload":{"prompt":"When a customer pays cash to a shop in Lekki and is given a receipt, which statement is correct?","options":["The original goes to the payer and the seller keeps the duplicate","Both copies are kept by the seller","The original goes to the bank and the seller keeps the duplicate","The seller keeps the original and the payer gets the duplicate"],"correctOption":0,"section":"Source documents and books of prime entry","explanation":"With a receipt, the original is handed to the payer as proof of payment and the duplicate is kept by the seller for its records. Reversing the copies is the usual slip. The bank plays no part in a cash receipt, and keeping both copies would leave the payer without evidence."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 260, $official_bank_source${"itemId":"1f28df06-632d-5276-b145-9736c2fd1f11","questionId":"c7fa054f-04dc-5b05-b204-061707cc303c","sourceKey":"bank:ACC101:A101N2-054","payload":{"prompt":"Which source document is used to update the store ledger when goods are released from the store?","options":["Payment voucher","Bank statement","Debit note","Store issue voucher"],"correctOption":3,"section":"Source documents and books of prime entry","explanation":"A store issue voucher records goods issued from the store and is used to update the store ledger. A payment voucher authorises cash payments, a bank statement shows the bank's record of the account, and a debit note deals with returns or undercharges."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 261, $official_bank_source${"itemId":"956832c1-531b-5bf1-99db-56641d6bf450","questionId":"2ce20ebb-af64-5847-82a7-70e1125a1566","sourceKey":"bank:ACC101:A101N2-055","payload":{"prompt":"Day books and journals are names used for the books where transactions are first written up. Which term is NOT another name for these books?","options":["Day books","Journals","Ledgers","Subsidiary books"],"correctOption":2,"section":"Source documents and books of prime entry","explanation":"Books of prime (original) entry are also called day books, journals or subsidiary books. The ledger is different: it is the principal book of account to which entries are posted from the books of prime entry."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 262, $official_bank_source${"itemId":"7032f495-2480-5e2f-b675-464a93f34904","questionId":"143da6e3-52b8-50e6-a6de-cfec1ccddbad","sourceKey":"bank:ACC101:A101N2-056","payload":{"prompt":"How often are transactions recorded in the books of prime entry first recorded and then posted to the ledger?","options":["Recorded daily, then posted to the ledger periodically, such as weekly, fortnightly or monthly","Recorded and posted to the ledger only once a year","Recorded weekly, then posted to the ledger only when the trial balance is drawn up","Recorded monthly, then posted to the ledger daily"],"correctOption":0,"section":"Source documents and books of prime entry","explanation":"Transactions are first written up in the books of prime entry each day, and the totals are posted to the ledger at regular intervals such as weekly, fortnightly or monthly. Recording monthly and posting daily reverses the order of frequency, and waiting a whole year would make the records useless for control."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 263, $official_bank_source${"itemId":"71591675-d8c1-5298-9836-0ece9d762068","questionId":"71393dab-9d50-5721-a36b-45c7f3232ab5","sourceKey":"bank:ACC101:A101N2-057","payload":{"prompt":"Which of the following is NOT one of the reasons for keeping books of prime entry?","options":["To show the financial position of the business at the end of the period","To help prevent errors, as their totals can be reconciled with individual accounts","To keep transactions in chronological order","To group the totals of transactions in one place"],"correctOption":0,"section":"Source documents and books of prime entry","explanation":"Books of prime entry group transaction totals, explain transactions, keep them in date order and help prevent errors. Showing the financial position at the end of the period is the purpose of the statement of financial position, not of the day books."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 264, $official_bank_source${"itemId":"af93f0ac-70ea-5581-8469-afcec0113c67","questionId":"b0c98eec-a58a-56e5-b1d0-03a28b2b7664","sourceKey":"bank:ACC101:A101N2-058","payload":{"prompt":"The source document for entries in the returns inwards book is the","options":["Bank pay-in slip","Credit note issued to the customer","Purchase invoice","Debit note received from a supplier"],"correctOption":1,"section":"Source documents and books of prime entry","explanation":"The returns inwards book records goods returned by customers, and the document behind each entry is the credit note the business issues to the customer. A debit note relating to a supplier concerns goods the business itself sends back, which belongs to the returns outwards side."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 265, $official_bank_source${"itemId":"ef070df6-8a58-5404-a23f-8f728b91ac8c","questionId":"64149524-d669-5ec0-9492-dc1c4fed6db7","sourceKey":"bank:ACC101:A101N2-059","payload":{"prompt":"How are entries in the purchases day book posted to the ledger?","options":["Each supplier is credited in the purchases ledger and the total is debited to the purchases account","Each supplier is debited in the purchases ledger and the total is credited to the purchases account","Each supplier is credited in the sales ledger and the total is debited to the sales account","Each supplier is debited in the general ledger and the total is credited to cash"],"correctOption":0,"section":"Source documents and books of prime entry","explanation":"Credit purchases increase what the business owes its suppliers, so each supplier's account in the purchases ledger is credited and the day book total is debited to purchases. Debiting suppliers reverses the entry, and the sales ledger and sales account relate to customers, not suppliers."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 266, $official_bank_source${"itemId":"121c3b40-4cd5-51b6-9a66-c65ee1745f4a","questionId":"ffc673cf-b533-5103-8a4b-39ebb2c7f6d4","sourceKey":"bank:ACC101:A101N2-060","payload":{"prompt":"In the general journal, the narration written below each entry gives","options":["The folio number of the trial balance","The balance on the account after posting","The purpose and authority for the entry","The total of the day book for the month"],"correctOption":2,"section":"Source documents and books of prime entry","explanation":"Each journal entry records the date, the accounts debited and credited, and a narration that explains the purpose and authority of the entry, usually beginning with \"Being\". Account balances appear in the ledger, not in the narration, and day book totals have nothing to do with it."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 267, $official_bank_source${"itemId":"54cb8f6e-1691-54ff-bc3d-54cb313a2f28","questionId":"ad428523-8248-5735-a13e-0a32b2e2d4c2","sourceKey":"bank:ACC101:A101N2-061","payload":{"prompt":"Which of the following is NOT recorded in the general journal (journal proper)?","options":["Purchase of a non-current asset on credit","Correction of errors","Credit sales of goods to customers","Opening entries"],"correctOption":2,"section":"Source documents and books of prime entry","explanation":"The general journal records items that are not credit sales or purchases, such as opening entries, transfers, credit purchases of non-current assets, adjustments and corrections. Credit sales of goods go into the sales day book instead."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 268, $official_bank_source${"itemId":"dd3adceb-aa43-54b4-a61c-02c4cd96acdc","questionId":"df072532-9329-52e9-97fa-ee78a1cb751c","sourceKey":"bank:ACC101:A101N2-062","payload":{"prompt":"When a new business in Ikeja opens its books, its assets total N1,450,000 and its liabilities total N320,000. In the opening journal entry, what is the capital figure?","options":["N1,770,000 credit","N1,450,000 credit","N1,130,000 credit","N1,130,000 debit"],"correctOption":2,"section":"Source documents and books of prime entry","explanation":"In an opening entry, assets are debited, liabilities are credited, and capital is the balancing credit: 1,450,000 - 320,000 = N1,130,000. N1,770,000 wrongly adds the liabilities instead of deducting them. Capital is a credit, not a debit, and N1,450,000 ignores the liabilities completely."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 269, $official_bank_source${"itemId":"768be84d-b6b1-50f1-92dd-7efd289c7844","questionId":"63ab866c-fe2c-57c1-b53f-d1cfde6670a5","sourceKey":"bank:ACC101:A101N2-063","payload":{"prompt":"Adamu owes a business N400,000. By agreement, Chika, another customer, takes over the debt. What is the journal entry?","options":["Debit cash, credit Adamu","Debit Chika, credit Adamu","Debit Adamu, credit Chika","Debit Chika, credit sales"],"correctOption":1,"section":"Source documents and books of prime entry","explanation":"Chika now owes the business, so Chika's account is debited, and Adamu no longer owes, so Adamu's account is credited. Reversing the names would make Adamu owe more. No new sale or cash payment has taken place, so neither sales nor cash is involved."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 270, $official_bank_source${"itemId":"70cfd956-e7ac-5a2b-8052-5e1d04bef18d","questionId":"6c005023-d88a-5fae-a2d4-6c0049c44784","sourceKey":"bank:ACC101:A101N2-064","payload":{"prompt":"A business sells one of its motor vehicles on credit to Jebeleje. Which journal entry records the sale?","options":["Debit Jebeleje, credit motor vehicle","Debit motor vehicle, credit Jebeleje","Debit Jebeleje, credit sales","Debit cash, credit motor vehicle"],"correctOption":0,"section":"Source documents and books of prime entry","explanation":"Jebeleje now owes the business, so his account is debited, and the vehicle leaves the business, so the motor vehicle account is credited. Crediting sales is the common mistake: a vehicle is a non-current asset, not trading stock. Cash is not involved because the sale is on credit."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 271, $official_bank_source${"itemId":"6d3f233f-0cf5-5e65-a805-3e034a4a0544","questionId":"91f98f18-dbe1-561b-9111-51177016cc5d","sourceKey":"bank:ACC101:A101N2-065","payload":{"prompt":"A credit sale to Bisi is posted in error to the account of Bimbo, another customer. In which book of prime entry should the correction first be recorded?","options":["Cash book","Returns inwards book","General journal","Sales day book"],"correctOption":2,"section":"Source documents and books of prime entry","explanation":"The correction of errors is one of the uses of the general journal, so a credit sale posted to the wrong customer is corrected there. The sales day book records new credit sales, not corrections, and the returns inwards book is only for goods returned by customers."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 272, $official_bank_source${"itemId":"65458469-4955-500f-81d5-c2b4361fbc25","questionId":"57e95706-dc7b-5b14-856b-993a3f539334","sourceKey":"bank:ACC101:A101N2-066","payload":{"prompt":"A UNILAG department pays N1,500 for a messenger's transport fare. In which book is this small payment most likely to be recorded?","options":["Petty cash book","Sales returns book","Purchases day book","General journal"],"correctOption":0,"section":"Source documents and books of prime entry","explanation":"The petty cash book is the book of prime entry for small transactions such as transport fares. The general journal handles items like opening entries and corrections, the purchases day book records credit purchases of goods, and the sales returns book records goods returned by customers."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 273, $official_bank_source${"itemId":"0586decc-9fdd-513d-9fb0-d4bb472a55c0","questionId":"f9c193db-eecc-52a7-bdc5-6c07dd00deff","sourceKey":"bank:ACC101:ACC-0005","payload":{"prompt":"The column of a ledger account used for reference purpose is","options":["Particulars","Folio","Amount","Contra-entry"],"correctOption":1,"section":"Ledger accounts and types of accounts","explanation":"The folio column is used for cross-referencing, showing the page or account number where the other side of the entry can be found. Option A, Particulars, describes the name of the other account involved, and option C simply holds the money value."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 274, $official_bank_source${"itemId":"3a149b91-d26d-52b4-8f5d-78e336e3ce6b","questionId":"b81ad602-1cf2-526b-ad2d-b996b57c6718","sourceKey":"bank:ACC101:ACC-0016","payload":{"prompt":"Which one of the following is the best description of a salary account?","options":["Real, personal ledger account","Real, impersonal ledger account","Nominal, impersonal ledger account","Nominal, personal ledger account"],"correctOption":2,"section":"Ledger accounts and types of accounts","explanation":"Salary is an expense, and expense and income accounts are nominal accounts; since it does not belong to a person or a physical asset, it is impersonal. Options A and B describe real accounts, which are for assets like buildings, and option D wrongly calls it personal."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 275, $official_bank_source${"itemId":"1f10ef6a-e8e2-5430-8519-d72666d54a67","questionId":"d83f00b8-fbb9-502b-a3b7-d5102b601a35","sourceKey":"bank:ACC101:ACC-0035","payload":{"prompt":"An entry on the right-hand side of a ledger account is","options":["Credit","Debit","Transaction","Balance"],"correctOption":0,"section":"Ledger accounts and types of accounts","explanation":"In a T-account the left-hand side is the debit side and the right-hand side is the credit side. Option B is the left side, and option D is the figure left after totalling both sides."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 276, $official_bank_source${"itemId":"0ffe8816-0f28-512a-a1db-fa933e04956b","questionId":"95f1d90e-9459-53c6-9019-7026823eeebe","sourceKey":"bank:ACC101:ACC-0038","payload":{"prompt":"Where are the personal accounts of customers to whom goods are sold on credit found?","options":["Sales journal","Journal proper","Sales ledger","Purchases ledger"],"correctOption":2,"section":"Ledger accounts and types of accounts","explanation":"The sales ledger holds the personal accounts of credit customers (debtors). Option A, the sales journal, is the book of prime entry where credit sales are first listed, not where customer accounts are kept."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 277, $official_bank_source${"itemId":"801fbb69-4088-5c40-913a-064572e2939c","questionId":"ef14b7e0-7776-5887-a70e-37e22198d063","sourceKey":"bank:ACC101:ACC-0184","payload":{"prompt":"The listing of accounts that are available for posting transactions is the ____ of accounts.","options":["Trial Balance","journal","balance sheet","Chart"],"correctOption":3,"section":"Ledger accounts and types of accounts","explanation":"A chart of accounts is the list of all account names (and often numbers) available for recording transactions. A trial balance (Option A) lists account balances at a date, and the journal (Option B) records the transactions themselves."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 278, $official_bank_source${"itemId":"a2d81ad5-6824-506e-8255-cfc03263ce83","questionId":"38a00124-b401-57fe-89bf-f910d006bb3a","sourceKey":"bank:ACC101:ACC-0201","payload":{"prompt":"Principally, ledger accounts can be classified into:","options":["Debtors ledger account and creditors ledger account","Nominal ledger account and sales ledger account","Main ledger account and subsidiary ledger account","Impersonal ledger account and personal-ledger account"],"correctOption":3,"section":"Ledger accounts and types of accounts","explanation":"Ledger accounts are broadly classified into personal accounts (people and firms, such as debtors and creditors) and impersonal accounts (real accounts for assets and nominal accounts for incomes and expenses). Option A lists only two kinds of personal account, and option B mixes one impersonal ledger with one personal ledger. Option C describes how ledgers are organised rather than how accounts are classified."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 279, $official_bank_source${"itemId":"09dd1091-cf2e-5274-abf6-a6a5729945e2","questionId":"653c882a-0db1-5730-b246-e03d28211fff","sourceKey":"bank:ACC101:ACC-0219","payload":{"prompt":"Which of the following is an example of impersonal real ledger account","options":["Motor vehicle account","Debtors account","Salary account","Creditors account"],"correctOption":0,"section":"Ledger accounts and types of accounts","explanation":"Real accounts are impersonal accounts for assets and property, so a Motor Vehicle account is a real account. Debtors (B) and creditors (D) are personal accounts because they relate to people or firms, while Salary (C) is a nominal account for an expense."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 280, $official_bank_source${"itemId":"14759478-23fc-50cb-8752-475dd916de31","questionId":"e4b5a39e-56ee-56f7-aa56-94256f6b0f86","sourceKey":"bank:ACC101:A101N2-067","payload":{"prompt":"The ledger is often described as the","options":["Book of prime entry","Principal book of account","Subsidiary book","Book of original entry"],"correctOption":1,"section":"Ledger accounts and types of accounts","explanation":"The ledger is the principal book of account, holding the permanent records of assets, liabilities, income, expenses and capital. The book of original entry, subsidiary book and book of prime entry are all names for the day books and journals where transactions are first recorded before being posted to the ledger."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 281, $official_bank_source${"itemId":"2bfc5921-b61a-5311-811b-5c6fd2c88f13","questionId":"5bd4b3c8-7c4a-5af4-b396-5b4c6e6491e1","sourceKey":"bank:ACC101:A101N2-068","payload":{"prompt":"Which of the following best describes the contents of the ledger?","options":["Original evidence of transactions such as invoices and receipts","Daily records of credit sales only","Permanent records of assets, liabilities, income, expenses and capital","A list of balances prepared to check arithmetical accuracy"],"correctOption":2,"section":"Ledger accounts and types of accounts","explanation":"The ledger holds the permanent records of every class of item: assets, liabilities, income, expenses and capital. Daily records of credit sales belong in the sales day book, invoices and receipts are source documents, and a list of balances is the trial balance extracted from the ledger."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 282, $official_bank_source${"itemId":"19dbd7d2-eebb-5991-b110-7f1f71c67617","questionId":"759ac54d-d429-5acd-9da2-7c6e943e434b","sourceKey":"bank:ACC101:A101N2-069","payload":{"prompt":"A bookkeeper in Ikeja lists the benefits of keeping a ledger. Which item on her list is wrong, because it describes something the ledger does NOT do?","options":["It shows the movements in each account","It provides the information needed for the income statement and statement of financial position","It is the record from which the trial balance is extracted","It is where transactions are first recorded in date order before posting"],"correctOption":3,"section":"Ledger accounts and types of accounts","explanation":"The ledger keeps permanent records, provides information for the financial statements, shows the origin of each transaction, shows movements in each account and is the basis for the trial balance. Recording transactions first in date order is the role of the books of prime entry, from which entries are later posted to the ledger."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 283, $official_bank_source${"itemId":"309fc5f5-2389-546c-89f9-aa5233d4dfb0","questionId":"a8929db0-b60d-5c90-8561-a67845b84ab3","sourceKey":"bank:ACC101:A101N2-070","payload":{"prompt":"A trader in Balogun market wants to see how the balance on her rent account changed during the month. Which feature of the ledger makes this possible?","options":["It is signed by the parties, so it cannot be denied","It shows the movements in each account","It authorises payments before cash is released","It groups the totals of transactions in one place"],"correctOption":1,"section":"Ledger accounts and types of accounts","explanation":"One importance of the ledger is that it shows the movements in each account, so the trader can follow every increase and decrease in rent. Grouping totals in one place is a reason for keeping books of prime entry, being signed by the parties describes source documents, and authorising payments is the role of a payment voucher."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 284, $official_bank_source${"itemId":"6692bde8-0b2b-5be6-bed5-102a33a0a952","questionId":"0d4d655b-53c9-5ec9-9513-6ac1c4cc3b78","sourceKey":"bank:ACC101:A101N2-071","payload":{"prompt":"The trial balance is extracted from the","options":["Ledger","Purchases day book","Sales day book","Source documents"],"correctOption":0,"section":"Ledger accounts and types of accounts","explanation":"The trial balance is a list of the balances on the ledger accounts, so it is extracted from the ledger. The day books are books of prime entry whose totals are posted to the ledger first, and source documents are the original evidence behind those entries."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 285, $official_bank_source${"itemId":"c0a62fdd-b120-556c-8a12-f386d89ffe98","questionId":"68743a30-8c9f-5202-a7c8-536a60dd7ab3","sourceKey":"bank:ACC101:A101N2-072","payload":{"prompt":"In a T account, the left-hand side and the right-hand side are respectively the","options":["Assets side and liabilities side","Receipts side and balance side","Credit side and debit side","Debit side and credit side"],"correctOption":3,"section":"Ledger accounts and types of accounts","explanation":"A T account has Dr (debit) on the left and Cr (credit) on the right. Reversing them is the usual slip. The sides are not named after assets and liabilities, because every account, whatever its type, has a debit and a credit side."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 286, $official_bank_source${"itemId":"446ef229-92f3-59fd-9861-3faea8241ac9","questionId":"72bef86e-9f4e-55c5-8983-3178ff39278a","sourceKey":"bank:ACC101:A101N2-073","payload":{"prompt":"Each side of a T account usually has which columns?","options":["Date, Invoice number and Customer","Date, Narration and Balance","Date, Particulars and Amount","Particulars, Debit and Credit"],"correctOption":2,"section":"Ledger accounts and types of accounts","explanation":"Each side of a T account is set out with Date, Particulars and Amount columns, with a folio column for reference. Date, invoice number and customer are the columns of a sales day book, and separate debit and credit columns side by side belong to the journal layout."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 287, $official_bank_source${"itemId":"a9af556a-37db-597b-bccf-ca210a79e5bb","questionId":"ab14d538-8b49-5e17-beb2-395f07366406","sourceKey":"bank:ACC101:A101N2-074","payload":{"prompt":"Accounts can be grouped into three types. These are","options":["Personal, impersonal and suspense accounts","Real, personal and nominal accounts","Sales, purchases and general accounts","Real, capital and revenue accounts"],"correctOption":1,"section":"Ledger accounts and types of accounts","explanation":"The three types of account are real (tangible things), personal (persons, companies and partnerships) and nominal (gains and losses). Sales, purchases and general are types of ledger, not types of account, and capital and revenue describe kinds of expenditure."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 288, $official_bank_source${"itemId":"36c05f6b-1417-5a63-add3-9ab2b711847e","questionId":"51aad836-ec3a-5370-b79a-0aaf8cc35ced","sourceKey":"bank:ACC101:A101N2-075","payload":{"prompt":"Accounts that record tangible things such as cash, cars and goods are called","options":["Suspense accounts","Real accounts","Personal accounts","Nominal accounts"],"correctOption":1,"section":"Ledger accounts and types of accounts","explanation":"Real accounts record tangible things the business owns, such as cash, cars and goods. Personal accounts are for persons, companies or partnerships, and nominal accounts are for gains and losses such as rent and salaries."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 289, $official_bank_source${"itemId":"3bb398ca-f432-5cb2-9e28-84ffcfb7e287","questionId":"d72283cd-183a-5d18-b163-720f06bb7f13","sourceKey":"bank:ACC101:A101N2-076","payload":{"prompt":"Personal accounts generally arise from","options":["Cash transactions only","Credit transactions","Depreciation of assets","Year-end adjustments"],"correctOption":1,"section":"Ledger accounts and types of accounts","explanation":"Personal accounts are kept for persons, companies or partnerships, and they arise from credit transactions, when someone owes the business or is owed by it. A pure cash transaction leaves no amount owing, so it does not need a personal account. Adjustments and depreciation involve nominal and real accounts."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 290, $official_bank_source${"itemId":"b575b70f-52e5-5a7a-8f60-f184699125bd","questionId":"51d465aa-8b69-575c-b216-2dbe3035b1e4","sourceKey":"bank:ACC101:A101N2-077","payload":{"prompt":"Accounts that record gains and losses, such as rent, salaries and electricity, are called","options":["Nominal accounts","Real accounts","Personal accounts","Contra accounts"],"correctOption":0,"section":"Ledger accounts and types of accounts","explanation":"Nominal accounts record gains and losses, including expenses such as rent, salaries and electricity and items such as discounts. Real accounts are for tangible assets, and personal accounts are for people and organisations the business deals with on credit."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 291, $official_bank_source${"itemId":"a4661eb1-9e19-587f-85b5-29e518ebff50","questionId":"1d7187c4-b9dd-5a76-9c98-e6db3dccb3d6","sourceKey":"bank:ACC101:A101N2-078","payload":{"prompt":"The rent account of a shop in Surulere is classified as a","options":["Real account","Nominal account","Personal account","Contra account"],"correctOption":1,"section":"Ledger accounts and types of accounts","explanation":"Rent is an expense, and expenses are gains and losses recorded in nominal accounts. It is not a real account, because rent is not a tangible thing the business owns. It is not personal either, because it records an expense rather than the account of the landlord."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 292, $official_bank_source${"itemId":"ce55bdf2-4f14-5553-96fd-20d4b33306d2","questionId":"5878e24b-4c5d-5018-9179-98cc7b479798","sourceKey":"bank:ACC101:A101N2-079","payload":{"prompt":"A business in Ikeja keeps a separate account for its electricity costs. This account is best described as","options":["Real and impersonal","Real and personal","Personal and nominal","Nominal and impersonal"],"correctOption":3,"section":"Ledger accounts and types of accounts","explanation":"Electricity is an expense, so its account is nominal, and nominal accounts are impersonal because they do not relate to a person or organisation. A real account is also impersonal, but it records tangible assets such as vehicles, not expenses. An account cannot be both personal and nominal."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 293, $official_bank_source${"itemId":"81382d5b-f56c-502c-bde4-73a1dbc27ca9","questionId":"5ef1ef75-f9ce-51d5-97bc-1653c94bbc49","sourceKey":"bank:ACC101:A101N2-080","payload":{"prompt":"Mr Bello buys goods on credit from a wholesaler in Idumota. In the wholesaler's books, Mr Bello's account is a","options":["Real account","Nominal account","Impersonal account","Personal account"],"correctOption":3,"section":"Ledger accounts and types of accounts","explanation":"Mr Bello is a person dealing with the business on credit, so his account is a personal account. Real and nominal accounts are the two kinds of impersonal account, recording tangible things and gains or losses respectively, so they do not fit an account kept for a customer."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 294, $official_bank_source${"itemId":"0aa95088-546a-5e5f-9735-713fdd2af8e4","questionId":"b97d7bb4-e7ab-5efd-b064-213a6fa3eed7","sourceKey":"bank:ACC101:A101N2-081","payload":{"prompt":"Okafor and Sons, a partnership, supplies goods on credit to a supermarket in Lekki. In the supermarket's books, the account of Okafor and Sons is a","options":["Purchases account","Personal account","Nominal account","Real account"],"correctOption":1,"section":"Ledger accounts and types of accounts","explanation":"Personal accounts are kept for persons, companies and partnerships, so the account of a partnership supplying goods on credit is personal. The purchases account is the tempting choice, but it is a nominal account recording the cost of goods bought, not the amount owed to a particular supplier."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 295, $official_bank_source${"itemId":"e71e83ad-bd28-5194-8c41-4a28b0c4d32f","questionId":"b6bf9e86-a659-5fa0-8719-0f2868148115","sourceKey":"bank:ACC101:A101N2-082","payload":{"prompt":"The land account of a manufacturing company in Ota is a","options":["Real account","Revenue account","Nominal account","Personal account"],"correctOption":0,"section":"Ledger accounts and types of accounts","explanation":"Land is a tangible asset owned by the business, so its account is a real account. Nominal accounts record gains and losses such as rent and wages, and personal accounts are kept for persons and organisations, so neither describes land."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 296, $official_bank_source${"itemId":"20ef63d2-c991-5201-aa07-ca5a62a5b3fb","questionId":"9b5f2f08-e925-55dc-9bdd-00083ffeb1ad","sourceKey":"bank:ACC101:A101N2-083","payload":{"prompt":"The discount received account is classified as a","options":["Nominal account","Capital account","Real account","Personal account"],"correctOption":0,"section":"Ledger accounts and types of accounts","explanation":"Discount received is a gain to the business, and gains and losses are recorded in nominal accounts, which include discounts. It is not a real account because it is not a tangible thing, and it is not personal because it is not the account of a supplier or customer."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 297, $official_bank_source${"itemId":"2920971f-af79-5bfe-8381-da9ec3800b53","questionId":"ac80bacb-b543-5e54-8c7c-badc6392af18","sourceKey":"bank:ACC101:A101N2-084","payload":{"prompt":"A trader in Balogun market gives some of her goods as a gift to a charity. On which side of the goods (real) account is this recorded?","options":["Neither side, because no money changes hands","Both sides, as a contra entry","Debit side","Credit side"],"correctOption":3,"section":"Ledger accounts and types of accounts","explanation":"Real accounts are debited with additions and credited with disposals, items damaged beyond use, or gifts given out. The goods leave the business, so the goods account is credited. Even though no money is received, the business has lost goods, so the transaction must still be recorded."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 298, $official_bank_source${"itemId":"af6de478-b68f-5983-8d18-6788d2746c7c","questionId":"b9d33fad-e985-5e05-add5-49dfe05599ba","sourceKey":"bank:ACC101:A101N2-085","payload":{"prompt":"A business buys a new delivery van. On which side of the motor vehicle (real) account is the purchase recorded?","options":["Credit side","Neither side, until the van is paid for","Debit side","The side of the supplier's account only"],"correctOption":2,"section":"Ledger accounts and types of accounts","explanation":"Real accounts are debited with additions, so a new van is debited to the motor vehicle account. The credit side is used for disposals, items damaged beyond use, or gifts given out. The van must be recorded when it is acquired, whether it is paid for at once or bought on credit."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 299, $official_bank_source${"itemId":"81b8a1aa-c86e-5514-9d73-df8e7b8423c2","questionId":"252e4969-08b5-5d91-b04b-e25d30d5b5bc","sourceKey":"bank:ACC101:A101N2-086","payload":{"prompt":"Equipment in a factory in Agbara is damaged beyond use in a fire. How is this recorded in the equipment (real) account?","options":["The equipment account is debited and credited with the same amount","The equipment account is debited","The equipment account is credited","The equipment account is not affected"],"correctOption":2,"section":"Ledger accounts and types of accounts","explanation":"Items damaged beyond use are recorded on the credit side of a real account, just like disposals, because the asset has left the business. Debiting the account would wrongly show an addition to equipment. Leaving the account unchanged would overstate the assets."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 300, $official_bank_source${"itemId":"2b808a1f-eb52-5a48-b0c0-1b556c7074e0","questionId":"cb074e51-1386-547f-9021-a23ea327f5e3","sourceKey":"bank:ACC101:A101N2-087","payload":{"prompt":"Impersonal accounts are made up of","options":["Personal accounts and nominal accounts","Customers' and suppliers' accounts","Personal accounts and real accounts","Real accounts and nominal accounts"],"correctOption":3,"section":"Ledger accounts and types of accounts","explanation":"Ledger accounts are classified principally into personal and impersonal accounts, and impersonal accounts are the real and nominal accounts together. Any group that includes personal accounts, such as customers and suppliers, cannot be impersonal."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 301, $official_bank_source${"itemId":"7a157329-c26c-5491-b027-ca30ca8e1f68","questionId":"10c95e74-8e9c-5b9a-9f75-50feca941a91","sourceKey":"bank:ACC101:A101N2-088","payload":{"prompt":"A cooperative society in Ibadan sorts its ledger accounts into personal and impersonal. Which account belongs with the personal accounts rather than the impersonal ones?","options":["Salaries account","The account of a credit customer, Mrs Adeyemi","Rent account","Motor vehicle account"],"correctOption":1,"section":"Ledger accounts and types of accounts","explanation":"A credit customer's account is a personal account, kept for a person, so it is not impersonal. The motor vehicle account is a real account, and the salaries and rent accounts are nominal accounts; real and nominal accounts together make up the impersonal accounts."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 302, $official_bank_source${"itemId":"3cb29267-483f-5e0e-a1cf-564a94ffc9da","questionId":"19d0531b-9795-55f6-8d89-91f8319503f1","sourceKey":"bank:ACC101:A101N2-089","payload":{"prompt":"Pick the set in which every account records a tangible thing owned by the business.","options":["Cash, rent, salaries","Motor vehicles, customers, electricity","Cash, motor vehicles, goods","Goods, discounts, wages"],"correctOption":2,"section":"Ledger accounts and types of accounts","explanation":"Real accounts record tangible things, and cash, motor vehicles and goods are all tangible. Rent, salaries, electricity, discounts and wages are gains or losses and so are nominal accounts, and customers' accounts are personal, so each of the other groups is mixed."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 303, $official_bank_source${"itemId":"4ce5dd9d-d116-5f49-ac11-2d228a35db7a","questionId":"87b1a81a-a454-5758-adf2-6320f3f52426","sourceKey":"bank:ACC101:A101N2-090","payload":{"prompt":"An accounting clerk is asked to group expense and income accounts together. Which set is made up entirely of nominal accounts?","options":["Salaries, suppliers, rent","Electricity, land, discounts","Rent, cash, salaries","Rent, salaries, electricity"],"correctOption":3,"section":"Ledger accounts and types of accounts","explanation":"Rent, salaries and electricity are all expenses, which are gains and losses recorded in nominal accounts. Cash and land are tangible things kept in real accounts, and suppliers' accounts are personal, so each of the other groups contains a non-nominal account."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 304, $official_bank_source${"itemId":"a70fc769-55d9-530a-b9f2-a69e326ce954","questionId":"b325e5b7-3098-58d6-a798-a2234401b49f","sourceKey":"bank:ACC101:A101N2-091","payload":{"prompt":"A business keeps sales, purchases and general ledgers, among others. Which book listed below is NOT a ledger?","options":["Sales (receivables) ledger","Sales day book","General (nominal) ledger","Purchases (payables) ledger"],"correctOption":1,"section":"Ledger accounts and types of accounts","explanation":"The four types of ledger are the sales ledger, the purchases ledger, the general ledger, and the cash book with the petty cash book. The sales day book is a book of prime entry, not a ledger; its entries are posted to the sales ledger and the sales account."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 305, $official_bank_source${"itemId":"5b270643-8e1d-5ce8-99cd-8b89c375e342","questionId":"99fad6ab-a0b9-5b5e-bb90-882ab6d458b3","sourceKey":"bank:ACC101:A101N2-092","payload":{"prompt":"The accounts of the suppliers from whom a business buys goods on credit are kept in the","options":["General (nominal) ledger","Purchases (payables) ledger","Sales (receivables) ledger","Petty cash book"],"correctOption":1,"section":"Ledger accounts and types of accounts","explanation":"Suppliers' accounts are kept in the purchases ledger, also called the payables or creditors ledger. The sales ledger is the tempting choice, but it holds the personal accounts of customers, not suppliers. The general ledger holds the nominal and real accounts."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 306, $official_bank_source${"itemId":"25d30d7d-659c-5878-8848-851da17a4101","questionId":"9e1a8591-c86b-5505-b74b-9fde22a18382","sourceKey":"bank:ACC101:A101N2-093","payload":{"prompt":"The sales ledger is also known as the","options":["Nominal ledger","Private ledger","Payables (creditors) ledger","Receivables (debtors) ledger"],"correctOption":3,"section":"Ledger accounts and types of accounts","explanation":"The sales ledger holds customers' personal accounts, so it is also called the receivables or debtors ledger. The payables or creditors ledger is the purchases ledger, which holds suppliers' accounts, and the nominal ledger is another name for the general ledger."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 307, $official_bank_source${"itemId":"826638c4-b837-57b9-9936-b54ea7f182d9","questionId":"c09ee1eb-91b6-51a1-aedf-39f9dff18ae0","sourceKey":"bank:ACC101:A101N2-094","payload":{"prompt":"The general (nominal) ledger contains","options":["Suppliers' personal accounts only","Customers' personal accounts only","Cash and bank transactions only","Nominal accounts and real accounts"],"correctOption":3,"section":"Ledger accounts and types of accounts","explanation":"The general ledger holds nominal accounts such as expenses, wages, rent, sales and purchases, and real accounts such as land, buildings, vehicles, inventory and plant. Customers' accounts are in the sales ledger, suppliers' accounts in the purchases ledger, and cash and bank transactions in the cash book."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 308, $official_bank_source${"itemId":"9a9672df-8668-5ef2-a0df-9e44f040e09e","questionId":"274d836e-48f9-56fa-a3dc-c0955f750c5d","sourceKey":"bank:ACC101:A101N2-095","payload":{"prompt":"In which ledger would a firm in Ikeja keep its land and buildings accounts?","options":["Sales ledger","Purchases ledger","Petty cash book","General ledger"],"correctOption":3,"section":"Ledger accounts and types of accounts","explanation":"Land and buildings are real accounts, and real accounts are kept in the general ledger together with the nominal accounts. The sales and purchases ledgers hold personal accounts of customers and suppliers, and the petty cash book records small cash transactions."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 309, $official_bank_source${"itemId":"b29f106a-c973-5a5e-9170-1578c290f7e9","questionId":"30b94e19-2f20-5061-922e-ed6590a1259d","sourceKey":"bank:ACC101:A101N2-096","payload":{"prompt":"A business's wages account and bad debts account are kept in the","options":["General ledger","Cash book","Purchases ledger","Sales ledger"],"correctOption":0,"section":"Ledger accounts and types of accounts","explanation":"Wages and bad debts are nominal accounts, which are kept in the general (nominal) ledger. The bad debts account may look linked to customers, but the customers' own accounts are in the sales ledger; the expense account itself is in the general ledger. The purchases ledger holds suppliers' accounts."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 310, $official_bank_source${"itemId":"f8266a76-a375-550d-b181-8fa084938c4c","questionId":"34743a33-b224-5953-9c9b-def8f10d9bb3","sourceKey":"bank:ACC101:A101N2-097","payload":{"prompt":"A UNILAG department buys new office furniture for its staff room. The furniture account is best described as","options":["A personal account","A purchases account","A real account","A nominal account"],"correctOption":2,"section":"Ledger accounts and types of accounts","explanation":"Furniture bought for use is a tangible asset of the department, so its account is a real account. It is not a nominal account, because it is not a gain or loss, and not a personal account, because it is not kept for a person. The purchases account is for goods bought for resale."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 311, $official_bank_source${"itemId":"fb58535f-aa24-58f6-bd8f-2e60743985f0","questionId":"37f59a16-1fbb-53bb-a11d-885b00d4c937","sourceKey":"bank:ACC101:A101N2-098","payload":{"prompt":"In the books of a printing firm in Yaba, which of these accounts would be kept as a personal account?","options":["The salaries account","The account of Femi Ventures, a credit customer","The commission received account","The plant and machinery account"],"correctOption":1,"section":"Ledger accounts and types of accounts","explanation":"Femi Ventures is a business customer buying on credit, and accounts for persons, companies or partnerships are personal accounts. Plant and machinery is a real account, while commission received and salaries are gains and losses recorded in nominal accounts."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 312, $official_bank_source${"itemId":"5ae256c3-e291-5c1c-840c-75d30c2fe2b6","questionId":"5e82ca42-820f-5d17-9702-df9c08bea4d8","sourceKey":"bank:ACC101:ACC-0012","payload":{"prompt":"The cash book showed a debit balance of N1,000 in the bank column. On the same day, the bank statement showed a credit balance of N900. Which could be the reason for this difference?","options":["Standing order for property tax paid directly by the bank","Bank interest received","Direct credit received from a customer","Unpresented cheque"],"correctOption":0,"section":"Cash book and bank reconciliation","explanation":"The bank balance (N900) is N100 lower than the cash book balance (N1,000), so the bank must have taken money out that the cash book has not recorded yet - a standing order paid directly by the bank does exactly that. Options B, C and D would all make the bank statement balance higher than the cash book, not lower."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 313, $official_bank_source${"itemId":"e6d35c21-f727-553e-ad2f-19df71f291f6","questionId":"ebf11eba-23ae-5d0b-aaf3-e93a00bd77d5","sourceKey":"bank:ACC101:ACC-0014","payload":{"prompt":"When preparing a bank reconciliation statement, which of the following is deducted from the balance as per bank statement?","options":["Uncredited cheques","Unpresented cheques","Bank charges","Returned cheques"],"correctOption":1,"section":"Cash book and bank reconciliation","explanation":"Unpresented cheques have already been deducted in the cash book but have not yet left the bank account, so they are deducted from the bank statement balance to arrive at the cash book balance. Option A, uncredited cheques, is added to the bank statement balance instead, while options C and D are corrections made in the cash book itself."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 314, $official_bank_source${"itemId":"2602eb44-e33b-5862-8e26-85af190328da","questionId":"4f184e53-2c2d-5f01-891d-c60c498e228c","sourceKey":"bank:ACC101:ACC-0015","payload":{"prompt":"In bank reconciliation, direct transfer is posted to where?","options":["The credit side of cash book","The debit side of bank statement","The credit side of bank statement","The debit side of adjusted cash book"],"correctOption":3,"section":"Cash book and bank reconciliation","explanation":"A direct transfer into the business account is money already received by the bank but not yet recorded by the business, so it is entered on the debit (receipts) side when the cash book is adjusted. Option A would treat it as a payment, and options B and C refer to the bank's own statement, which already shows it."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 315, $official_bank_source${"itemId":"2cb88b29-f7f5-5a00-8010-f31b8c6e5486","questionId":"cc72ce6d-b338-5780-955b-d7c144ebea3a","sourceKey":"bank:ACC101:ACC-0025","payload":{"prompt":"Where is an unpresented cheque found?","options":["On the debit side of the cash book","On the credit side of the cash book","On the credit side of bank reconciliation","On the debit side of bank statement"],"correctOption":1,"section":"Cash book and bank reconciliation","explanation":"An unpresented cheque is one the business has written and recorded as a payment, so it sits on the credit (payments) side of the cash book, but the bank has not paid it yet. Option A is where receipts go, and option D is wrong because the bank has not yet recorded it at all."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 316, $official_bank_source${"itemId":"8dd90513-50c5-5cf8-b3a5-7ad8428c7799","questionId":"b12e5288-2e08-55b4-ad86-7cbe9b5726c7","sourceKey":"bank:ACC101:ACC-0034","payload":{"prompt":"What is the effect of bank charges on adjusted cash book","options":["It Reduces the adjusted cash book balance","It has no effect","It can increase or reduce the adjusted cash book balance","It increases the adjusted cash book balance"],"correctOption":0,"section":"Cash book and bank reconciliation","explanation":"Bank charges are money the bank has already taken from the account, so they are entered on the credit side of the cash book and reduce the adjusted cash book balance. Option D gets the direction wrong, and option C is wrong because charges can only reduce the balance."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 317, $official_bank_source${"itemId":"82424d28-5f1e-55ef-be93-0151248e5a24","questionId":"f4dbb3f2-329a-5701-801b-b612edac8ff8","sourceKey":"bank:ACC101:ACC-0036","payload":{"prompt":"The discount values in the cashbook should, at an agreed period be","options":["Balanced against each other","Deducted from respective cash balances in the cash book","Added to respective bank balances in the cash book","Transferred in total to their respective accounts"],"correctOption":3,"section":"Cash book and bank reconciliation","explanation":"The discount columns in a three-column cash book are memorandum columns, so their totals are transferred periodically to the discount allowed and discount received accounts in the ledger. Option A is wrong because the two discounts are separate items, and options B and C would mix discounts with real cash and bank balances."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 318, $official_bank_source${"itemId":"ad253d58-18d7-58e7-a3a5-3a476a7b27eb","questionId":"cbb2e91e-c696-5ab0-92d4-f35d5486323c","sourceKey":"bank:ACC101:ACC-0039","payload":{"prompt":"After the cash book has been updated (adjusted), which of the listed items are used to prepare the bank reconciliation statement? I Direct credit; II Error made by bank; III Dishonoured cheques; IV Error made by the cashier; V Uncredited cheques; VI Bank charges; VII Unpresented cheques","options":["III, IV and VI","I, II, V, and VII","II, III, IV and VI","II, V, and VII"],"correctOption":3,"section":"Cash book and bank reconciliation","explanation":"A bank reconciliation statement shows the items that explain why the updated cash book and the bank statement still differ: errors made by the bank, uncredited cheques (lodgements not yet credited) and unpresented cheques. Direct credits, dishonoured cheques, bank charges and cashier errors are put right in the cash book first, which is why options A, B and C are wrong."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 319, $official_bank_source${"itemId":"1928af66-3d5a-5a56-a096-1fc69bfbb4c8","questionId":"26c921e4-89f1-581a-9534-9f71e4005d6b","sourceKey":"bank:ACC101:ACC-0163","payload":{"prompt":"The difference between the balance in a company's cash account and its bank statement is documented in the ____ of the bank statement.","options":["Net loss","Reconciliation","Materiality","Conservatism"],"correctOption":1,"section":"Cash book and bank reconciliation","explanation":"A bank reconciliation statement explains the differences between the cash book balance and the bank statement balance, such as unpresented cheques and lodgements not yet credited. Materiality (Option C) and conservatism (Option D) are accounting concepts, not documents that compare the two balances."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 320, $official_bank_source${"itemId":"bc30433b-6cb6-5803-90f3-95c3ba47c694","questionId":"9f1a826c-eebc-5772-a4fa-0e053b5357c5","sourceKey":"bank:ACC101:ACC-0198","payload":{"prompt":"Which of the following would not cause a difference between a bank statement and cash book","options":["Book-keeping errors in bank statement","Book-keeping errors in cash book (bank column)","Bookkeeping errors in petty cash book","Direct debits in bank statement"],"correctOption":2,"section":"Cash book and bank reconciliation","explanation":"The petty cash book records small cash payments and has nothing to do with the bank account, so its errors cannot cause a difference between the cash book (bank column) and the bank statement. Errors in the bank statement (Option A), errors in the bank column of the cash book (Option B) and direct debits not yet in the cash book (Option D) are all normal reasons for a difference."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 321, $official_bank_source${"itemId":"d9bab4c0-73c8-5160-a590-ed303df11daf","questionId":"46c3a7d8-fb8b-5a1a-af7d-aa499d188c42","sourceKey":"bank:ACC101:ACC-0206","payload":{"prompt":"Which of the following items should not appear on the debit side of the bank statement?","options":["Cheques issued by account holders and paid by the bank","Direct debit","Standing order","Dividend received by the bank on behalf of the account holder"],"correctOption":3,"section":"Cash book and bank reconciliation","explanation":"The debit side of a bank statement shows money going out of the customer's account, such as cheques paid, direct debits and standing orders. A dividend collected by the bank for the customer increases the account, so it appears on the credit side. Options A, B and C are all withdrawals and correctly appear as debits."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 322, $official_bank_source${"itemId":"23c769d1-7773-58d3-a716-51ad446b0692","questionId":"d140354c-e3e8-5d88-bbbb-7eff35bf6535","sourceKey":"bank:ACC101:ACC-0207","payload":{"prompt":"Which of the following may have been recorded in the cash book and yet fail to appear in the bank statement?","options":["Bank charges and commission","cheques issued, presented and cashed","Bank lodgements","Payments made by the bank on standing order"],"correctOption":2,"section":"Cash book and bank reconciliation","explanation":"A lodgement entered in the cash book may not yet have been credited by the bank by the statement date, so it appears in the cash book but not on the bank statement. Option B is wrong because a cheque that has been presented and cashed has already passed through the bank account. Options A and D are the opposite case: the bank records them first, and they are often missing from the cash book."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 323, $official_bank_source${"itemId":"95c17180-dc73-5e57-abcc-92c50f0704aa","questionId":"ed556b42-91d8-5c50-b0af-48a7bccf6905","sourceKey":"bank:ACC101:ACC-0211","payload":{"prompt":"Which of the following items appearing on bank reconciliation would require an adjusting entry?","options":["Outstanding cheques","Uncredited cheques","Interest on balance","Adjusted cash balance"],"correctOption":2,"section":"Cash book and bank reconciliation","explanation":"Interest credited by the bank appears on the bank statement but is not yet in the cash book, so the business must make an entry to record it. Outstanding cheques (A) and uncredited cheques (B) are timing differences already correctly recorded in the cash book, and they clear on their own when the bank processes them. Option D is a result of the reconciliation, not an item needing an entry."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 324, $official_bank_source${"itemId":"b50c52ee-e4bf-5a82-98cb-4e15a46620c3","questionId":"72a4578a-1696-5d68-b4d2-1d6991bcad9a","sourceKey":"bank:ACC101:ACC-0256","payload":{"prompt":"A bank reconciliation statement explains the difference between which two balances?","options":["The bank statement balance and the cash book (bank column) balance","The imprest and the cash book balance","The trial balance and the ledger balance","None of the above"],"correctOption":0,"section":"Cash book and bank reconciliation","explanation":"A bank reconciliation statement explains why the balance on the bank statement differs from the bank column balance in the cash book, for example because of unpresented cheques or bank charges. Option B mentions the imprest, which belongs to petty cash, not the bank account. Option C describes the trial balance, which checks ledger balances and has nothing to do with the bank."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 325, $official_bank_source${"itemId":"f39b26e8-89d3-5a57-baa5-eb3f922e553e","questionId":"9c88c173-f23c-527d-8f68-abf07dace52b","sourceKey":"bank:ACC101:ACC-0282","payload":{"prompt":"A book showing statement of payment and receipt balances","options":["cash book","journal","ledger","all of the above"],"correctOption":0,"section":"Cash book and bank reconciliation","explanation":"The cash book records cash and bank receipts on the debit side and payments on the credit side, and it is balanced off to show the cash and bank balances. A journal (B) is a book of prime entry for unusual transactions, and the ledger (C) contains accounts of all kinds, not specifically receipts and payments."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 326, $official_bank_source${"itemId":"a40b7bbc-3f11-5d95-8d87-28334b24dd91","questionId":"c88449a8-889e-5fd5-a584-eeea843cb09f","sourceKey":"bank:ACC101:ACC-0333","payload":{"prompt":"In a bank reconciliation statement, which of the following would be added to the balance as per bank statement?","options":["Service charge","Direct transfer","Outstanding cheques","Uncredited cheques"],"correctOption":3,"section":"Cash book and bank reconciliation","explanation":"Uncredited cheques (lodgements already entered in the cash book but not yet shown by the bank) are added to the bank statement balance to arrive at the cash book balance. Option C (outstanding or unpresented cheques) is deducted from the bank statement balance, not added. Options A and B are items that need to be entered in the cash book rather than adjusted on the bank statement balance."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 327, $official_bank_source${"itemId":"81dc71be-8ef2-5bdf-823a-fce1cee51356","questionId":"0b254328-1e77-5003-aea8-63a881b76559","sourceKey":"bank:ACC101:ACC-0343","payload":{"prompt":"When is a petty cash account debited?","options":["When the fund is established and every time money is spent","Every time money is drawn from the petty cash","When the fund is established and when the size of the float is decreased","When the fund is established and every time money is replenished"],"correctOption":3,"section":"Cash book and bank reconciliation","explanation":"Under the imprest system the petty cash account is debited when the float is first set up and each time it is topped up (reimbursed) to the original amount. Options A and B are wrong because spending petty cash is recorded on the credit side. Option C is wrong because reducing the float takes money out, which is a credit."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 328, $official_bank_source${"itemId":"de8ebb96-d01f-5ee8-9891-4bebc634fc21","questionId":"14bb1dec-7324-518d-b47a-77356ec0793b","sourceKey":"bank:ACC101:ACC-0345","payload":{"prompt":"Which of the following Items is not recorded in the cash book?","options":["Bank charges","Depreciation of equipment","Salaries of workers","Receipt from a debtor"],"correctOption":1,"section":"Cash book and bank reconciliation","explanation":"Depreciation is a non-cash expense, so it never passes through the cash book; it is recorded through the journal. Bank charges, salaries and receipts from debtors (options A, C and D) all involve actual movements of money, so they are recorded in the cash book."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 329, $official_bank_source${"itemId":"c8d796db-c338-510d-96f4-351302428005","questionId":"a9c0a8da-b216-592a-95dd-9782b7a150d8","sourceKey":"bank:ACC101:ACC-0352","payload":{"prompt":"A credit balance in the bank column of double column cash book is an Indication of","options":["Bank overdraft","Bank owing to the business","Shortfall of cash at hand","Surplus of cash in the bank"],"correctOption":0,"section":"Cash book and bank reconciliation","explanation":"In the cash book the debit side shows money coming in and the credit side money going out, so a credit balance in the bank column means more has been paid out than the business has in the bank: an overdraft. Options B and D describe a debit balance, and option C is wrong because the bank column has nothing to do with cash at hand."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 330, $official_bank_source${"itemId":"7247fee4-cd75-5367-8f75-fa10f7453242","questionId":"d02fef8c-a27e-564a-b386-1fbff0317a62","sourceKey":"bank:ACC101:ACC-0359","payload":{"prompt":"The unticked items on the debit side of the bank statement could be all of the following except","options":["Direct debit","Bank charges","Direct transfer","Dishonoured cheque"],"correctOption":2,"section":"Cash book and bank reconciliation","explanation":"Items on the debit side of the bank statement that are not yet in the cash book are amounts the bank has taken out of the account, such as direct debits, bank charges and dishonoured cheques (options A, B and D). A direct (credit) transfer is money paid into the account, so it appears on the credit side of the bank statement and is the exception."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 331, $official_bank_source${"itemId":"29aaaafb-fc01-569e-b990-5905e151c9bc","questionId":"af7cfd2f-381f-5705-9a90-488e42a63595","sourceKey":"bank:ACC101:A101N2-099","payload":{"prompt":"The cash book is said to be both a journal and a ledger because it","options":["Lists the balances of all accounts at the end of the period","Records transactions as they happen, and double entry is completed in it","Records only credit transactions and their totals","Is prepared by the bank and checked by the business"],"correctOption":1,"section":"Cash book and bank reconciliation","explanation":"The cash book acts as a journal because transactions are written in it as they happen, and as a ledger because double entry is completed within it. It is kept by the business, not the bank, it records cash rather than credit transactions, and a list of balances is a trial balance."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 332, $official_bank_source${"itemId":"f709c145-0042-5b29-a40d-17cbd4f379db","questionId":"3b5c6bf6-0856-52b3-b354-a91bfb185264","sourceKey":"bank:ACC101:A101N2-100","payload":{"prompt":"On which side of the cash book are receipts recorded?","options":["The debit side","The discount side","The credit side","Either side, depending on the amount"],"correctOption":0,"section":"Cash book and bank reconciliation","explanation":"The cash book is an asset account, so receipts, which increase cash or bank, go on the debit side and payments go on the credit side. The credit side is the tempting answer for anyone thinking from the bank statement's point of view, where lodgements are shown as credits."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 333, $official_bank_source${"itemId":"070c238b-6e61-5779-bea7-fbca80166bc7","questionId":"638bfa31-1acc-5edc-84f1-4327076d7481","sourceKey":"bank:ACC101:A101N2-101","payload":{"prompt":"A trader in Balogun market pays N50,000 of office cash into the business bank account. How is this recorded in a two-column cash book?","options":["As a contra entry: debit the bank column and credit the cash column","Debit the cash column and credit the bank column","Debit capital and credit the bank column","Debit the bank column only, with no other entry"],"correctOption":0,"section":"Cash book and bank reconciliation","explanation":"Moving money between cash and bank is a contra entry within the cash book: the bank column is debited because bank increases, and the cash column is credited because cash decreases. Debiting cash and crediting bank reverses the movement. Both sides must be recorded, and capital is not involved since the money stays in the business."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 334, $official_bank_source${"itemId":"cace8909-f8e1-56f4-992b-f3acc7127083","questionId":"2ff5d0b4-0065-5fc9-88a3-d6565305314b","sourceKey":"bank:ACC101:A101N2-102","payload":{"prompt":"A three-column cash book has money columns for","options":["Cash, bank and petty cash","Bank, discount and drawings","Cash, bank and discount","Cash, discount and capital"],"correctOption":2,"section":"Cash book and bank reconciliation","explanation":"The three-column cash book has columns for cash, bank and discount. The two-column cash book has only cash and bank, and the single-column cash book has just one of them. Petty cash is kept in a separate petty cash book."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 335, $official_bank_source${"itemId":"55c2e282-7337-5288-bfb8-b6d9fdd59d09","questionId":"41fde538-1fbd-5dc8-8c8d-f3307172b69a","sourceKey":"bank:ACC101:A101N2-103","payload":{"prompt":"In a three-column cash book, discount allowed and discount received are recorded","options":["Discount allowed on the credit side and discount received on the debit side","Both on the credit side","Discount allowed on the debit side and discount received on the credit side","Both on the debit side"],"correctOption":2,"section":"Cash book and bank reconciliation","explanation":"Discount allowed is given to customers when they pay, so it sits on the debit (receipts) side next to the money received. Discount received is given by suppliers when the business pays, so it sits on the credit (payments) side. Swapping the two is the common slip."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 336, $official_bank_source${"itemId":"1edc5d84-1e88-59a2-b0d0-9093cac57627","questionId":"56ddb7c0-4474-5489-ac54-534a0a4c1d52","sourceKey":"bank:ACC101:A101N2-104","payload":{"prompt":"On a bank statement, the credit column shows","options":["Unpresented cheques issued by the customer","Bank charges deducted by the bank","Payments and withdrawals from the account","Lodgements paid into the account"],"correctOption":3,"section":"Cash book and bank reconciliation","explanation":"The bank statement is the bank's record of the customer's account, which is a liability to the bank, so lodgements are shown in the credit column. Payments, withdrawals and bank charges are shown in the debit column. Unpresented cheques do not appear on the statement at all, because they have not yet reached the bank."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 337, $official_bank_source${"itemId":"9c8634fa-fd1e-56d1-bd44-dc500be33814","questionId":"5059c418-bfbd-5a1d-9d95-6210f3cdfc83","sourceKey":"bank:ACC101:A101N2-105","payload":{"prompt":"Which of the following is NOT a reason for preparing a bank reconciliation statement?","options":["To calculate the depreciation charge for the year","To detect and prevent fraud","To update the cash book","To highlight errors made by the bank"],"correctOption":0,"section":"Cash book and bank reconciliation","explanation":"A bank reconciliation statement is prepared to update the cash book, correct errors, detect and prevent fraud, and highlight bank errors. Depreciation is a year-end adjustment to non-current assets and has nothing to do with comparing the cash book with the bank statement."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 338, $official_bank_source${"itemId":"109b92e0-f061-5846-a04d-c986c60f325c","questionId":"cea06de4-cc07-5e5b-bbd0-405256e2d445","sourceKey":"bank:ACC101:A101N2-106","payload":{"prompt":"A cheque received from a customer has been entered on the debit side of the cash book but has not yet been credited by the bank. This is called","options":["An unpresented cheque","A dishonoured cheque","An uncredited cheque","A standing order"],"correctOption":2,"section":"Cash book and bank reconciliation","explanation":"An uncredited cheque has been received and debited in the cash book but not yet credited by the bank. An unpresented cheque is the opposite case: one the business has issued and credited in the cash book that the payee has not yet presented. A dishonoured cheque is one the paying bank refuses."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 339, $official_bank_source${"itemId":"5ca966f7-4f76-5c29-8370-7de9b8da3f41","questionId":"10211141-16a7-5828-bca0-ba297e85ee44","sourceKey":"bank:ACC101:A101N2-107","payload":{"prompt":"A written instruction by a customer to the bank to pay a fixed sum regularly to a named payee is known as a","options":["Standing order","Credit transfer","Pay-in slip","Dishonoured cheque"],"correctOption":0,"section":"Cash book and bank reconciliation","explanation":"A standing order is the customer's written instruction to the bank to pay a fixed amount regularly to a named payee, and it appears as a debit on the bank statement. A credit transfer is money paid directly into the account, which is the opposite direction. A pay-in slip is used to lodge money."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 340, $official_bank_source${"itemId":"d2fdc054-d24b-58dc-b6b8-8ab859c6bccc","questionId":"06af6220-2a76-5c01-a532-f30e5ad85784","sourceKey":"bank:ACC101:A101N2-108","payload":{"prompt":"Which of the following is NOT a reason for a bank to dishonour a cheque?","options":["The amounts in words and figures differ","The cheque has an alteration that has not been endorsed","There are insufficient funds in the drawer's account","The cheque was paid into the bank on the same day it was received"],"correctOption":3,"section":"Cash book and bank reconciliation","explanation":"Paying a cheque in promptly is perfectly normal and gives the bank no reason to refuse it. Cheques are dishonoured for defects such as insufficient funds, an irregular or missing signature, words and figures that differ, no date or a post-dated cheque, or an unendorsed alteration."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 341, $official_bank_source${"itemId":"81fb0edf-0120-5ac3-8706-eb82fdd17da6","questionId":"ea1dd112-1113-57c4-b8fa-3eeb7333651f","sourceKey":"bank:ACC101:A101N2-110","payload":{"prompt":"When the cash book is ticked against the bank statement, unticked items on the credit side of the cash book are","options":["Uncredited cheques","Standing orders","Unpresented cheques","Credit transfers"],"correctOption":2,"section":"Cash book and bank reconciliation","explanation":"The credit side of the cash book records payments, so an unticked credit is a cheque the business has issued that has not yet reached the bank: an unpresented cheque. Uncredited cheques are found among the unticked debits of the cash book, while credit transfers and standing orders are found among the unticked items on the bank statement."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 342, $official_bank_source${"itemId":"fe967b50-6c6c-53c1-81e3-e0f9133a2135","questionId":"3406b4c4-55bd-50bb-826d-7ddb5e32f5bc","sourceKey":"bank:ACC101:A101N2-111","payload":{"prompt":"In preparing the adjusted (updated) cash book, a cheque from a customer that the bank has returned as dishonoured is","options":["Debited to the adjusted cash book","Left out because it was already recorded as a receipt","Credited to the adjusted cash book","Added to the bank statement balance in the BRS"],"correctOption":2,"section":"Cash book and bank reconciliation","explanation":"The dishonoured cheque was earlier debited as a receipt, but the money never arrived, so it is credited in the adjusted cash book to reverse it. Debiting it would count the receipt twice. It belongs in the adjusted cash book, not the BRS, which contains only uncredited cheques, unpresented cheques and bank errors."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 343, $official_bank_source${"itemId":"a3acdf44-6ce1-5d7b-a174-282946964103","questionId":"0c37b461-41b7-506a-ac7d-c2730079195e","sourceKey":"bank:ACC101:A101N2-112","payload":{"prompt":"A bank in Lagos collects a dividend directly for its customer and credits it to the customer's account. When the business prepares its adjusted cash book, the dividend is","options":["Recorded only in the bank statement and never in the cash book","Credited to the adjusted cash book","Debited to the adjusted cash book","Deducted from the bank statement balance in the BRS"],"correctOption":2,"section":"Cash book and bank reconciliation","explanation":"A dividend received by the bank on the customer's behalf is a direct credit, which increases the business's bank balance, so it is debited to the adjusted cash book. Crediting it would reduce the balance. Once the cash book has been updated, the dividend does not need to appear in the BRS at all."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 344, $official_bank_source${"itemId":"fef3fee2-0776-581c-8c93-85bd804158a0","questionId":"d0a7d26b-ae65-56f0-bbd7-bf0a4b73dbe0","sourceKey":"bank:ACC101:A101N2-113","payload":{"prompt":"Items that appear on the bank statement but not yet in the cash book include","options":["Discount allowed and discount received","Contra entries between cash and bank","Uncredited cheques and unpresented cheques","Direct debits and direct credits, such as bank charges and credit transfers"],"correctOption":3,"section":"Cash book and bank reconciliation","explanation":"Items in the bank statement but not in the cash book are direct debits, such as standing orders and bank charges, and direct credits, such as credit transfers, dividends and interest. Uncredited and unpresented cheques are the reverse case: they are in the cash book but not yet in the bank statement."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 345, $official_bank_source${"itemId":"45727c5f-da38-550c-9fb1-8c0c94a61792","questionId":"99048407-f37d-5198-9f8c-6321adefbfd2","sourceKey":"bank:ACC101:A101N2-114","payload":{"prompt":"A firm's cash book shows a debit bank balance of N180,000. The bank statement reveals bank charges of N2,500, a standing order of N12,000, a credit transfer of N30,000 and a dishonoured cheque of N8,000, none yet in the cash book. What is the adjusted cash book balance?","options":["N127,500 debit","N157,500 debit","N187,500 debit","N195,500 debit"],"correctOption":2,"section":"Cash book and bank reconciliation","explanation":"Add the credit transfer and deduct the bank charges, standing order and dishonoured cheque: 180,000 + 30,000 - 2,500 - 12,000 - 8,000 = N187,500. N195,500 forgets to deduct the dishonoured cheque, which reverses an earlier receipt. N157,500 leaves out the credit transfer, and N127,500 wrongly deducts it instead of adding it."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 346, $official_bank_source${"itemId":"ea2b413c-a592-570d-972e-cd7a6ea4bd93","questionId":"f956f322-2663-549f-b491-617f8cf4f91b","sourceKey":"bank:ACC101:A101N2-115","payload":{"prompt":"A trader's adjusted cash book shows a debit balance of N187,500. There are unpresented cheques of N45,000 and uncredited cheques of N22,000. What balance should the bank statement show?","options":["N120,500","N164,500","N210,500","N254,500"],"correctOption":2,"section":"Cash book and bank reconciliation","explanation":"Starting from the adjusted cash book, add back unpresented cheques and deduct uncredited cheques: 187,500 + 45,000 - 22,000 = N210,500. N164,500 reverses the two adjustments. N254,500 adds both items, forgetting that uncredited cheques are not yet in the bank balance."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 347, $official_bank_source${"itemId":"924c8281-ec01-58e0-a44e-11eb3a54bb4d","questionId":"c20f830b-38e9-5f9a-ad29-afed2c6911d2","sourceKey":"bank:ACC101:A101N2-116","payload":{"prompt":"A business's cash book shows a bank overdraft of N40,000. The bank statement shows bank charges of N1,500 and a direct credit of N10,000, neither yet in the cash book. What is the adjusted cash book balance?","options":["An overdraft of N31,500","An overdraft of N48,500","A favourable balance of N31,500","An overdraft of N51,500"],"correctOption":0,"section":"Cash book and bank reconciliation","explanation":"Bank charges make the overdraft larger and the direct credit reduces it: 40,000 + 1,500 - 10,000 = N31,500 overdrawn. N51,500 treats the direct credit as if it increased the overdraft, and N48,500 adds the credit and deducts the charges the wrong way round. The account is still overdrawn because the credit is smaller than the overdraft."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 348, $official_bank_source${"itemId":"636e773c-d9ea-5c85-b4f4-d97c717a7b95","questionId":"1830515d-1c10-547a-9bce-26b763e98c0e","sourceKey":"bank:ACC101:A101N2-117","payload":{"prompt":"The bank statement of a shop in Ikeja shows a favourable balance of N95,000. Uncredited cheques total N18,000 and unpresented cheques total N27,500. Starting from the bank statement, what is the balance per cash book?","options":["N140,500","N85,500","N49,500","N104,500"],"correctOption":1,"section":"Cash book and bank reconciliation","explanation":"Starting from the bank statement, add uncredited cheques and deduct unpresented cheques: 95,000 + 18,000 - 27,500 = N85,500. N104,500 reverses the two adjustments, and N140,500 adds both of them. Uncredited cheques are added because the cash book already includes them, while unpresented cheques are deducted because the cash book has already paid them out."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 349, $official_bank_source${"itemId":"14857654-07c7-581d-9f09-88b1cbd5bfd2","questionId":"b7f2a63f-3257-58b5-bfd3-7c05c78f9973","sourceKey":"bank:ACC101:A101N2-118","payload":{"prompt":"In a bank reconciliation statement, how is an overdrawn balance usually shown?","options":["In red ink with no sign","As a positive figure in a separate column","As a footnote below the statement","In brackets"],"correctOption":3,"section":"Cash book and bank reconciliation","explanation":"An overdraft is an abnormal balance, and in a bank reconciliation statement overdrawn balances are shown in brackets, for example (32,500). Showing it as a plain positive figure would make it look like money in the bank, and a footnote would leave it out of the calculation."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 350, $official_bank_source${"itemId":"a27bbc73-c717-579e-9d93-90c8e23ae2bf","questionId":"a28be7b7-9090-5d57-9b60-d2235873f9c8","sourceKey":"bank:ACC101:A101N2-119","payload":{"prompt":"When preparing a bank reconciliation statement, which balances are compared?","options":["The petty cash book and the bank statement","The cash column of the cash book and the opening balance on the bank statement","The discount columns and the bank statement","The bank column of the cash book and the closing balance on the bank statement"],"correctOption":3,"section":"Cash book and bank reconciliation","explanation":"The comparison is always between the bank column of the cash book and the bank statement, using the closing bank-statement balance. The cash column records physical cash held by the business, and the petty cash book and discount columns are not part of the bank account at all."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 351, $official_bank_source${"itemId":"2d4792bb-1f94-5b64-8e67-ce3db62bf80d","questionId":"662f6838-222f-5798-9591-a275cac05bd5","sourceKey":"bank:ACC101:ACC-0008","payload":{"prompt":"Trial balance could be used to","options":["Check accuracy of postings to ledger","Correct errors","To detect errors in the ledger","Provide details of transactions"],"correctOption":0,"section":"Trial balance and correction of errors","explanation":"A trial balance lists every ledger balance to check that total debits equal total credits, which confirms the arithmetical accuracy of the postings to the ledger. Option C is partly true, but many errors, such as errors of omission or principle, leave the trial balance in agreement, so checking accuracy is the best answer. Option B is wrong because a trial balance does not correct anything by itself."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 352, $official_bank_source${"itemId":"1fce2252-8b74-5c96-af59-fae652d747e7","questionId":"a28dce6d-cd8b-57c0-8f67-c609c37ec3e3","sourceKey":"bank:ACC101:ACC-0148","payload":{"prompt":"A listing of the balances in the accounts in order to determine whether debits are equal to credits is a ____ balance.","options":["Trial Balance","journal","balance sheet","Chart"],"correctOption":0,"section":"Trial balance and correction of errors","explanation":"A trial balance lists the balances on all ledger accounts to check that total debits equal total credits. The journal (Option B) is a book of original entry, the balance sheet (Option C) reports financial position, and a chart of accounts (Option D) only lists account names."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 353, $official_bank_source${"itemId":"fe0fbabe-b5a5-555a-87ef-53017bb822bb","questionId":"59592146-2663-5d27-903e-064091138fe0","sourceKey":"bank:ACC101:ACC-0248","payload":{"prompt":"___ is a statement which lists all the debit and credit balances of an organization","options":["suspense account","trial balance","profit and loss account","trading account"],"correctOption":1,"section":"Trial balance and correction of errors","explanation":"A trial balance lists all the debit and credit balances from the ledger accounts at a date, to check that total debits equal total credits. A suspense account (option A) only holds a difference temporarily. The trading account (option D) and the profit and loss account (option C) use some of these balances to work out profit, but they do not list all of them."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 354, $official_bank_source${"itemId":"0a75d72e-9339-5f55-9171-e505a710b166","questionId":"9513e49b-a761-51b1-8ecd-ea6fb0498dfa","sourceKey":"bank:ACC101:ACC-0254","payload":{"prompt":"In trial balance, all expenses are treated in the ___","options":["credit side","debit side","a and b are correct","none of the above"],"correctOption":1,"section":"Trial balance and correction of errors","explanation":"Expenses have debit balances in the ledger, so they appear on the debit side of the trial balance. The credit side (A) holds incomes, liabilities and capital. Option C is wrong because an expense balance cannot be on both sides."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 355, $official_bank_source${"itemId":"8847c04c-2c0f-5303-b7a1-f2982808aaad","questionId":"13297175-33d7-5199-af59-7862c037d142","sourceKey":"bank:ACC101:A101N3-001","payload":{"prompt":"Which of the following best describes a trial balance?","options":["A list of all debit and credit balances extracted from the ledger at the end of a period","A record of transactions in date order before they are posted to the ledger","A statement comparing the cash book balance with the bank statement balance","A statement showing the profit or loss made by a business for a period"],"correctOption":0,"section":"Trial balance and correction of errors","explanation":"A trial balance is a schedule of every debit and credit balance taken from the ledger at the end of a period, and its two column totals are expected to agree. A record of transactions in date order before posting describes a book of prime entry such as the journal, which comes before the ledger, not after it."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 356, $official_bank_source${"itemId":"fcc48371-7409-5e3b-a3fc-d7ed0530b243","questionId":"ce912934-fc7b-5551-af89-8658c9ecf1a9","sourceKey":"bank:ACC101:A101N3-002","payload":{"prompt":"Because it brings every ledger balance together in one schedule, a trial balance is often described as a","options":["Book of original entry","Summary of ledger balances","Bank reconciliation statement","Statement of financial position"],"correctOption":1,"section":"Trial balance and correction of errors","explanation":"A trial balance simply summarises the balances already sitting in the ledger accounts, which is why it is called a summary of ledger balances. A book of original entry is where transactions are first recorded before they ever reach the ledger, so it cannot be a summary of ledger balances."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 357, $official_bank_source${"itemId":"55a21d59-25da-51d7-a1ee-6ea5719d5243","questionId":"ef96df88-eecc-53b1-a6da-aff91b1b4d54","sourceKey":"bank:ACC101:A101N3-003","payload":{"prompt":"The main purpose of extracting a trial balance is to","options":["Show how much the business owes its bank at the year end","Confirm that the general ledger entries are balanced","Show the profit earned by the business for the year","Record transactions before they are posted to the ledger"],"correctOption":1,"section":"Trial balance and correction of errors","explanation":"A trial balance checks whether total debit balances equal total credit balances, which confirms that the general ledger entries are balanced. Showing the profit for the year is the job of the income statement, which is prepared later using the trial balance figures."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 358, $official_bank_source${"itemId":"9ea90dd4-e616-541f-88be-ee846cb246fa","questionId":"0dbbcf3a-7d26-5a6d-afa6-99008292517e","sourceKey":"bank:ACC101:A101N3-004","payload":{"prompt":"Which of the following is the correct heading for the trial balance of Femi Traders, Balogun market?","options":["Trial Balance as at 31 December 2025","Trial Balance for the year ended 31 December 2025","Trial Balance during the year 2025","Trial Balance for the period ended 31 December 2025"],"correctOption":0,"section":"Trial balance and correction of errors","explanation":"A trial balance lists the balances on the ledger accounts at one particular date, so its heading uses \"as at\" followed by that date. \"For the year ended\" describes a statement that covers a whole period, such as the income statement, so it does not suit a list of balances taken at a point in time."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 359, $official_bank_source${"itemId":"def56a3a-cd8d-5acd-b8dc-50af396b12d6","questionId":"fa996907-35e1-5ffa-811a-5e7bc74540c2","sourceKey":"bank:ACC101:A101N3-005","payload":{"prompt":"When a bookkeeper in Balogun market extracts a trial balance, the figure taken from each ledger account is the","options":["Largest single entry in the account","Opening balance at the start of the year","Total of the debit side of the account","Balance brought down (bal b/d)"],"correctOption":3,"section":"Trial balance and correction of errors","explanation":"Each ledger account is balanced off, and the balance brought down (bal b/d) is the figure listed in the trial balance. Using the total of the debit side would ignore the credit entries in the account and would not give the account's balance."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 360, $official_bank_source${"itemId":"1a19432d-4b8f-50ab-96c0-026b5b6199f0","questionId":"0e12c927-7c2a-5cbb-bad4-95c1bef25a10","sourceKey":"bank:ACC101:A101N3-006","payload":{"prompt":"A trial balance extracted from the ledger before any end-of-year adjustments have been made is called","options":["An adjusted trial balance","A suspense account","A post-closing trial balance","An unadjusted trial balance"],"correctOption":3,"section":"Trial balance and correction of errors","explanation":"Before items like accruals, prepayments and depreciation are adjusted for, the list of ledger balances is an unadjusted trial balance. An adjusted trial balance is the version prepared after those year-end adjustments have been put through, so it does not fit the description."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 361, $official_bank_source${"itemId":"3101702c-8501-5a77-b62e-cf0de946509d","questionId":"841a1504-e83f-59b4-997b-3e643b2f5056","sourceKey":"bank:ACC101:A101N3-007","payload":{"prompt":"All but one of these are uses of a trial balance. Identify the exception.","options":["It serves as the basis for preparing the final accounts","It checks the accuracy of postings and extraction","It helps auditors in their work","It proves that the ledger contains no errors at all"],"correctOption":3,"section":"Trial balance and correction of errors","explanation":"A trial balance whose totals agree only shows that debits equal credits; some errors, such as an error of omission, leave the totals in agreement, so it cannot prove the ledger is error-free. Checking the accuracy of postings and extraction is a genuine use, because a disagreement points to a posting or extraction mistake."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 362, $official_bank_source${"itemId":"eda7110f-776e-52d8-bc72-00cc012a0ade","questionId":"22651cbe-76bb-5ae0-afa9-8c1204c92025","sourceKey":"bank:ACC101:A101N3-008","payload":{"prompt":"A trial balance is said to give a \"bird's eye view\" of the books. This means it","options":["Shows the cash position as confirmed by the bank","Lists transactions in the order in which they occurred","Shows the detailed entries in each ledger account","Gives an overview of all the ledger balances at a glance"],"correctOption":3,"section":"Trial balance and correction of errors","explanation":"Like a view from above, a trial balance shows all the ledger balances together on one page, giving a quick overview of the books. It does not show the detailed entries inside each account; those are found only in the ledger accounts themselves."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 363, $official_bank_source${"itemId":"788ee871-a398-5da2-b533-81c49074aefd","questionId":"1b9fb6f8-ed59-58d5-ac5c-4dd72f5d04ec","sourceKey":"bank:ACC101:A101N3-009","payload":{"prompt":"Extracting a trial balance is important for several reasons. Which of these is not among them?","options":["It eases the preparation of the final accounts","It checks the arithmetical accuracy of the ledger","It records transactions in the order in which they occur","It aids comparative analysis"],"correctOption":2,"section":"Trial balance and correction of errors","explanation":"Recording transactions in date order is the job of the books of prime entry, such as the journal and day books, not the trial balance. Checking the arithmetical accuracy of the ledger is a real importance of the trial balance, since it tests whether total debits equal total credits."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 364, $official_bank_source${"itemId":"88004cef-3aa3-52a5-bd8a-6250a1924985","questionId":"3afff911-21a5-547b-849c-854e151452fb","sourceKey":"bank:ACC101:A101N3-010","payload":{"prompt":"The manager of a firm in Ikeja uses the figures in this year's trial balance to help draw up next year's spending plan. Which importance of the trial balance does this illustrate?","options":["It aids budgets and decision-making","It helps prepare the audit report","It checks the arithmetical accuracy of the ledger","It helps rectify ledger errors"],"correctOption":0,"section":"Trial balance and correction of errors","explanation":"Using trial balance figures to plan future spending is an example of the trial balance aiding budgets and decision-making. Rectifying ledger errors is a different importance: it is about finding and correcting mistakes, not planning ahead."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 365, $official_bank_source${"itemId":"50386ce2-3cd4-5f3a-b6ed-c3d304de09d5","questionId":"2c098119-69fc-5ec6-b627-5f3d38936fcd","sourceKey":"bank:ACC101:A101N3-011","payload":{"prompt":"The accountant of a UNILAG cooperative shop places this year's trial balance beside last year's to see how each expense has changed. This use of the trial balance is best described as","options":["Comparative analysis","Rectification of errors","Checking of arithmetical accuracy","Preparation of the audit report"],"correctOption":0,"section":"Trial balance and correction of errors","explanation":"Setting the figures of two years side by side to spot changes is comparative analysis, one of the stated importances of a trial balance. Checking arithmetical accuracy is about whether debits equal credits in one trial balance, not about comparing years."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 366, $official_bank_source${"itemId":"1edfdd31-fab4-5deb-bdd3-aacb823d8fab","questionId":"d11b0e6d-af72-5d7a-b090-b538c04b6134","sourceKey":"bank:ACC101:A101N3-012","payload":{"prompt":"Once a trial balance has been extracted and agrees, it is mainly used as the basis for preparing","options":["The sales invoices and receipts","The books of prime entry","The final accounts","The ledger accounts"],"correctOption":2,"section":"Trial balance and correction of errors","explanation":"The balances in an agreed trial balance are used to prepare the final accounts, that is, the income statement and the statement of financial position. Invoices, receipts, the books of prime entry and the ledger all come before the trial balance in the accounting process, so they cannot be prepared from it."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 367, $official_bank_source${"itemId":"7afd3804-05a3-50c2-a2bd-3037a962213d","questionId":"51de5109-1afd-5662-ba9c-5fe15c300a72","sourceKey":"bank:ACC101:A101N3-013","payload":{"prompt":"In a trial balance, which of the following balances is shown in the credit column?","options":["Motor vehicles","Purchases","Capital","Drawings"],"correctOption":2,"section":"Trial balance and correction of errors","explanation":"Capital is what the business owes its owner, so it is a credit balance in the trial balance. Drawings are a debit balance because they are recorded as Dr drawings when the owner takes value out of the business, which reduces capital."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 368, $official_bank_source${"itemId":"7d654318-09ec-5692-a992-5ec81cb2e519","questionId":"fe3b3bd3-f82b-507a-a9c9-96c1e458321a","sourceKey":"bank:ACC101:A101N3-014","payload":{"prompt":"Which of the following balances would appear in the debit column of a trial balance?","options":["Rent expense","Sales","Bank loan","Capital"],"correctOption":0,"section":"Trial balance and correction of errors","explanation":"Expenses are debit balances, so rent expense goes in the debit column. Sales is income and is therefore a credit balance, while a bank loan is a liability and capital is owed to the owner, both shown as credits."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 369, $official_bank_source${"itemId":"73e875fe-1757-5148-983e-68aa61552e5d","questionId":"85dad653-a2a3-5b54-9791-3ac5a177d48e","sourceKey":"bank:ACC101:A101N3-015","payload":{"prompt":"In a trial balance, the balance on a Commission received account is shown","options":["In the debit column, because it is an asset","In the credit column, because it is income","In the credit column, because it is a liability","In the debit column, because it is income"],"correctOption":1,"section":"Trial balance and correction of errors","explanation":"Commission received is income earned by the business, and income balances are credits in a trial balance. Placing it in the debit column because it is income gets the rule backwards: it is expenses, not income, that are debits."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 370, $official_bank_source${"itemId":"7f664b52-455c-5b60-bae5-1aae7686f2cf","questionId":"9c943665-7d5d-57d2-885e-f73c3b686059","sourceKey":"bank:ACC101:A101N3-016","payload":{"prompt":"A balance of N45,000 on the Prepaid insurance account appears in the trial balance as a","options":["Credit, because it is a liability","Debit, because it is an asset","Credit, because it is income","Debit, because it is an expense owing"],"correctOption":1,"section":"Trial balance and correction of errors","explanation":"Prepaid insurance is a payment made in advance for cover not yet used, so it is an asset and assets are debit balances. Treating it as a liability confuses it with an amount owing, such as salary payable, which would be a credit."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 371, $official_bank_source${"itemId":"38443d1b-2f58-5d41-8cd4-859d1373997f","questionId":"1cca1962-64ee-51aa-bf34-6085437e8182","sourceKey":"bank:ACC101:A101N3-017","payload":{"prompt":"Which pair of balances is correctly placed in a trial balance?","options":["Discounts received - debit; bad debts - debit","Discounts received - credit; bad debts - credit","Discounts received - debit; bad debts - credit","Discounts received - credit; bad debts - debit"],"correctOption":3,"section":"Trial balance and correction of errors","explanation":"Discounts received are a gain to the business, so they are a credit balance, while bad debts are an expense and therefore a debit balance. The pair with both as debits wrongly treats discounts received as a cost, when they actually reduce what the business pays."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 372, $official_bank_source${"itemId":"5c135a1b-73a5-5a63-a311-02bdf2bdbd69","questionId":"1e8a31f8-0c32-59a3-b25e-6055dc62cd8a","sourceKey":"bank:ACC101:A101N3-018","payload":{"prompt":"At the year end, a trader's ledger shows balances for prepaid insurance, salaries expense, salary payable and cash in hand. Which of these is a credit balance in the trial balance?","options":["Salary payable","Prepaid insurance","Cash in hand","Salaries expense"],"correctOption":0,"section":"Trial balance and correction of errors","explanation":"Salary payable is salary owed to staff but not yet paid, which is a liability and therefore a credit balance. Salaries expense is a tempting choice, but it is an expense, and expenses are debit balances."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 373, $official_bank_source${"itemId":"240f0f26-13f5-586f-9436-cb8bec383f72","questionId":"35866a74-ff46-565e-96b6-f9666c518ff7","sourceKey":"bank:ACC101:A101N3-019","payload":{"prompt":"Rent receivable of N5,000, being rent earned by the business but not yet received at the year end, appears in the trial balance as a","options":["Debit balance, because it is an expense","Debit balance, because it is an asset","Credit balance, because it is a liability","Credit balance, because it is income"],"correctOption":1,"section":"Trial balance and correction of errors","explanation":"Rent that has been earned but not yet received is accrued income, an amount owed to the business, so it is an asset and a debit balance. The rent income itself is a credit in the income account, but the receivable balance is the asset side of that entry, so calling the receivable a credit is wrong."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 374, $official_bank_source${"itemId":"63eecd48-90ad-59a6-90ce-2782d12ae352","questionId":"ba5ab056-e2f9-52ce-b22e-1d797f95fe73","sourceKey":"bank:ACC101:A101N3-020","payload":{"prompt":"Which of the following statements about a trial balance whose two totals agree is correct?","options":["The ledger is free from all errors","Every transaction must have been recorded at the correct amount","No transaction can have been posted to the wrong account","Errors may still exist in the ledger even though the totals agree"],"correctOption":3,"section":"Trial balance and correction of errors","explanation":"Agreement only shows that total debits equal total credits, and some errors, such as omissions or postings to the wrong account, leave the totals equal. Saying the ledger is free from all errors goes too far, because those errors would not show up as a difference."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 375, $official_bank_source${"itemId":"6e0c24ab-b03f-540b-a449-70a239af9ab7","questionId":"2459c7fe-dd1e-5709-a063-ceeebc7d9990","sourceKey":"bank:ACC101:A101N3-021","payload":{"prompt":"Errors discovered in the ledger are corrected by first recording the correcting entries in the","options":["Cash book","Sales day book","Journal","Petty cash book"],"correctOption":2,"section":"Trial balance and correction of errors","explanation":"The journal is the book of prime entry used for unusual entries, including the correction of errors, before they are posted to the ledger. The cash book records cash and bank receipts and payments, not corrections."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 376, $official_bank_source${"itemId":"8dbedab2-3850-55ad-bec0-0b4f64748d81","questionId":"7f117a30-49e5-5491-af7b-909a29d43b1b","sourceKey":"bank:ACC101:A101N3-022","payload":{"prompt":"Which of the following errors does NOT affect the agreement of the trial balance totals?","options":["Adding up one ledger account incorrectly","Listing a debit balance in the credit column of the trial balance","Error of complete reversal","Posting only the debit side of a transaction"],"correctOption":2,"section":"Trial balance and correction of errors","explanation":"In an error of complete reversal, the correct accounts are used but the debit and credit are swapped, so equal amounts still appear on both sides and the totals agree. Posting only the debit side of a transaction leaves the debits larger than the credits, so it does cause a difference."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 377, $official_bank_source${"itemId":"9b9d33a4-39c8-5e78-9377-2cb9485301fa","questionId":"6a89d600-c4ba-5aec-a2da-3642728097cf","sourceKey":"bank:ACC101:A101N3-023","payload":{"prompt":"Pick the group in which every error leaves the debit and credit totals of the trial balance equal.","options":["Original entry, complete reversal and compensating errors","Original entry, single entry and casting errors","Compensating, one-sided posting and casting errors","Principle, single entry and complete reversal"],"correctOption":0,"section":"Trial balance and correction of errors","explanation":"Errors of original entry, complete reversal and compensating errors all leave equal amounts on the debit and credit sides, so the trial balance still agrees. Any list containing a single entry or one-sided posting is wrong, because posting only one side of a transaction makes the totals differ."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 378, $official_bank_source${"itemId":"804016a2-fd38-5746-9df8-985114cadd59","questionId":"97311763-4c8c-5f09-9382-5e604b1e835d","sourceKey":"bank:ACC101:A101N3-024","payload":{"prompt":"When the two totals of a trial balance do not agree, the difference is temporarily entered in a","options":["Sundry expenses account","Drawings account","Suspense account","Capital account"],"correctOption":2,"section":"Trial balance and correction of errors","explanation":"A suspense account holds the difference in a trial balance until the errors causing it are found and corrected through the journal. Putting the difference in the capital account would hide the error inside the owner's balance instead of tracking it for correction."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 379, $official_bank_source${"itemId":"71574359-c604-5e04-83c6-c58cea3fbf23","questionId":"531b53f7-8914-5f46-83e1-5d2faa279f45","sourceKey":"bank:ACC101:A101N3-025","payload":{"prompt":"Chika Ventures, Ikeja, had the following balances at 31 December 2025: Capital N400,000; Equipment N250,000; Purchases N180,000; Sales N320,000; Trade payables N60,000; Trade receivables N90,000; Rent expense N40,000; Cash at bank N220,000. What is the total of the debit column of the trial balance?","options":["N560,000","N780,000","N1,560,000","N840,000"],"correctOption":1,"section":"Trial balance and correction of errors","explanation":"The debit balances are the assets and expenses: 250,000 + 180,000 + 90,000 + 40,000 + 220,000 = N780,000, which equals the credits of 400,000 + 320,000 + 60,000. N840,000 comes from wrongly treating trade payables, a liability, as a debit."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 380, $official_bank_source${"itemId":"480cb685-1f7b-5176-9cfa-981c5fa32c52","questionId":"bc45a2cd-4ff3-539c-bebc-97656eb1adfa","sourceKey":"bank:ACC101:A101N3-026","payload":{"prompt":"The ledger of Mama Nkechi's provision store shows: Cash N35,000; Inventory N120,000; Furniture N80,000; Purchases N200,000; Wages N45,000; Sales N310,000; Trade payables N50,000; and Capital (balance missing). If the trial balance agrees, what is the capital balance?","options":["N120,000","N220,000","N80,000","N480,000"],"correctOption":0,"section":"Trial balance and correction of errors","explanation":"Debits are 35,000 + 120,000 + 80,000 + 200,000 + 45,000 = N480,000, and the known credits are 310,000 + 50,000 = N360,000, so capital must be 480,000 - 360,000 = N120,000. N220,000 results from placing trade payables in the debit column, but payables are a liability and belong on the credit side."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 381, $official_bank_source${"itemId":"d8c3e1a5-c009-5b5c-97cf-a8d2e40592f8","questionId":"de021d40-0648-5993-995a-06c9f3a06ff9","sourceKey":"bank:ACC101:A101N3-027","payload":{"prompt":"A trial balance shows a debit total of N1,245,000 and a credit total of N1,230,000. To make the totals agree while the errors are investigated, a suspense account is opened with","options":["N15,000 on the debit side","N7,500 on the credit side","N15,000 on the credit side","N30,000 on the credit side"],"correctOption":2,"section":"Trial balance and correction of errors","explanation":"The credit column is short by 1,245,000 - 1,230,000 = N15,000, so the suspense entry of N15,000 goes on the credit side to bring it up to the debit total. Entering it on the debit side would widen the gap to N30,000 instead of closing it."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 382, $official_bank_source${"itemId":"46e4447d-9c3b-54fc-8c04-4484a36c3894","questionId":"5c0169a6-03b4-57e2-901a-388a9ebc92b1","sourceKey":"bank:ACC101:A101N3-028","payload":{"prompt":"When the bookkeeper of a UNILAG student cooperative added up her trial balance, the credit column came to N684,800 and the debit column to N680,000. The suspense account needed to balance it is","options":["N2,400 debit","N9,600 debit","N4,800 credit","N4,800 debit"],"correctOption":3,"section":"Trial balance and correction of errors","explanation":"The debit column is N4,800 lower than the credit column (684,800 - 680,000), so a debit of N4,800 is placed in the suspense account to make the totals agree. A credit entry would push the credit side even higher and double the difference."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 383, $official_bank_source${"itemId":"efbb927a-ad1d-5f1d-a10f-3d85b62f0ba5","questionId":"09094b9f-66d5-5fab-8d5b-1def6a0cca63","sourceKey":"bank:ACC101:A101N3-029","payload":{"prompt":"A Lagos trading firm's balances are: Capital N1,000,000; Bank loan N500,000; Sales N1,800,000; Discounts received N20,000; Trade payables N180,000; Premises N900,000; Purchases N1,100,000; Salaries N300,000; Bad debts N15,000; Trade receivables N250,000; Bank N935,000. What is the total of the credit column of the trial balance?","options":["N3,000,000","N3,500,000","N3,480,000","N3,515,000"],"correctOption":1,"section":"Trial balance and correction of errors","explanation":"The credit balances are capital, the loan, sales, discounts received and payables: 1,000,000 + 500,000 + 1,800,000 + 20,000 + 180,000 = N3,500,000, which matches the debit total. N3,480,000 comes from wrongly treating discounts received as a debit, when it is a gain and therefore a credit."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 384, $official_bank_source${"itemId":"75fbe41d-77c3-535f-b3b6-e4c24715aa00","questionId":"d947b8b8-3a4d-5ef9-88be-b70ff1e8dceb","sourceKey":"bank:ACC101:A101N3-030","payload":{"prompt":"A trader's trial balance includes: Capital N600,000; Sales N450,000; Trade payables N70,000; Machinery N400,000; Purchases N300,000; Trade receivables N85,000; Carriage inwards N15,000; Drawings N40,000; and Cash (balance missing). If the trial balance agrees, what is the cash balance?","options":["N360,000","N140,000","N310,000","N280,000"],"correctOption":3,"section":"Trial balance and correction of errors","explanation":"Credits total 600,000 + 450,000 + 70,000 = N1,120,000, and the known debits total 400,000 + 300,000 + 85,000 + 15,000 + 40,000 = N840,000, so cash is 1,120,000 - 840,000 = N280,000. N360,000 comes from treating drawings as a credit, but drawings are a debit because they reduce what the business owes the owner."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 385, $official_bank_source${"itemId":"4560cd52-9968-5309-95e8-e7b3701afcb0","questionId":"6c73ed80-fd04-5352-8576-d409b779c5db","sourceKey":"bank:ACC101:A101N3-031","payload":{"prompt":"A credit sale of N25,000 to Bola was correctly debited to Bola's account, but no entry was made in the sales account. What effect does this have on the trial balance?","options":["The debit total exceeds the credit total by N50,000","The totals still agree","The debit total exceeds the credit total by N25,000","The credit total exceeds the debit total by N25,000"],"correctOption":2,"section":"Trial balance and correction of errors","explanation":"Only the debit side of the transaction was posted, so the debit column is N25,000 larger than the credit column, and the difference would go to a suspense account. The totals cannot still agree, because one side of the double entry is missing."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 386, $official_bank_source${"itemId":"72ad72ba-999d-51d2-88c5-193d534e7cbc","questionId":"be59ee3d-b5f4-5db5-9bec-5547f7000046","sourceKey":"bank:ACC101:A101N3-032","payload":{"prompt":"A rent payment of N8,000 was credited in the bank account and also credited, instead of debited, in the rent account. What effect does this have on the trial balance?","options":["The debit total exceeds the credit total by N8,000","The totals still agree","The credit total exceeds the debit total by N8,000","The credit total exceeds the debit total by N16,000"],"correctOption":3,"section":"Trial balance and correction of errors","explanation":"The rent account should have had a debit of N8,000 but got a credit of N8,000 instead, so the credits are N8,000 too high and the debits N8,000 too low, a total gap of N16,000. Saying the gap is only N8,000 forgets that the missing debit and the extra credit both widen the difference."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 387, $official_bank_source${"itemId":"004f44d7-66b1-5c3a-983b-b0855a23e101","questionId":"aac2cad8-b2d2-5e25-998f-be206cdbb2f9","sourceKey":"bank:ACC101:A101N3-033","payload":{"prompt":"The purchases balance of N50,000 was entered in the credit column of a trial balance instead of the debit column. Assuming no other errors, the trial balance will show","options":["Debits exceeding credits by N100,000","Credits exceeding debits by N50,000","Credits exceeding debits by N100,000","Debits exceeding credits by N50,000"],"correctOption":2,"section":"Trial balance and correction of errors","explanation":"Purchases is an expense and belongs in the debit column, so moving it to the credit side makes credits N50,000 too high and debits N50,000 too low, a difference of N100,000. A gap of only N50,000 counts just one of the two effects."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 388, $official_bank_source${"itemId":"fd113e38-36cc-5ba8-bff2-2b2e5e3073da","questionId":"1fce2ce9-7408-5eb8-a570-82a05d556db6","sourceKey":"bank:ACC101:A101N3-034","payload":{"prompt":"Which of the following correctly states where items are placed in a trial balance?","options":["Assets and capital in the debit column; liabilities, expenses and income in the credit column","Assets and expenses in the debit column; liabilities, capital and income in the credit column","Expenses and liabilities in the debit column; assets, capital and income in the credit column","Assets and income in the debit column; liabilities, capital and expenses in the credit column"],"correctOption":1,"section":"Trial balance and correction of errors","explanation":"Assets and expenses are debit balances, while liabilities, capital and income are credit balances, and this is how the two columns are filled. The option placing income in the debit column is wrong because income, such as sales, is always a credit balance."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 389, $official_bank_source${"itemId":"b56caa82-2b76-5faf-9788-7f0d59f9b523","questionId":"350e65dd-0827-5144-ac5e-6f47ae0e01bb","sourceKey":"bank:ACC101:A101N3-035","payload":{"prompt":"A trial balance laid out with the columns Narration, Debit (N) and Credit (N) uses the Narration column to show","options":["The name of each ledger account","The folio reference of each posting","The date of each transaction","The explanation of each journal entry"],"correctOption":0,"section":"Trial balance and correction of errors","explanation":"The Narration (or Particulars) column lists the name of each ledger account whose balance is shown in the Debit or Credit column beside it. A folio reference is not shown, because this layout has no folio column at all."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 390, $official_bank_source${"itemId":"50aa0dad-f60d-57be-b2f1-32d72a59df28","questionId":"ca66242d-15b1-5415-80f6-ae75446c98b8","sourceKey":"bank:ACC101:A101N3-036","payload":{"prompt":"At what stage of the accounting process is a trial balance normally extracted?","options":["Only when an external audit is being carried out","At the end of a period, after transactions have been posted to the ledger","Each time a single transaction is recorded","Before transactions are recorded in the books of prime entry"],"correctOption":1,"section":"Trial balance and correction of errors","explanation":"A trial balance is drawn up at the end of a period from the balances already posted in the ledger. It cannot come before the books of prime entry, because there would be no ledger balances to list yet."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 391, $official_bank_source${"itemId":"2a305113-e6bd-5874-a88c-c37571855ce9","questionId":"9c720d4c-9332-5a7b-be9a-904b15bfbf5e","sourceKey":"bank:ACC101:ACC-0021","payload":{"prompt":"Which one of the following is the correct entry for unsold stock at the end of the accounting period?","options":["Debit inventory; credit sales","Debit cost of sales; credit inventory","Debit profit or loss; credit inventory","Debit inventory; credit cost of sales"],"correctOption":3,"section":"Accruals, prepayments and other adjustments","explanation":"Unsold stock at the year end is an asset carried into the next period, so inventory is debited and cost of sales is credited, which cuts cost of sales down to the cost of the goods actually sold. Option A is wrong because closing stock has not been sold, so it is never added to sales revenue. Options B and C reverse the entry by crediting inventory."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 392, $official_bank_source${"itemId":"3532cf71-3761-53c6-b60a-dca8904a77a3","questionId":"2eb65dfa-2c5b-5546-bc9d-8be9497be0c5","sourceKey":"bank:ACC101:ACC-0144","payload":{"prompt":"What type of entry will increase the normal balance of the general ledger account that reports the amount owed as of the balance sheet date for a company's accrued expenses?","options":["Revenue","Equity","Debit","Credit"],"correctOption":3,"section":"Accruals, prepayments and other adjustments","explanation":"Accrued expenses owed at the balance sheet date are recorded in a liability account, and liabilities have normal credit balances, so a credit entry increases them. A debit (Option C) would reduce the liability, and Options A and B are account types, not entry types."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 393, $official_bank_source${"itemId":"258b0735-d3fd-5862-bae4-5e0956ddf0e5","questionId":"b16235fe-cdb9-5d37-8d87-f6a5d9d3994f","sourceKey":"bank:ACC101:ACC-0145","payload":{"prompt":"What type of accounts are Interest Receivable and Fees Receivable?","options":["Asset","Liability","Equity","Revenue"],"correctOption":0,"section":"Accruals, prepayments and other adjustments","explanation":"Interest receivable and fees receivable are amounts other people owe the business, so they are assets (usually current assets). They are not liabilities (Option B), which are amounts the business owes, and they are not revenue (Option D), even though they arise from earning interest or fees."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 394, $official_bank_source${"itemId":"51ad8188-d6e5-55a1-8bbc-62191ddeb21e","questionId":"b40c4fe8-e45f-53e9-812a-dd4ea6ff0403","sourceKey":"bank:ACC101:ACC-0154","payload":{"prompt":"What type of entry will decrease the normal balances of the accounts Deferred Revenues and Unearned Revenues?","options":["Asset","Equity","Debit","Credit"],"correctOption":2,"section":"Accruals, prepayments and other adjustments","explanation":"Deferred or unearned revenues are liabilities, which normally carry credit balances, so they are decreased by a debit entry (for example when the revenue is earned). Option D, a credit, would increase the liability. Options A and B are account types, not entry types."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 395, $official_bank_source${"itemId":"ac74b3fa-a889-5fbe-a8dd-b980a74a99d6","questionId":"8fdd6a50-fee2-5f27-84e0-0b9ed1caea81","sourceKey":"bank:ACC101:ACC-0155","payload":{"prompt":"A ____ entry typically removes an accrual-type adjusting entry that had been recorded in the preceding accounting period.","options":["Reconciliation","Reversing","Current","Revenue"],"correctOption":1,"section":"Accruals, prepayments and other adjustments","explanation":"A reversing entry is made at the start of a new period to cancel an accrual adjustment from the previous period, so that the later cash payment or receipt can be recorded normally. A reconciliation (Option A) compares two records, such as the cash book and bank statement, and does not remove adjustments."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 396, $official_bank_source${"itemId":"5fa2f3d0-1380-5900-b2bc-5b46e7d4a6cb","questionId":"dc9e9fde-2295-5f50-8735-4eb4d01ab873","sourceKey":"bank:ACC101:ACC-0164","payload":{"prompt":"What type of accounts are Deferred Revenues and Unearned Revenues?","options":["Asset","Liability","Equity","Revenue"],"correctOption":1,"section":"Accruals, prepayments and other adjustments","explanation":"Deferred or unearned revenues are amounts received before the work is done, so the business owes the customer goods or services - that is a liability. Option A, asset, is a common mix-up with prepaid expenses, which are amounts the business has paid in advance. Option D is wrong because the revenue has not yet been earned."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 397, $official_bank_source${"itemId":"663cca79-75f6-518e-8cd6-9de856529332","questionId":"2508f5fb-f7fb-5cc2-bf3a-bebf71021b07","sourceKey":"bank:ACC101:ACC-0165","payload":{"prompt":"What type of accounts are Prepaid Insurance, Prepaid Advertising, and Prepaid Expenses?","options":["Asset","Liability","Equity","Expense"],"correctOption":0,"section":"Accruals, prepayments and other adjustments","explanation":"Prepaid insurance, prepaid advertising and other prepaid expenses are payments made for future benefits that the business still has the right to receive, so they are assets. Option D, expense, is tempting, but the cost only becomes an expense as the period passes. They are not liabilities (Option B) because nothing is owed by the business."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 398, $official_bank_source${"itemId":"5e731457-ee08-5bfc-8306-6e04c52bece4","questionId":"bb37222f-d6ac-58c8-bdab-19a939c5eff3","sourceKey":"bank:ACC101:ACC-0166","payload":{"prompt":"What type of entry will decrease the normal balances of the accounts Prepaid Insurance and Prepaid Expenses, and Insurance Expense?","options":["Asset","Debit","Credit","Liability"],"correctOption":2,"section":"Accruals, prepayments and other adjustments","explanation":"Prepaid insurance and prepaid expenses are assets, and insurance expense is an expense; both kinds of account have normal debit balances, so a credit entry decreases them. A debit (Option B) would increase them, and Options A and D are account types, not entry types."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 399, $official_bank_source${"itemId":"57c6ff81-191a-53d8-a079-10036d4810dd","questionId":"11472d3d-b93d-5b81-9c60-564b07b71e87","sourceKey":"bank:ACC101:ACC-0189","payload":{"prompt":"The adjusting entry that reduces the balance in Deferred Revenues or Unearned Revenues will also include which of the following?","options":["A Debit To Cash","A Credit To Fees Earned","A Debit To Fees Earned","A Credit To Fees Receivable"],"correctOption":1,"section":"Accruals, prepayments and other adjustments","explanation":"When unearned revenue becomes earned, the liability is debited (reduced) and a revenue account such as Fees Earned is credited. Option C, a debit to fees earned, reverses the correct side, and Option A involves cash, which was received earlier and is not part of the adjustment."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 400, $official_bank_source${"itemId":"eaa32ded-e919-581e-b57c-5e0fb232ba1e","questionId":"dd05529c-4419-5263-83c0-9f5b6f69968a","sourceKey":"bank:ACC101:ACC-0190","payload":{"prompt":"The adjusting entry that reduces the balance in Prepaid Insurance will also include which of the following?","options":["A Credit To Cash","A Credit To Insurance Expense","A Debit To Insurance Expense","A Debit To Insurance Payable"],"correctOption":2,"section":"Accruals, prepayments and other adjustments","explanation":"As insurance is used up, the adjusting entry is DR Insurance Expense and CR Prepaid Insurance, which moves the expired part from an asset to an expense. Option B puts insurance expense on the wrong side, and Option A wrongly involves cash, because the premium was already paid when the prepayment was set up."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 401, $official_bank_source${"itemId":"dd1737a2-a184-5092-9fb0-1c064caab9d8","questionId":"7dd42f40-967f-5801-a7e4-8fecbec259f4","sourceKey":"bank:ACC101:ACC-0191","payload":{"prompt":"In the case of a company's deferred revenues, which occurs first?","options":["Earning The Revenues","Receiving The Money From The Customer","A Debit To Interest Payable","A Debit To Prepaid Interest"],"correctOption":1,"section":"Accruals, prepayments and other adjustments","explanation":"Deferred (unearned) revenue arises when the customer pays before the business does the work, so receiving the money comes first and earning the revenue comes later. Option A describes accrued revenue, where the revenue is earned first and paid for later. Options C and D relate to interest and do not describe deferred revenues."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 402, $official_bank_source${"itemId":"75eb9b20-2867-5678-a049-aa468ded6690","questionId":"1d6ba584-b53b-5401-8431-958492b2e262","sourceKey":"bank:ACC101:ACC-0196","payload":{"prompt":"In the case of a bank's accrued interest revenues, which occurs first?","options":["Paying The Interest To The Lender","Earning The Interest Revenues","Receiving The Interest From The Borrower","Incurring The Interest Expenses"],"correctOption":1,"section":"Accruals, prepayments and other adjustments","explanation":"Accrued interest revenue means the bank has earned the interest but has not yet received it, so earning the revenue comes first and receiving the cash comes later. Option C, receiving the interest, happens after the revenue is earned, and Options A and D describe the borrower's side, not the bank's revenue."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 403, $official_bank_source${"itemId":"c3b2c35d-fa81-5320-841d-c46c48bc8c7f","questionId":"e11c6ebf-1861-5600-9708-5926cc76df27","sourceKey":"bank:ACC101:ACC-0205","payload":{"prompt":"The ending balance in the account Prepaid Insurance is expected to report which of the following?","options":["The Accrued Amount Of Insurance Expense","The Original Amount Of The Insurance Premiums Paid","The Expired Portion Of The Insurance Premiums Paid","The Unexpired Portion Of The Insurance Premiums Paid"],"correctOption":3,"section":"Accruals, prepayments and other adjustments","explanation":"Prepaid insurance is an asset representing insurance paid for in advance that has not yet been used up, so its ending balance is the unexpired portion. Option C, the expired portion, has become insurance expense in the profit or loss account. Option B is the full premium, which would only equal the balance before any of it expires."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 404, $official_bank_source${"itemId":"83331377-6212-53d2-bf2e-38f219629e01","questionId":"3c02d52f-6322-5464-946a-cbd5651fe419","sourceKey":"bank:ACC101:ACC-0217","payload":{"prompt":"Which of the following will be included in the adjusting entry to accrue interest income or interest revenues?","options":["A Debit To Cash","A Debit To Interest Income","A Credit To Interest Receivable","A Debit To Interest Receivable"],"correctOption":3,"section":"Accruals, prepayments and other adjustments","explanation":"To accrue interest income that has been earned but not yet received, the entry is debit Interest Receivable (an asset) and credit Interest Income. Option C has the receivable on the wrong side, and Option B debits income instead of crediting it. Option A is wrong because no cash has been received yet."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 405, $official_bank_source${"itemId":"985bd32d-493a-5f90-9810-4ba3ced82a3c","questionId":"21b69f69-9b6c-57ae-baf6-12e5d5991f1a","sourceKey":"bank:ACC101:ACC-0221","payload":{"prompt":"In the case of a company deferring insurance expense, which occurs first?","options":["Incurring The Insurance Expense","Paying The Insurance Company","A Debit To Fees Earned","A Credit To Fees Receivable"],"correctOption":1,"section":"Accruals, prepayments and other adjustments","explanation":"A deferred (prepaid) insurance expense arises when the company pays the insurer in advance, so the payment comes first and the expense is incurred later as the cover is used up. Option A describes the order for an accrued expense, where the cost is incurred before it is paid. Options C and D relate to fees revenue, not insurance expense."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 406, $official_bank_source${"itemId":"9360f206-ebac-5df4-90b8-8826e0ea5644","questionId":"41b2041e-ec2b-5c62-83e3-3bee2a4c5070","sourceKey":"bank:ACC101:ACC-0224","payload":{"prompt":"In the case of a company's accrued interest expense, which of the following occurs first?","options":["Earning The Interest Revenues","Paying The Interest To The Lender","Incurring The Interest Expenses","Receiving The Interest From The Borrower"],"correctOption":2,"section":"Accruals, prepayments and other adjustments","explanation":"With an accrued interest expense, the company incurs the interest first and pays the lender later, which is why a liability (interest payable) is recorded at the year end. Option B, paying the lender, comes after the expense is incurred. Options A and D relate to the lender's side, where interest is earned or received, not to the borrower's expense."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 407, $official_bank_source${"itemId":"92c53f5b-e44f-51ad-87da-954047bcd2ee","questionId":"0233e5b5-1287-5c39-a13f-f6d3de3b6a2a","sourceKey":"bank:ACC101:ACC-0237","payload":{"prompt":"Which of the following will be included in the adjusting entry to accrue interest expense?","options":["A Debit To Cash","A Credit To Interest Payable","A Debit To Interest Payable","A Debit To Prepaid Interest"],"correctOption":1,"section":"Accruals, prepayments and other adjustments","explanation":"To accrue interest expense that has been incurred but not yet paid, the entry is debit Interest Expense and credit Interest Payable (a liability). Option C puts Interest Payable on the wrong side; debiting it happens later, when the interest is paid. Option A is wrong because no cash has been paid yet, and Option D relates to interest paid in advance."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 408, $official_bank_source${"itemId":"92facea6-7167-5457-a9f9-7237c20228c7","questionId":"155d6f3b-31ac-5939-a909-39c35cb5d86d","sourceKey":"bank:ACC101:ACC-0350","payload":{"prompt":"Prepaid rent given in the Trial Balance will be treated as a:","options":["Asset or deferred expense","Deferred income","Liability","Revenue"],"correctOption":0,"section":"Accruals, prepayments and other adjustments","explanation":"Prepaid rent is rent paid now for a future period, so the business has a benefit still to come, which makes it a current asset (a deferred expense). Option B (deferred income) and option C (liability) describe rent received in advance from someone else, and option D is wrong because paying rent is never revenue."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 409, $official_bank_source${"itemId":"9a603ed9-47f5-5114-9201-273649a2f13c","questionId":"182c1b98-633b-5c2e-bdb9-5e508817feef","sourceKey":"bank:ACC101:ACC-0357","payload":{"prompt":"When Rent receivable A/c is debited, the double entry effect of this transaction signifies","options":["An increase to the account","A null effect to the a/c","A decrease to the A/c","A stall effect to the a/c"],"correctOption":0,"section":"Accruals, prepayments and other adjustments","explanation":"Rent receivable is an asset (income earned but not yet received), and assets increase on the debit side, so debiting it signifies an increase. Option C would be right only for a credit entry, while options B and D do not describe any real double entry effect."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 410, $official_bank_source${"itemId":"40569990-efef-580c-9a14-2489ceade791","questionId":"d2208221-c070-543e-9758-4ebaa44205d8","sourceKey":"bank:ACC101:ACC-0358","payload":{"prompt":"End of year adjustments are made in order to satisfy the","options":["Adjustment Concept","Consistency concept","Matching Concept","Going Concern concept"],"correctOption":2,"section":"Accruals, prepayments and other adjustments","explanation":"Year-end adjustments such as accruals, prepayments, depreciation and provisions make sure income and expenses are matched to the period they belong to, which is the matching concept. Option B (consistency) is about using the same methods each year, and option D (going concern) is about the business continuing. There is no 'adjustment concept' (option A)."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 411, $official_bank_source${"itemId":"b5632faf-bb4e-5a78-a22b-aeae7876f685","questionId":"12b3d8c7-e382-5b04-8c7a-45c5c58249d8","sourceKey":"bank:ACC101:ACC-0362","payload":{"prompt":"If the accrued wages of a business amounting to N1800 is not recorded then","options":["It is a liability, hence will overstate liability by N1,800","The profit will be over-stated by N1,800 and liabilities understated by N1,800","The profit will be under-stated by N1,800 and cash will be overstated by N1,800","The profit will be under-stated by N1,800 and liabilities overstated by N1,800"],"correctOption":1,"section":"Accruals, prepayments and other adjustments","explanation":"Accrued wages are an expense owed at the year end; if they are left out, expenses are too low by N1,800, so profit is overstated by N1,800, and the amount owed is missing, so liabilities are understated by N1,800. The options saying profit is understated have the effect the wrong way round, and leaving out an accrual cannot overstate liabilities."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 412, $official_bank_source${"itemId":"2cae0a24-b211-5953-8a7c-f9fda9e6ac50","questionId":"6125d760-6f13-5ddf-94f3-00e288ea6d6f","sourceKey":"bank:ACC101:ACC-0365","payload":{"prompt":"During the year ended 31st December 20X2 the proprietor of a business had the following transactions with the business: Salaries received N100,000, Cash drawn to pay school fees N10,000, Withdrew goods worth N2,400 from the business. Half of this went towards the Xmas of the children while the balance was used as gifts to long standing customers of the business. From the above the total amount relevant as business expense is","options":["N112,400","N111,200","N1,200","N101,200"],"correctOption":2,"section":"Accruals, prepayments and other adjustments","explanation":"Only the goods given as gifts to long-standing customers are a business expense: half of N2,400 = N1,200. The owner's salary, school fees and the goods used for the children's Christmas are all drawings because they benefit the owner personally. Option D (N101,200) wrongly treats the owner's salary as a business expense."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 413, $official_bank_source${"itemId":"85f91e40-e0d3-5c88-a7df-81aa4a5b5dff","questionId":"fd156413-201a-5a4c-b32f-546ad8845ee9","sourceKey":"bank:ACC101:ACC-0366","payload":{"prompt":"During the year ended 31st December 20X2 the proprietor of a business had the following transactions with the business: Salaries received N100,000, Cash drawn to pay school fees N10,000, Withdrew goods worth N2,400 from the business. Half of this went towards the Xmas of the children while the balance was used as gifts to long standing customers of the business. The total of the drawings of the proprietor is","options":["N112,400","N111,200","N1,200","N101,200"],"correctOption":1,"section":"Accruals, prepayments and other adjustments","explanation":"Drawings are everything the owner takes out for personal use: salary taken N100,000 + school fees N10,000 + half the goods N1,200 = N111,200. Option A (N112,400) includes all the goods, but the half given to customers is a business expense, not drawings. Option D (N101,200) leaves out the school fees."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 414, $official_bank_source${"itemId":"b3aed362-33b0-5a75-a5c2-c49145601cf0","questionId":"c988062a-a809-5285-abbc-e7cd73ae9d55","sourceKey":"bank:ACC101:ACC-0368","payload":{"prompt":"Which of the following accounts is not an asset?","options":["Prepaid rent","Prepaid Insurance","Rent received in advance","Accrued rent received"],"correctOption":2,"section":"Accruals, prepayments and other adjustments","explanation":"Rent received in advance is money received for a period not yet covered, so the business owes that service and it is a liability. Prepaid rent, prepaid insurance and accrued rent received (options A, B and D) are all amounts the business is owed or has paid ahead, which makes them assets."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 415, $official_bank_source${"itemId":"4a025d3a-d07f-53e2-9f5e-44ca554c9a49","questionId":"4a96e64a-fdd1-5d27-b1f1-15c104f8b227","sourceKey":"bank:ACC101:ACC-0372","payload":{"prompt":"Given the following information, what is the rent for the period 2020. Rent paid in advance (31/12/2019): N1,000; Rent paid during the year 2020: N8,000; Rent owing (31/12/2020): N600","options":["N8600","N9400","N9000","N9600"],"correctOption":3,"section":"Accruals, prepayments and other adjustments","explanation":"Rent for 2020 = opening prepayment + paid during the year + closing amount owing = N1,000 + N8,000 + N600 = N9,600. Option C (N9,000) leaves out the rent owing at the year end, and option A (N8,600) ignores the opening prepayment."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 416, $official_bank_source${"itemId":"0e1ee9ca-cb8c-5065-9e92-e7e1b0afc283","questionId":"b3829a78-0783-54ec-84da-46905994fdd4","sourceKey":"bank:ACC101:ACC-0373","payload":{"prompt":"Electricity bill remaining unpaid as at the year-end should be accounted for as:","options":["Dr. Electricity account and Cr. Cash account","Dr. Electricity accrued account and Cr. Electricity current account","Dr. Electricity account and Cr. Electricity accrued account","Dr. Pre-paid electricity account and Cr. Electricity account"],"correctOption":2,"section":"Accruals, prepayments and other adjustments","explanation":"An unpaid electricity bill is an accrued expense: debit the electricity account to charge the expense this year and credit an accrual (liability) account to show the amount owed. Option A is wrong because no cash has been paid yet, and option D records a prepayment, which is the opposite situation."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 417, $official_bank_source${"itemId":"1b3a3ad8-1578-5bde-83b3-fb63ca90fd59","questionId":"6b872d5e-7d3e-56be-a772-696e2e84652e","sourceKey":"bank:ACC101:ACC-0375","payload":{"prompt":"Rent and rates are N6,000 and Insurance N1,500. If a further N500 rent needs to be accrued and N250 of insurance is prepaid, what balances need to be shown in the profit and loss account?","options":["Rent N6,500, Insurance N1,750","Rent N5,500, Insurance N1,750","Rent N6,500, Insurance N1,250","Rent N5,500, Insurance N1,250"],"correctOption":2,"section":"Accruals, prepayments and other adjustments","explanation":"An accrual adds to the expense, so rent = N6,000 + N500 = N6,500; a prepayment reduces it, so insurance = N1,500 - N250 = N1,250. Option A adds the insurance prepayment instead of deducting it, and options B and D deduct the rent accrual instead of adding it."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 418, $official_bank_source${"itemId":"28112b81-c895-5865-8f13-a7c40bf14cf9","questionId":"7caaeec9-2ac4-5bde-baf9-6f553bb733a7","sourceKey":"bank:ACC101:A101N3-037","payload":{"prompt":"End-of-year adjustments are best described as","options":["Amendments made at the end of a financial period in the income statement and statement of financial position so that the accounts show a true view","Corrections made in the cash book after comparing it with the bank statement at the end of each month","Entries made in the journal to record the capital introduced when the business first starts trading","Changes made to the trial balance figures only to force its debit and credit totals to agree"],"correctOption":0,"section":"Accruals, prepayments and other adjustments","explanation":"End-of-year adjustments are amendments made at the end of each financial period to the income statement and the statement of financial position, so that the accounts give a true view. Changing figures just to force the trial balance to agree is not an adjustment; differences of that kind go to a suspense account until the errors are found."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 419, $official_bank_source${"itemId":"5f35b8a5-021a-575e-b0dd-4b26623f155d","questionId":"4c820d51-88e8-5d4f-972f-03f52d4354ea","sourceKey":"bank:ACC101:A101N3-038","payload":{"prompt":"Which of the following is NOT a reason for making end-of-year adjustments?","options":["To provide for depreciation of fixed assets","To reduce the amount of tax the business pays","To record all income generated in the year","To value closing stock"],"correctOption":1,"section":"Accruals, prepayments and other adjustments","explanation":"Adjustments are made so that the accounts follow accepted principles and show a true view, such as valuing closing stock, providing for depreciation and recording all income earned. Reducing tax is not a purpose of adjustments; recording all income generated in the year may even raise profit."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 420, $official_bank_source${"itemId":"c92baaca-78d0-5881-a042-632ddd76f76c","questionId":"42a972ec-0d3e-5c7f-b5e0-3062b899aeca","sourceKey":"bank:ACC101:A101N3-040","payload":{"prompt":"The idea that revenue and expenditure should be recorded in the period to which they relate, not the period in which cash is received or paid, is known as the","options":["Business entity concept","Money measurement concept","Accruals concept","Going concern concept"],"correctOption":2,"section":"Accruals, prepayments and other adjustments","explanation":"The accruals concept matches income and expenses to the period they belong to, regardless of when the cash moves. The going concern concept is about assuming the business will continue operating in the foreseeable future, which says nothing about the timing of income and expenses."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 421, $official_bank_source${"itemId":"d480ae58-a87a-59b4-bd79-3f546866caa6","questionId":"17d18493-3f70-515f-9018-97bf6aeb2366","sourceKey":"bank:ACC101:A101N3-041","payload":{"prompt":"An agent in Ikeja earned commission of N35,000 for work done in December 2025 but will not receive the money until January 2026. In the accounts for the year ended 31 December 2025, the N35,000 is","options":["An accrued expense, shown as a current liability","A prepaid expense, shown as a current asset","Accrued income, shown as a current asset","Income received in advance, shown as a current liability"],"correctOption":2,"section":"Accruals, prepayments and other adjustments","explanation":"Income that has been earned but not yet received at the year end is accrued income, and because it is owed to the business it is a current asset. Income received in advance is the opposite case, where cash comes in before the income is earned, so it is a liability."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 422, $official_bank_source${"itemId":"91f5beb5-66d9-5c21-99b1-1ebf208d84bc","questionId":"e8b7e379-67a2-5947-a944-9ffe4d636124","sourceKey":"bank:ACC101:A101N3-042","payload":{"prompt":"A business received commission of N45,000 in cash during 2025. Commission receivable was N6,000 at 1 January 2025 and N9,000 at 31 December 2025. What commission income should be credited to the income statement for 2025?","options":["N48,000","N45,000","N60,000","N42,000"],"correctOption":0,"section":"Accruals, prepayments and other adjustments","explanation":"Income for the year = received - opening accrual + closing accrual = 45,000 - 6,000 + 9,000 = N48,000. N42,000 reverses the two adjustments, adding the opening accrual and deducting the closing one."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 423, $official_bank_source${"itemId":"2e742f29-d634-554a-a61d-44b27dd9b48d","questionId":"ce5b2747-aec7-5672-ae66-674681843c33","sourceKey":"bank:ACC101:A101N3-043","payload":{"prompt":"A firm paid motor expenses of N72,000 during the year. Motor expenses owing were N8,000 at the start of the year and N11,500 at the end of the year. What is the motor expenses charge in the income statement?","options":["N72,000","N91,500","N68,500","N75,500"],"correctOption":3,"section":"Accruals, prepayments and other adjustments","explanation":"Expense charge = paid - opening accrual + closing accrual = 72,000 - 8,000 + 11,500 = N75,500. N68,500 swaps the adjustments by adding the opening accrual and deducting the closing accrual."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 424, $official_bank_source${"itemId":"f73d6e82-2ac3-5561-adea-c2c2f17cb77a","questionId":"fcfd87cb-59d1-5f53-8199-3693939fa511","sourceKey":"bank:ACC101:A101N3-044","payload":{"prompt":"A trader in Balogun market paid insurance of N36,000 during the year. Insurance prepaid was N4,000 at the start of the year and N9,000 at the end of the year. What insurance expense should appear in the income statement?","options":["N49,000","N41,000","N23,000","N31,000"],"correctOption":3,"section":"Accruals, prepayments and other adjustments","explanation":"Expense charge = paid + opening prepayment - closing prepayment = 36,000 + 4,000 - 9,000 = N31,000. N23,000 wrongly deducts the opening prepayment as well, but last year's prepayment is cover used up this year and must be added."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 425, $official_bank_source${"itemId":"5ecc5ec5-4685-5feb-94cd-4306f88985ab","questionId":"1e6f9256-6026-5a07-8255-d6ba345e3406","sourceKey":"bank:ACC101:A101N3-045","payload":{"prompt":"A UNILAG department lets out its hall and received rent of N120,000 during the year. Rent received in advance was N15,000 at the start of the year and N20,000 at the end of the year. What rent income should be credited to the income statement for the year?","options":["N115,000","N155,000","N125,000","N85,000"],"correctOption":0,"section":"Accruals, prepayments and other adjustments","explanation":"Income credited = received + opening income in advance - closing income in advance = 120,000 + 15,000 - 20,000 = N115,000. N125,000 swaps the two figures, but the closing amount received in advance belongs to next year and must be deducted."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 426, $official_bank_source${"itemId":"08b1be42-6004-5aac-b9d8-a8faa1eec365","questionId":"15f19ec7-586e-5c4d-ab61-803b24f03521","sourceKey":"bank:ACC101:A101N3-046","payload":{"prompt":"On 1 April 2025, a firm paid N480,000 for insurance cover for 2 years. If its year ends on 31 December 2025, how much of the payment is a prepayment in the statement of financial position at that date?","options":["N360,000","N240,000","N300,000","N180,000"],"correctOption":2,"section":"Accruals, prepayments and other adjustments","explanation":"The cover runs for 24 months, and 9 months (April to December) are used in 2025, so 15/24 x 480,000 = N300,000 is prepaid at the year end. N180,000 is the 9/24 share that is charged as an expense for 2025, not the amount still prepaid."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 427, $official_bank_source${"itemId":"d3229bc8-319c-50d0-97c7-9d8047e9d8dc","questionId":"eca00879-1af1-52e9-adad-ceca9ed767a7","sourceKey":"bank:ACC101:A101N3-047","payload":{"prompt":"A business paid electricity of N50,000 during the year. At the start of the year N4,000 was owing for electricity, and at the end of the year N3,000 had been paid in advance. What is the electricity charge for the year?","options":["N49,000","N43,000","N51,000","N57,000"],"correctOption":1,"section":"Accruals, prepayments and other adjustments","explanation":"Expense charge = paid - opening accrual - closing prepayment = 50,000 - 4,000 - 3,000 = N43,000. N51,000 adds the opening accrual instead of deducting it, but that N4,000 related to last year's electricity and was already charged then."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 428, $official_bank_source${"itemId":"d2d2e175-1c43-5c52-a48d-c75cef758065","questionId":"6b2dfd7b-d195-5020-a518-98a51010c7cf","sourceKey":"bank:ACC101:A101N3-048","payload":{"prompt":"Mr Okon, who owns a shop in Ikeja, takes N20,000 from the business cash till for his personal use. The correct entry is","options":["Debit cash, credit capital","Debit cash, credit drawings","Debit wages expense, credit cash","Debit drawings, credit cash"],"correctOption":3,"section":"Accruals, prepayments and other adjustments","explanation":"Cash taken by the owner for private use is debited to the drawings account and credited to cash, and the drawings are later deducted from capital. Debiting wages expense is wrong because the owner's withdrawal is not a business expense."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 429, $official_bank_source${"itemId":"75f56fd2-01b9-557f-9fd8-4dc38f5076e5","questionId":"ed79e19e-17fb-52fa-8932-96106b491b82","sourceKey":"bank:ACC101:A101N3-049","payload":{"prompt":"Wages of N18,000 for the last week of December 2025 were not paid until 5 January 2026. In the statement of financial position at 31 December 2025, the N18,000 is shown as","options":["A current asset (prepaid expense)","A current liability (accrued expense)","A deduction from capital (drawings)","A current asset (accrued income)"],"correctOption":1,"section":"Accruals, prepayments and other adjustments","explanation":"The wages were incurred in 2025 but were still unpaid at the year end, so they are an accrued expense, which is a current liability. A prepaid expense is the reverse situation, where payment is made before the expense is incurred."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 430, $official_bank_source${"itemId":"66ad1ef4-be9c-585a-a760-77ef4d3e8e2a","questionId":"4e789111-868e-55ee-97ea-6c36873a3c9f","sourceKey":"bank:ACC101:ACC-0009","payload":{"prompt":"A motor van was bought for $20,000 on 1 September 2005 with a residual value of $2,000. Depreciation was charged at 20% by the reducing balance method on yearly basis. It was sold for $18,000 after three years of use on 30 September 2008. Compute the profit on sale of asset.","options":["$990","$505","$5,201","$7,760"],"correctOption":3,"section":"Depreciation of non-current assets","explanation":"Under 20% reducing balance, the net book value after three years is $20,000 x 0.8 x 0.8 x 0.8 = $10,240 (depreciation of $4,000, $3,200 and $2,560). Profit on sale = $18,000 - $10,240 = $7,760. The residual value is not used in the reducing balance calculation here, so the smaller options come from wrong bases."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 431, $official_bank_source${"itemId":"eb9dd467-a70e-5afb-95a4-765cd1a82032","questionId":"e6513a25-8db4-50e9-b57f-6e9d2d5258eb","sourceKey":"bank:ACC101:ACC-0017","payload":{"prompt":"If an asset has original cost of N100,000, a useful life of 5 years and a salvage value of zero, what is the depreciation charge for the first year using the sum of the year digits.","options":["N33,333.33","N20,000.00","None of the above","N26,666.67"],"correctOption":0,"section":"Depreciation of non-current assets","explanation":"With a 5-year life, the sum of the years' digits is 1+2+3+4+5 = 15, and the first year takes 5/15 of the cost: 5/15 x N100,000 = N33,333.33. Option B, N20,000, is the straight-line charge (N100,000 / 5), which is a different method."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 432, $official_bank_source${"itemId":"29f50fca-a955-5a43-b353-bba5f7ae81e3","questionId":"a6298539-fb24-51b3-a8b4-0aa8e0cee770","sourceKey":"bank:ACC101:ACC-0022","payload":{"prompt":"What would be the accounting treatment for a cheque of N1,254,000 received for the disposal of a Plant and Machinery Item?","options":["Debit Bank Account, Credit Accumulated Depreciation Account with N1,254,000","Debit Bank Account, Credit Asset Disposal Account with N1,254,000","Debit Bank Account, Credit Plant and Machinery Account with N1,254,000","Debit Asset Disposal Account, Credit Bank Account"],"correctOption":1,"section":"Depreciation of non-current assets","explanation":"Disposal proceeds are recorded by debiting bank (money received) and crediting the asset disposal account, where they are compared with the asset's book value to find the gain or loss. Option C skips the disposal account, and option D reverses the entry."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 433, $official_bank_source${"itemId":"6db28f4f-7875-589e-8994-774658738232","questionId":"f63139d7-efeb-57f5-92e5-590eda06a75b","sourceKey":"bank:ACC101:ACC-0024","payload":{"prompt":"Assume that a vehicle that depreciates on the straight-line basis over 5 years is purchased at a cost of N170,000, and it is expected to have a salvage value of N20,000. Calculate the accumulated depreciation balance at the end of the third year.","options":["N150,000.00","N30,000.00","N90,000.00","N102,000.00"],"correctOption":2,"section":"Depreciation of non-current assets","explanation":"Straight-line depreciation charges the same amount every year: (N170,000 - N20,000) / 5 = N30,000 per year. After three years the accumulated depreciation is N30,000 x 3 = N90,000. Option B is only one year's charge, and option A is the total depreciation over the whole five years."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 434, $official_bank_source${"itemId":"bfe3f0cb-c01d-5406-9b63-02d0ea262c7a","questionId":"b8670bed-b77d-5ee9-aa1c-8b7a6f38627e","sourceKey":"bank:ACC101:ACC-0032","payload":{"prompt":"A fixed asset cost $100,000, had a book value of $40,000. It was sold for $10,000. What is the provision for depreciation sold?","options":["$50,000","$60,000","$30,000","$10,000"],"correctOption":1,"section":"Depreciation of non-current assets","explanation":"Book value = cost - accumulated depreciation, so the provision for depreciation on the asset sold is $100,000 - $40,000 = $60,000. Option C, $30,000, is the loss on sale ($40,000 - $10,000), not the depreciation."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 435, $official_bank_source${"itemId":"509a3020-545d-5777-bf18-7ab71b1fdd8d","questionId":"53ee80c3-b157-553b-afd1-25aa67db9439","sourceKey":"bank:ACC101:ACC-0044","payload":{"prompt":"What does it mean by the yearly method of depreciation","options":["Monthly depreciation in year of purchase and sale","Full year's depreciation in year of purchase and sale","Full year's depreciation in year of purchase and no depreciation in year of sale","No depreciation in the year of purchase and full year's depreciation in year of sale"],"correctOption":2,"section":"Depreciation of non-current assets","explanation":"Under this method a full year's depreciation is charged in the year an asset is bought, whatever the purchase date, and no depreciation is charged in the year it is sold. Option A describes time-apportioning by months, option B would charge depreciation in both the purchase and sale years, and option D reverses the rule."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 436, $official_bank_source${"itemId":"6c188872-87be-5bf2-b8db-addde1aae415","questionId":"8c05a6c3-d46d-5fe1-8d5e-79871d224e8b","sourceKey":"bank:ACC101:ACC-0156","payload":{"prompt":"What type of accounts are Accumulated Depreciation and Allowance for Doubtful Accounts?","options":["Contra Asset","Equity","Expense","Liability"],"correctOption":0,"section":"Depreciation of non-current assets","explanation":"Accumulated depreciation and the allowance (provision) for doubtful debts are contra asset accounts: they carry credit balances that reduce non-current assets and receivables to their carrying amounts. They are not liabilities (Option D), because nothing is owed to anyone, and they are not expenses (Option C), although the yearly depreciation and provision charges are."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 437, $official_bank_source${"itemId":"172fb2a4-1bb2-5ce3-9c96-13c3d7f5c1c2","questionId":"4801ce22-0145-5bb5-a09d-2f3716e2127d","sourceKey":"bank:ACC101:ACC-0200","payload":{"prompt":"A machine costs N360,000 and has a useful life span of n years and an expected disposal value of N12,000 with annual depreciation of N69,600. Using the straight-line method of depreciation, what is the useful life of the machine?","options":["4 years","5 years","6 years","7 years"],"correctOption":1,"section":"Depreciation of non-current assets","explanation":"Under straight-line, annual depreciation = (cost - residual value) / useful life, so useful life = (N360,000 - N12,000) / N69,600 = N348,000 / N69,600 = 5 years. Option A (4 years) or C (6 years) would give annual charges of N87,000 and N58,000, which do not match the N69,600 given."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 438, $official_bank_source${"itemId":"0f8f7e2e-3ff1-5c00-a014-b7905d5221bb","questionId":"957f433b-727e-545d-8695-ad9f7de65a9c","sourceKey":"bank:ACC101:ACC-0234","payload":{"prompt":"What type of entry will increase the balances that are normally found in the accounts Accumulated Depreciation and Allowance for Doubtful Accounts?","options":["Debit","Credit","Equity","Expense"],"correctOption":1,"section":"Depreciation of non-current assets","explanation":"Accumulated depreciation and the allowance for doubtful accounts are contra-asset accounts with normal credit balances, so a credit entry increases them. A debit (A) would reduce them. Options C and D are types of account, not types of entry."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 439, $official_bank_source${"itemId":"d874d55c-1c2b-5069-b3c8-4c205ad3a093","questionId":"6007e738-8bd7-52fb-9a80-bcefb308a3db","sourceKey":"bank:ACC101:ACC-0348","payload":{"prompt":"A fixed asset cost N100,000. The provision for depreciation brought forward from previous years is N20,000, and the depreciation charge for the current year is N2,000. What net book value will be shown in the balance sheet at the year end?","options":["N80,000","N98,000","N78,000","N82,000"],"correctOption":2,"section":"Depreciation of non-current assets","explanation":"Net book value is cost less all depreciation charged to date: N100,000 - (N20,000 brought forward + N2,000 for this year) = N78,000. Option A (N80,000) forgets the current year's charge, and option B (N98,000) deducts only this year's charge and ignores the provision from earlier years."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 440, $official_bank_source${"itemId":"24fe1965-3bb0-5fa9-b33a-cab307c61a34","questionId":"d88e0b55-f245-5b12-90ec-21097aaa63a4","sourceKey":"bank:ACC101:ACC-0353","payload":{"prompt":"What is ignored in the computation of depreciation of a fixed asset?","options":["Its estimated residual value at the end of its useful life in the business","Its length of expected useful economic life to the business","Its cost","Its cost of repairs"],"correctOption":3,"section":"Depreciation of non-current assets","explanation":"Depreciation is worked out using the asset's cost, its estimated residual value and its expected useful life (options A, B and C). The cost of repairs is ignored, because ordinary repairs are revenue expenditure charged directly to profit or loss, not part of the depreciable amount."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 441, $official_bank_source${"itemId":"128cdbcb-9900-5ae3-8cf6-2f97a26e94ee","questionId":"a853ce75-f093-589d-84c8-032fe9733ac7","sourceKey":"bank:ACC101:A101N3-050","payload":{"prompt":"Depreciation is best described as","options":["Writing off the cost of repairs carried out on an asset","Spreading the cost of a non-current asset over its useful life","Recording an increase in the market value of an asset","Setting aside cash to replace an asset at the end of its life"],"correctOption":1,"section":"Depreciation of non-current assets","explanation":"Depreciation allocates the cost of a non-current asset, such as a machine or a van, across the years in which it is used. It is not a cash fund for replacement; charging depreciation does not move any money out of the bank."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 442, $official_bank_source${"itemId":"deacb5d3-6207-5a13-9964-548ad43921e0","questionId":"01b0ac7d-7f77-5e9d-b9b1-02888cf5ae96","sourceKey":"bank:ACC101:A101N3-051","payload":{"prompt":"Depreciation can be described as the expired portion of","options":["Owner's capital","Revenue expenditure","Capital expenditure","Trade receivables"],"correctOption":2,"section":"Depreciation of non-current assets","explanation":"Buying a non-current asset is capital expenditure, and the part of that cost used up each year is the depreciation charge. Revenue expenditure, such as rent or wages, is charged in full in the year it is incurred, so there is nothing left to expire later."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 443, $official_bank_source${"itemId":"1f26183f-32e3-57d8-808d-8ec063d19991","questionId":"62a29738-c7be-5eff-bca4-67ae85a74410","sourceKey":"bank:ACC101:A101N3-052","payload":{"prompt":"Charging part of the cost of a delivery van as an expense in each year that the van helps to earn revenue follows the","options":["Matching concept","Business entity concept","Realisation concept","Money measurement concept"],"correctOption":0,"section":"Depreciation of non-current assets","explanation":"Depreciation matches part of the cost of an asset against the revenue it helps to earn in each year of its use. The realisation concept is about when revenue is recognised, not about spreading the cost of an asset over the years."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 444, $official_bank_source${"itemId":"75289174-ba7e-5b7b-ab66-978851723fb4","questionId":"d26cc96e-925f-5d1b-ae71-aa4ef77556df","sourceKey":"bank:ACC101:A101N3-053","payload":{"prompt":"Which of the following is NOT a method of depreciation?","options":["Sum of the years' digits method","Weighted average method","Straight line method","Reducing balance method"],"correctOption":1,"section":"Depreciation of non-current assets","explanation":"The weighted average method is a way of valuing inventory, not of depreciating non-current assets. Straight line, reducing balance and sum of the years' digits are the three depreciation methods named for this course."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 445, $official_bank_source${"itemId":"a6b6644c-c2c3-549f-8144-93af10e6a312","questionId":"0cc01a4f-41b1-5667-816e-072cae2ee008","sourceKey":"bank:ACC101:A101N3-054","payload":{"prompt":"Which of the following is taken into account when computing the annual depreciation of a machine?","options":["Its fuel and running costs","Its cost of repairs","Its residual value","Its annual insurance premium"],"correctOption":2,"section":"Depreciation of non-current assets","explanation":"Depreciation is worked out from the asset's cost, its useful life and its residual value, the amount expected when it is disposed of. Repair costs are ignored, because they are running expenses charged separately, not part of the cost being spread."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 446, $official_bank_source${"itemId":"9c882027-f1ba-5056-9e4d-4ca1560c3e29","questionId":"2ef52264-4d7b-58ef-8722-69c5b4f0e021","sourceKey":"bank:ACC101:A101N3-055","payload":{"prompt":"Under the straight line method, the annual depreciation charge is calculated as","options":["(Cost - residual value) / useful life in years","(Cost + residual value) / useful life in years","(Remaining life / sum of the digits) x cost","Rate x net book value at the start of the year"],"correctOption":0,"section":"Depreciation of non-current assets","explanation":"The straight line method spreads the depreciable amount, cost less residual value, equally over the useful life, giving the same charge each year. Rate x net book value at the start of the year is the reducing balance method, which gives a falling charge."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 447, $official_bank_source${"itemId":"192f726d-5d3a-5883-bdfa-842beadd0567","questionId":"829ab34d-fa4c-50a0-95d0-2e1b45d90f1a","sourceKey":"bank:ACC101:A101N3-056","payload":{"prompt":"Under the reducing balance method, each year's depreciation charge is calculated as","options":["A fixed rate applied to the original cost every year","Remaining life over the sum of the digits applied to cost less residual value","Cost less residual value divided by the useful life","A fixed rate applied to the net book value at the start of the year"],"correctOption":3,"section":"Depreciation of non-current assets","explanation":"The reducing balance method applies the same percentage to the net book value at the start of each year, so the charge falls as the book value falls. Applying the rate to the original cost every year would give an equal charge each year, which is how the straight line method behaves."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 448, $official_bank_source${"itemId":"2d27b601-011f-5628-8a60-954ed6b73db2","questionId":"e700a96d-37aa-57ff-a52a-f34b43197513","sourceKey":"bank:ACC101:A101N3-057","payload":{"prompt":"The net book value of a non-current asset is","options":["Cost plus accumulated depreciation","Selling price less cost","Cost less residual value","Cost less accumulated depreciation"],"correctOption":3,"section":"Depreciation of non-current assets","explanation":"Net book value is what remains of the asset's cost after deducting all depreciation charged on it so far. Cost less residual value is the depreciable amount that is spread over the asset's life, not the value at which the asset is carried."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 449, $official_bank_source${"itemId":"e7108997-215b-5a80-be73-66ea09fa46ce","questionId":"02cafa3e-1af9-5b53-ba89-5293ba13b2d8","sourceKey":"bank:ACC101:A101N3-058","payload":{"prompt":"A gain made on the disposal of a non-current asset is","options":["Debited to the income statement","Debited to the asset account","Credited to the income statement","Added directly to the owner's capital account"],"correctOption":2,"section":"Depreciation of non-current assets","explanation":"A gain on disposal is treated as income for the year, so it is credited to the income statement. Debiting it to the income statement would treat it as a loss and reduce profit, which is the treatment for a loss on disposal."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 450, $official_bank_source${"itemId":"2e3a66c2-940a-55db-a4bb-5909f8418411","questionId":"72203cbf-13d1-5a95-94e7-f5ed1bd71558","sourceKey":"bank:ACC101:A101N3-059","payload":{"prompt":"A firm with a 31 December year end bought a machine in March 2023 and sold it in June 2025. Depreciation is N10,000 a year on the straight line method, and the firm uses the yearly method. What total depreciation is charged on the machine over its life in the firm?","options":["N23,333","N30,000","N10,000","N20,000"],"correctOption":3,"section":"Depreciation of non-current assets","explanation":"Under the yearly method, a full year is charged in the year of purchase (2023) and in 2024, but nothing in the year of sale (2025), so the total is 2 x 10,000 = N20,000. N30,000 wrongly charges a full year in 2025 as well."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 451, $official_bank_source${"itemId":"bdf4f10d-dfdb-5d16-92bd-93d6f17a51af","questionId":"c7d4809b-9240-5360-9eeb-14aa7d2d80a7","sourceKey":"bank:ACC101:A101N3-060","payload":{"prompt":"For an asset with a useful life of 4 years, the sum of the digits used in the sum of the years' digits method is","options":["10","8","16","4"],"correctOption":0,"section":"Depreciation of non-current assets","explanation":"The sum of the years' digits is 1 + 2 + 3 + 4 = 10, so the first year's charge is 4/10 of cost less residual value. The figure 4 is just the useful life, not the sum of the digits."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 452, $official_bank_source${"itemId":"72ae756c-538c-57d7-961c-08f354bccb2d","questionId":"71d1c5e6-a0eb-57e0-98d5-d89ab54a7f27","sourceKey":"bank:ACC101:A101N3-061","payload":{"prompt":"A bank in Lagos buys a generator for N2,400,000. It has a useful life of 4 years and a residual value of N400,000. What is the annual depreciation charge using the straight line method?","options":["N600,000","N500,000","N400,000","N700,000"],"correctOption":1,"section":"Depreciation of non-current assets","explanation":"Annual charge = (2,400,000 - 400,000) / 4 = N500,000. N600,000 ignores the residual value and divides the full cost by 4."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 453, $official_bank_source${"itemId":"fb029ea8-930d-5ab6-94da-aca58563ba9c","questionId":"dc08ac8b-73d4-578e-bc08-368833114e63","sourceKey":"bank:ACC101:A101N3-062","payload":{"prompt":"A machine costing N900,000 has a residual value of N100,000 and a useful life of 8 years. Using the straight line method, what is its net book value at the end of year 3?","options":["N300,000","N562,500","N600,000","N500,000"],"correctOption":2,"section":"Depreciation of non-current assets","explanation":"The annual charge is (900,000 - 100,000) / 8 = N100,000, so after 3 years accumulated depreciation is N300,000 and NBV = 900,000 - 300,000 = N600,000. N300,000 is the accumulated depreciation, not the net book value."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 454, $official_bank_source${"itemId":"1f7fefc7-68e0-588d-9fc8-cb4a7db860e5","questionId":"d4518497-7103-5a21-89f0-200565897c96","sourceKey":"bank:ACC101:A101N3-063","payload":{"prompt":"Equipment cost N750,000 and is depreciated by the straight line method over 5 years at N140,000 a year. What residual value was assumed?","options":["N50,000","N190,000","N0","N610,000"],"correctOption":0,"section":"Depreciation of non-current assets","explanation":"Total depreciation over the life is 140,000 x 5 = N700,000, so residual value = 750,000 - 700,000 = N50,000. N610,000 deducts only one year's charge from the cost."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 455, $official_bank_source${"itemId":"6ce55b69-d54f-5999-a2ec-47724880fbb8","questionId":"9bff8d17-418c-57ca-a790-2b3890ec3b50","sourceKey":"bank:ACC101:A101N3-064","payload":{"prompt":"Using a 25% reducing balance rate, what is the second-year depreciation on a delivery van that cost N500,000?","options":["N62,500","N93,750","N218,750","N125,000"],"correctOption":1,"section":"Depreciation of non-current assets","explanation":"Year 1 charge is 25% x 500,000 = N125,000, leaving NBV of N375,000, so year 2 charge is 25% x 375,000 = N93,750. N125,000 applies the rate to the original cost again, which is the straight line approach."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 456, $official_bank_source${"itemId":"9c6e472c-207f-5fac-8499-2c78a11edf61","questionId":"25cb993c-1bd7-52c0-9174-6debb7e5ee0d","sourceKey":"bank:ACC101:A101N3-065","payload":{"prompt":"A printing machine bought by a firm in Ikeja for N800,000 is depreciated at 10% a year on the reducing balance method. What is its net book value at the end of year 3?","options":["N583,200","N560,000","N648,000","N216,800"],"correctOption":0,"section":"Depreciation of non-current assets","explanation":"NBV after n years = cost x (1 - rate)^n = 800,000 x 0.9^3 = N583,200. N560,000 deducts 10% of the original cost for each of 3 years, which treats the method as straight line."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 457, $official_bank_source${"itemId":"4f0df038-454e-5e56-98aa-d202ecd2821d","questionId":"2398cde6-4ed5-5034-b36a-dad7cfee32b4","sourceKey":"bank:ACC101:A101N3-066","payload":{"prompt":"Office equipment cost N1,000,000. If depreciation is provided at 20% per annum on the reducing balance, how much accumulated depreciation will stand in the books after two years?","options":["N160,000","N640,000","N400,000","N360,000"],"correctOption":3,"section":"Depreciation of non-current assets","explanation":"Year 1 charge is N200,000 and year 2 charge is 20% x 800,000 = N160,000, so accumulated depreciation is N360,000. N400,000 charges 20% of cost in both years, which is the straight line result, not reducing balance."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 458, $official_bank_source${"itemId":"4814f203-aa54-5dbe-ab69-28ad15779b39","questionId":"ac34d47a-d7eb-5b07-8930-6c625aa5fd8f","sourceKey":"bank:ACC101:A101N3-067","payload":{"prompt":"Find the year 2 sum-of-the-years'-digits charge for a machine costing N650,000 with a 4-year life and N50,000 residual value.","options":["N180,000","N195,000","N150,000","N240,000"],"correctOption":0,"section":"Depreciation of non-current assets","explanation":"The sum of the digits is 10 and the depreciable amount is N600,000; in year 2 the remaining life is 3, so the charge is 3/10 x 600,000 = N180,000. N195,000 applies 3/10 to the full cost and forgets to deduct the residual value."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 459, $official_bank_source${"itemId":"17d67b67-cf67-57f1-8ea7-84ee1b4b7091","questionId":"3293017a-9f68-5b69-ae36-1e5ff8ebcbac","sourceKey":"bank:ACC101:A101N3-068","payload":{"prompt":"An asset (cost N320,000, residual N20,000, life 5 years) is depreciated on the sum of the years' digits basis. How much is charged in its third year?","options":["N64,000","N60,000","N80,000","N100,000"],"correctOption":1,"section":"Depreciation of non-current assets","explanation":"The sum of the digits is 15 and the remaining life at the start of year 3 is 3, so the charge is 3/15 x (320,000 - 20,000) = N60,000. N64,000 applies 3/15 to the full cost without deducting the residual value."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 460, $official_bank_source${"itemId":"d5ec0911-a59f-541e-bb12-8d176063f97a","questionId":"e8694729-e28d-5747-8a1d-1e4a107693de","sourceKey":"bank:ACC101:A101N3-069","payload":{"prompt":"A machine cost N600,000, has no residual value and is depreciated by the straight line method over 5 years. It is sold for N300,000 after 3 full years. What is the result on disposal?","options":["Gain of N60,000","Loss of N60,000","Gain of N300,000","Loss of N300,000"],"correctOption":0,"section":"Depreciation of non-current assets","explanation":"Annual depreciation is N120,000, so after 3 years NBV = 600,000 - 360,000 = N240,000, and selling for N300,000 gives a gain of N60,000. The loss of N300,000 wrongly compares the proceeds with the original cost instead of the net book value."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 461, $official_bank_source${"itemId":"25c1b0d3-5d37-5bdd-8ec9-25048f64ec97","questionId":"91eca9e8-ea11-5c15-b04b-e4195e11e2e6","sourceKey":"bank:ACC101:A101N3-070","payload":{"prompt":"Equipment costing N400,000 is depreciated at 20% a year on the reducing balance method. After 2 full years it is sold for N200,000. What is the result on disposal?","options":["Loss of N120,000","Loss of N56,000","Loss of N40,000","Gain of N56,000"],"correctOption":1,"section":"Depreciation of non-current assets","explanation":"NBV after 2 years is 400,000 x 0.8^2 = N256,000, and selling for N200,000 gives a loss of N56,000. The loss of N40,000 uses a straight line NBV of N240,000, which does not apply under the reducing balance method."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 462, $official_bank_source${"itemId":"de47ecbe-ca4e-5522-be1c-92a202772867","questionId":"b295e8a2-b616-5b59-adca-04f9445f1a4d","sourceKey":"bank:ACC101:A101N3-071","payload":{"prompt":"A firm in Ikeja bought a generator for N3,000,000. It has a residual value of N600,000 and a useful life of 6 years. Using the straight line method, what is the accumulated depreciation at the end of year 4?","options":["N1,400,000","N1,200,000","N1,600,000","N2,000,000"],"correctOption":2,"section":"Depreciation of non-current assets","explanation":"The annual charge is (3,000,000 - 600,000) / 6 = N400,000, so after 4 years accumulated depreciation is 4 x 400,000 = N1,600,000. N2,000,000 ignores the residual value, and N1,400,000 is the net book value rather than the accumulated depreciation."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 463, $official_bank_source${"itemId":"17bfa744-3996-52cf-b0a0-b1c00addc8b4","questionId":"8ea81dc5-ce64-5ef5-8fca-4ea806b5cc59","sourceKey":"bank:ACC101:A101N3-072","payload":{"prompt":"What depreciation will be charged in the third year on a N600,000 machine written down at 30% per annum on the reducing balance basis?","options":["N180,000","N126,000","N205,800","N88,200"],"correctOption":3,"section":"Depreciation of non-current assets","explanation":"NBV falls to 600,000 x 0.7 = N420,000 after year 1 and to N294,000 after year 2, so year 3 charge is 30% x 294,000 = N88,200. N126,000 is the year 2 charge (30% x 420,000), not the year 3 charge."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 464, $official_bank_source${"itemId":"e325d8d9-3ff9-585d-a3a6-b6267d678d4e","questionId":"61153370-921e-5bbc-9656-dc411d0fa60e","sourceKey":"bank:ACC101:A101N3-073","payload":{"prompt":"In the statement of financial position, the net book value of equipment is its cost less the","options":["Residual value","Provision for doubtful debts","Depreciation charge for the current year only","Provision for depreciation"],"correctOption":3,"section":"Depreciation of non-current assets","explanation":"The provision for depreciation (accumulated depreciation) holds all depreciation charged on the asset to date, and deducting it from cost gives net book value. Deducting only the current year's charge would ignore depreciation from earlier years and overstate the asset."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 465, $official_bank_source${"itemId":"cad567bb-db6d-553e-9f7d-9faa10c22400","questionId":"fdc5727f-03cd-5290-93c2-0d4577f92c0f","sourceKey":"bank:ACC101:A101N3-075","payload":{"prompt":"A machine is depreciated by the straight line method at N90,000 a year over 6 years, and its residual value is N30,000. What did the machine cost?","options":["N540,000","N600,000","N570,000","N510,000"],"correctOption":2,"section":"Depreciation of non-current assets","explanation":"Cost less residual value equals total depreciation, 90,000 x 6 = N540,000, so cost = 540,000 + 30,000 = N570,000. N540,000 is only the depreciable amount; it leaves out the residual value that is still part of the cost."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 466, $official_bank_source${"itemId":"bd67b7d8-3ca0-5917-b012-fbbde2396611","questionId":"daacb800-23dd-55a3-91db-f767c3d8e5bb","sourceKey":"bank:ACC101:A101N3-076","payload":{"prompt":"Using sum of the years' digits, find the net book value at the end of year 2 of an asset bought for N330,000 (residual value N30,000, useful life 5 years).","options":["N150,000","N120,000","N180,000","N210,000"],"correctOption":0,"section":"Depreciation of non-current assets","explanation":"The depreciable amount is N300,000, so year 1 charge is 5/15 x 300,000 = N100,000 and year 2 is 4/15 x 300,000 = N80,000; NBV = 330,000 - 180,000 = N150,000. N210,000 uses straight line depreciation of N60,000 a year instead of the sum of the digits."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 467, $official_bank_source${"itemId":"763aefb6-8495-590e-becb-a6ffd7869df2","questionId":"087df9cb-bccc-51e6-8373-c08c8c23f39b","sourceKey":"bank:ACC101:A101N3-077","payload":{"prompt":"Which depreciation method gives the same charge in every year of an asset's life?","options":["Both reducing balance and sum of the years' digits","Sum of the years' digits method","Reducing balance method","Straight line method"],"correctOption":3,"section":"Depreciation of non-current assets","explanation":"The straight line method divides cost less residual value equally by the useful life, so the charge is the same every year. The reducing balance method gives a falling charge because the rate is applied to a falling net book value."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 468, $official_bank_source${"itemId":"4b9891eb-dad5-5cf3-924d-c727bfab27bb","questionId":"98ded3bf-a479-509d-9664-072485e82aa2","sourceKey":"bank:ACC101:A101N3-078","payload":{"prompt":"What is the first-year charge on a N440,000 machine (residual value N20,000, 6-year life) under the sum of the years' digits method?","options":["N20,000","N125,714","N120,000","N70,000"],"correctOption":2,"section":"Depreciation of non-current assets","explanation":"The sum of the digits for 6 years is 21, so year 1 charge is 6/21 x (440,000 - 20,000) = N120,000. N125,714 applies 6/21 to the full cost without deducting the residual value."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 469, $official_bank_source${"itemId":"ece1c01f-6642-567c-9cae-e7bba7dd1b56","questionId":"b2db6d4d-bb4f-50d8-ab07-44fd013e9374","sourceKey":"bank:ACC101:ACC-0043","payload":{"prompt":"The trial balance of Olumide Bakare & Co shows a Trade receivable balance of N2,500,000 as at 31 December, 2012 while the provision for doubtful debt was given as N500,000.00. Additional information was given to the effect that the provision for doubtful debt should be N750,000.00 of trade receivables. How much should reflect in Profit and Loss account as cost?","options":["N625,000.00","N500,000.00","N750,000.00","N250,000.00"],"correctOption":3,"section":"Bad debts and doubtful debt provisions","explanation":"Only the increase in the provision is charged to profit and loss: N750,000 - N500,000 = N250,000. Option C is the full new provision, which would double-count the N500,000 already charged in earlier years."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 470, $official_bank_source${"itemId":"3dc75821-ef59-5bbb-b7f0-5c0b0e301392","questionId":"e006dd5f-7d41-5589-9eaf-7ccd41aba7c2","sourceKey":"bank:ACC101:ACC-0367","payload":{"prompt":"Trial Balance of a business shows a trade receivables balance of N30,000. Allowance for doubtful debt is to be 5% of total trade receivables, while allowance for discount on trade receivables is to be 2% of the trade receivables remaining after deducting the allowance for doubtful debt. The amount to show on the Statement of financial position as net Trade receivables is","options":["N27,900","N27,930","N2,070","N2,100"],"correctOption":1,"section":"Bad debts and doubtful debt provisions","explanation":"First deduct the allowance for doubtful debts: 5% x N30,000 = N1,500, leaving N28,500. The discount allowance is then 2% x N28,500 = N570, so net trade receivables = N30,000 - N1,500 - N570 = N27,930. Option A (N27,900) takes the 2% on the full N30,000, and options C and D are allowance totals, not net receivables."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 471, $official_bank_source${"itemId":"d177990e-4636-5dd5-b716-fde8e876aa7f","questionId":"6e03c521-82b4-5097-870c-f93a527f55ba","sourceKey":"bank:ACC101:ACC-0381","payload":{"prompt":"Olude Enterprises had bad debts of N3,000 and accumulated provision for bad debts of N3,500. It is desired to make the provision of N4,000 at the end of the year. The total amount to be debited to P & L A/C is:","options":["N4,000","N5,000","N6,500","N3,500"],"correctOption":3,"section":"Bad debts and doubtful debt provisions","explanation":"The charge to profit or loss is the bad debts written off plus the increase in the provision: N3,000 + (N4,000 - N3,500) = N3,500. Option A (N4,000) is just the new provision, and option C (N6,500) adds the bad debts to the old provision instead of charging only the increase."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 472, $official_bank_source${"itemId":"5be6ca58-6433-5e1d-90c3-8b0075158bdf","questionId":"ca3db401-68ec-5c71-8786-7def15d20590","sourceKey":"bank:ACC101:ACC-0389","payload":{"prompt":"At the end of the financial year, accounts receivables have a balance of N100,000 and provision for the bad & doubtful debts provided amounting to N70,000. The Net realizable value of the accounts receivable in the statement of financial position is:","options":["N170,000","N70,000","N30,000","N100,000"],"correctOption":2,"section":"Bad debts and doubtful debt provisions","explanation":"Receivables are shown net of the provision for bad and doubtful debts: N100,000 - N70,000 = N30,000. Option A (N170,000) adds the provision instead of deducting it, and option D (N100,000) ignores the provision altogether."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 473, $official_bank_source${"itemId":"14985e27-4efb-538b-8146-68e1d35d13ee","questionId":"2102f02b-0b09-563c-b211-1e1550df56f2","sourceKey":"bank:ACC101:A101N3-079","payload":{"prompt":"A customer owing N40,000 to a trader in Balogun market is declared bankrupt, and the debt is written off. The correct entry is","options":["Debit cash, credit the customer's account","Debit bad debts, credit sales","Debit bad debts, credit the customer's account","Debit the customer's account, credit bad debts"],"correctOption":2,"section":"Bad debts and doubtful debt provisions","explanation":"Writing off a bad debt charges an expense (debit bad debts) and removes the amount from the customer's receivable balance (credit the customer). Debiting cash is wrong because no money has been received from the bankrupt customer."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 474, $official_bank_source${"itemId":"db8f7368-7dbd-595f-a5e3-b4a2df3b6bb2","questionId":"1754938c-4e67-5d9b-b7f0-d9c7a1d77ea7","sourceKey":"bank:ACC101:A101N3-080","payload":{"prompt":"What effect does writing off a bad debt have on the statement of financial position?","options":["It increases trade receivables","It increases the provision for depreciation","It reduces trade receivables","It reduces trade payables"],"correctOption":2,"section":"Bad debts and doubtful debt provisions","explanation":"The customer's account is credited when the debt is written off, so the amount owed to the business, trade receivables, goes down. Trade payables are amounts the business owes its suppliers, so they are not affected."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 475, $official_bank_source${"itemId":"36fd7092-e9c4-5161-884a-6dda3cf18715","questionId":"6bd536a5-a8ff-571b-b0d3-9dff684a5253","sourceKey":"bank:ACC101:A101N3-081","payload":{"prompt":"In the income statement, bad debts written off are treated as","options":["A current asset","An expense","Income","A current liability"],"correctOption":1,"section":"Bad debts and doubtful debt provisions","explanation":"A bad debt is a loss to the business, so it is debited to the bad debts account and charged as an expense, reducing profit. Treating it as a current asset is wrong, because the amount can no longer be collected and has been removed from receivables."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 476, $official_bank_source${"itemId":"7c888be7-6e64-56d3-a276-fb9787aa70e7","questionId":"7783b539-a9dc-5a41-ac27-2dcf257cda54","sourceKey":"bank:ACC101:A101N3-082","payload":{"prompt":"A provision for doubtful debts is","options":["Discounts given to customers for paying promptly","An estimate of debts that may not be collected","Debts that have already been written off as irrecoverable","The total amount owed by all credit customers"],"correctOption":1,"section":"Bad debts and doubtful debt provisions","explanation":"A provision for doubtful debts is an estimate of the part of receivables that may not be collected, made before any particular debt has gone bad. Debts already written off are bad debts, which are actual losses, not an estimate."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 477, $official_bank_source${"itemId":"fd3a38ba-d6d4-5020-b2c4-22b9eeeb09e3","questionId":"5c41da5a-bd62-594b-b45b-3d827481791d","sourceKey":"bank:ACC101:A101N3-083","payload":{"prompt":"In the statement of financial position, the provision for doubtful debts is shown","options":["As a current liability","As an addition to trade receivables","As a deduction from trade receivables","As a non-current liability"],"correctOption":2,"section":"Bad debts and doubtful debt provisions","explanation":"The provision reduces trade receivables to the amount the business expects to collect, so it is deducted from receivables. It is not a liability, because the business does not owe anyone this amount."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 478, $official_bank_source${"itemId":"f2c89d3c-293e-5459-b71d-55d148f1c489","questionId":"e746b205-4710-5ed2-b7f9-efa806756e27","sourceKey":"bank:ACC101:A101N3-084","payload":{"prompt":"Making a provision for doubtful debts, so that receivables are not shown at more than the amount expected to be collected, follows the","options":["Business entity concept","Prudence concept","Going concern concept","Money measurement concept"],"correctOption":1,"section":"Bad debts and doubtful debt provisions","explanation":"Prudence requires that assets are not overstated, so the business provides for debts that may not be collected. The going concern concept assumes the business will continue operating, which does not deal with the risk of customers not paying."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 479, $official_bank_source${"itemId":"37d7c9b8-7de4-5956-b740-991cddffce74","questionId":"9235ee95-36dc-558d-b4b1-7c97db6cabc2","sourceKey":"bank:ACC101:A101N3-085","payload":{"prompt":"When a provision for doubtful debts already exists from the previous year, the amount taken to profit or loss in respect of the provision this year is","options":["The old provision only","The full new provision plus the old provision","Only the change (increase or decrease) in the provision","The full new provision"],"correctOption":2,"section":"Bad debts and doubtful debt provisions","explanation":"The old provision has already been charged in earlier years, so only the change in the provision is taken to profit or loss. Charging the full new provision would count the old part twice."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 480, $official_bank_source${"itemId":"36a54cc7-8078-5372-b1de-e5e7b8157778","questionId":"a08dc5fa-f991-5ada-88bd-43454580c062","sourceKey":"bank:ACC101:A101N3-086","payload":{"prompt":"A reduction in the provision for doubtful debts is treated in the income statement as","options":["A non-current liability","An expense","Income","Drawings"],"correctOption":2,"section":"Bad debts and doubtful debt provisions","explanation":"When the provision falls, part of an amount charged in earlier years is no longer needed, so the decrease is credited to profit or loss as income. Treating it as an expense is the rule for an increase in the provision, not a decrease."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 481, $official_bank_source${"itemId":"e29bd323-265d-56fc-998c-4463d467c3d6","questionId":"2e26ef8c-e8cd-58b0-82a3-333fcadece1f","sourceKey":"bank:ACC101:A101N3-087","payload":{"prompt":"The double entry to record an increase in the provision for doubtful debts is","options":["Debit profit and loss account, credit provision for doubtful debts","Debit provision for doubtful debts, credit trade receivables","Debit trade receivables, credit provision for doubtful debts","Debit provision for doubtful debts, credit profit and loss account"],"correctOption":0,"section":"Bad debts and doubtful debt provisions","explanation":"An increase in the provision is an expense, so profit and loss is debited, and the provision, a contra-asset account, is increased by a credit. Debiting the provision and crediting profit and loss is the entry for a decrease in the provision."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 482, $official_bank_source${"itemId":"e82909b2-953f-559a-9e24-38520c1ede63","questionId":"5492684e-c746-58ac-93e1-ec500744857f","sourceKey":"bank:ACC101:A101N3-088","payload":{"prompt":"When the provision for doubtful debts is reduced at the year end, which entry records the reduction?","options":["Debit profit and loss account, credit provision for doubtful debts","Debit trade receivables, credit profit and loss account","Debit provision for doubtful debts, credit profit and loss account","Debit bad debts, credit trade receivables"],"correctOption":2,"section":"Bad debts and doubtful debt provisions","explanation":"A decrease reduces the provision, a contra-asset normally increased by credits, so the provision is debited and profit and loss is credited with the income. Debiting profit and loss and crediting the provision is the entry for an increase, which would be an expense."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 483, $official_bank_source${"itemId":"7d5d7614-a826-5bab-af25-0dea5ff93337","questionId":"fb41f9c5-764a-56f2-908e-3bac39ea9c0d","sourceKey":"bank:ACC101:A101N3-089","payload":{"prompt":"A provision for discount on debtors is calculated on","options":["Total trade receivables before any provision is deducted","The provision for doubtful debts itself","Trade payables at the year end","Trade receivables remaining after deducting the provision for doubtful debts"],"correctOption":3,"section":"Bad debts and doubtful debt provisions","explanation":"Discount is only expected to be given to customers who will actually pay, so it is worked out on receivables after deducting the provision for doubtful debts. Calculating it on total receivables before the doubtful debt provision would allow a discount on debts that may never be collected."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 484, $official_bank_source${"itemId":"0d09f73a-aea7-5526-b9e2-4ab304fd6f4d","questionId":"deb9aaa5-f715-5b4b-833f-d87667e175c4","sourceKey":"bank:ACC101:A101N3-090","payload":{"prompt":"In the profit and loss account, an increase in the provision for bad debts appears as","options":["A credit, being income","A debit, being an expense","A debit, being an asset","A credit, being a liability"],"correctOption":1,"section":"Bad debts and doubtful debt provisions","explanation":"An increase in the provision for bad debts reduces profit, so it is debited to profit and loss as an expense. A credit as income would be the treatment of a decrease in the provision."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 485, $official_bank_source${"itemId":"814d05e6-a061-5b29-94b6-0401861d3f0c","questionId":"f40435ca-23a6-5bbc-8e34-1848e14b511a","sourceKey":"bank:ACC101:A101N3-091","payload":{"prompt":"A trader fails to write off a debt of N15,000 that is known to be irrecoverable. What is the effect on the accounts?","options":["Profit is overstated and trade receivables understated by N15,000","Profit is understated and trade receivables overstated by N15,000","Profit and trade receivables are both understated by N15,000","Profit and trade receivables are both overstated by N15,000"],"correctOption":3,"section":"Bad debts and doubtful debt provisions","explanation":"The missing write-off means the bad debts expense of N15,000 is left out, so profit is too high, and the uncollectable debt is still counted in receivables, so they are too high as well. Profit cannot be understated, because a missing expense always makes profit look bigger."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 486, $official_bank_source${"itemId":"db233229-a90f-5b90-b1b5-fcf2fdf660cc","questionId":"bc69fc61-8aa5-5063-adeb-6e4527a6786d","sourceKey":"bank:ACC101:A101N3-092","payload":{"prompt":"A business in Ikeja had a provision for doubtful debts of N40,000 at the start of the year. At the year end the provision is to be N55,000. What amount is charged to profit and loss for the provision?","options":["N15,000","N95,000","N55,000","N40,000"],"correctOption":0,"section":"Bad debts and doubtful debt provisions","explanation":"Only the change goes to profit and loss: 55,000 - 40,000 = N15,000, charged as an expense. N55,000 charges the whole new provision, but N40,000 of it was already charged in earlier years."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 487, $official_bank_source${"itemId":"3e5dd7b5-6f43-5d9d-98f1-41dcf520625a","questionId":"3e4eff95-0361-511b-8ce4-d1b51788058f","sourceKey":"bank:ACC101:A101N3-093","payload":{"prompt":"A firm's provision for doubtful debts is to be reduced from N80,000 to N65,000 at the year end. How is this treated in profit and loss?","options":["N15,000 credited as income","N80,000 credited as income","N65,000 debited as an expense","N15,000 debited as an expense"],"correctOption":0,"section":"Bad debts and doubtful debt provisions","explanation":"The provision falls by 80,000 - 65,000 = N15,000, and a decrease in the provision is income, so N15,000 is credited to profit and loss. Debiting N15,000 as an expense treats the change as an increase, which it is not."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 488, $official_bank_source${"itemId":"8bad4bfa-ab83-5dec-ae65-69f25b1b0d11","questionId":"1e7357d5-a519-5061-bc0e-11dab270038c","sourceKey":"bank:ACC101:A101N3-094","payload":{"prompt":"Trade receivables at the year end are N600,000, and the provision for doubtful debts is to be 5% of receivables. The provision brought forward from last year is N20,000. What is charged to profit and loss for the provision this year?","options":["N30,000","N20,000","N10,000","N50,000"],"correctOption":2,"section":"Bad debts and doubtful debt provisions","explanation":"The required provision is 5% x 600,000 = N30,000, so the increase is 30,000 - 20,000 = N10,000. N30,000 charges the whole required provision instead of just the increase."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 489, $official_bank_source${"itemId":"bb29de70-a0f8-5cc8-925f-1d017cc88c65","questionId":"539bf5e5-638c-5224-8d9c-9ab765272e13","sourceKey":"bank:ACC101:A101N3-095","payload":{"prompt":"Trade receivables before adjustments are N820,000. A debt of N20,000 is to be written off, and the provision for doubtful debts is to be 5% of the remaining receivables. The existing provision is N25,000. What is the total charge to profit and loss for bad and doubtful debts?","options":["N15,000","N36,000","N60,000","N35,000"],"correctOption":3,"section":"Bad debts and doubtful debt provisions","explanation":"Remaining receivables are N800,000, so the provision should be N40,000, an increase of N15,000; the total charge is 20,000 + 15,000 = N35,000. N36,000 calculates the 5% on N820,000 before the write-off, which overstates the provision."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 490, $official_bank_source${"itemId":"99b03d2b-eb73-524f-9ba1-bd0da8974bc0","questionId":"99e18ab6-5b0e-558d-b8e6-1659961a6d4c","sourceKey":"bank:ACC101:A101N3-096","payload":{"prompt":"Trade receivables are N950,000 before a bad debt of N50,000 is written off. The provision for doubtful debts is to be 10% of the remaining receivables. What figure is shown for net trade receivables in the statement of financial position?","options":["N855,000","N900,000","N805,000","N810,000"],"correctOption":3,"section":"Bad debts and doubtful debt provisions","explanation":"After the write-off, receivables are N900,000 and the provision is 10% x 900,000 = N90,000, so net receivables are 900,000 - 90,000 = N810,000. N805,000 takes 10% of N950,000 before the write-off, which overstates the provision."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 491, $official_bank_source${"itemId":"a80ed9b1-8cac-544d-9c9a-49e558786595","questionId":"4ae8da95-a597-529b-9666-992cb050a07c","sourceKey":"bank:ACC101:A101N3-097","payload":{"prompt":"During the year, a business wrote off bad debts of N6,000. Its provision for doubtful debts was reduced from N12,000 to N9,000. What is the net charge to profit and loss for bad and doubtful debts?","options":["N9,000","N15,000","N18,000","N3,000"],"correctOption":3,"section":"Bad debts and doubtful debt provisions","explanation":"The bad debts of N6,000 are an expense, while the N3,000 fall in the provision is income, so the net charge is 6,000 - 3,000 = N3,000. N9,000 adds the decrease instead of deducting it, treating it as an expense."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 492, $official_bank_source${"itemId":"5b58abfd-02a2-543e-9f6d-22fb82785b84","questionId":"8cff794b-f7cc-503b-83c5-4847a9d5b824","sourceKey":"bank:ACC101:A101N3-098","payload":{"prompt":"A trader in Balogun market creates a provision for doubtful debts for the first time, at 3% of trade receivables of N300,000. What is charged to profit and loss for the provision this year?","options":["N18,000","N9,000","Nil, since there was no previous provision","N291,000"],"correctOption":1,"section":"Bad debts and doubtful debt provisions","explanation":"With no opening provision, the whole new provision of 3% x 300,000 = N9,000 is the increase and is charged to profit and loss. Saying nil is wrong, because moving from no provision to N9,000 is itself an increase of N9,000."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 493, $official_bank_source${"itemId":"887e605b-de32-562b-92f9-1bddab32f6a5","questionId":"c4fb8b6e-0a1d-5792-a03e-b26c84e0007c","sourceKey":"bank:ACC101:A101N3-099","payload":{"prompt":"Trade receivables are N200,000. The provision for doubtful debts is 5% of receivables, and the provision for discount on debtors is 2.5% of receivables after the doubtful debt provision. What is the provision for discount on debtors?","options":["N5,000","N250","N14,750","N4,750"],"correctOption":3,"section":"Bad debts and doubtful debt provisions","explanation":"The doubtful debt provision is N10,000, leaving N190,000, so the discount provision is 2.5% x 190,000 = N4,750. N5,000 applies 2.5% to the full N200,000, ignoring that discount is worked out after the doubtful debt provision."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 494, $official_bank_source${"itemId":"acb288ea-dca5-5835-8c3e-4447fe8c61a5","questionId":"dd11418d-f8f6-58f1-a24e-6e605bf303ea","sourceKey":"bank:ACC101:A101N3-100","payload":{"prompt":"A Lagos wholesaler has trade receivables of N400,000. It makes a provision for doubtful debts of 10%, and then a provision for discount of 5% on the receivables remaining after the doubtful debt provision. What is the net trade receivables figure in the statement of financial position?","options":["N342,000","N382,000","N360,000","N340,000"],"correctOption":0,"section":"Bad debts and doubtful debt provisions","explanation":"The doubtful debt provision is N40,000, leaving N360,000; the discount provision is 5% x 360,000 = N18,000, so net receivables are N342,000. N340,000 works out the 5% discount on the full N400,000 instead of on the reduced figure."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 495, $official_bank_source${"itemId":"faf28180-cc59-5d1b-9b01-f1507b260e3d","questionId":"9cfc0f51-669a-55ad-90de-2433fdcb225e","sourceKey":"bank:ACC101:A101N3-101","payload":{"prompt":"A business had a provision for doubtful debts of N10,000 at the start of the year. During the year bad debts of N4,000 were written off, and the total charge to profit and loss for bad and doubtful debts was N9,000. What is the provision at the end of the year?","options":["N5,000","N23,000","N19,000","N15,000"],"correctOption":3,"section":"Bad debts and doubtful debt provisions","explanation":"Of the N9,000 charge, N4,000 is bad debts, so the increase in provision is N5,000, and the closing provision is 10,000 + 5,000 = N15,000. N5,000 is only the increase, not the closing balance of the provision."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 496, $official_bank_source${"itemId":"992919ec-fa5c-57bd-a162-b58b7b06aa74","questionId":"14c4615c-16dc-5fc4-b231-ba8fe48b52a0","sourceKey":"bank:ACC101:A101N3-102","payload":{"prompt":"A firm's provision for doubtful debts of N12,500 is 5% of its trade receivables. What is the amount of trade receivables?","options":["N237,500","N250,000","N262,500","N625,000"],"correctOption":1,"section":"Bad debts and doubtful debt provisions","explanation":"If 5% of receivables is N12,500, then receivables are 12,500 / 0.05 = N250,000. N237,500 is the net receivables after deducting the provision, not the receivables on which the 5% was worked out."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 497, $official_bank_source${"itemId":"b80bb924-155a-5a10-a690-eb9e80be7c7d","questionId":"8cb2716e-473d-52b0-9899-517c004a3edc","sourceKey":"bank:ACC101:A101N3-103","payload":{"prompt":"A trader's draft net profit is N500,000. He has not yet written off bad debts of N20,000 or increased the provision for doubtful debts by N8,000. What is the corrected net profit?","options":["N480,000","N472,000","N528,000","N492,000"],"correctOption":1,"section":"Bad debts and doubtful debt provisions","explanation":"Both the bad debts and the increase in provision are expenses, so profit falls to 500,000 - 20,000 - 8,000 = N472,000. N480,000 deducts the bad debts but forgets the increase in the provision."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 498, $official_bank_source${"itemId":"88970145-debb-5522-b42b-0b22a1a7f8e1","questionId":"a71ea2ac-7df5-5250-8c60-32ae030e4ff9","sourceKey":"bank:ACC101:A101N3-104","payload":{"prompt":"The draft net profit of a firm in Ikeja is N300,000 before adjusting for a decrease of N5,000 in the provision for doubtful debts. There are no bad debts this year. What is the corrected net profit?","options":["N305,000","N310,000","N295,000","N300,000"],"correctOption":0,"section":"Bad debts and doubtful debt provisions","explanation":"A decrease in the provision is income, so it is added to profit: 300,000 + 5,000 = N305,000. N295,000 deducts the decrease as though it were an expense."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 499, $official_bank_source${"itemId":"03d5c748-e5c7-5391-b28e-f1f85cdeacc0","questionId":"5f65e75a-832a-5d2b-92d6-937755d72c02","sourceKey":"bank:ACC101:A101N3-105","payload":{"prompt":"During the year, a business wrote off bad debts of N2,000, and its provision for doubtful debts fell by N5,000. What is the net effect on profit and loss?","options":["A net credit (income) of N3,000","A net debit (expense) of N7,000","A net debit (expense) of N3,000","A net credit (income) of N7,000"],"correctOption":0,"section":"Bad debts and doubtful debt provisions","explanation":"The bad debts are an N2,000 expense and the N5,000 fall in the provision is income, giving a net credit of 5,000 - 2,000 = N3,000. A net debit of N7,000 wrongly treats the decrease in the provision as an expense and adds it to the bad debts."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 500, $official_bank_source${"itemId":"4871b8a3-4919-5735-92f6-38ee17f5cee0","questionId":"539d1492-f823-5f13-a3b3-a1d2e70e369b","sourceKey":"bank:ACC101:A101N3-106","payload":{"prompt":"A firm keeps its provision for doubtful debts at 5% of trade receivables. Receivables were N400,000 last year and are N360,000 this year. How is the change in the provision treated this year?","options":["N18,000 debited to profit and loss as an expense","N2,000 debited to profit and loss as an expense","N38,000 debited to profit and loss as an expense","N2,000 credited to profit and loss as income"],"correctOption":3,"section":"Bad debts and doubtful debt provisions","explanation":"Last year's provision was N20,000 and this year's is 5% x 360,000 = N18,000, a decrease of N2,000, which is credited to profit and loss as income. Debiting N18,000 charges the whole new provision instead of only the change."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 501, $official_bank_source${"itemId":"d873d71f-4593-5689-8032-9d2183466715","questionId":"dab70beb-cf28-5fda-a81f-8362bbde1d37","sourceKey":"bank:ACC101:A101N3-107","payload":{"prompt":"A business has trade receivables of N15,000 before writing off bad debts of N1,000. It then creates, for the first time, a provision for doubtful debts of 10% of the remaining receivables. What is the total charge to profit and loss for bad and doubtful debts?","options":["N2,500","N1,500","N2,400","N1,400"],"correctOption":2,"section":"Bad debts and doubtful debt provisions","explanation":"Remaining receivables are N14,000, so the provision is N1,400, and the total charge is 1,000 + 1,400 = N2,400. N2,500 takes 10% of N15,000 before the write-off, which overstates the provision."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 502, $official_bank_source${"itemId":"a4907acc-3906-5970-9bbf-f12ead453733","questionId":"87f0e1a6-dab5-52dc-bd45-dc954744d08d","sourceKey":"bank:ACC101:A101N3-108","payload":{"prompt":"Another name for the provision for doubtful debts is the","options":["Bad debts written off account","Provision for depreciation","Allowance for doubtful debts","Accrued income account"],"correctOption":2,"section":"Bad debts and doubtful debt provisions","explanation":"The provision for doubtful debts is also called the allowance for doubtful debts; both describe the estimate deducted from receivables. Bad debts written off are actual losses already removed from receivables, so they are a different item."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 503, $official_bank_source${"itemId":"dd317449-2116-5333-8ab2-ff2798612cd8","questionId":"63d36526-fbb2-5b10-a428-9052f3223029","sourceKey":"bank:ACC101:A101N3-109","payload":{"prompt":"The main difference between a bad debt and a provision for doubtful debts is that","options":["A bad debt is written off as uncollectable, while a provision is an estimate of debts that may not be collected","A bad debt is added to receivables, while a provision is added to payables","A provision is written off as uncollectable, while a bad debt is an estimate of debts that may not be collected","A bad debt is shown as a current liability, while a provision is shown as a current asset"],"correctOption":0,"section":"Bad debts and doubtful debt provisions","explanation":"A bad debt is a specific debt removed from the books because it will not be paid, while a provision is only an estimate of debts that may not be collected. The option that swaps the two descriptions reverses the meaning of both terms."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 504, $official_bank_source${"itemId":"fae0cda8-735e-535a-908a-08e29a2182d9","questionId":"37a74534-de91-506d-8a2f-09b2be8d7285","sourceKey":"bank:ACC101:A101N3-110","payload":{"prompt":"Which of the following statements about the provision for doubtful debts is NOT correct?","options":["The full balance of the provision is charged to profit and loss every year","It reflects the prudence concept","A decrease in it is treated as income","It is shown as a deduction from trade receivables"],"correctOption":0,"section":"Bad debts and doubtful debt provisions","explanation":"Only the change in the provision is taken to profit and loss each year, not the full balance. The statement that a decrease is treated as income is correct, since a lower provision releases part of an earlier charge back to profit."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 505, $official_bank_source${"itemId":"14009339-9d8c-5575-a5da-36445d8e42f8","questionId":"3d6dadb0-2e8e-5f4a-9cee-9fc1fda143d5","sourceKey":"bank:ACC101:A101N3-111","payload":{"prompt":"Trade receivables are N80,000 before writing off a bad debt of N5,000. A provision for doubtful debts of 4% of the remaining receivables is then made. What figure is shown for net trade receivables?","options":["N71,800","N72,000","N76,800","N75,000"],"correctOption":1,"section":"Bad debts and doubtful debt provisions","explanation":"After the write-off, receivables are N75,000, and the provision is 4% x 75,000 = N3,000, so net receivables are N72,000. N71,800 works out the 4% on the N80,000 before the write-off, giving a provision that is too large."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 506, $official_bank_source${"itemId":"231cdacd-8446-5a34-8a25-a26c5694dcdf","questionId":"e7f482c9-a299-5577-bf1c-6a682a7965e0","sourceKey":"bank:ACC101:A101N3-112","payload":{"prompt":"An increase of N12,000 in the provision for doubtful debts has which effect on the accounts?","options":["It reduces net trade receivables but does not affect net profit","It reduces both net profit and net trade receivables by N12,000","It reduces net profit but does not affect net trade receivables","It increases net profit and reduces net trade receivables"],"correctOption":1,"section":"Bad debts and doubtful debt provisions","explanation":"The increase is charged to profit and loss as an expense, lowering net profit, and the larger provision is deducted from receivables, lowering net receivables, both by N12,000. Saying profit is unaffected ignores that an increase in the provision is an expense."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 507, $official_bank_source${"itemId":"57e187b5-ae13-5096-a699-5a025ef5f09c","questionId":"bae9203a-b9bb-5e57-84b0-2929cce3570e","sourceKey":"bank:ACC101:A101N3-113","payload":{"prompt":"Bayo, a wholesaler in Ikeja, expects that about 5% of his customers' balances may never be paid, although no customer has yet defaulted. What should he do at the year end?","options":["Record a 5% liability to his customers","Write off 5% of trade receivables as bad debts","Reduce his sales figure by 5%","Create a provision for doubtful debts"],"correctOption":3,"section":"Bad debts and doubtful debt provisions","explanation":"Because no specific debt has gone bad, Bayo should make a provision for doubtful debts, which is an estimate of debts that may not be collected. Writing off 5% as bad debts would be wrong, since bad debts are written off only when particular debts are known to be uncollectable."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 508, $official_bank_source${"itemId":"81fb2b74-3134-5156-8d38-739d8a37aa8c","questionId":"8afec813-73d0-5d34-8f86-1d6c2732e43a","sourceKey":"bank:ACC101:A101N3-114","payload":{"prompt":"A Lagos distributor's trade receivables were N500,000 at both the start and the end of the year, but the provision for doubtful debts was raised from 2% to 4% of receivables. What is charged to profit and loss for the provision this year?","options":["N10,000","Nil, since receivables did not change","N20,000","N30,000"],"correctOption":0,"section":"Bad debts and doubtful debt provisions","explanation":"The provision rises from 2% x 500,000 = N10,000 to 4% x 500,000 = N20,000, so the increase of N10,000 is charged as an expense. N20,000 is the whole new provision, but only the change in the provision goes to profit and loss."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 509, $official_bank_source${"itemId":"4e97cdfd-6786-5ab3-ad9b-4c9380f6bf48","questionId":"b8ca0b29-db9c-5297-83f8-9526b9d64d56","sourceKey":"bank:ACC101:ACC-0030","payload":{"prompt":"Which one of the following is not a reporting category in the income statement?","options":["Operational profit or loss","Cost of sales","Trading account","Selling and distribution cost"],"correctOption":2,"section":"Final accounts of a sole trader","explanation":"An income statement is presented under headings such as revenue, cost of sales, distribution costs and operating profit or loss. The trading account is a bookkeeping account used to work out gross profit, not a reporting category of the statement itself. Options A, B and D are all standard headings."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 510, $official_bank_source${"itemId":"c0434fa5-d25f-50d0-9b4c-53c14b71a6a5","questionId":"513d6895-bf90-52b6-bd7c-7543dce8dbdc","sourceKey":"bank:ACC101:ACC-0143","payload":{"prompt":"The financial statement that reports the portion of change in owner's equity resulting from revenues and expenses during a specified time interval is the","options":["Journal","liability","Profit and loss","Dividends"],"correctOption":2,"section":"Final accounts of a sole trader","explanation":"The profit and loss account (income statement) shows revenues minus expenses for a period, which is exactly the part of the change in owner's equity caused by trading. A journal (Option A) is a book of entry, a liability (Option B) is an obligation, and dividends (Option D) are distributions to owners, not a statement."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 511, $official_bank_source${"itemId":"63052488-1c5b-5964-a2cf-1ab4ece42567","questionId":"379a9bce-5dd9-5dcb-b488-8138ce3433d9","sourceKey":"bank:ACC101:ACC-0182","payload":{"prompt":"The financial statement with a structure that is similar to the accounting equation is the","options":["Reconciliation","Balance sheet","Equity","Trial Balance"],"correctOption":1,"section":"Final accounts of a sole trader","explanation":"The balance sheet lists assets on one side and liabilities plus owner's equity on the other, which follows the accounting equation Assets = Liabilities + Equity. A trial balance (Option D) also balances, but it lists debits and credits for all accounts, including income and expenses, so it does not follow the equation's structure."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 512, $official_bank_source${"itemId":"65fea8df-673b-563d-846f-102cace74991","questionId":"b6e2315d-3433-59b1-99e6-7c1752ea5dd1","sourceKey":"bank:ACC101:ACC-0203","payload":{"prompt":"Financial statements are reports that allow interested parties to evaluate the profitability and solvency of a business. This statement do not includes one of the following","options":["Income Statement","Expenditure Statement","Statement of Owner's Equity","Balance Sheet"],"correctOption":1,"section":"Final accounts of a sole trader","explanation":"The main financial statements are the income statement (profit or loss), the statement of owner's equity (changes in equity) and the balance sheet (statement of financial position), so an \"expenditure statement\" is not one of them. Options A, C and D are all standard financial statements used to judge profitability and solvency."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 513, $official_bank_source${"itemId":"7904c858-0865-5f61-bbe5-71cbbdbf48f6","questionId":"32222527-95c3-5b6e-be55-45a829e29375","sourceKey":"bank:ACC101:ACC-0228","payload":{"prompt":"A balance sheet is drawn up to ascertain","options":["The assets owned by the reporting entity as at the balance sheet date","The liabilities owed by the reporting as at the balance sheet date","The profit/loss made by the reporting entity for the period to the balance sheet date","The financial position of the reporting entity as at the balance sheet date"],"correctOption":3,"section":"Final accounts of a sole trader","explanation":"A balance sheet shows the financial position of the business at a particular date by listing its assets, liabilities and capital together. Options A and B describe only one part of the balance sheet. Option C describes the profit and loss account, which covers a period rather than a single date."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 514, $official_bank_source${"itemId":"fa0bd671-8753-588b-85c0-37b4b9dcfe09","questionId":"750077c3-d4b0-56af-bf9b-85aa62e0da90","sourceKey":"bank:ACC101:ACC-0354","payload":{"prompt":"A trader's inventory was N1,000 higher at the end of a year than at the beginning of the year. Net sales for the year were N25,000 and purchases were N14,000. As a result, the year's","options":["cost of goods sold was N15,000","gross profit was N14,000","gross profit was 48% of net sales.","cost of goods available for sales was N13,000"],"correctOption":2,"section":"Final accounts of a sole trader","explanation":"Closing inventory is N1,000 higher than opening, so cost of goods sold = purchases - increase in inventory = N14,000 - N1,000 = N13,000. Gross profit = N25,000 - N13,000 = N12,000, which is N12,000 / N25,000 = 48% of net sales. Option A (N15,000) adds the inventory increase instead of subtracting it, and option B (N14,000) confuses gross profit with purchases."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 515, $official_bank_source${"itemId":"5b4d319f-49c2-53ee-af60-1124501ddbc3","questionId":"acfda706-3154-55f7-9b73-2c8e84194dd7","sourceKey":"bank:ACC101:ACC-0363","payload":{"prompt":"A trader has the following data pertaining to the year ended 31st December 20X2: Opening Inventory N340,000, Purchases N900,000, Closing Inventory N420,000, Carriage Inwards N100,000, Carriage Outwards N150,000. The cost of goods sold during the year was","options":["N770,000","N920,000","N970,000","N1,080,000"],"correctOption":1,"section":"Final accounts of a sole trader","explanation":"Cost of goods sold = opening inventory + purchases + carriage inwards - closing inventory = N340,000 + N900,000 + N100,000 - N420,000 = N920,000. Carriage outwards is a selling expense in the profit or loss, not part of cost of goods sold, so option C (N970,000), which uses carriage outwards instead of carriage inwards, is wrong. Option A (N770,000) wrongly deducts carriage outwards."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 516, $official_bank_source${"itemId":"a3d247e9-545b-59ff-97f4-369955532eff","questionId":"3f922700-e7ff-5065-88a9-dae7b03e7df5","sourceKey":"bank:ACC101:ACC-0364","payload":{"prompt":"The following information is extracted from the records of a trading entity for the year ended 31st December 20X2: Opening inventory N990,000, Purchases N3,740,000, Carriage inwards N22,000, Sales N5,280,000. The gross profit recorded was 25% of sales. What was the closing inventory as at 31st December 20X2?","options":["N770,000","N792,000","N1,237,500","N1,320,000"],"correctOption":1,"section":"Final accounts of a sole trader","explanation":"Gross profit is 25% of sales, so cost of sales = 75% x N5,280,000 = N3,960,000. Closing inventory = opening inventory + purchases + carriage inwards - cost of sales = N990,000 + N3,740,000 + N22,000 - N3,960,000 = N792,000. Option A (N770,000) forgets the carriage inwards, and option D (N1,320,000) is simply the gross profit figure."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 517, $official_bank_source${"itemId":"7c0802fd-634c-5cb1-a845-926661ce0939","questionId":"1e83aec2-6ddb-5071-a2af-7155ccbbfdbd","sourceKey":"bank:ACC101:ACC-0369","payload":{"prompt":"All of the following are contra (or reduction) accounts except","options":["Accumulated depreciation","Provision for doubtful debt","Sales returns","Carriage inwards"],"correctOption":3,"section":"Final accounts of a sole trader","explanation":"A contra account reduces another account: accumulated depreciation (A) and provision for doubtful debts (B) reduce assets, while sales returns (C) reduce sales. Carriage inwards is not a reduction of anything; it is an extra cost added to purchases in the trading account, which makes it the exception."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 518, $official_bank_source${"itemId":"ca9b943f-14ef-541f-be70-445be0a908b2","questionId":"6db4ed18-a11d-5831-8f81-0fb19ca397a8","sourceKey":"bank:ACC101:ACC-0370","payload":{"prompt":"Which of the following results in over-stated gross profit?","options":["Purchases are overstated","Closing stock is overstated","Carriage inward is overstated","Opening stock is overstated"],"correctOption":1,"section":"Final accounts of a sole trader","explanation":"Closing stock is deducted in working out cost of goods sold, so if it is overstated, cost of goods sold is too low and gross profit is too high. Overstating purchases, carriage inwards or opening stock (options A, C and D) increases cost of goods sold and so understates gross profit."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 519, $official_bank_source${"itemId":"b84f4d55-0f74-5b0a-91f8-a9f8048a4d09","questionId":"95b2de78-5ef9-54d6-90c2-cfff95114506","sourceKey":"bank:ACC101:ACC-0374","payload":{"prompt":"If sales are N8200, opening stock N1300, closing stock N900, purchases N6400, carriage inwards N200, the cost of goods sold figure is","options":["N7,500","N6,200","N6,800","N7,000"],"correctOption":3,"section":"Final accounts of a sole trader","explanation":"Cost of goods sold = opening stock + purchases + carriage inwards - closing stock = N1,300 + N6,400 + N200 - N900 = N7,000. Sales do not enter this calculation. Option C (N6,800) forgets to add the carriage inwards."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 520, $official_bank_source${"itemId":"3a690e30-81be-5f5d-a6ab-7ae8b9b517e0","questionId":"93496fa3-ce14-5d15-a094-de89b5f388f0","sourceKey":"bank:ACC101:ACC-0379","payload":{"prompt":"Calculate the gross profit if rate of gross profit is 20% on sales and cost of goods is N120,000","options":["N24,000","N30,000","N20,000","None of these"],"correctOption":1,"section":"Final accounts of a sole trader","explanation":"If gross profit is 20% of sales, cost of goods is 80% of sales, so sales = N120,000 / 0.8 = N150,000 and gross profit = 20% x N150,000 = N30,000. Option A (N24,000) wrongly takes 20% of the cost instead of the sales."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 521, $official_bank_source${"itemId":"0e572788-ff39-5554-bb26-1a7fe191fb95","questionId":"81200273-52d9-5bfa-97ac-13eef4bfe923","sourceKey":"bank:ACC101:ACC-0380","payload":{"prompt":"Opening stock N8,500; Purchases N30,700; Wages N4,800; Return inwards N5,200; Closing Stock N9,000. Cost of goods sold will be:","options":["N29,800","N32,000","N35,000","N40,000"],"correctOption":2,"section":"Final accounts of a sole trader","explanation":"Cost of goods sold = opening stock N8,500 + purchases N30,700 + wages N4,800 - closing stock N9,000 = N35,000, with wages treated as a direct cost of getting the goods ready for sale. Return inwards is deducted from sales, not from cost of goods sold, so option A (N29,800), which subtracts it, is wrong."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 522, $official_bank_source${"itemId":"0fd66eba-f4be-55f6-be08-027a366d943d","questionId":"0ab0e5fd-d0d7-51ca-89b0-d41bbb4695b9","sourceKey":"bank:ACC101:ACC-0382","payload":{"prompt":"A firm purchased goods of N90,000 and spent N6,000 on freight towards it. At the end of the year the cost of goods still unsold was N12,000. Sales during the year N120,000. What is the gross profit earned by the firm?","options":["N36,000","N18,000","N42,000","N38,000"],"correctOption":0,"section":"Final accounts of a sole trader","explanation":"Cost of goods sold = purchases + freight (carriage inwards) - unsold goods = N90,000 + N6,000 - N12,000 = N84,000. Gross profit = N120,000 - N84,000 = N36,000. Option C (N42,000) ignores the freight, which is part of the cost of the goods."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 523, $official_bank_source${"itemId":"899c511a-e090-55b6-a4f1-347f7747591f","questionId":"a8b048bc-502c-58c7-b09a-44319b040e4b","sourceKey":"bank:ACC101:ACC-0384","payload":{"prompt":"A person started a business with capital of N50,000 and he takes loan from his relative N5,000. Profit for the year is N10,000 and drawings N9,000. What will be the amount of closing capital?","options":["N60,000","N51,000","N56,000","N46,000"],"correctOption":1,"section":"Final accounts of a sole trader","explanation":"Closing capital = opening capital + profit - drawings = N50,000 + N10,000 - N9,000 = N51,000. The loan from the relative is a liability, not capital, so option C (N56,000), which adds it, is wrong. Option A (N60,000) forgets to deduct drawings."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 524, $official_bank_source${"itemId":"1dae0e4a-dcf6-5e5d-b8fe-f203d4a4ae18","questionId":"17a0de30-eaa3-5df8-8df3-1db68b83672f","sourceKey":"bank:ACC101:ACC-0387","payload":{"prompt":"Sales = N300,000; G.P. on sales is 20%; Purchases = N240,000; opening stock = N20,000. Find closing stock","options":["N20,000","N24,000","N16,000","N12,000"],"correctOption":0,"section":"Final accounts of a sole trader","explanation":"Gross profit is 20% of sales, so cost of goods sold = 80% x N300,000 = N240,000. Closing stock = opening stock + purchases - cost of goods sold = N20,000 + N240,000 - N240,000 = N20,000. Closing stock equals opening stock here because purchases exactly match cost of goods sold, so options B, C and D cannot be right."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 525, $official_bank_source${"itemId":"f1d6730a-b705-59c0-b18a-fda1c35648ae","questionId":"0eae404f-b1bf-5c9b-91d0-5662d85e33b7","sourceKey":"bank:ACC101:ACC-0388","payload":{"prompt":"The fixed assets of a company is double of the current assets and half of capital. If the current assets are N300,000 and investments N400,000. Calculate the current liabilities assuming that there are no other items in the balance sheet","options":["N1,200,000","N100,000","N1,300,000","N400,000"],"correctOption":1,"section":"Final accounts of a sole trader","explanation":"Fixed assets are double current assets: 2 x N300,000 = N600,000, and capital is double fixed assets: 2 x N600,000 = N1,200,000. Total assets = N600,000 + N300,000 + N400,000 = N1,300,000, so current liabilities = N1,300,000 - N1,200,000 = N100,000. Option C (N1,300,000) is total assets, and option A (N1,200,000) is capital."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 526, $official_bank_source${"itemId":"20ba1d39-4aa9-51f5-a822-05f4bcbaa1a2","questionId":"570cf7cc-9fc3-5417-8ee2-7631f3503991","sourceKey":"bank:ACC101:A101N3-115","payload":{"prompt":"A trader in Balogun market made sales of N900,000 during the year, and customers returned goods worth N40,000. What is the net sales figure in the trading account?","options":["N860,000","N820,000","N900,000","N940,000"],"correctOption":0,"section":"Final accounts of a sole trader","explanation":"Net sales = sales - returns inwards = 900,000 - 40,000 = N860,000. N940,000 adds the returns instead of deducting them, but goods sent back by customers reduce sales."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 527, $official_bank_source${"itemId":"ae4519b2-ea32-5adb-b004-d163e50bef13","questionId":"1b29493f-d8df-536b-a320-d5423181cff7","sourceKey":"bank:ACC101:A101N3-116","payload":{"prompt":"A business has: opening inventory N120,000; purchases N600,000; carriage inwards N15,000; returns outwards N25,000; closing inventory N90,000. What is the cost of goods sold?","options":["N605,000","N670,000","N620,000","N710,000"],"correctOption":2,"section":"Final accounts of a sole trader","explanation":"Cost of goods sold = 120,000 + 600,000 + 15,000 - 25,000 - 90,000 = N620,000. N670,000 adds returns outwards instead of deducting them, but goods returned to suppliers reduce purchases."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 528, $official_bank_source${"itemId":"bdfa5de6-3ad9-59c2-9d24-e08826b3149c","questionId":"1fa9336c-a087-599c-b14d-f12ffacbbffd","sourceKey":"bank:ACC101:A101N3-117","payload":{"prompt":"For the year ended 31 December 2025, a sole trader had: sales N1,000,000; returns inwards N30,000; opening inventory N150,000; purchases N700,000; carriage inwards N20,000; returns outwards N10,000; closing inventory N180,000. What is the gross profit?","options":["N320,000","N290,000","N270,000","N310,000"],"correctOption":1,"section":"Final accounts of a sole trader","explanation":"Net sales are 1,000,000 - 30,000 = N970,000, and cost of goods sold is 150,000 + 700,000 + 20,000 - 10,000 - 180,000 = N680,000, so gross profit is N290,000. N320,000 ignores the returns inwards, which must be deducted from sales."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 529, $official_bank_source${"itemId":"103f93a1-6238-5d0b-97d9-7cb073b9781d","questionId":"6d9d3ce1-25bf-51f0-bb98-5e3e42b501ff","sourceKey":"bank:ACC101:A101N3-118","payload":{"prompt":"In the final accounts of a sole trader, carriage outwards is shown","options":["As a current asset in the statement of financial position","As a selling and distribution expense in the profit and loss account","As part of the cost of goods sold in the trading account","As a deduction from sales in the trading account"],"correctOption":1,"section":"Final accounts of a sole trader","explanation":"Carriage outwards is the cost of delivering goods to customers, so it is a selling and distribution expense in the profit and loss account. It is not part of cost of goods sold; that treatment applies to carriage inwards, the cost of bringing goods in."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 530, $official_bank_source${"itemId":"7d0aec1e-2006-53b5-8724-cbb0ae36b76a","questionId":"243c6901-0f1e-5739-afec-f151e8a0da05","sourceKey":"bank:ACC101:A101N3-119","payload":{"prompt":"Where is carriage inwards treated when a sole trader prepares final accounts?","options":["Deducted from purchases in the trading account","Shown as a selling and distribution expense in the profit and loss account","Deducted from sales in the trading account","Added in arriving at cost of goods sold in the trading account"],"correctOption":3,"section":"Final accounts of a sole trader","explanation":"Carriage inwards is part of the cost of getting goods into the business, so it is added in calculating cost of goods sold. Treating it as a selling and distribution expense confuses it with carriage outwards, which is the cost of delivering goods to customers."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 531, $official_bank_source${"itemId":"c5588991-e31f-52f4-b664-817fc335dedf","questionId":"12f133ee-452a-5add-ab1a-8a6cd7c10a8a","sourceKey":"bank:ACC101:A101N3-120","payload":{"prompt":"In the trading account, returns inwards are","options":["Added in arriving at cost of goods sold","Deducted from purchases","Shown as an expense in the profit and loss account","Deducted from sales to give net sales"],"correctOption":3,"section":"Final accounts of a sole trader","explanation":"Returns inwards are goods sent back by customers, so they reduce sales and are deducted to arrive at net sales. Deducting them from purchases confuses them with returns outwards, which are goods the business sends back to its suppliers."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 532, $official_bank_source${"itemId":"dbf4e5e0-0d52-514f-b986-6d6bf13fc870","questionId":"2064d7a4-77f3-5d47-9171-318328d98dc2","sourceKey":"bank:ACC101:A101N3-121","payload":{"prompt":"In calculating cost of goods sold, returns outwards are","options":["Deducted from purchases","Added to purchases","Deducted from sales","Added to closing inventory"],"correctOption":0,"section":"Final accounts of a sole trader","explanation":"Returns outwards are goods the business sends back to its suppliers, so they reduce purchases in the cost of goods sold calculation. Deducting them from sales confuses them with returns inwards, which are goods returned by customers."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 533, $official_bank_source${"itemId":"b981e2c8-b474-5828-a0f3-9083e121c2fd","questionId":"97f26bed-4624-58a4-93cd-d0134a60201b","sourceKey":"bank:ACC101:A101N3-122","payload":{"prompt":"A sole trader's gross profit is N400,000, and he also received rent of N10,000. Expenses were: rent paid N80,000; salaries N120,000; depreciation N30,000; increase in provision for doubtful debts N5,000. What is the net profit?","options":["N205,000","N175,000","N155,000","N180,000"],"correctOption":1,"section":"Final accounts of a sole trader","explanation":"Net profit = gross profit + other income - expenses = 400,000 + 10,000 - (80,000 + 120,000 + 30,000 + 5,000) = N175,000. N155,000 deducts the rent received as though it were an expense instead of adding it as income."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 534, $official_bank_source${"itemId":"9bd1eecf-4473-586b-a541-eb6be7096cd8","questionId":"dbfc917f-6616-503f-9167-a6eb8c221c49","sourceKey":"bank:ACC101:A101N3-123","payload":{"prompt":"A trader's opening capital was N800,000. Net profit for the year was N175,000 and drawings were N60,000. What is the closing capital?","options":["N740,000","N975,000","N915,000","N1,035,000"],"correctOption":2,"section":"Final accounts of a sole trader","explanation":"Closing capital = opening capital + net profit - drawings = 800,000 + 175,000 - 60,000 = N915,000. N1,035,000 adds the drawings, but drawings take value out of the business and reduce capital."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 535, $official_bank_source${"itemId":"652d198d-2148-5cdf-90ab-84c142b7f6ab","questionId":"8f849c29-fe17-5c54-bd62-9db663fb509a","sourceKey":"bank:ACC101:A101N3-124","payload":{"prompt":"Which of the following is a current asset in the statement of financial position of a sole trader?","options":["Prepayments","Bank overdraft","Accrued expenses","Income received in advance"],"correctOption":0,"section":"Final accounts of a sole trader","explanation":"Prepayments are amounts paid in advance for benefits still to be received, so they are current assets. A bank overdraft, accrued expenses and income received in advance are all amounts the business owes, so they are current liabilities."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 536, $official_bank_source${"itemId":"b706f30d-0982-5c31-be94-5822fd982364","questionId":"f0e0429f-1c51-5fae-82d0-33476faed9c2","sourceKey":"bank:ACC101:A101N3-125","payload":{"prompt":"In the statement of financial position, non-current assets are shown at","options":["Residual value","Original cost with no deduction","Net book value","Expected selling price"],"correctOption":2,"section":"Final accounts of a sole trader","explanation":"Non-current assets are shown at net book value, that is, cost less accumulated depreciation. Showing them at original cost with no deduction would ignore the depreciation already charged and overstate the assets."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 537, $official_bank_source${"itemId":"455aaba4-d38d-51aa-bff2-f60575bb5c42","questionId":"d3ef1913-1ffe-5779-a594-0601e7490bc4","sourceKey":"bank:ACC101:A101N3-126","payload":{"prompt":"The income statement of a sole trader is made up of","options":["The profit and loss account and the cash book","The trading account and the profit and loss account","The statement of financial position and the trial balance","The trading account and the statement of financial position"],"correctOption":1,"section":"Final accounts of a sole trader","explanation":"The income statement combines the trading account, which works out gross profit, and the profit and loss account, which works out net profit. The statement of financial position is a separate statement showing the position as at a date, not part of the income statement."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 538, $official_bank_source${"itemId":"4b287caa-fa46-5a73-9f82-88566823ad67","questionId":"8319effe-f319-5c1f-be2d-98bf978f2ef2","sourceKey":"bank:ACC101:A101N3-127","payload":{"prompt":"A sole trader's capital was N500,000 at the start of the year and N620,000 at the end. Net profit for the year was N200,000. What were the drawings for the year?","options":["N80,000","N200,000","N320,000","N120,000"],"correctOption":0,"section":"Final accounts of a sole trader","explanation":"Closing capital = opening capital + net profit - drawings, so 620,000 = 500,000 + 200,000 - drawings, giving drawings of N80,000. N120,000 is just the increase in capital, which ignores the profit added during the year."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 539, $official_bank_source${"itemId":"b536f574-95dd-51a8-9bac-365f05c84055","questionId":"256d6e1a-611e-55cb-8a1d-4e9451076a5d","sourceKey":"bank:ACC101:A101N3-128","payload":{"prompt":"Opening capital of a trader in Ikeja was N300,000, drawings were N50,000 and closing capital was N400,000. What was the net profit for the year?","options":["N50,000","N150,000","N100,000","N350,000"],"correctOption":1,"section":"Final accounts of a sole trader","explanation":"From closing capital = opening capital + net profit - drawings, 400,000 = 300,000 + net profit - 50,000, so net profit is N150,000. N100,000 is only the increase in capital and forgets that drawings of N50,000 were also taken out."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 540, $official_bank_source${"itemId":"45714329-dcb0-5232-8037-7a207a5d3e18","questionId":"e3f7a019-08f3-535b-8837-b4687fdb269c","sourceKey":"bank:ACC101:A101N3-129","payload":{"prompt":"If the closing inventory of a business is understated, what is the effect on the trading account for the year?","options":["Gross profit is overstated","Cost of goods sold is understated","Net sales are understated","Gross profit is understated"],"correctOption":3,"section":"Final accounts of a sole trader","explanation":"Closing inventory is deducted in arriving at cost of goods sold, so a figure that is too low makes cost of goods sold too high and gross profit too low. Gross profit would be overstated only if closing inventory were overstated, the opposite case."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 541, $official_bank_source${"itemId":"7c2fee7c-804f-508c-9dd0-dd51ea087e9f","questionId":"6c126b54-6932-5b99-aa75-3627f382391e","sourceKey":"bank:ACC101:A101N3-130","payload":{"prompt":"A business made sales of N600,000, and its gross profit was 25% of sales. What was the cost of goods sold?","options":["N150,000","N450,000","N480,000","N750,000"],"correctOption":1,"section":"Final accounts of a sole trader","explanation":"Gross profit is 25% x 600,000 = N150,000, so cost of goods sold = 600,000 - 150,000 = N450,000. N480,000 treats the 25% as a mark-up on cost (600,000 / 1.25), but the question gives the percentage on sales."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 542, $official_bank_source${"itemId":"37e8eee2-143d-5880-b0a1-e3fe5b6fb17b","questionId":"1e32639c-3540-5cb1-b769-18490321fbf9","sourceKey":"bank:ACC101:A101N3-131","payload":{"prompt":"In the final accounts of a sole trader, depreciation of motor vehicles for the year is shown","options":["As an expense in the profit and loss account","As a deduction from capital","As part of cost of goods sold in the trading account","As an addition to gross profit"],"correctOption":0,"section":"Final accounts of a sole trader","explanation":"Depreciation is one of the expenses deducted from gross profit in the profit and loss account to arrive at net profit. It is not part of cost of goods sold, which covers only the cost of the goods sold such as inventory, purchases and carriage inwards."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 543, $official_bank_source${"itemId":"475ca22d-0a27-5df0-9e86-776063c47077","questionId":"dc4d4fcd-607f-56d7-a394-1930abc910a8","sourceKey":"bank:ACC101:A101N3-132","payload":{"prompt":"A sole trader took a bank loan repayable in 5 years' time. In the statement of financial position at the year end, the loan is shown as","options":["A non-current asset","Part of capital","A non-current liability","A current liability"],"correctOption":2,"section":"Final accounts of a sole trader","explanation":"A loan that is not repayable for several years is a non-current liability. It is not part of capital, because it is owed to the bank, not to the owner."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 544, $official_bank_source${"itemId":"409363f6-53c5-5a93-909a-c1121602cec0","questionId":"6115bb17-8de8-5353-bf6c-aa3d4e3d241d","sourceKey":"bank:ACC101:A101N3-133","payload":{"prompt":"In the profit and loss account, net profit is arrived at by","options":["Adding drawings to gross profit and deducting expenses","Deducting closing capital from opening capital","Adding other income to gross profit and deducting expenses","Deducting cost of goods sold from net sales"],"correctOption":2,"section":"Final accounts of a sole trader","explanation":"The profit and loss account starts with gross profit, adds other income and deducts expenses such as depreciation and bad debts to give net profit. Deducting cost of goods sold from net sales gives gross profit, which is the trading account step, not net profit."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 545, $official_bank_source${"itemId":"c8af5793-938f-5a3c-ab2e-82cdcc7fc85a","questionId":"4ca2874a-dc2f-58ca-8138-238d3f2e7a0c","sourceKey":"bank:ACC101:A101N3-134","payload":{"prompt":"A sole trader's statement of financial position shows total assets of N2,000,000, current liabilities of N300,000 and a long-term bank loan of N500,000. What is the owner's capital?","options":["N2,800,000","N1,500,000","N1,700,000","N1,200,000"],"correctOption":3,"section":"Final accounts of a sole trader","explanation":"The statement of financial position mirrors the accounting equation, so capital = assets - liabilities = 2,000,000 - 300,000 - 500,000 = N1,200,000. N1,700,000 deducts only the current liabilities and forgets that the long-term loan is also a liability."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 546, $official_bank_source${"itemId":"debd9fc0-5384-5d58-8ca7-ed815dfd1892","questionId":"c42a7cdb-bb7e-5227-b0e2-bd2fcd6589f4","sourceKey":"bank:ACC101:A101N3-135","payload":{"prompt":"A trader's cost of goods sold was N500,000. Opening inventory was N80,000 and closing inventory was N100,000. What were the purchases for the year?","options":["N680,000","N500,000","N520,000","N480,000"],"correctOption":2,"section":"Final accounts of a sole trader","explanation":"Cost of goods sold = opening inventory + purchases - closing inventory, so 500,000 = 80,000 + purchases - 100,000, giving purchases of N520,000. N480,000 comes from adding closing inventory and deducting opening inventory, which reverses the formula."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 547, $official_bank_source${"itemId":"42b2b1a3-9387-5506-9eb6-fcc4a7f490f6","questionId":"512670bf-2165-5a4f-9cd1-1924b9d02116","sourceKey":"bank:ACC101:A101N3-136","payload":{"prompt":"A firm in Ikeja had: sales N2,500,000; returns inwards N100,000; opening inventory N300,000; purchases N1,600,000; carriage outwards N50,000; closing inventory N400,000. What is the gross profit?","options":["N850,000","N1,000,000","N950,000","N900,000"],"correctOption":3,"section":"Final accounts of a sole trader","explanation":"Net sales are N2,400,000 and cost of goods sold is 300,000 + 1,600,000 - 400,000 = N1,500,000, so gross profit is N900,000. N850,000 wrongly includes carriage outwards in cost of goods sold, but it is a selling expense in the profit and loss account."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 548, $official_bank_source${"itemId":"0d7da1b6-aeb5-5309-9c40-20fcc37a0b27","questionId":"77418cae-5157-5be9-b73f-60e27ac4cd0e","sourceKey":"bank:ACC101:A101N3-137","payload":{"prompt":"In the statement of financial position of a sole trader, the net profit for the year is","options":["Added to opening capital","Added to drawings","Deducted from non-current assets","Added to current liabilities"],"correctOption":0,"section":"Final accounts of a sole trader","explanation":"Net profit belongs to the owner, so it is added to opening capital, and drawings are then deducted to give closing capital. Adding it to drawings is wrong, because drawings are value the owner takes out, which reduces capital."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 549, $official_bank_source${"itemId":"41fa5e8d-a02c-5e15-8085-0e81134e8fd6","questionId":"c23d2076-e98b-587f-a817-bff3ef154032","sourceKey":"bank:ACC101:ACC-0235","payload":{"prompt":"Which of the following is not an attribute of financial accounting?","options":["It is historical","It does not record financial transactions","It reports financial information about a business entity","It treats business as a separate entity"],"correctOption":1,"section":"Branches of accounting","explanation":"Financial accounting does record financial transactions, so the statement that it does not is false and is therefore not an attribute. Options A, C and D are true: financial accounting looks at past events, reports on a business entity, and treats the business as separate from its owner."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 550, $official_bank_source${"itemId":"14afa89e-671c-5565-96b7-16ebdf23504b","questionId":"1670627c-2dff-5a2a-af37-43e506aad81f","sourceKey":"bank:ACC101:A101N4-001","payload":{"prompt":"Which branch of accounting provides managers with information for internal planning, control and decision-making?","options":["Auditing","Financial accounting","Management accounting","Taxation"],"correctOption":2,"section":"Branches of accounting","explanation":"Management accounting serves people inside the business, giving managers information they need to plan, control operations and make decisions. Financial accounting is the tempting choice, but its reports are historical and prepared mainly for external users such as shareholders and lenders."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 551, $official_bank_source${"itemId":"16fbce10-ebd9-5eff-ba33-b00eaa914466","questionId":"812f40c1-7065-50f3-99ce-01564d322e47","sourceKey":"bank:ACC101:A101N4-002","payload":{"prompt":"The branch of accounting that is concerned mainly with ascertaining product and process costs is","options":["Cost accounting","Financial accounting","Financial management","Auditing"],"correctOption":0,"section":"Branches of accounting","explanation":"Cost accounting works out what it costs to make each product or run each process. Financial accounting reports the results of the whole business to outsiders and does not give the cost of individual products, which is exactly the gap cost accounting fills."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 552, $official_bank_source${"itemId":"e75ff053-37b7-569f-99a3-a6767e347c1b","questionId":"be9cabb2-782f-5cad-9b20-c0adb9925640","sourceKey":"bank:ACC101:A101N4-003","payload":{"prompt":"An independent examination of the financial statements of an organisation is known as","options":["Bookkeeping","Cost accounting","Management accounting","Auditing"],"correctOption":3,"section":"Branches of accounting","explanation":"Auditing is the independent examination of financial statements that have already been prepared. Bookkeeping may look close, but it is only the recording of transactions as they happen, not an independent check on the finished statements."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 553, $official_bank_source${"itemId":"dbf0cd17-b0d5-5680-b5cc-5b173ab5e553","questionId":"0ed2e06a-4348-501b-95e1-ed9bce29848e","sourceKey":"bank:ACC101:A101N4-004","payload":{"prompt":"Which branch of accounting deals with tax computation and tax planning?","options":["Auditing","Taxation","Financial management","Cost accounting"],"correctOption":1,"section":"Branches of accounting","explanation":"Taxation is the branch that computes the tax a person or business owes and plans its tax affairs. Financial management also deals with money decisions, but its focus is on raising and using funds, not on working out tax."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 554, $official_bank_source${"itemId":"26f93fe2-a300-5355-bdd1-cd00bdaca855","questionId":"9cc86de2-9082-5e3f-9fe4-65b29ebf6c88","sourceKey":"bank:ACC101:A101N4-005","payload":{"prompt":"The raising and use of funds in a business is the main concern of which branch of accounting?","options":["Financial accounting","Financial management","Cost accounting","Auditing"],"correctOption":1,"section":"Branches of accounting","explanation":"Financial management deals with how a business raises funds and how it uses them. Financial accounting sounds similar, but it records transactions and produces historical reports for external users rather than deciding how money is raised and used."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 555, $official_bank_source${"itemId":"cc8b486a-841c-574b-9d8e-8642ab62ecc2","questionId":"e9b16c2b-1441-557d-8dd3-9c0a4ab468df","sourceKey":"bank:ACC101:A101N4-006","payload":{"prompt":"Which branch of accounting produces historical reports mainly for external users such as shareholders and lenders?","options":["Financial accounting","Cost accounting","Taxation","Management accounting"],"correctOption":0,"section":"Branches of accounting","explanation":"Financial accounting records past transactions and summarises them in financial statements for outsiders like shareholders and lenders. Management accounting is the tempting option, but it is aimed at managers inside the business for planning, control and decisions."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 556, $official_bank_source${"itemId":"71bed4ad-7cdc-5069-8b7e-e10ce8de11dc","questionId":"665de073-9cac-5c3c-b4a2-c76709a58ba7","sourceKey":"bank:ACC101:A101N4-007","payload":{"prompt":"Management accounting is best described as","options":["The computation of tax payable and tax planning","The preparation of historical reports for external users","The provision of information for internal planning, control and decisions","An independent examination of the financial statements"],"correctOption":2,"section":"Branches of accounting","explanation":"Management accounting gives managers inside the organisation the information they need to plan, control and decide. Preparing historical reports for external users describes financial accounting, which looks back and faces outward rather than inward."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 557, $official_bank_source${"itemId":"f1167452-6e2f-5861-9f74-88e61ca6d301","questionId":"0544a12c-c29c-5803-a0a6-7f5ce1b6bc27","sourceKey":"bank:ACC101:A101N4-008","payload":{"prompt":"Auditing is best described as","options":["The determination of product and process costs","The raising and use of funds in a business","An independent examination of the financial statements","The day-to-day recording of transactions in the books"],"correctOption":2,"section":"Branches of accounting","explanation":"Auditing means an independent check of financial statements that the business has already prepared. Day-to-day recording of transactions is bookkeeping, which produces the records that an auditor later examines."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 558, $official_bank_source${"itemId":"bf6f0f23-2c9e-52ee-9f47-91a952bc2866","questionId":"0638e258-c110-597b-b67c-5df17d715e21","sourceKey":"bank:ACC101:A101N4-009","payload":{"prompt":"Financial management, as a branch of accounting, is concerned mainly with","options":["Raising funds and deciding how they are used","Independently examining the financial statements","Recording transactions for reports to outsiders","Ascertaining the cost of each product made"],"correctOption":0,"section":"Branches of accounting","explanation":"Financial management focuses on where a business gets its funds and how it puts them to use. Recording transactions for reports to outsiders is the work of financial accounting, which is easy to confuse with financial management because the names are similar."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 559, $official_bank_source${"itemId":"275b60b3-823a-5d81-b3a5-1088d74841bc","questionId":"4fffb4ff-f5f8-5240-a71f-e7e7d5b448ae","sourceKey":"bank:ACC101:A101N4-010","payload":{"prompt":"Cost accounting is concerned mainly with","options":["Computing tax payable and tax planning","Preparing historical reports for external users","Independently examining the financial statements","Determining product and process costs"],"correctOption":3,"section":"Branches of accounting","explanation":"Cost accounting finds out how much each product or process costs, which helps with pricing and cost control. Preparing historical reports for external users describes financial accounting, which reports on the whole business and not on the cost of individual products."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 560, $official_bank_source${"itemId":"3e5ceabe-8df4-5a28-a94a-4bdbb704215e","questionId":"a2b5607e-04ae-50ac-a908-0644cadc2556","sourceKey":"bank:ACC101:A101N4-011","payload":{"prompt":"Which of the following is NOT a specialised branch of accounting?","options":["Cost accounting","Taxation","Auditing","Marketing research"],"correctOption":3,"section":"Branches of accounting","explanation":"Marketing research belongs to marketing, not accounting, so it is not a branch of accounting. Auditing, taxation and cost accounting are all specialised branches, together with financial management and management accounting."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 561, $official_bank_source${"itemId":"11a24b17-27ab-5abd-8d42-b3239333979b","questionId":"996eefb6-550c-517c-95d7-5219aea6fb78","sourceKey":"bank:ACC101:A101N4-012","payload":{"prompt":"Financial management, cost accounting, management accounting, taxation and ______ are the specialised branches of accounting commonly named alongside financial accounting.","options":["Insurance","Marketing","Banking","Auditing"],"correctOption":3,"section":"Branches of accounting","explanation":"Auditing completes the list of five specialised branches: financial management, cost accounting, management accounting, taxation and auditing. Banking and insurance are industries that use accounting, but they are not branches of accounting themselves."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 562, $official_bank_source${"itemId":"9664ad57-41c5-5cfa-9b68-ab5422ac6995","questionId":"43077965-69cd-5ea0-a733-686d03fc6ee8","sourceKey":"bank:ACC101:A101N4-013","payload":{"prompt":"A plastic-chair manufacturer in Ikeja wants to know exactly how much it costs to produce one chair. Which branch of accounting will provide this information?","options":["Financial management","Taxation","Cost accounting","Auditing"],"correctOption":2,"section":"Branches of accounting","explanation":"Working out the cost of each unit produced is the core job of cost accounting, which deals with product and process costs. Financial management may sound relevant because money is involved, but it is about raising and using funds, not costing a product."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 563, $official_bank_source${"itemId":"2ac43d54-19b1-5f21-abf3-25b7afdc155f","questionId":"f50be85d-f19c-5f78-90c5-283512092b01","sourceKey":"bank:ACC101:A101N4-014","payload":{"prompt":"A bank in Lagos engages an independent firm of accountants to examine the financial statements it has prepared for the year. This work falls under which branch of accounting?","options":["Management accounting","Taxation","Cost accounting","Auditing"],"correctOption":3,"section":"Branches of accounting","explanation":"An independent examination of financial statements already prepared is auditing. Management accounting is done for the bank's own managers to plan and control, and it is not an independent examination of the statements."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 564, $official_bank_source${"itemId":"a47647fc-2df8-5b47-a936-fc145e21a5de","questionId":"e6637ea7-754b-5872-b3d4-0cf4177084b2","sourceKey":"bank:ACC101:A101N4-015","payload":{"prompt":"A trader in Balogun market hires an accountant to work out how much tax he owes on his profit and to plan his tax affairs for next year. This is an example of which branch of accounting?","options":["Cost accounting","Auditing","Taxation","Management accounting"],"correctOption":2,"section":"Branches of accounting","explanation":"Computing tax payable and planning tax affairs is the work of the taxation branch. Auditing involves money records too, but it is an independent examination of financial statements, not a computation of tax."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 565, $official_bank_source${"itemId":"6f3f2b69-2b79-5488-affc-4ea394269def","questionId":"06fab4d6-9657-5b6e-ac3c-9188ca114784","sourceKey":"bank:ACC101:A101N4-016","payload":{"prompt":"A firm in Ikeja is deciding whether to raise money for expansion through a bank loan or through extra capital from its owners, and how best to use the money. Which branch of accounting is most concerned with this?","options":["Taxation","Auditing","Financial management","Financial accounting"],"correctOption":2,"section":"Branches of accounting","explanation":"Choosing how to raise funds and how to use them is the focus of financial management. Financial accounting is tempting because of the name, but it records past transactions and reports historical results rather than deciding how to raise and use funds."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 566, $official_bank_source${"itemId":"783078ad-c5af-504d-b1a8-480e9d7adfa9","questionId":"c2f2e9ea-3126-5022-9b32-3c6bd7d4c1cd","sourceKey":"bank:ACC101:A101N4-017","payload":{"prompt":"The managing director of a company in Ikeja wants monthly reports comparing actual results with the budget so that she can control operations. Which branch of accounting provides such reports?","options":["Management accounting","Taxation","Auditing","Financial accounting"],"correctOption":0,"section":"Branches of accounting","explanation":"Comparing actual results with budget for control is internal information for managers, which is what management accounting provides. Financial accounting cannot compare actual results with budget, and its historical reports are aimed mainly at external users."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 567, $official_bank_source${"itemId":"0efb1db1-8243-57b4-a947-1310fa179819","questionId":"c285895e-7d19-583c-84b6-098fdd42ba0f","sourceKey":"bank:ACC101:A101N4-018","payload":{"prompt":"The shareholders of a Lagos company receive its income statement and statement of financial position for the year just ended. These reports are the product of which branch of accounting?","options":["Management accounting","Cost accounting","Financial accounting","Financial management"],"correctOption":2,"section":"Branches of accounting","explanation":"Financial accounting produces historical reports, such as the income statement and statement of financial position, for external users like shareholders. Management accounting is the closest wrong choice, but its reports are for managers inside the company, not for shareholders outside it."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 568, $official_bank_source${"itemId":"decd487a-c9a6-59b2-bc2e-ad6d4541b1fd","questionId":"e0e161da-084a-5e8b-96b3-d626869cdcf9","sourceKey":"bank:ACC101:A101N4-019","payload":{"prompt":"The keeping and reporting of accounts showing how public funds are received and spent by a federal government ministry is known as","options":["Public sector accounting","Taxation","Auditing","Cost accounting"],"correctOption":0,"section":"Branches of accounting","explanation":"Public sector accounting, also called government accounting, deals with the accounts of government bodies such as ministries. Taxation is tempting because government collects taxes, but taxation as a branch is about computing and planning tax, not recording how a ministry receives and spends public funds."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 569, $official_bank_source${"itemId":"d81d6742-4eb3-5979-89c4-e1987598ee7c","questionId":"88b00ab1-208d-5b25-b706-af33ac326c26","sourceKey":"bank:ACC101:A101N4-020","payload":{"prompt":"Public sector accounting is also known as","options":["Management accounting","Government accounting","Cost accounting","Social accounting"],"correctOption":1,"section":"Branches of accounting","explanation":"Public sector accounting is another name for government accounting, the branch that deals with the accounts of government bodies. Social accounting is a different branch, concerned with the social and environmental effects of an organisation's activities."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 570, $official_bank_source${"itemId":"846960c4-7175-5b21-b331-440395e5e2eb","questionId":"123e2d51-f096-5f0e-bc2c-212e2123b789","sourceKey":"bank:ACC101:A101N4-021","payload":{"prompt":"Apart from the main specialised branches such as auditing and taxation, which of the following is also often listed as a branch of accounting?","options":["Actuarial science","Forensic accounting","Quantity surveying","Estate management"],"correctOption":1,"section":"Branches of accounting","explanation":"Forensic accounting is often listed among the branches of accounting, along with public sector and social or environmental accounting. Actuarial science, estate management and quantity surveying are separate professions, not branches of accounting."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 571, $official_bank_source${"itemId":"21ac49f1-e250-51c0-9080-cf6d83e7f803","questionId":"446dfa85-c99c-527a-9ebf-7b976d1b1180","sourceKey":"bank:ACC101:A101N4-022","payload":{"prompt":"A company in Lagos prepares a report on the effects of its operations on the environment and the local community. This report belongs to which branch of accounting?","options":["Social and environmental accounting","Auditing","Taxation","Cost accounting"],"correctOption":0,"section":"Branches of accounting","explanation":"Reporting the effects of a business on society and the environment is social and environmental accounting. Cost accounting may seem related because it deals with costs, but it focuses on product and process costs, not on the firm's impact on the community."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 572, $official_bank_source${"itemId":"d29409de-eb76-55cc-97ea-ea3fb1101c09","questionId":"6d7a9cf2-4a3f-5b29-9ce3-26a9dae36c02","sourceKey":"bank:ACC101:A101N4-023","payload":{"prompt":"Which of these statements correctly describes financial accounting?","options":["It is an independent examination of accounts","It is prepared mainly for budget control","It is historical in nature","It is mainly concerned with product costs"],"correctOption":2,"section":"Branches of accounting","explanation":"Financial accounting records transactions that have already happened, so it is historical in nature. Being prepared mainly for budget control describes management accounting, which serves managers inside the business."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 573, $official_bank_source${"itemId":"b2af5d9c-cdc1-5905-a75f-844c3271e47f","questionId":"f115d1b5-f09f-5fb1-a4ed-5faf4992ffd9","sourceKey":"bank:ACC101:A101N4-024","payload":{"prompt":"A trader in Balogun market keeps his household spending out of his shop's books. Which attribute of financial accounting does this reflect?","options":["It reports mainly to external users","It treats the business as a separate entity","It is concerned with product costs","It is historical in nature"],"correctOption":1,"section":"Branches of accounting","explanation":"Financial accounting treats the business as separate from its owner, so the owner's private spending is not recorded as a business transaction. Being historical is also an attribute of financial accounting, but it explains when transactions are recorded, not why the owner's household spending is kept out."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 574, $official_bank_source${"itemId":"053baca2-bcff-5a35-a67a-7c569f930812","questionId":"7a22bbda-a432-5c30-aae3-4228aaae1589","sourceKey":"bank:ACC101:A101N4-025","payload":{"prompt":"Which of the following best states the main difference between financial accounting and management accounting?","options":["Financial accounting raises and uses funds; management accounting determines the cost of each product made","Financial accounting computes tax payable; management accounting examines the financial statements independently","Financial accounting supports internal planning and control; management accounting gives historical reports to external users","Financial accounting gives historical reports to external users; management accounting supports internal planning and control"],"correctOption":3,"section":"Branches of accounting","explanation":"Financial accounting looks back and reports to outsiders, while management accounting serves managers inside the business with information for planning, control and decisions. The option that swaps the two descriptions is the most tempting trap, because it uses the right ideas but attaches each to the wrong branch."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 575, $official_bank_source${"itemId":"ea9afc17-ae8d-59a9-86e3-300b5a7c110e","questionId":"da7ceca7-5502-5f91-aa39-8a695114c3b6","sourceKey":"bank:ACC101:A101N4-026","payload":{"prompt":"Which of the following correctly distinguishes financial management from financial accounting?","options":["Financial management deals with raising and using funds; financial accounting gives historical reports to external users","Financial management gives historical reports to external users; financial accounting deals with raising and using funds","Financial management determines product costs; financial accounting supports internal planning and control","Financial management computes tax payable; financial accounting independently examines the financial statements"],"correctOption":0,"section":"Branches of accounting","explanation":"Financial management is about obtaining funds and putting them to use, while financial accounting records past transactions and reports them to outsiders. The option that swaps the two descriptions is the usual trap, since the similar names make the branches easy to mix up."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 576, $official_bank_source${"itemId":"a2b253c3-e1de-53ca-89cf-585f01a44d68","questionId":"e78c6009-403c-51ba-84b5-64ae475a81fa","sourceKey":"bank:ACC101:A101N4-027","payload":{"prompt":"Auditing and financial accounting differ in that","options":["Auditing independently examines financial statements; financial accounting prepares historical reports for external users","Auditing prepares historical reports for external users; financial accounting independently examines financial statements","Auditing determines product and process costs; financial accounting deals with raising and using funds","Auditing supports internal planning and control; financial accounting computes tax payable"],"correctOption":0,"section":"Branches of accounting","explanation":"Financial accounting prepares the financial statements, and auditing is the independent examination of those statements afterwards. The option that reverses the two roles is the most tempting wrong answer, because it uses the correct descriptions but gives each to the wrong branch."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 577, $official_bank_source${"itemId":"4ef1bd29-eb6f-5396-91d7-74882ecb331d","questionId":"a2b9ae66-156a-5e49-a957-e61222629344","sourceKey":"bank:ACC101:A101N4-028","payload":{"prompt":"Financial accounting does not give the cost of the products a business manufactures. Which branch of accounting fills this gap?","options":["Taxation","Cost accounting","Financial management","Auditing"],"correctOption":1,"section":"Branches of accounting","explanation":"Cost accounting deals with product and process costs, so it supplies the product costs that financial accounting does not give. Financial management is the most tempting wrong choice, but it is concerned with raising and using funds, not with costing products."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 578, $official_bank_source${"itemId":"758f0b39-f187-5f74-a110-70950b3166f8","questionId":"6ff1efac-5285-5a10-adc2-090a410d0dba","sourceKey":"bank:ACC101:A101N4-029","payload":{"prompt":"Which limitation of financial accounting is usually given as a reason why cost and management accounting are needed?","options":["It does not give the cost of products manufactured","It treats the business as a separate entity","It reports to external users such as lenders","It is prepared using the double-entry system"],"correctOption":0,"section":"Branches of accounting","explanation":"Financial accounting reports on the business as a whole and does not show product costs, budget comparisons or departmental results, which is why cost and management accounting are needed. Treating the business as a separate entity is a basic feature of financial accounting, not a weakness that another branch has to fix."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 579, $official_bank_source${"itemId":"b00fcc89-16dd-5585-9c1b-b4ba346f74d6","questionId":"bfd88199-8b59-5064-8f54-ab9a899db4b0","sourceKey":"bank:ACC101:A101N4-030","payload":{"prompt":"Which of the following is NOT usually given as a reason for needing cost and management accounting?","options":["Financial accounting does not give product costs","Financial accounting cannot compare results with budget","Financial accounting does not show departmental results","Financial accounting treats the business as a separate entity"],"correctOption":3,"section":"Branches of accounting","explanation":"Treating the business as separate from its owner is a normal attribute of financial accounting and creates no need for another branch. Missing product costs, no comparison with budget and no departmental results are the gaps usually given as the reason cost and management accounting are needed."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 580, $official_bank_source${"itemId":"0fda95f8-625b-58e7-a4a8-dfea20f26a35","questionId":"6b1fe701-5491-5112-9b90-2d2a63f75a3f","sourceKey":"bank:ACC101:A101N4-031","payload":{"prompt":"The management of a firm in Ikeja wants to know which of its departments are making losses. Which branch of accounting is best placed to provide this information?","options":["Auditing","Financial accounting","Taxation","Management accounting"],"correctOption":3,"section":"Branches of accounting","explanation":"Management accounting gives managers internal information for control and decisions, such as how each department is performing. Financial accounting is the tempting choice, but it reports on the whole business and does not show which departments perform well or make losses."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 581, $official_bank_source${"itemId":"e1dbe27c-5423-5d72-a1da-fb9b2cb7e900","questionId":"ad536367-529d-577e-abbd-eb16f57ac662","sourceKey":"bank:ACC101:A101N4-032","payload":{"prompt":"Financial accounting is sometimes likened to a \"post-mortem report\". This is mainly because it","options":["Plans how the business will raise funds in future","Reports on events after they have happened, using historical figures","Shows the cost of each product the business makes","Independently examines the accounts for errors and fraud"],"correctOption":1,"section":"Branches of accounting","explanation":"Like a post-mortem done after death, financial accounting reports on transactions after they have taken place and relies on historical figures. Independently examining the accounts describes auditing, which is a separate branch rather than the reason for the post-mortem comparison."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 582, $official_bank_source${"itemId":"6bc427df-0b13-596e-b07a-47c4a914d426","questionId":"b4b4f7cc-872d-5290-b342-7203013376fb","sourceKey":"bank:ACC101:A101N4-033","payload":{"prompt":"A firm in Ikeja is deciding whether to replace an old machine and launch a new product. Which branch of accounting is designed to provide information for such decisions?","options":["Public sector accounting","Financial accounting","Management accounting","Forensic accounting"],"correctOption":2,"section":"Branches of accounting","explanation":"Management accounting provides information for internal planning, control and decisions such as replacement, new products and expansion. Financial accounting is the tempting choice, but it does not help with strategic decisions of this kind because it mainly reports historical results."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 583, $official_bank_source${"itemId":"f8221d7c-7808-5b84-ab98-64969a8dd070","questionId":"905031ae-2254-5a47-b93e-80362bb600da","sourceKey":"bank:ACC101:A101N4-034","payload":{"prompt":"Management accounting information is used for all of the following EXCEPT","options":["Planning","Control","Decision-making","Independent examination of the financial statements"],"correctOption":3,"section":"Branches of accounting","explanation":"Independent examination of the financial statements is auditing, not management accounting. Planning, control and decision-making are exactly what management accounting information is used for inside the business."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_acc101', 'add', 584, $official_bank_source${"itemId":"6913ed81-5415-5c23-9446-a6e100107722","questionId":"ea51deb9-59b9-50e5-a2ae-14471794cc33","sourceKey":"bank:ACC101:A101N4-035","payload":{"prompt":"Which of the following pairs correctly matches a branch of accounting with its main concern?","options":["Financial management - examining financial statements","Cost accounting - product and process costs","Auditing - raising and using funds","Taxation - internal planning and control"],"correctOption":1,"section":"Branches of accounting","explanation":"Cost accounting is correctly matched, because it deals with product and process costs. Raising and using funds belongs to financial management, not auditing, while auditing is the independent examination of financial statements."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 585, $official_bank_source${"itemId":"572070dd-5e3b-5d99-bd18-ed9b41173d3a","questionId":"3f16e245-48bd-5954-a87a-cfc4aed6bab8","sourceKey":"bank:ACC101:A101N4-036","payload":{"prompt":"One of these branch-and-concern pairs is mismatched. Which one is it?","options":["Auditing - independent examination of financial statements","Financial management - tax computation and planning","Management accounting - internal planning and control","Financial accounting - historical reports for external users"],"correctOption":1,"section":"Branches of accounting","explanation":"The pairing of financial management with tax computation is wrong, because financial management deals with raising and using funds while tax computation and planning belongs to taxation. The other three pairs, such as auditing with independent examination of financial statements, are all correct."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 586, $official_bank_source${"itemId":"cab8a209-cbc7-52f7-b77a-2ca42eddec60","questionId":"2b3f41d9-fbd3-5c75-b557-941d55479967","sourceKey":"bank:ACC101:A101N4-037","payload":{"prompt":"The main users of management accounting information are","options":["Managers within the business","Tax authorities","Shareholders outside the business","Lenders such as banks"],"correctOption":0,"section":"Branches of accounting","explanation":"Management accounting is meant for internal planning, control and decisions, so its main users are the business's own managers. Shareholders are users of financial accounting reports, which are historical and prepared mainly for people outside the business."}}$official_bank_source$::jsonb),
  ('official_bank_acc101', 'add', 587, $official_bank_source${"itemId":"28c73f1e-7bf4-50ac-a092-ba8fb759271c","questionId":"41e7f263-43e5-5fa1-9016-60a0204acfff","sourceKey":"bank:ACC101:A101N4-038","payload":{"prompt":"Financial accounting reports are prepared mainly for","options":["Auditors only, for their examination","External users such as shareholders and lenders","Cost clerks, for product costing","Managers only, for budget control"],"correctOption":1,"section":"Branches of accounting","explanation":"Financial accounting produces historical reports for external users such as shareholders and lenders. Preparing reports for managers' budget control describes management accounting, which serves people inside the business."}}$official_bank_source$::jsonb);
